		["Могу научить тебя ловить рыбу."] = "7e16cec2614e5f2a337e7a0f19d3b1fb",
	},
	["Арман Меднокноп"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "41e918ce5d8b5a41ff38961622d0549a",
		["Сейчас бы каштанов пожарить… Ммм!"] = "b6dafafd31fc1556e3a2a4d282f57535",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "ba70cc90cf6fed160c19534755c94deb",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "cc87a307413254d64af804bd33e37001",
