		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "3fabe072e57d6a47c2f6ca2b9c8134a7",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "33f7fa4705c0138ea7a4c54342903154",
		["Сезонные скидки для вас и вашей семьи!"] = "6c6b13e6f0ac323bc0364cf61cf53234",
	},
	["Арнок"] = {
		["Я – медицинский орк, $r. Если ты хочешь стать лекарем, я приложу все усилия, чтобы помочь тебе в этом."] = "8e7239601de1c8f6d5c6553a819d76ab",
	},
	["Арнольд Лиланд"] = {
		["Добро пожаловать в Штормград. Мы долго поднимали наш город из руин – но оно того стоило. Вы просто так приехали или по делу?"] = "e980a3fd7dce3ba0d906cea472aaa320",
	},
	["Арториус Добродушный"] = {
		["Как приятно увидеть живую душу в этом отдаленном уголке мира. Давай прогуляемся. Пусть наши тела согреют друг друга."] = "592e299bd0edf1ea20bdb5dabf705526",
	},
	["Артур Верный"] = {
		["Да хранит тебя Свет в этот день."] = "0635f703e43c62457aadee823a30493b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Артур Мур"] = {
		["До моей смерти я был библиотекарем, я не имел ничего общего с войнами и чумой. И никогда не хотел стать этим. С другой стороны, теперь, когда мой разум вновь принадлежит мне, я не сдамся без боя."] = "a7e84b1b5e75939894edeab15157fc04",
	},
	["Арчибальд"] = {
		["Ты хочешь научиться владеть новым оружием? Ну так поторопись, у меня мало времени!"] = "cebc5bda58373eb38beb32738253fcd6",
		["Сайок, орочий эксперт по оружию, живет на Аллее Чести в Оргриммаре. Он обучает владению луками, кинжалами, кистевым и метательным оружием, а еще одноручными и двуручными топорами.\n\nТролль Ханаши обитает там же. Он покажет тебе, как пользоваться одноручными и двуручными топорами, посохами и всем возможным метательным оружием.\n\nАнсеква, тауренский эксперт по оружию, трудится на нижнем ярусе Громового Утеса. Он обучает владению двуручными булавами, посохами и огнестрельным оружием."] = "1e08fa1b1a06707d7772a9d8bffbb01c",
	},
	["Аска Вестница Туманов"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "f4ecc692c98606d458fb7c830b10e27c",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "0ed954dd02d4a7694fc374f6df8dc387",
		["\"Поваренную книгу умельца\" можно купить у Вулана в Деревне Ночных Охотников. Тебе она понадобится, если ты хочешь расти над собой."] = "781459db7da362b3fa5744abdcd013b1",
		["Я могу научить тебя готовить!"] = "de1872cd5c5303ee685544d18a1c6b9d",
	},
	["Астайя"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "e170ac547f813e355db1e3b75f753815",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "49c592e9b3c5eeb0c33e65239b4c0b06",
		["Могу научить тебя ловить рыбу."] = "b4dab18389b060695ecdb043fb33d368",
	},
	["Астария Ловец Звезд"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Астор Хадрен"] = {
		["Что вы хотите, $c? Я уже опаздываю, а мой хозяин этого ох как не любит."] = "4d9d8b2efc14201a6e931c1e0c7c9c54",
		["Да, это я. А вам-то что?"] = "75ff43dd97408c7355a214344f6383ba",
	},
	["Аурий"] = {
		["Приятно видеть противников Плети в Стратхольме, ведь именно здесь она сильнее всего.$B$BМеня зовут Аурий. Когда-то я был паладином Серебряной Длани, но, как и прочие, чья вера поколебалась, впал в немилость. Приспешники Плети ввели меня в соблазн и чуть не превратили в рыцаря смерти!$B$BОсознав, как велик риск, я укрылся в этой часовне. Это святое место, где первый паладин Утер Светоносец был принят в орден Серебряной Длани."] = "838b9927288bcbb1e762b2ef266b1a9d",
		["В этом мире у меня немного времени, но, волею Света, его хватит, чтобы исполнить предначертание. Когда ты встретишься с бароном Ривендером, я буду с тобой."] = "a30c5c705bd6b70241922ce37f6afcdb",
		["Оставь меня. Мои раны глубоки, и я боюсь, что смерть скоро настигнет меня. Спасибо тебе, $N. Я умру здесь, но благодаря тебе… я умру с миром."] = "1459e6358a1d64d948e842c494640010",
	},
	["Ахану"] = {
		["Здравствуй. Если ты ищешь товары из кожи, то у меня найдется все, что тебе нужно."] = "03925a7b505107b23b456755061ec21a",
	},
	["Аянна Вечнобродка"] = {
		["Я не обучаю таких, как ты, $c."] = "9bd1614bca66fd26e163696ba1b6b6fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
