		["Куда бы вы хотели слетать?"] = "8ee9e2b8b1fbeba82851331d36cb251c",
	},
	["Барнил Каменный Кубок"] = {
		["Господин Эрнестуэя собирается на большую охоту. Готовить его к таким вылазкам в джунгли мне нравится куда больше, чем к войне. Хотя, конечно, мгновений боевой славы мне не хватает."] = "e3a348a35882a9d1e3d9c86ff56b6bbe",
	},
	["Барон Ревилгаз"] = {
		["Добро пожаловать в Трофейную Бухту, коллега. Надеюсь, твое пребывание в моем городе будет приятным и тихим. Ключевое слово \"тихим\". У нас много выпивки для жаждущих и вышибал для буянов. $B$BНу а теперь… чем скромный слуга картеля \"Хитрая Шестеренка\" может быть тебе полезен? Или лучше – чем ты можешь быть $gполезен:полезна; мне?"] = "a122cd69a20b3e81ab38fa94be544fd8",
	},
	["Баррус"] = {
		["Здравствуйте! Я могу рассказать вам о состязании рыболовов в Тернистой долине. На это состязание допускаются все, кто достаточно крепок, чтобы выжить в наших краях, и достаточно искушен в рыбной ловле, чтобы вытащить рыбку из воды.$B$BВозвращайтесь, когда наберетесь опыта!"] = "3f6b8f110896d04e7a6ad663cef0e70d",
		["Приветствую $gдруга-рыбака:подругу-рыбачку;! Если хочешь померяться силами с лучшими рыболовами этих земель, слушай внимательно! В это воскресенье в Тернистой долине состоится состязание, на котором будет избран Лучший удильщик!"] = "999cf7c2621e41f28cf2b13cc9d97ede",
	},
	["Белдрук Роковое Чело"] = {
		["Да пребудет с тобой Свет, $c. Чем я могу помочь?"] = "0c2e5af8c299738c3e541d7e001d442e",
		["Возможно, ты и не следуешь путем Света, подобно рыцарям Серебряной Длани, но ты всегда можешь рассчитывать на нашу помощь."] = "6d05441079c12f5737a4ae0732070946",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Белия Громовой Гранит"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "12e2351404174f85aa98fa3a3524bcd0",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "b439ced1ada35971e9ff2706f428bff0",
	},
	["Бен Триас"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "a86de99ac7614f683ab7eab24b0a0b93",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "0a50227fd4a79a221c5e74147031f06e",
	},
	["Бенгус Подземная Кузня"] = {
		["Уж надеюсь, ты не для того $gзашел:зашла; в Великую Кузню, чтобы просто погреться. Рассказывай, что тебе от меня нужно."] = "e40bd9cff0a2b475b7f856f9b06f20cd",
		["Ты $gпохож:похожа; на кузнеца. Под ногтями копоть, в костях сталь. Да, в твоих жилах течет кровь настоящих кузнецов… Стало быть, учиться $gпришел:пришла;? Ну что ж, $gпарень:девица;, бери молоток. Посмотрим, чему я сумею тебя выучить."] = "6d836253374e7258f1d26abac7475d18",
		["Мне жаль, $gпарень:девица;, но у тебя просто нет основы, необходимой для изучения того, чему я могу научить. Но не переживай, поговори с моим студентом Ротгатом, он тебя подтянет…"] = "ae2d32ca31d33d2e9a8717028c168fb8",
		["Не устаю тебя хвалить – с молотом и наковальней ты вытворяешь просто потрясающие вещи. Теперь так: никому не говори, что я посоветовал тебе найти гоблина, чтобы у него учиться, но я собираюсь сделать именно это. Его зовут Брикк Мастерец, и вроде как сейчас он держит лавку в Пиратской бухте."] = "c3356da865caee5c14d5f6bf59f6db2a",
	},
	["Бера Камнемолот"] = {
		["Куда бы вы хотели слетать?"] = "43540ff7458382b18eb66468d4ff2856",
	},
	["Берам Небесный Охотник"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "d96f407d05286ba207ff46bf75ef4510",
		["Да пребудут с тобой духи."] = "1eec7529a102737979dbaf19908f6ac0",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Бернард Гамп"] = {
		["Мы – единственные поставщики живых цветов во всем Штормграде. У нас есть прекрасные цветы на все случаи жизни."] = "8235974cfa833adfdaf9b2864225d19f",
	},
	["Бибильфас Перосвист"] = {
		["Куда бы вы хотели слетать?"] = "4a4d46597b846228dbd070932127a575",
	},
	["Билибуб Шестеренок"] = {
		["Если вставить панель А в гнездо Б, то, разумеется, оно РВАНЕТ! Вот, дайте я покажу вам, что у меня есть, а потом вы сможете спросить Лилиама о том, состыковать эти предметы, чтобы они не взорвались."] = "d1c3a174065be73fad87b0bff53c38b7",
	},
	["Бильбан Болтокрут"] = {
		["Вследствие несовместимости вашей классовой специализации я не могу помочь вам исправить никакую ситуацию, в которую вы попали из-за недостаточного развития умения."] = "43a1a5f8d367e470a976ff4bba7a35ed",
		["Великолепно! Вы соответствуете всем необходимым параметрам и условиям! Что я могу сделать для вас?"] = "bb5e78178b059f89784b631f64c36858",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Бинджи Перосвист"] = {
		["Я могу научить тебя новым приемам вождения механодолгонога, если у тебя хватит золота заплатить за урок!"] = "144516c0f69573ee3346350d1c8751f1",
		["Учить тебя вождению механодолгонога – пустая трата моего времени и твоего золота, $c. Больно уж ты $Gздоровый:широка в кости;."] = "8793a1e3bacd16171e597a2e6e349f3b",
		["Тебе нужно заслужить полное доверие Изгнанников Гномрегана, прежде чем я научу тебя управлять механодолгоногами, $c."] = "4a0058f7e90fd806fca67dea42c579d6",
	},
	["Бинк"] = {
		["Приветствую. Я гном, наставник магов. Ну а вы – маг."] = "cdf2e086bf2b6776973657b23b505e5a",
		["Здравствуйте, $c. Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано."] = "162dfb07afee97dc4d79532fb14ed623",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "6cabdb4331ddecbb973a32e419e6be83",
	},
	["Биргитта Кранстон"] = {
		["Тебе повезло быть $gодним:одной; из нас – ведь только маг сможет создать портал для возвращения сюда. Я могу научить тебя, если хочешь."] = "972de67fb04e5abac98c6158c6b5bcc6",
		["Мне кажется, ваших умственных способностей недостаточно для постижения тонкой магии порталов."] = "3a497353f8cb102ec4debd8d8adc446a",
	},
	["Бодли"] = {
		["Ты меня видишь? Знаешь, сколько времени я ни с кем не общался только потому, что меня никто не мог увидеть? До чего же здорово наконец-то поговорить!$B$BТак тебя, должно быть, прислал кто-то из моих выживших приятелей-наемников, да? Ну конечно!$B$BНо хватит болтовни, у нас с тобой еще куча работы – если, конечно, ты собираешься все уладить и вернуть Лорду Вальтхалаку его дух."] = "d8a5cf6d252aa70c9685e327fb97066f",
		["$n! Ты $gвернулся:вернулась;, только чтобы поговорить со мной? Как это мило! Кстати, этот наряд тебе очень идет.$B$BТы не представляешь, как я рад тебя видеть! Иногда мне так одиноко – меня же почти никто не видит. Ты столько $gсделал:сделала; для всех нас, и я никогда этого не забуду! $B$BСпасибо, что $gзаглянул:заглянула;. Будь как дома!"] = "31cec36e221c24d2e395f87f8a13b7c7",
	},
	["Больюн"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "3108806b44f37624987d36cafc8de658",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "963db5ef5555edf879e137a605643024",
	},
	["Бом'бей"] = {
		["Привет. Поговори с мастером Гадрином – тут неподалеку. Помоги ему с этим чокнутым Залазаном – и я помогу тебе."] = "5c340bf8d079d06c25dc98c4fde2c2c0",
		["Ага, я помогать Гэдрину. Работать, чтобы учиться на знахаря. Раз твоя помогать ему, то моя помогать тебе. Что тебе подлатать?"] = "c47613e829659c77c1817810ed8fa886",
	},
	["Бор Буйногривый"] = {
