	["Браун"] = {
		["Пока что на этом континенте у нас есть лишь маленькая крепость, но люди не могут бороться с нами вечно. Когда-нибудь они заплатят за то, что поработили нас. За их предательство мы вырежем их лживые языки."] = "14c20e89440319b1fc7df3e53552a16d",
		["Я бы тебя научил, да самому знаний не хватает. Вот что я скажу: иди и поговори с тауреном Уной. Она работает в мастерских на северо-западе центрального плато Громового Утеса. Таланта ей не занимать."] = "f58bf6b4db68eb60245db834b0c12194",
		["Храбрости у тебя больше, чем мозгов, раз ты $gпришел:пришла; ко мне без должного обучения. Иди поищи более подходящего учителя – да хоть ту же орка Камари из оргримарского Волока."] = "333ced88b7c1e9498193f4e7df73a47d",
	},
	["Браэнна Кремнескал"] = {
		["Да хранит тебя Свет, $c."] = "a2d6560ac0ea81674c83c91abf44c3ec",
		["Надеюсь, $n, Свет на твоей стороне. Могу я чем-нибудь помочь?"] = "4aab004f4103403f80277e098e208dd0",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "125a186cc1dc5f89644a87549bcf2140",
	},
	["Брейк"] = {
		["Куда бы вы хотели слетать?"] = "f686b3319d4af5004c6ee3403aea3f5e",
	},
	["Бреннок"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "958a146c28400f9f9854e051f637dcfa",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "2b445553ef42041e4fb79936cb957400",
		["Могу научить тебя ловить рыбу."] = "a8d1f968e17b0d4c93ec75f0c6e5bfad",
	},
	["Бригадный генерал Альянса"] = {
		["Война с Ордой в самом разгаре, $n. В эти дни Альянсу необходима помощь и поддержка каждого бойца."] = "59639744f57566c294774d64cbef1436",
	},
	["Брикк Мастерец"] = {
		["Да? Разумеется, я кузнец! А вы как думали, только дворфы могут по наковальне колотить? Ну и ладно! Вот пусть вам дворф и помогает!"] = "29b36a70548ade1ec5054bd5082e4b54",
		["Ты шутишь? Ты, должно быть, шутишь! Или так, или ты думаешь, что я клоун, пришедший развлечь тебя. Это ты думаешь? Что я клоун? Ха, да! Ты думаешь, что я клоун, да!"] = "939a1307b0cf9e41fb14a7b51a7e6adc",
		["Ты ведешь себя так, словно этот хлам может кого-то впечатлить. Нет, конечно, он очень даже ничего, но вещи такого уровня встречаются везде и всюду. Вот что: сумей меня удивить, и я научу тебя таким вещам, которые заставляют дворфов улыбаться во сне."] = "0a4352094f4852338fc9624bcf71bd3f",
	},
	["Брогун Камнещит"] = {
		["К сожалению, $c, тебе нужно поднабраться опыта, иначе ты не выживешь в Альтеракской долине."] = "f78c3c41a85a94fe125292149c2763de",
		["Ну что, $gюноша:девушка;, вы готовы отправиться в Альтеракскую долину и дать Орде то, на что она так напрашивается?"] = "8b3c666dc6e4c0c98f9d6747a2aea0f8",
	},
	["Брок Камнекоп"] = {
		["Хорошего горняка можно узнать по крепкой хватке, отважному сердцу и черной пыли в волосах."] = "8b98ed3895e46abfab305a7b3fe85366",
	},
	["Бромос Груммнер"] = {
		["Да пребудет с тобой Свет, $c. Чем я могу помочь?"] = "0c2e5af8c299738c3e541d7e001d442e",
		["Возможно, ты и не следуешь путем Света, подобно рыцарям Серебряной Длани, но ты всегда можешь рассчитывать на нашу помощь."] = "6d05441079c12f5737a4ae0732070946",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Бронк Пропойца"] = {
		["Всего лишь небольшая поправка здесь… вот так!"] = "7a6856a43c935660b28dc73571129644",
	},
	["Бронн Выкрутас"] = {
		["Чем я могу помочь тебе, $n? Говори быстро, мне время дорого!"] = "b9dfff243575891bcfc18fc60feb4f58",
	},
	["Бруки Каменная Коса"] = {
		["Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать."] = "8ee2a69ee63c41a11aeca4da11d55e13",
	},
	["Брумн Заиндевевшее Копыто"] = {
		["Духи сказали мне, что ты придешь, что станешь искать меня по какой-то причине, которая, может статься, не будет известна даже тебе. Итак, ты знаешь, зачем $gпришел:пришла;?"] = "f7eb9170dcfaa7e5f749986588580ced",
	},
	["Бубуло Груббер"] = {
		["Недавно мы, изгнанники Гномрегана, обнаружили, вдобавок ко всему прочему, что у нас кончились запасы ткани!$B$BМожет, у тебя найдется ненужная ткань? Принеси ее мне, и за это тебе будет почет и доверие ото всех гномов! А этого за деньги не купишь! Гм, зато купишь за ткань… Но суть-то, суть-то не в этом!"] = "6b524e6f63821d7aa775800797480d02",
	},
	["Булкрек Десница Гнева"] = {
		["Куда бы вы хотели слетать?"] = "f686b3319d4af5004c6ee3403aea3f5e",
	},
	["Бульвайф Крепкорук"] = {
		["Ты хочешь, чтобы я научил тебя обращаться с новым видом оружия, да? Ну, не стой разинув рот, говори, $gпарень:девушка;!"] = "944b95dab7611ca743debffc47ea0d42",
		["С гномкой Бикси Пошатушкой, экспертом по оружию, ты можешь встретиться прямо здесь. Она научит тебя обращаться с арбалетами, кинжалами и метательным оружием.\n\nВу Пинг из арсенала Веллера в Штормграде обучает владению арбалетами, кинжалами, мечами, древковым оружием и посохами.\n\nНочную эльфийку Илиению Лунное Пламя ты найдешь на Террасе Воинов в Дарнассе. Она покажет тебе, как пользоваться луками, кинжалами, кистевым оружием, посохами и метательным оружием."] = "907cb6456b6c5ff065e865380e9b9180",
	},
	["Бунтен Ветер Равнин"] = {
		["Ты не друид!"] = "5cfd7206f10c06184a22b230f17e7e9b",
		["Если хочешь полететь в деревню Рут'теран, поговори с моей подругой Сильвой Фил'навет. Она из ночных эльфов."] = "e06e352070d1d0f09e52dc97d8a078e5",
		["Не хотите ли совершить полет в Громовой Утес? Услугу предоставляет Круг Кенария."] = "155c5f7fcaa47599e5718aa28c430db2",
		["Ты $gдолжен:должна; искать в водах Западного Края, к западу или северо-западу от того места, где Прииск на Золотом Берегу выходит на побережье. Место, где затонула лодка, можно найти по якорю. Там очень глубоко – давление воды может оказаться смертельным даже для самого опытного пловца.$B$BЧтобы выжить, $n, пользуйся помощью природы. Там неподалеку есть бурлящая расщелина, в которой можно набрать воздуха."] = "58917c8c3ab49673db3986c9f9ce7b31",
		["В Серебряный бор, у Берега Северного прилива, на берегу покоится полуразвалившаяся лодка. К западу от нее лежит то, что ты ищешь; заплыви слишком далеко, и океан сокрушит тебя усталостью. Оно находится на дне океана, в сундуке, ожидая тебя.$B$BТебе будет тяжело пережить нырок на такую глубину без помощи, так что соберись с духом; разлом, из которого струятся пузырьки, дает второе дыхание ныряльщикам, ищущим эту половину подвески. Используй его мудро."] = "8f4726b4aaa640c64d970e27f5507d9f",
	},
	["Бьянси"] = {
		["Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора."] = "49a613b778992ca51b3a3d070eadd735",
		["Я слышал, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи."] = "d64bde6554e9c8b2bd854db8a7bbe49b",
		["Я могу научить тебя оказывать первую помощь."] = "5b09af4b70a11e0b3b1b1c7ccc834d62",
	},
	["Вагнер Молотобоец"] = {
		["Здравствуй, $c. Пришло время Праздника Урожая – время щедрых даров и воспоминаний. Мы устраиваем пиры, чтоб отпраздновать все, за что нам следует быть благодарными, и вспоминаем наших предков и героев прошлого, чтобы поблагодарить их за наследие.$B$BНе стесняйся, присоединяйся к нашему пиру. А еще я устраиваю фейерверки, чтобы лучше отпраздновать это радостное время года."] = "20a2672934e46dd87b9f9e585c09dd52",
	},
	["Вагрук"] = {
		["Куда бы вы хотели слетать?"] = "f686b3319d4af5004c6ee3403aea3f5e",
	},
	["Ваелан"] = {
		["Давным-давно, задолго до нынешних войн и раздоров, из-за нашей доброты мы оказались на краю гибели. Мы пережили очень многое, $r.$B$BНападение Пылающего Легиона. Души демонов. Раскол Аспектов. Возвышение Смертокрыла. Пленение нашей королевы Алекстразы кланом Драконьей Пасти.$B$BНо, несмотря ни на что, наша несгибаемая воля всегда оставалась с нами. Только она позволила нам сохранить место под солнцем этого мира."] = "70ff6628453819c5b1c1d6d5eed119e7",
		["Не подноси это ближе. Я даже отсюда чувствую зло, которым пронизана эта печать.$B$BДержи этот предмет крепко – дай мне рассмотреть его."] = "0958c9f61564c247675031fbb4a44632",
		["Несомненно. Я принял облик, доступный восприятию смертных. Естественно, ты не сможешь вынести присутствия дракона Валестраза.$B$B*Ваелан смеется.*$B$BЯ могу продолжать?"] = "8333270249e46a72656aa0258ec27a0a",
		["Наверное, следует рассказать, зачем я здесь.$B$BВы знаете об Аспекте Смертокрыле? Или о его потомках, Нефарионе и Ониксии?"] = "8e2703518fe6096cd0cf2fb34cc39fc7",
	},
	["Вазарио Цепесмаз"] = {
		["Здравствуйте! Если вы хотите получить доступ к чертежам, просим вас приготовить свой членский билет гильдии гоблинов-инженеров для проверки."] = "e814cc2694856d5e9fb32efcf2ea7186",
	},
	["Валадар Звездная Песня"] = {
		["Почитать своих старейшин – значит почитать свою культуру и свой народ, $c. А Монеты Предков служат зримым способом узнать тех, кто желает следовать почтенной традиции уважения.$B$BВо время этого Праздника луны тебе может представиться возможность выказать уважение многим старейшинам. Сделав это, ты получишь Монеты Предков. Принеси их мне, и я в награду за усердие предложу тебе подборку уникальных вещей."] = "5ff684abf73ab59dca0e0d04d8c6f804",
		["Омен спит в глубинах Озер Элуны, но может быть призван к юго-восточному берегу, возле Кельи Малфуриона. Там ты найдешь пусковые установки для фейерверков…$B$BКак только ты выстрелишь, появятся прислужники Омена. Запусти побольше ракет, десятка четыре, или выстрели свечой Элуны по его прислужникам, и вскоре он пробудится."] = "8380da37ec60070f5cc0417fd12e3bc6",
	},
	["Валдор"] = {
		["В пещерах под нами можно добыть немало странных и удивительных шкур. Но будь $gосторожен:осторожна;, если решишь отправиться туда, $n. Твоя собственная шкурка в любом случае ценнее."] = "d60817dbe236b7089fc232eee4ef8e4a",
		["Вы научились работать с кожей лучше меня. Возможно, вам стоит отправиться в Степи и познакомиться с тауреном Крульмоо Полная Луна из Лагеря Таурахо. Он много чему сможет вас научить."] = "ebdbe70c30588d8e64ff468af9fbab81",
	},
	["Вальгар Высшая Кузня"] = {
		["Да пребудет с тобой Свет, $c. Чем я могу помочь?"] = "0c2e5af8c299738c3e541d7e001d442e",
		["Возможно, ты и не следуешь путем Света, подобно рыцарям Серебряной Длани, но ты всегда можешь рассчитывать на нашу помощь."] = "6d05441079c12f5737a4ae0732070946",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Ванс Мрачнейший"] = {
		["Приветствую тебя, $Gпутник:путешественница;! Желаешь постичь тайную магию?"] = "70cedd46427b60803ef6cb69ad0be4cb",
		["Даже у меня есть свои пределы! Если хочешь учиться дальше – пойди поговори с Лавинией Кроу в Подгороде!"] = "147f7781bcfc14024f4c4c8fae38a676",
		["Неплохо… Пожалуй, из тебя может выйти толк. Ну что ж, начнем!"] = "8e93c72122e45dcdc82ece99e2656405",
	},
	["Вар'джун"] = {
		["Я кое-кого ищу, $c. Оставь меня, пожалуйста… важно найти их."] = "139d2506ed562303b66f560b7502291c",
	},
	["Варг Рыбовод"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "88fec34af6aec4e24b11fe1f3ad60422",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "b4e4101905820aead3b6b58b95cdc8ed",
		["Могу научить тебя ловить рыбу."] = "cc6057593751f84f1d2743551c270cf4",
	},
	["Варгус"] = {
		["Великое зло пробудилось, $r. Ты чувствуешь?$B$BХа! Конечно же нет! Давай твои доспехи и оружие, и я приведу их в норму."] = "8df70dd608a3c4cf651cb64b15114023",
	},
	["Вельма Варнам"] = {
		["Я могу научить тебя новым приемам верховой езды нежити – если, конечно, у тебя хватит золота заплатить за урок!"] = "2e65eb1fa48fb06278bb020f60a84d34",
		["Чтобы я смог учить тебя, $c, ты $gдолжен:должна; завоевать полное доверие Отрекшихся из Подгорода."] = "dcd0a28a88596d37aad3b937bda5ab9f",
	},
	["Верон Янтарлен"] = {
		["Считай, что ты и не $gвидел:видела; настоящих скакунов, пока не $gоседлал:оседлала; породистого горного барана Барак Торола. Не стесняйся, осмотри внимательно этих достойных спутников искателя приключений. Поверь, любой из них отлично послужит тебе."] = "3caea1966e7ba5ccaa3d5ba89520c93f",
		["Не так быстро, $gгосподин:госпожа;… Я не доверю элитного ездового барана тому, кто не заслужил уважения дворфов Стальгорна. Когда вас станут превозносить в нашем городе, я с радостью покажу вам всех скакунов, что у меня есть на продажу."] = "5953f84af6e63c466e0a1f64d4a3f981",
	},
	["Верховная жрица Лорена"] = {
		["Я вижу, $n, что душа твоя светла. Могу ли я тебе чем-нибудь помочь?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["Не отворачивайся от Света, $c. Возможно, когда-нибудь он спасет тебя."] = "120875f188ac12780f811009b51a783b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Верховная жрица Макдонелл"] = {
		["Чума Плети все еще свирепствует в этом районе, и нам еще многое предстоит сделать. Собери необходимые припасы и помоги вести войну!"] = "58b0554b4eb137e72abec05c73e93452",
		["Распространение чумы Плети практически остановлено. Еще несколько котлов – и мы победим! Только не забудь сделать свою часть дела."] = "cdbc784d0f00f4659ccee11833a3128b",
		["Мы научились обращать чуму Плети против нее самой, но до победы еще очень далеко! Помоги нам изменить ее котлы!"] = "a26eb8b0ce0bb0171f1b4303aac09ecc",
		["Мы побеждаем Плеть – измененная чума будет действовать на нежить как минимум еще один день! Но чтобы закрепить эффект, нужно как можно скорее вывести из строя следующий котел!"] = "335dcfc9ba7e7b8a587e1d82f288ba64",
	},
	["Верховный друид Фэндрал Олений Шлем"] = {
		["Отнимая время у меня, вы отнимаете его у всего Круга Кенария. Надеюсь, что вы не настолько глупы, чтобы решиться на такое."] = "dbf255d67eb367a5e2e26df7615ab1d9",
		["Да, но теперь вам куда полезнее обратиться к травничеству! Вы будете выращивать редчайшие растения вместо того, чтобы махать топором или зубрить дурацкие заклинания. С сумой вечного цветения даже последний бездарь что-нибудь да вырастит, а уж опытный специалист добьется фантастических успехов."] = "246b760cf38fc3d7b56b064fcda8d886",
	},
	["Верховный друид Хамуул Рунический Тотем"] = {
		["Земля хранит немало тайн, $c. Наш долг – следить, чтобы то, чему положено быть тайной, ей же и оставалось."] = "73e67356c136d17ab74d016286b17aa3",
		["Да, но теперь вам куда полезнее обратиться к травничеству! Вы будете выращивать редчайшие растения! С сумой вечного цветения даже последний бездарь что-нибудь да вырастит, а уж опытный специалист добьется фантастических успехов."] = "aae2fc74b9bc45ed8363aab158366369",
	},
	["Верховный жрец Рохан"] = {
		["Да хранит тебя Свет, $c."] = "852369f0d2fbc11e555e75fe5a433853",
		["Надеюсь, $n, Свет на твоей стороне. Могу я чем-нибудь помочь?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Верховный инквизитор Фэйрбанкс"] = {
		["Наконец-то проклятье снято! Спасибо вам!"] = "3146d1e3ce619ce4be9719884bfd59d3",
		["Ты что, не знаешь? Меч, который ты носишь за спиной, зовется Пеплоносцем – по имени первого владельца."] = "5305da0d8750979d1bc134fec6194486",
		["Да, верховный лорд Могрейн – основатель первоначального Алого ордена. Рыцарь непоколебимой веры и чистоты, Могрейн был предан своим собственным сыном и убит силами Кел'Тузада в Стратхольме. Вот как я оказался здесь…"] = "ef7daa42b41400a1595d39af4a6e8762",
	},
	["Верховный лорд Демитриан"] = {
		["Взгляни на это разоренное поле! Узри силу Стихий, $r."] = "c249a2eaed40f813e602ee17f9452029",
		["*Демитриан падает на колени.*$B$BТы $gнашел:нашла; место вечного плена моего господина!$B$BКак же долго я ждал этого дня – и вот он настал.$B$BГосподина надо освободить!"] = "c7d0d5f0497c7bbd94f17ecb262de67c",
		["Я знаю многое. Слушай и запоминай, $r."] = "7624b1b9032ec89ab17724443dfdadf7",
		["*Демитриан смеется.*$B$BНаградой тебе, тупица, будет быстрая и болезненная смерть!"] = "c6c892dcc9a95f0b111608dfcf84c37b",
		["Я храню сосуд его возрождения. Когда ты будешь $Gготов:готова; выполнить задание, тебе потребуется укрепить этот сосуд и в конце концов освободить самого Рагнароса!"] = "0ba174f63cc2f24d23e0cfd845eb7767",
		["В те времена, что позднее захватчики назовут Эрой Творения, мой повелитель и его дети правили всем этим миром. Это были они, Древние боги, создавшие все.$B$BИ это они были свергнуты теми, кто назвал себя Оформителями."] = "c09678227a9af6c89356887b10213442",
		["Сосуд Возрождения необходимо укрепить элементием. Мне известен лишь один источник этого минерала: пространства элементалей в самом сердце нашего мира.$B$BГоворят, в мире есть некий демиург, сведущий в этом вопросе. Тебе необходимо найти его!"] = "df4e9cd871fca0c53d2e4b158280e34f",
	},
	["Верховный маг Тарсис Кир-Молдир"] = {
		["*Тарсис стонет.*$B$BМожет, еще не поздно… Слушай меня внимательно.$B$BЯ обыскал все время и всю Пустоту. Но сделки с повелителем зла и жестокости никогда не бывают честными…$B$B*Тарсис кашляет кровью.*$B$BМожешь ли ты… поверить, что сама Элуна отвернулась от меня, $r? И теперь я умираю здесь, вот так…"] = "1bf590bada9041c70d2e3870e5674fbb",
		["Что я наделал… Чудовищно, непредставимо…$B$B*Тарсис начинает всхлипывать.*"] = "b479ad369d216b4d010c09f20b8c4cf4",
		["Я из высокорожденных, $r. Но теперь это ничего не значит. Однако раньше Высокорожденные правили этим миром. С тех пор прошло десять тысяч лет…"] = "053c0fa7412311c64d1afb7f93c896c5",
	},
	["Верховный маг Тервош"] = {
		["Рад встрече, $n. Буду краток: у нас много дел."] = "96a3daa8a4f7ab7babfc5a1c8d9f5ca1",
	},
	["Верховный маг Шимм"] = {
		["Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?"] = "a6c8531f923dc7ee0e543e0e81ce1717",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "449fe8a183d9fbd6474051e5e1ba406e",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Верховный палач Деррингтон"] = {
		["Добро пожаловать на фронт, $c. Здесь нет места интригам и хитростям политиков. Здесь, в Бастионе, нам каждый день приходится бороться за жизнь.$B$BЕсли вы хотите совершить подвиг, то здесь найдете предостаточно возможностей для этого… особенно когда мы пойдем на Андорал и бросим вызов тем силам, что повелевают Плетью."] = "4ac4718c375b9ac2eb798b72c74e2c6a",
	},
	["Верховный правитель Саурфанг"] = {
		["Я тот, кто смотрит за ними. Я кулак возмездия. Я подавляю недовольных. Не боишься Вождя? Не боишься моего суда?"] = "ed0691b342e85f8155b2545fa09aff4c",
		["Взгляни на павшего дракона, $r. Мощь Орды неоспорима!"] = "5d36ebec7ba87ea72d8bc75fa1708950",
	},
	["Верховой Каэр Дарроу"] = {
		["Тунеядство, хулиганство, сквернословие, драки и все прочие непотребства, которыми ты собираешься заниматься, в Каэр Дарроу запрещены."] = "4c4f28300ec91dd44dcc6b9766779e5d",
		["У тебя вид, как у уличной шпаны!"] = "f4a68005ee615866bd6901fa901730b9",
		["У меня много нерастраченной злобы и ярости. Только дай повод, бродяга."] = "8aefd7ed4734fdad575f3aa8cabd868b",
		["Я за тобой слежу, $r."] = "98696987285136bfb07bf8b6b4ca71f2",
		["Будь $gосторожен, незнакомец:осторожна, незнакомка;. В нашем городе не терпят еретиков."] = "a97a57480f28e32779349ee115d11474",
	},
	["Верховой горный пехотинец Стальгорна"] = {
		["Банк? А-а-а, значит, вам нужен банк! Конечно, где еще хранить ценности, как не в нашем банке? Он прямо к северо-востоку от входа в Стальгорн."] = "726ce72b8aa754ecf613d9315fa35780",
		["Эх, поезд, поезд… все хотят ездить на поезде. Что случилось со старой доброй ездой на грифонах? Лететь, держась изо всех сил за седло?.. \n\nБа! Ну иди, садись на поезд… он в Городе Механиков, вместе с остальными гномьими штучками."] = "b6f01b7cfb83b6af6ea28d402cd03b91",
		["Ничто не сравнится с полетом на грифоне! Ночные эльфы могут оставить своих гиппогрифов себе – мне нужен только добрый грифон и ветер в волосах!\n\nНу ладно, не буду тебя больше задерживать, ступай к Гриту Турдену, это на восток от Великой Кузни. Он доставит тебя куда надо."] = "cb6734d0257007705c4566a44b980164",
		["Ну что ж, тебе понадобятся бумаги, чтобы основать гильдию, и Иондор Стальной Лоб может помочь тебе начать этот процесс. Когда будешь $gготов:готова;, его можно будет найти в Гостевых покоях Стальгорна."] = "7b31a92e46c77d8643368a8d82916e89",
		["Если тебе нужна гостиница, следует пойти в таверну \"Горючий камень\". Ты найдешь ее слева от входа в Стальгорн, если ты входишь, или справа, если выходишь.$B$BА, и если соберешься туда, скажи им, чтобы приготовили мне кружку."] = "9678dcc90aee99c0461684dd12aa5a6d",
		["Ба! Почтовые ящики… в последнее время один мусор приходит! \n\nУвеличить то… уменьшить это… подпишись и выиграй меч Драконоборца. Мне через месяц адрес менять приходится!\n\nНу что же, мое дело предупредить. Если все же ищешь почтовый ящик – он рядом с таверной \"Горючий камень\"."] = "cc8d5bdde66d34c96aeda15e29b244e5",
		["Найди Ульбрека Огненную Длань в Оружейной. Он позаботится о том, чтобы твои питомцы были хорошо устроены и досыта накормлены."] = "8417670da6e88a3c0046fbf19a284faf",
		["Хочешь умело обращаться с новым оружием? Тогда тебе прямая дорога в оружейную лавку Лесной Границы. Поговори там с Бикси и Бульвайфом – они по части оружия настоящие асы."] = "fc659204f3f853f42dd60c81107e99b8",
		["О, Альтеракская долина! Славные воспоминания! *вздыхает* Что ж, я не могу к вам присоединиться, но буду гордиться вами! Чтоб попасть туда, найдите в Оружейной Глордрума Сталеборода. Это здесь, в Оружейной Стальгорна."] = "e06fd55d9c7b155fdb8e8ed8c2d4b286",
		["Лига Аратора пытается отбить свои исконные владения в Низине Арати у Отрекшихся. Если ты хочешь помочь им, $n, поговори с Доналом Осгудом в Оружейной."] = "44b04e19a4aa4b719b00c378a9acd900",
		["Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место."] = "fa89dafc6960a6d66ea3bc3288a08a03",
		["Есть ли у тебя задатки хорошего охотника? Ну, $gпарень:девица;, только время покажет. Только не стреляй по яблокам на человеческих головах, пока не поговоришь с Регнусом из Оружейной."] = "4ee53decdddf5b8264e87b7865aae7ab",
		["Ну, ты точно можешь поучиться магии в Зале Тайн, к северу от Врат Стальгорна. Джули Скороварга сидит там постоянно, уткнувшись носом в книжку."] = "7e98ceebc9414083a4cc3fb3ae42f394",
		["А, так тебе нужен старина Брандар Железный Молот. Без сомнения, он знает все, что тебе нужно, $gпарень:девушка;. Поищи его в Зале Тайн, к северу от Врат Стальгорна."] = "63f213a9fe7d396bded4b0fcdb6f51b1",
		["Твоим горестям лучше всего поможет жрец. Конечно, пинта доброго пива тоже от многого помогает, но не думаю, чтобы Браэнна Кремнескал учила варить пиво. Думаю, тебе лучше договориться в Зале Тайн насчет обучения жрецов."] = "c813addf44eeb3041f9442747e4f19b7",
		["Все темные личности ошиваются в Заброшенном гроте, к северу от Врат Стальгорна. Иззаспинс непременно будет там – наверняка сидит и пересчитывает монетки из очередного подрезанного кошелька. Ух и доберусь я до него! \n\nИ за тобой я тоже пригляжу, $gдруг любезный:подруга;."] = "9528aea502ae9f7db96fe57bfe2c7e48",
		["А, $gчернокнижник:чернокнижница;… Ну, если тебе вздумается заняться чем-то таким здесь, потрудись держать своих демонов в узде, $gпарень:девушка;. Демонов я не люблю, а вот шинковать их секирой – очень даже. Ясно? \n\nА теперь оставь меня в покое и иди, поброди в Заброшенном гроте. Там ты и найдешь этого чернокнижника, Недотрогинса."] = "8dd3f0d79f6df157dda9178efcf166dd",
		["Конечно, Кельструм – трепло и хвастун… Но он один из самых опытных воинов на свете! \n\nЯ вот что тебе скажу: если ты интересуешься путем воинов – поговори с ним. Его можно найти в Оружейной, к востоку от Врат Стальгорна."] = "cbf2a15cc62d3fbd23d5f088837de2bf",
		["Вы ищете учительницу алхимии? Я только что от нее. Вам нужна мисс Гонобобельзз из Города Механиков. \n\n*вздыхает* …И почему я не выбрал синее зелье?"] = "10124c09c298bee683297933e30e1865",
		["Ты меня всерьез спрашиваешь, где кузнецы? Ты что, не $gслышал:слышала; о Великой Кузне?! Все наши лучшие кузнецы собираются там, чтобы ковать оружие и доспехи!\n\nОна прямо посреди Стальгорна, и именно там ты работает один из наших самых блестящих кузнецов, Бенгус Подземная Кузня."] = "79bd37ced9c62943a531dbe47af6053b",
		["О! Этот Дарил Рикнуссун – прекрасный повар! Он делает такой острый чили, что в нем можно закалять сталь! Не думаю, что он передаст тебе этот рецепт, но он обязательно поможет тебе стать хорошим поваром. Ты найдешь его в \"Бронзовом котелке\" с северо-восточной стороны Великой Кузни."] = "5a9c20e893c2fd018c67b13bea773ae2",
		["Ох! Осторожнее с зачаровыванием, $gпарень:девушка;. Я как-то зачаровал свою кружку, чтобы из нее пиво не проливалось, – и теперь она ни на что не годится! Такая трагедия.\n\nПрипомни мой совет, когда встретишься с Гимблом. Он живет в своей лавке у Великой Кузни, рядом с укротителем грифонов."] = "5906a29765d2173d53b9ab776005d62b",
		["А, так тебе нужен Пружиннер Шумотор. Есть тут один гном… Знаешь что? Если пойдешь в его мастерскую в Городе Механиков, ничего там не трогай, а главное – не прикасайся к его овечкам! \n\nВзрывопасные овцы… Это ж надо было такое придумать!"] = "cb4411cf05a5193ed1592cf994d7a1e6",
		["Первая помощь? А ты что, $gранен:ранена;? Ну, если ты и вправду интересуешься первой помощью, ступай к Ниссе Огневик. Ищи ее в лавке целителя возле Великой Кузни."] = "acbd5104f14dbadffa1e4f40e28a6ffd",
		["Я как-то слыхал от старины Гримнура, что он выловил меч. Или это была рыба-меч? Чертов Гримнур – он рассказывал столько баек, что теперь я не помню, что к чему. Сходи-ка ты к нему в Заброшенный грот, да и распроси, что там было."] = "b4e38865182ec7942e86379c3c9fcdf9",
		["О, ты, никак, хочешь научиться собирать маргаритки? Ха! Я просто тебя дразню, $gпарень:девушка;.\n\nЭто хорошая профессия, и Рейна Каменная Ветвь может обучить тебя. Она работает в лавке Целителя на южной стороне Великой Кузни."] = "9ba6396c2f8ca0fde5f32bf5810ac783",
		["Так ты точно не хочешь стать кузнецом? Что ж, если тебе так хочется заняться кожевничеством, тогда лучше поговори с Фимблом Остроиглом, у него лавочка на северо-западной стороне Великой Кузни."] = "a3b00fdf92a61d7b9b93fae27791e95f",
		["Так-так! Если хочешь учиться горному делу, $gпаренек:девочка;, значит, $gпришел:пришла; по адресу! В Шахтерской гильдии рудокопов Темной Горы обретается сам Геофрам Твердопал. Лучшего учителя, чем он, и желать нельзя."] = "57c3f67ebbf0020b5e1987aa2869782f",
		["Снять шкуру? Да ты, небось, даже собственные коленки ободрать не сможешь! Ха! Поговори-ка с Балтусом Шлифовальщиком, уж он-то умеет снимать шкуры. Ищи его в кожевенной лавке Остроигла на северной стороне Великой Кузни."] = "5a0adca7c8c31d843cea219178821576",
		["Может, ты этого и не знаешь, но Джормунд не только опытный портной, но еще и убийца великанов! Как-то он услышал, как мы рассказывали всякие истории, да и закричал вдруг, что побил семерых одним ударом!\n\nТебе стоит наведаться к нему в лавку на северной стороне Великой Кузни и попросить, чтобы поведал все подробнее!"] = "c8b7cc29723f78c9a33d40dd94b43a31",
		["Куда вы хотите направиться?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
		["Где аукционный дом? Как же, он сразу за Вратами Стальгорна, как войдешь в наш славный город. Это напротив хранилища."] = "d6e64cdc436665776809311fd999e5cd",
		["У тебя есть сокровища, которые ты хочешь надежно сохранить? Тогда тебе нужно в банк, к Каменной Мантии.\n\nБанк находится на расстоянии броска молота от ворот Стальгорна."] = "d3430aba4fb0b400b8dca87cf1df8b15",
		["Ну да, все хотят покататься на поезде, это тебе не ерунда какая-нибудь. Значит, так: поезд отходит из Города Механиков, от Врат Стальгорна прямо на восток."] = "e151e5a6629ea4a4c716bafbf9cf9641",
		["Ищите, где бы полетать на грифоне, не так ли? Попробуйте обратиться к Гриту Турдену. \n\nЕго можно найти в центре Стальгорна, к востоку от Великой Кузни."] = "818c80ba62a6062182774f0d488d44b8",
		["Если ты подумываешь о создании своей гильдии, то тебе нужно поговорить с Иондором Стальным Лбом в Гостевых покоях Стальгорна. Направляйся на юго-восток от Врат Стальгорна – и увидишь его."] = "67bc72e3f75682dc138f1d22ef089d92",
		["Трактир? А, так ты хочешь отведать лучшего эля в Стальгорне? Ну, тогда тебе надо в \"Горючий камень\".$B$BЕсли идти из ворот Стальгорна, он будет слева, а если к воротам – справа."] = "886fa9ce5bf2e50d6df39dca00c5e72c",
		["Почтовый ящик прямехонько у таверны Горючего Камня. Это чуть севернее Врат Стальгорна."] = "164f8858641d9fa2782d051756979421",
		["Забота о животных – то, в чем Ульбрек Огненная Длань знает толк. Обычно он водит компанию с охотниками в Оружейной. Если хочешь доверить ему своего питомца, там его и ищи."] = "02f503b66aaa06ff7cf2372c215ba1f0",
		["Бикси и Бульвайф убивают орков всеми известными видами оружия. Если хочешь взять у них пару уроков, загляни в оружейню Лесной Границы."] = "96990add552d311d4fe9f5b1e0e496d4",
		["Ага, и на какое поле боя вы собирались?"] = "495cb758f46f91069a540dc47968d5b3",
		["Для какого класса тебе нужен учитель?"] = "dcadd0f33e63218ef70a191c145117f6",
		["Какой профессии ты хочешь учиться?"] = "cf38911600ac02c04cb72aafa6596e66",
		["Итак, $gпарнишка:девочка;, ты считаешь, что можешь сражаться во славу Альянса в Альтеракской долине? Что ж, хорошо. Тогда отправляйся в Стальгорн и поговори с Глордрумом Сталебородом. Скорее всего, он будет сидеть в Оружейной и разрабатывать очередной план наступления."] = "f0b32b90ead935933c43bb1468fa3f95",
		["Людям нужна ваша помощь в бою с Отрекшимися в Низине Арати. Ступайте в Оружейную и поговорите с их представителем Доналом Осгудом."] = "a551a630e051c403297c7c5b9ebba84b",
		["Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной."] = "65538115404a72c45137bf80f3f5572c",
		["Недавно я случайно услышал, как Регнус Громовой Гранит в Оружейной хвастался новой добычей для его клетки. Если ты ищешь умелого охотника, способного обучить тебя, то Регнус – тот, кто тебе нужен."] = "d93d0f3b1e5ea15a5dd989a27017ef56",
		["Думаю, Бинк – наша крошка-чаровница из Зала Тайн – помогла бы тебе справиться с любым магическим делом.\n\nЗал Таинств находится к северу от Врат Стальгорна."] = "8d292d1b067d993333147a509e6e409c",
		["Кто вам нужен, так это Брандар Железный Молот. Его можно найти в Зале Тайн к северу от Врат Стальгорна."] = "31c78e407d6e78277f84d7122edc2533",
		["Браэнна Кремнескал поистине творит чудеса. По всем жреческим делам надо обращаться именно к ней. \n\nИди на север от Врат Стальгорна к Залу Тайн. Там ты ее и найдешь."] = "59e9a008fc9fe41cf912bf06861683df",
		["А с чего бы это ты интересуешься этими типами? Мало нам Хальфдана Черноборода из Заброшенного грота – так теперь еще и за тобой приглядывать?"] = "36ac17a15ff106629b6c52dbefcd7203",
		["Такими мрачными делами у нас занимаются только в Заброшенном гроте, самой заброшенной части Стальгорна. Недотрогинс обычно там и сидит – призывает всяких жутких тварей и командует ими."] = "205d885c660f13d010f41ecd69423cc6",
		["Ой! Вы что, хотите изучать воинское искусство, да? Кельструм Камнелом вас всему научит! Ступайте в Оружейную, это к востоку от Врат Стальгорна."] = "740a72f70d8805a7b803e0d29dbe0d05",
		["Интересуешься алхимией? А я как раз возвращаюсь от ее учителя. Мисс Гонобобельзз живет в Городе Механиков – там, где собираются гномы."] = "76c8e36d99bf968b0318157d711f4ce3",
		["Ты $gпришел:пришла; по адресу, $gпарень:девушка;! Сюда приезжают учиться кузнецы со всех концов света! Бенгус Подземная Кузня лупит по своей наковальне прямо посреди нашего славного города, у самой Великой Кузни."] = "2ffc912f1ac294a9f6bb188522b88c70",
		["Учитель кулинарии? Ну, это тебе в \"Бронзовый котелок\", на северо-восток от Великой Кузни. Дарил Рикнуссун научит тебя готовить вкусные и здоровые блюда!"] = "f62abc611ce83aa205cd0e2b5918cc10",
		["Ну, думаю, Гимбл Чертополуш – именно тот, кто тебе нужен. Зачаровывать он умеет… Ты найдешь Гимбла в его лавке \"Колдовские штучки Чертополуша\", возле Великой Кузни, справа от укротителя грифонов."] = "6e1942115134fa4728a8bd01469f0ee2",
		["Тебе нужно снаряжение механика? Тогда тебе точно надо повидаться с Пружиннером Шумотором в Городе Механиков.\n\nИди от Врат Стальгорна на восток – или на грохот взрывов."] = "6edc9f2da8079aff91202f55fb3e3dc7",
		["Первая помощь – ценный навык. Наша постоянная учительница, Нисса Огневик, может показать тебе, как это делать. Ищи ее на южной стороне Великой Кузни среди целителей Стальгорна."] = "aa54bc8510198f4330f29e9a0b3eae00",
		["Мрачнур Каменное Клеймо будет тебе заливать, что он уже старый и все забыл, но ты его не слушай: он рыбак первейший. У него есть лавка в Заброшенном гроте, называется \"Странствующий рыбак\"."] = "0ddcbbb7af1ef15099416e16690edff4",
		["Цветы, семена и все такое? За этим – к Рейне Каменной Ветви. Она возится со своими травами возле лавки целителя к югу от Великой Кузни."] = "9341074330c1dbc19f8fdf714badbebf",
		["У Фимбла Остроигла магазин в северо-западной части Великой Кузни. Держу пари, он может показать тебе, как делать хорошую броню."] = "e6b5bccb2a9112e11e11306a28cbcb09",
		["Есть ли у нас учителя горного дела? А ты $gсам:сама;-то как думаешь?!\n\nВ нашей гильдии рудокопов Темной Горы собрались лучшие горняки Дун Морога! Это к северу от Великой Кузни. Спроси там Геофрама Твердопала – он тебя всему научит."] = "75e0a88cc8fcf68c42a9c9a4f31ea193",
		["По поводу снятия шкур обращайся к Балтусу Шлифовальщику. Уж он-то с кого угодно шкуру снимет… Найти его можно в кожевенной лавке Остроигла к северу от Великой Кузни."] = "19d7a62aa644748c5d13eaad7341a221",
		["Джормунд Камнелоб – настоящий виртуоз кройки и шитья! Его лавка одежды находится к северу от Великой Кузни."] = "759b920689d00afab4a880a03c8bd208",
	},
	["Весприст"] = {
		["Наши гиппогрифы постоянно летают между деревней Рут'теран и Темным Берегом, поддерживая связь с материком."] = "1159084dc6a505d44935a66ab899c095",
	},
	["Вестник Утеса Быстрое Копыто"] = {
		["Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов."] = "ed86d1f63d2d45272ce63c2046fb4084",
	},
	["Визглик"] = {
		["Если вы интересуетесь портняжным делом, в лавке Визглика найдется много интересного для вас. Посмотрите товары, $n, и дайте мне знать, если захотите что-нибудь приобрести!"] = "910ba4b855e200d5675b3e6eabb50a83",
		["Собирай вещички, $n! Нилита Локрав сообщила мне, что Черный рынок что-то замышляет в самом сердце Котлована. Найди Нилиту в Тлеющем Ущелье – и будь $gосторожен:осторожна;!"] = "9b4127810f51260020b2c2688447edd5",
	},
	["Виктор Уорд"] = {
		["У нас здесь немного посетителей. Я могу заинтересовать тебя чем-нибудь?"] = "5d1d54fe06f83ab0d94d3657a2656351",
		["Я и сам всего лишь новичок. Вот у Рианнон есть чему поучиться. Она стоит рядом с ящиками."] = "b3ce892e3e9d7520713df2a64935ea72",
		["Да, вроде талант у вас есть. Пожалуй, научу вас кое-чему."] = "667d01f5431aa66becfa107bd97d1b6b",
	},
	["Виллиден Маршал"] = {
		["Приветствую тебя, $gнезнакомец:незнакомка;, и добро пожаловать в величественный Кратер Ун'Горо!$B$BМеня зовут Виллиден Маршал. Мы с моей сестрой и нашими спутниками составляем экспедицию Маршала – сообщество ученых, исследующих великие тайны диких земель Азерота.$B$BУ нас тут некоторые неприятности, и было бы здорово, если бы ты $gсогласился:согласилась; нам помочь!"] = "e0280ea403de38a99d9f00704dc83cf8",
	},
	["Вильгельм Штранг"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "0644f6eb50bbf423901c39cf0e35e268",
	},
	["Вильям Кайлар"] = {
		["Не беспокойся… пусть мои грифоны не совсем живы, они с радостью отнесут тебя в нужное тебе место. Скажи, какая башня тебе нужна?"] = "8c3e5d1b67a507ae3bf5d583b20cea89",
	},
	["Винчакса"] = {
		["Позади меня находится алтарь Занзы, святыня Зандалара. Здесь мы молимся об укреплении нашей решимости в борьбе с кровавым богом Хаккаром.$B$BДокажите, что вы друг нашего племени – уничтожьте на алтаре все брелоки Хаккари, которые найдете в Зул'Гурубе. Кстати, зул'гурубские монеты я могу обменять на почетные знаки нашего народа. Приносите их мне!"] = "146cded4f6f6a9fde55acea952be56eb",
	},
	["Вира Нежное Копыто"] = {
		["Теперь лишь известный доктор Грегори Виктор может помочь тебе отточить твои навыки. Его можно найти на Нагорье Арати в Павшем Молоте."] = "f8ec6bcdb5cf9af5f0aab1297a7dd947",
		["Бала Лок'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!"] = "ae13783d5fa12defb8f6b3abb812bdf9",
		["Я могу научить тебя оказывать первую помощь."] = "38e95494bef2a4dc003afca7cad45853",
	},
	["Виш Коцус"] = {
		["Наш командир последнее время сам не свой. Его любимая поехала в археологическую экспедицию в южную пустыню – и там исчезла без следа! Очень странная история.$B$BА ты, небось, работу ищешь? Тебя огреть по голове, или ты сам намек понял?"] = "b60ac134e16be202debcce1733994a3f",
		["Охотишься на Смертехвата, $n? Впечатляет. Эта тварь у меня за неделю уже двоих сожрала. Будем надеяться, тебе повезет больше."] = "a8ee595039d5f688ef88300a94ae9a8a",
	},
	["Властитель Рунтак"] = {
		["Посмотри на врага повнимательнее, $r. Видишь, во что мощь Орды превратила могущественнейшего из драконов? Так будет с каждым, кто встанет у нас на пути!"] = "e84dc958c4a38bb68b73f260ddc8edec",
		["Я готов выполнить любой приказ Вождя. Я воин Орды."] = "9f1fc0f188303aa506b43d5e4203e697",
	},
	["Воевода Лаггронд"] = {
		["Я отвечаю за вербовку новобранцев в клан Северного Волка. Будучи бойцом клана, ты $gдолжен:должна; докладывать мне о каждом своем повышении в звании.$B$BНа этих мерзлых полях тебя ждут честь и слава!"] = "ce047d2a3dd6d9e301b393ee2954c796",
	},
	["Военный глашатай Горлач"] = {
		["Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов."] = "cef7b238bc3c92479b26bc56a061585a",
	},
	["Воитель из ордена Серебряного Рассвета"] = {
		["Битва выиграна. Угроза Плети устранена – на время. Мы можем направить свои ресурсы в помощь тебе, в благодарность и для подготовки к грядущему."] = "4b36cae8ffab10bd243caafa37fd7ebd",
		["Битва протекает неплохо. Силы Плети кажутся ослабевшими. Я уверен, изгнание их с наших берегов – лишь дело времени. Я направлю свою магию в вашу сторону, чтобы помочь вам в этой борьбе."] = "fdaab9e2b8a9ef75ee889a83109b9758",
		["Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет вас к дальнейшим победам."] = "b4933008c7c76fbea261d6b6ba7192ca",
	},
	["Волкор"] = {
		["*Волкор вовсе не смотрит на вас, пока вы приближаетесь к нему. Похоже, что он сосредоточен на том, чтобы не дать свалиться своим бинтам. Через секунду он смотрит на вас немного удивленно.*$B$BОй, извини, $c. Сейчас неудачное время. Надеюсь, ты понимаешь."] = "7ca86bd3e09f6043007de96fec4773a6",
		["Что ж, $n, судя по всему, у нас есть только два способа покинуть эту пещеру.$B$BЛибо мы выберемся незаметно – я воспользуюсь тем плащом, что ты мне $gдал:дала;, а ты – своими собственными средствами. Либо, что, учитывая мои раны, будет гораздо сложнее, мы проложим себе дорогу, сражаясь спиной к спине.$B$BРешать тебе, ведь ты лучше меня знаешь свои сильные стороны."] = "2cb42068ee7ca52b04d1b1033e275953",
	},
	["Волхв Тирт"] = {
		["Будьте осмотрительны, $c. Я уже подготовил заклинание превращения на ваше имя…"] = "580054d04eb523be430e4750bc42907f",
	},
	["Восур Брактел"] = {
		["Пусть эти большие невинные глаза тебя не обманывают. Талли свое дело знает – я каждый день чему-то новому учусь. С чего я, по-твоему, в Город Механиков подался? Я что, похож на инженера? Вот и я думаю, что нет."] = "32a5626d8140ad954652c141442fc86c",
		["Выкладывайся полностью, $gпарень:девушка;. Терпение и труд все перетрут! И не верь тем, кто говорит, что любое дело можно выучить по книгам!"] = "94877755c9cc3beb33d35c6e3279a7f0",
		["Ох, а мне и нечему больше вас учить, $n. Поговорите с Талли Гонобобельзз, она вон там. Едва достает до стола, но как начнет мешать зелья – тут только держись!"] = "39ebd1b988bad54e8ab04456d49fb6c9",
	},
	["Врена Темнопружник"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "e152d80f8a65a632eb862a6df3b5bc91",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "ba8b5b409d8e88979163e3833b3ca8f7",
	},
	["Ву Пинг"] = {
		["Вы пришли потренироваться в умении доспешного боя?"] = "da8269ec529338fb71da4bda52aa2d08",
		["В оружейной лавке Лесной Границы, что в Стальгорне, ты найдешь дворфа Бульвайфа. Он научит тебя управляться с кистевым, ударным и огнестрельным оружием, а также со всевозможными топорами.\n\nВ той же лавке ты можешь встретиться с гномкой Бикси Пошатушкой, экспертом по оружию. Она покажет тебе, как пользоваться арбалетами, кинжалами и метательным оружием.\n\nНочную эльфийку Илиению Лунное Пламя ты найдешь на Террасе Воинов в Дарнассе. Она покажет тебе, как пользоваться луками, кинжалами, кистевым оружием, посохами и метательным оружием."] = "0cf4036d40658806b00933ae705fa922",
	},
	["Ву Шен"] = {
		["Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком."] = "0a37426688f72de523d491b07d11f473",
		["Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…"] = "8493fe09c36205db0684a4321f2d5dcf",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Вульгра"] = {
		["Куда бы вы хотели слетать?"] = "0edd3c73540d735f036ac6e027466523",
	},
	["Вуут"] = {
		["Во всех этих бутылочках зелья, которые я сварил сегодня. А говорят еще, что если на горшок смотреть, он никогда не закипит! Ха!"] = "3acb15be9a5e8a5571335dcfcf05d155",
		["Меня обзывали дураком, но я им всем покажу! Буду присматривать за всеми котлами и докажу, что все годятся для варки. Да, я теперь в ударе! И кто из нас дурак, а? А?!"] = "5aeba2ee94183ab7088af2ae15c03a01",
		["Ничем не могу помочь. Ты знаешь о зельях больше меня. А мне еще за горшками следить надо. Поговори с Йелмаком. Он о зельях многое знает."] = "a6fce2f8c4b47202a170ae54b00fdde8",
	},
	["Вхан"] = {
		["Ни одна часть убитых нами животных не пропадает даром."] = "9a3119143d987293762c854224943bc0",
		["Тебе нужен кто-то более сведущий. Например, Тепа. Она как раз должна быть где-то поблизости…"] = "8ad7eccb4b49cd7d5405cd10a2652680",
		["Начнем, и да благославит нас Мать-Земля."] = "a25b3302ffe572a2b66ceb81dc6c8089",
	},
	["Габана Меднокноп"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "f9f9e7611322bf1ddbc11a3d206fbee1",
		["Сейчас бы каштанов пожарить… Ммм!"] = "ec96335ecef05c3900dab2def0ea7d06",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "871ad3477a3322d9a312056c078ef843",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "8d77629139cb2841d86e8e3ea861bc05",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "6d2f68e829351e067178b3f036cd5d75",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "4a32fbea4eafa7cc8a55a50a91ae41de",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "f328cb6cd509244010ffea357d309bfc",
		["Сезонные скидки для вас и вашей семьи!"] = "06446c93717ee24cf71146c8844d5209",
	},
	["Гакин Темнопряд"] = {
		["Да, $c?"] = "81a3bc97669edf115176b3a8458cf81a",
	},
	["Ганн Каменное Копье"] = {
		["Я один иду этой дорогой в поисках способов защитить свою честь и избавить эту землю от наших врагов. $b$b Что я могу сделать для вас, $N?"] = "8f91f2acecd0ce7ec9e9398bfec0d760",
		["Да, я видел шаманку, которую ты ищещь. В последний раз я встречал ее на западе. Она скрылась в холмах, где обитает племя Иглогривых. Если у тебя хватит ума, ты сможешь найти дорогу к ее хижине. Это не очень далеко, к северу отсюда. На этой дороге тебе даже не придется драться с иглогривами."] = "352919ecdb6b9b239ce6b40f838cf528",
	},
	["Гарел Красногор"] = {
		["Здравствуй, $c. Не тебя ли я недавно видел на одном собрании? Лицо вроде знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду."] = "c5afae87abc614718a9d01193dc59430",
	},
	["Гарольд Риггс"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "13d2af5f294a07ae2cff1bf240fa32c1",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "43ebea4a5129c29af35af2064eb93951",
		["Могу научить тебя ловить рыбу."] = "b285645e1bdb1be37d7bfdc440534eec",
	},
	["Гарон Хатчинс"] = {
		["А, так это ты $gнашел:нашла; письмо. Спасибо за… Видимо, за новости о моей семье. Прошу тебя, раздели мой скромный стол."] = "db0fd82a2e87168de7f37ba74147a476",
		["Будь осторожнее в пустыне, $c."] = "ba66fca13d25f11aec60b7a40abc3055",
	},
	["Гарт Вестник Туманов"] = {
		["$n, чему еще я могу тебя научить, во имя Матери-Земли?"] = "f316fce98de9499e71406388009e60c4",
		["Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, $c."] = "b6f4bdc2a8d3684c359c1880591a1f0c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Гаэриан"] = {
		["Прошу вас, оставьте старого духа в покое…"] = "75c7653932086fa3c6eb2d294f26bd7a",
		["Меня редко кто ищет… Что я могу сделать для вас?"] = "dddedefbebc656d4bd061f2f18065149",
	},
	["Гед"] = {
		["Имей в виду, $gкрасавчик:принцесса;, сейчас у меня нет времени на твои шуточки. Я слежу за тем, чтобы исследования верховного друида проходили по плану. Мне приказано избавляться от любых посторонних, если только они не хотят присоединиться к моему славному Кругу Кенария."] = "8e2b442664f11c1d603c1dbdef886718",
	},
	["Гелвас Углешлюз"] = {
		["Выдача призов! Меняйте купоны на призы! Подходим, подходим!"] = "41e1418f674fe4ab79111719d0059787",
	},
	["Гельман Камнерук"] = {
		["Я из Стальгорна, помогаю здесь с ремонтом. Но если я смогу передать тебе свои знания, то, может быть, оставлю дело на тебя и вернусь домой."] = "ecfb26a965f871793f254dd052d3a1af",
		["М-да? Ты меня $gперебил:перебила; – надеюсь, у тебя была уважительная на то причина."] = "7baf64adcb2bac12353e20b721380581",
	},
	["Генерал Зог"] = {
		["Лок'тар, $r. Я – генерал Зог, посол Орды. Здесь я слежу за тем, как великая Орда собирает припасы для войны в Ан'Кираже. Что вы хотели спросить у меня?"] = "d2747cbf9e92ad97f5c16f908b596c77",
		["Как это ни странно, но у вас тоже может быть порядок. И Альянс, и Орда уже закончили все приготовления к ан'киражской войне. В данный момент припасы доставляются в Силитус. Не пройдет и $2113w дней, как они будут там. Потом кому-нибудь придется собрать скипетр Зыбучих песков и ударить им в гонг на помосте Скарабея. Тогда ворота Ан'Киража распахнутся – и начнется настоящая война!"] = "558293036bc20ba9ec357e7955395f89",
		["Мы заодно с Альянсом, $r. Зло, столь древнее, что мир позабыл о нем, стремится поглотить нас всех – сначала Калимдор, а затем и весь остальной Азерот. Им движет ненависть ко всем творениям великих Творцов: Титанов Вечности.$B$BМы все стоим на пути войск К'Туна. Мы ударим первыми и сломим силы Ан'Киража. Пусть Азерот дрожит от объединенной мощи Орды и Альянса.$B$BТы $gнужен:нужна; фронту!"] = "867569b880563887beb157cd19a1f51b",
		["Сколько слитков, говоришь? Вот что мне известно по последним сводкам Орды. Медные слитки – $2018w из $1998w, оловянные – $2005w из $2006w, мифриловые – $2009w из $2008w."] = "8caa274c49387b4edd0ba33ed966f6b7",
		["По последним данным, у Орды есть: мироцвет – $2021w из $2020w, огнецвет – $2050w из $2051w, пурпурный лотос – $2054w из $2055w."] = "c87aec42c0c1d25bbb47559200796d1d",
		["Сбор кожи? Да, я как раз получил кое-какие сведения. Тяжелая кожа – $2066w из $2067w, плотная кожа – $2070w из $2071w и, наконец, прочная кожа – $2073w из $2074w."] = "6fc4d0924029489ffd0a60e0ee958c21",
		["Орде нужно много бинтов. У нас уже есть $2079w из $2080w шерстяных бинтов, $2085w из $2086w волшебных бинтов и $2089w из $2090w бинтов из рунной ткани."] = "a262f229e20203f5b92f45814fe50213",
		["Ты хочешь узнать насчет продовольствия? Ладно. По последним данным запасы Орды таковы: постные стейки из волчатины – $2095w из $2096w, пятнистый желтохвост – $2102w из $2103w, запеченный лосось – $2105w из $2106w."] = "c2a83d587c94ee4ec39e5ad2da461816",
	},
	["Генерал-лейтенант Андоров"] = {
		["*Андоров мрачно смотрит на вас.>$B$BЕсли у него течет кровь, значит, его можно убить."] = "cbb32bb2891d6e835c05709df5717dc5",
	},
	["Генния Рунический Тотем"] = {
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Генри Штерн"] = {
		["Спасибо, что $gспас:спасла; меня!$B$BЯ повар и алхимик из Штормграда. Я здесь искал местные травы и собирал рецепты для дяди Ангуса, когда меня похитили эти иглогривы. Если бы не ты, я бы, несомненно, окончил жизнь в качестве их ужина."] = "f252a63ef02f49f36892505401561fee",
		["Хм… да, у меня есть рецепт, который может вам пригодиться. Позвольте мне обучить вас!"] = "9a1a67bf16978dd21ee48e13a42ce8c5",
		["Ты пока не слишком хорошо готовишь. Подучись еще немного, а потом приходи ко мне."] = "59c157459d6c37182d6e0335633c83ea",
		["Да, я знаю один редкий алхимический рецепт. Могу поделиться!"] = "8bd69da5c8875db363f8ca049bf10cf2",
		["Ваши познания в алхимии еще недостаточно глубоки для того, чтобы учиться у меня. Приходите как-нибудь потом…"] = "7927759d8b72b02485457ac0d2c022e0",
	},
	["Генрих Стоун"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "0644f6eb50bbf423901c39cf0e35e268",
	},
	["Георгия"] = {
		["Куда бы вы хотели слетать?"] = "99afa7bbff40b3ecca37eb15b8c29387",
	},
	["Герик Коэн"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "0644f6eb50bbf423901c39cf0e35e268",
	},
	["Гест"] = {
		["Изувеченная Длань увидит Орду во всей былой славе, когда ее перестанет сдерживать робость Вождя."] = "5070548a9c45a19ece573bb4b49296f4",
		["$C – это не ко мне."] = "60044d7f82718835ed805cb5fdc7067b",
		["У меня есть кое-что для тебя, $n. Кажется, это важно."] = "be71e303387ffea0be60a35c3c78e8d3",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Гилл"] = {
		["Самые быстрые грифоны по эту сторону Заоблачного Пика. Хотите прокатиться?"] = "9a496e2e710165d755663d0d9ae15ef8",
	},
	["Гимбл Чертополуш"] = {
		["Кто ты? Что ты от меня хочешь?"] = "8632fa71e51a2117b8aea60d681a69cd",
		["Я что, похож на величайшего зачаровывателя всех времен и народов? Обучением таких, как ты, должен заниматься профессионал! Разыщи Китту Огневетер в башне Азоры."] = "87fbe434423bc54374ebb83d5f1e1cd4",
		["Ты шутишь, не так ли? Полагаю, тебе нужен ДРУГОЙ коротышка, Тонис Пилон. Он внизу. А теперь дуй отсюда!"] = "b10770dd7a0519306cbaf4e55d6acf9f",
		["Ну, неплохо… Хотя могло быть и лучше. Ладно, раз ты $gдоказал:доказала; свое мастерство, можно начинать!"] = "6060b8c4b3447bc4bc2a3a4970d592bb",
	},
	["Гимризз Которышка"] = {
		["Чары развращают лишь тех, кто слаб духом. Не прекращай работать над собой, если не хочешь, чтобы тебя постигла такая участь."] = "073492d1b775dad17b73e4495accc8b7",
		["Тьма не примет тебя, $c. Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!"] = "b18ac3abb515a9b18a91daf4c6f17c2e",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Гин Денбург"] = {
		["Более совершенного, технологичного, удобного средства передвижения ни за какие деньги не построить. Что? Подземный поезд? Гномы? Слушай, приятель, если ты веришь в эту чушь, то у меня на продажу есть статуя в Тернистой долине. А теперь решай, ты идешь пешком в Гром'гол или собираешься воспользоваться прекрасной, стильной летательной машиной? Тебе выбирать."] = "e3996fa2197a021a95b58d4b134537dd",
	},
	["Главный сержант Гримсфорд"] = {
		["Мы все сделали, $gпарень:девушка;! Альянс и Орда собрали все, что сочли нужным, для войны в Ан'Кираже. Прямо сейчас припасы везут в Силитус. Не пройдет и $2113w дней, как последняя партия будет в Крепости Кенария. После этого $gнекий храбрый герой:некая храбрая героиня; ударит скипетром Зыбучих песков в гонг Скарабея, чтобы открыть ворота Ан'Киража. Вот тогда-то война и начнется!"] = "ed6188bded57a0cd48b72762e07b5202",
		["Здравия желаю, $c. Уверен, вы здесь, чтобы спросить о подготовке к войне в Ан'Кираже. Так вот, нам понадобится серьезная помощь. $b$bОрда и Альянс предпринимают совместные усилия по подготовке к надвигающейся войне против силитидов и их хозяев в Ан'Кираж. В Оргриммаре, в Аллее Духов, мы собираем огромное количество различных товаров для формирования военных припасов, и как раз в сборе нам и понадобится ваша помощь.$b$bМогу ли я предложить вам переговорить с нашим командующим о помощи?"] = "f54d2505d254f8e348f3bd182ed879e7",
	},
	["Главный сержант Кай'джин"] = {
		["Здравия желаю, $c. Уверен, вы здесь, чтобы спросить о подготовке к войне в Ан'Кираже. Так вот, нам понадобится серьезная помощь. $b$bОрда и Альянс предпринимают совместные усилия по подготовке к надвигающейся войне против силитидов и их хозяев в Ан'Кираж. В Оргриммаре, в Аллее Духов, мы собираем огромное количество различных товаров для формирования военных припасов, и как раз в сборе нам и понадобится ваша помощь.$b$bМогу ли я предложить вам переговорить с нашим командующим о помощи?"] = "17bbc17d735f1204b639e93017b4f12d",
	},
	["Главный сержант Тайга"] = {
		["Здравия желаю, $c. Уверен, вы здесь, чтобы спросить о подготовке к войне в Ан'Кираже. Так вот, нам понадобится серьезная помощь. $b$bОрда и Альянс предпринимают совместные усилия по подготовке к надвигающейся войне против силитидов и их хозяев в Ан'Кираж. В Оргриммаре, в Аллее Духов, мы собираем огромное количество различных товаров для формирования военных припасов, и как раз в сборе нам и понадобится ваша помощь.$b$bМогу ли я предложить вам переговорить с нашим командующим о помощи?"] = "228c7995c13842a05cb0db6e14827e56",
	},
	["Глашатай Гудман"] = {
		["Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов."] = "b8290ddda0b05b868413d4053a016622",
	},
	["Глашатай Лунопарда"] = {
		["Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов."] = "3725afd9871a58ee99a7d026e3563aeb",
	},
	["Глордрум Сталебород"] = {
		["$n, понимаешь ли ты, кто противостоит нам в Альтеракской долине? Ты $gготов:готова; сражаться против клана Северного Волка?"] = "fe70eb05a6a384f2150bdbcaad041ebd",
	},
	["Гнев'рел"] = {
		["Наш вождь Рок'рел услышал этот вызов."] = "a372bc64e7ea57b0c42f74c9c3cd93a4",
	},
	["Гном-инженер"] = {
		["Мой технологический альманахотрон говорит, что мы выиграем у гоблинов на двадцать секунд больше, чем в прошлый раз!"] = "29cb9f241b67a6bd58f46757f27f6f9e",
		["Да мой сын может собрать машину лучше, чем рухлядь этого гоблина!"] = "5a9bf6255acd34e980aebcd04a7a6def",
		["Я усовершенствовал матричный регулометр нашей машины. Теперь ее скорость должна возрасти как минимум в пятнадцать раз!"] = "bb2e2ac84fdaea93b4cb5f24ace4d539",
		["\"Смелый\"? Я думаю, что распорядитель гонок Гореездник наверху, в башне, знает, где он."] = "288dfdbe6b0b08a6f2781e22dc5d8ce0",
		["Эти гонки дают отличную возможность продемонстрировать нашу изобретательность!"] = "88d6d4700d0a9435deac731bbef17f8c",
		["Джонсон? Я думаю, он где-то здесь…"] = "5d227c61a514e3f0b41f912efe022c52",
		["Правду говорят: дуракам везет, иначе эти гоблины разбивали бы свои машины в каждой гонке!"] = "413ec8412f752d13ea7d3bc09e39592d",
		["Тирт в последнее время сам не свой, и его помощник тоже."] = "329639fd7e8c50ac0b798afe6c0f563e",
	},
	["Гнус'рел"] = {
		["Наш вождь Рок'рел услышал этот вызов."] = "a372bc64e7ea57b0c42f74c9c3cd93a4",
	},
	["Гоблин-автомеханик"] = {
		["Говорят, они собираются взорвать машину гномов в следующей гонке! Правда это или нет, но я буду держаться подальше от их боксов."] = "0c2296859db21b24eb9910aa4b0c2053",
		["Мои деньги у гоблинов! И если ты хоть что-нибудь соображаешь, то и твои должны быть там же!"] = "8a6ae51d27ab952a233cd6f757870376",
		["Я бы на твоем месте поставил на гоблинов. Болеть за любую другую команду – пустая трата времени."] = "84067fc993444ce72a27b52f4f74bec4",
		["Ищешь \"Отчаянного\"? Ладно, я тебе этого не говорил, но… расспроси Кронкрайдера в башне, он тебе расскажет…"] = "6ca0e5f286f5115ccba86010cc9d19a7",
		["Если бы не это треклятое гномское везение, они бы ни одной гонки не выиграли!"] = "1707d93334e41f8adae340c8be1bc91a",
		["Ха! Тирт уже который день его ищешь, но он все прячется, трус!"] = "4cf39f0b48e67e4fb4e5d3538ae49f07",
		["Что касается меня, я считаю гоблинов фаворитами. У нас есть и оборудование, и талант!"] = "ef38b09c14f46b5a8dcf5d782c630fd6",
		["А, вы имеете в виду Джонсона? Говорят, он сейчас в бегах."] = "38a01b6277bccedcf3bd8f0506a44706",
	},
	["Годан"] = {
		["Некоторые думают, что зачаровывание – бесполезное баловство. Однако после дуэли со мной они быстро меняют свое мнение!"] = "3c96e38d8275bcb879a7e7eb43dca519",
		["Твои навыки вне моей компетенции, $gнезнакомец:незнакомка;. Обратись к Хгарту в Приюте у Солнечного Камня в Когтистых горах. Его знания превосходят мои."] = "b763ebb2808596a973203acbe4b2c81b",
		["$n, вы еще недостаточно опытны, чтобы учиться у меня. Позанимайтесь сначала с моим помощником Джагом, вон он."] = "e5af5d1c3def492a1f23240e2763be98",
		["Отлично! Я вижу блеск в твоих глазах. Мне он хорошо знаком, мои глаза так же блестели, когда я был молод! А теперь посмотрим, смогу ли я тебя чему-нибудь научить."] = "0535431e80accd3492c256c1ceb98fe1",
	},
	["Голнир Твердопал"] = {
		["Нет лучше профессии, чем горняк. И нет лучше горняков, чем дворфы!"] = "77ab7ea3aff9f5b83ed9f444750c2f64",
	},
	["Голодный завсегдатай"] = {
		["Через час у меня служба, но до того… гори все огнем!"] = "e5940ea614a92eb97e63caf9aa1b863e",
		["Ты когда-нибудь $gпробовал:пробовала; громоварское светлое? Отличная штука!"] = "591c33205f87d8b8a04f0848826ff374",
		["Мой отец говорил, что настанет день, подобный сегодняшнему, когда $gнезнакомец:незнакомка; заговорит со мной, и я должен буду сдержаться, чтобы не убить $gего:ее;."] = "68be82e6e85048cb5a920f993ea55b98",
		["Сплошные выстрелы и пламя, а потом кто-то проигрывает и умирает."] = "abf0280c9a560d25936f42186fd8a258",
	},
	["Голхайн-в-капюшоне"] = {
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого."] = "95baad8c0ee127ac815bdd480620f4f4",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Гонец клана Песни Войны"] = {
		["Да, $c? Ты $gприбыл:прибыла; на службу?"] = "ecb5c5765055132283e8f669c19aa1d7",
	},
	["Горбольд Сталерук"] = {
		["Здравствуй, $gпарень:девушка;, если ты ищешь лучшие цены во всем Стальгорне, ты $gпришел:пришла; по адресу."] = "30788884689c5bb0102e781a007f9ad6",
	},
	["Гордон Уиндем"] = {
		["Приветствую – и добро пожаловать. У меня не очень-то выходит улыбаться, но поверьте, я счастлив вам служить."] = "f036f024de84a7992c236bf86b742eab",
	},
	["Горзиеки Дикоглаз"] = {
		["У тебя есть пауки или жуки, $c? Они твари быстрые, но если ты быстрее – не упускай шанс!"] = "767f180e80a535e7f390f3d311039337",
	},
	["Горкас"] = {
		["Я буду здесь, пока не поймаю во-о-от такого окуня! А ты уже хочешь куда-то сорваться, верно?"] = "618fd179dc62675047c361ba163020cb",
		["Чем могу быть полезен, $c?"] = "8954aa5e093a20511ce5bc5c69380aac",
		["Ты $gраспугал:распугала; всю рыбу! Чего тебе надо?"] = "fdcd1e64bf065be3a6c23042d93a5b68",
		["Ты не видишь – я здесь рыбачу!"] = "6d360eae76ce9d8dd443dda348dde45e",
	},
	["Горнек"] = {
		["Пройдя долину Испытаний, любой слабак превращается в воина, достойного служить Орде… или навсегда остается лежать под палящим солнцем пустыни."] = "bf70aae4154725dec8a65fa84ba0d954",
	},
	["Горный пехотинец Кэдрелл"] = {
		["Здравствуй, $n. Добро пожаловать в Телcамар. И раз уж ты здесь, обзательно посети местную пивоварню!"] = "185744ecb6ab01130a75f717debfc573",
		["Добро пожаловать в Телcамар – ваш дом на озере Лок Модан!$B$BТелcамар – прекрасное место, и те, кто ценит доблесть, найдут здесь не только отличное пиво и вкусное мясо! Если вы желаете послужить Альянсу, прочитайте плакат на стене Телcамарского отделения Лиги исследователей."] = "84a74f16eb6fad3d9b9ac64cef383cac",
	},
	["Горный пехотинец Стальгорна"] = {
		["Ближайший банк у нас в Стальгорне."] = "83965dbeffe98cceda0d3e3dbf0734c2",
		["Укротитель грифонов живет в Стальгорне возле Великой Кузни. Так что если хочешь куда-нибудь слетать, ступай в Стальгорн."] = "c32efb4b50768d9afd75e50dc0393a88",
		["Ежели тебе нужны какие-то гильдейские бумаги, ступай в Стальгорн и загляни в тамошние Гостевые покои."] = "395a422b3eb1d579d18416f0b5ef4bff",
		["Таверна, говоришь? Лучше всего, конечно, \"Громоварка\". Там и просто отдохнуть можно, но я тебе советую пропустить пару кружек местного эля."] = "e66a69d239e7c3f1206d7f638c44bec1",
		["У Шелби Щебенки полно всякого зверья. Ее можно найти в \"Громоварке\". Если что, она и за вашим питомцем присмотрит."] = "5011b7376cf9fbdf9a91842132fba2e6",
		["По мне, так Гриф слишком много возится со всяким зверьем. Однако охотник он хоть куда, уж в этом ему не откажешь. Поищите его около кузницы в Караносе."] = "5d54f11c82628de5397e4af70d935d39",
		["Ты $gуверен:уверена;, что не хочешь учиться на воина? Ну, это твой выбор. Если действительно хочешь научиться размахивать пальцем, лучше тебе поговорить с Магисом Искроплащом в \"Громоварке\"."] = "3361a9560236765dd4f9f954267bed44",
		["Хочешь учиться? Азар Мощный Молот всегда готов показать молодежи пару приемов. Его можно найти в \"Громоварке\"."] = "63af3d038f4096f6bba167a9b297ef08",
		["Максан Анвол целыми днями промывает себе глотку в \"Громоварке\". Почему бы тебе $gсамому:самой; не взять кружечку и не расспросить его насчет обучения?"] = "f9ef4e04eea4de713fc61313fd8a4c8e",
		["Ты ищешь Хограла? А в таверне $gсмотрел:смотрела;? Запомни: если тебе нужен дворф, да еще и разбойник, ищи его в таверне!"] = "d218e9d1194ff62a08601af71245f9b8",
		["От этой разновидности магии – одни неприятности. Не представляю, кто этому Гримриззу вообще разрешил поселиться возле \"Громоварки\". Держись от него подальше!"] = "f1180972db6665288081c1cfc7b5f408",
		["Гранис Быстрый Топор остается превосходным бойцом даже после трех бочонков пива. Но если ты хочешь у него учиться, поговори с ним, пока он еще держится на ногах."] = "ee5ecc14e2bf49a6990e74cae4288e7b",
		["Говорят, в Стальгорне есть отличная лавка гномов-алхимиков. Обязательно загляни туда."] = "e59e7a5d5007c14bc99785f8ce315a5c",
		["Звон наковальни Тогнуса слышно даже в Караносе. Потому прочисти уши и загляни в кузню."] = "9f64ea1b3225a2261a71922332f8c889",
		["Гремлок – не слишком удачливый повар, но коллекция рецептов у него внушительная. Поболтай с ним и выведай пару секретов. Он сейчас в \"Громоварке\"."] = "812ca9ddb549b5088d51719a6d51434b",
		["Если ты интересуешься зачаровыванием, наведайся в Стальгорн. Вроде бы там была мастерская – прямо возле укротителя грифонов."] = "e56f9fe4500923af12e19f791a883d14",
		["Со всеми этими винтиками, что Бронк затягивал, он растерял пару своих, если ты понимаешь, о чем я. И все же у него до сих пор светлая голова на предмет создания этих жутких устройств. Тебе следует нанести ему визит в Поселок Сталежара."] = "d505dd7c90c149052d96dc5021198f21",
		["Меня однажды угораздило наткнуться на мерзкого трогга, так старик Трамнер тогда очень здорово перебинтовал, все сразу зажило. Думаю, Трамнер с радостью научит и вас накладывать повязки."] = "93839b8ccc68c7af9e06e65b17c1fd90",
		["Здесь мало подходящих мест для рыбалки. Пакстон знает их все, но рассказывает только о некоторых. Почему бы вам не сходить на Заледеневшее озеро и не порасспросить его лично?"] = "8bbfc8f6de8eca0089d8559839569436",
		["Нет, здесь некому тебя научить травничеству. Но думаю, что тебе больше повезет в Стальгорне."] = "5aaf2f083eef745315ab1a2dc692fcb0",
		["Лучшие кожевники живут в Стальгорне. Если мне не изменяет память, около Великой Кузни как раз есть лавка, где вам смогут помочь."] = "712130efaf95afb9ccb5f2a5c069c0fc",
		["Шахтер? Ты можешь не спрашивать есть ли, $gпарень:девица;, только где! Тебе нужен Ярр, и я думаю, что ты найдешь его прячущимся в \"Поселке Сталежара\"."] = "4ef02a6cde5565b37e151274512c0641",
		["Обычно шкуры в Стальгорн, чтобы просушить их. Почему бы вам не наведаться туда и не узнать, не возьмет ли тебя кто-нибудь в ученики?"] = "12bf423a5f31db52e9d292ceb06ece6b",
		["Ну, вряд ли тебе повезет найти портного здесь. А вот в Стальгорне есть несколько весьма талантливых мастеров. Почему бы тебе не пойти и не спросить там стража?"] = "720fafcfb6472426d4149a74769fda89",
		["Куда вы хотите направиться?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
		["Ближайший банк у нас тут в Стальгорне, $gпарень:девушка;."] = "501c83ee292da27782fae1e60bf7c3f3",
		["В Дун Мороге нет грифонов, $gпарень:девушка;. Если тебе нужно куда-нибудь слетать, отправляйся в Стальгорн."] = "f3c8a5a8b088f61349bd467d2e1e02b1",
		["Все официальные лица проживают в Стальгорне. Бумаги для создания гильдии можно получить в Гостевых покоях Стальгорна."] = "f9fd222716447c9fab43d7fdd2bdcab4",
		["Семейство Громоваров держит отличный трактир в Караносе, названный в их честь. Заходи туда на пару кружек эля и пару минут отдыха."] = "0ee12bb81d2947b566609b7ba822b401",
		["Что ж, $gюноша:девушка;, ищите Шелби Щебенку прямо возле \"Громоварки\" в Караносе. Она прекрасно позаботится обо всех ваших питомцах."] = "bee5611eb524aaf54dfb7c803d87d4c9",
		["Для какого класса тебе нужен учитель?"] = "dcadd0f33e63218ef70a191c145117f6",
		["Какой профессии ты хочешь учиться?"] = "cf38911600ac02c04cb72aafa6596e66",
		["Есть только один охотник, к которому я бы тебе посоветовал обратиться. Его зовут Гриф Дикое Сердце. Ищи его возле кузницы в Караносе."] = "3043df25383951a157419bf109bd7229",
		["В \"Громоварке\" есть один маг, который мог бы обучить тебя кой-каким новым заклинаниям. Кажется, его зовут Магис Искроплащ."] = "cfa572bac748ea1fa7e7c25dc2a4ae04",
		["О, паладин? Что ж, $gпарень:девушка;, тебе повезло! Азар Мощный Молот вернулся с учений и остановился в \"Громоварке\", что в Караносе."] = "9d8f2dd4c4db277f02b3c5d5f15c9354",
		["О, так вы – $gжрец:жрица;? Тогда обязательно навестите старину Максана в \"Громоварке\" – у него есть чему поучиться."] = "9a7b6a50e57d38d1acb4f3bff531e0f2",
		["Что ж, тогда нам нужен один и тот же дворф – Хограл Баккан. Он рано или поздно обязательно отправится в \"Громоварку\", чтобы пропустить кружечку… А может, он уже там."] = "1f4384179f7f2eff7cf1e505f549b91e",
		["Чернокнижники… Терпеть их не могу! Вон тот же Гимризз – открыл, понимаешь, лавку прямо возле \"Громоварки\". Да от его рожи, скажу я тебе, там весь эль прокиснет! Чернокнижники, значит… фу!"] = "60bf6744b34a4b35ea7e3f938b4de2fd",
		["Ох! Вот это дело! Готов поспорить, Гранис Быстрый Топор мог бы тебя научить паре вещей о рубке сталью. Сейчас он в \"Громоварке\", в Караносе."] = "0fd2049ea24b3dbd43761a96e891bd61",
		["Не, в Дун Мороге алхимиков нет. Поищи лучше в Стальгорне… например, среди гномов из Города Механиков."] = "f7cf19aeccddff42a9a0b22c505718cc",
		["О! Этому навыку стоит обучиться! Тогнус бьет по наковальне с силой, которую нечасто встретишь. Почему бы тебе не поговорить с ним и не посмотреть, чему он сможет тебя обучить?"] = "5240f70aad5a8e58147ce8fae9c1ec57",
		["Громоварское и стряпня Гремлока – вот обед что надо. Если уж ты хочешь стать кулинаром – попроси его, пусть тебя поучит."] = "d280277830161709ce905baf4cb22615",
		["Здесь, в Дун Мороге, никто не занимается зачаровыванием. Если хочешь изучать это искусство, отправляйся в Стальгорн."] = "ccffed48b48def2c22f1c44f31434020",
		["Поищи Бронка в Поселке Сталежара. Он там или штуковины всякие паяет, или болтает с водителями о паровых танках."] = "f4fbd7429c935511c5657b11b95d1303",
		["Может, первая помощь и не заменит искусства жрецов, но зато она всегда под рукой. Я б тебе советовал поговорить с Трамнером из \"Громоварки\" и научиться у него всему, чему сумеешь."] = "a88b941bc8e164b364a0b5d642a579b5",
		["Не так уж много здесь рыболовных мест, но кто о них знает, так это Пакстон. Он, несомненно, ловит рыбу в Заледеневшем озере."] = "467b47eb9a3d4006f250fad9ecb18eb0",
		["Цветы, как ни странно, выдерживают холода Дун Морога, но травников ты здесь не найдешь. Чтобы учиться этому ремеслу, тебе нужно отправиться в Стальгорн."] = "3fd9a5ca3019eefa0d287e45aeacd7da",
		["Если хочешь учиться кожевничеству, отправляйся в Стальгорн. Говорят, там возле Великой Кузни есть отличная мастерская."] = "5ca39ccf61fd158a1d527dc435d98222",
		["Не $gдумал:думала; же ты, что найдешь город без горняка, правда? Ярра можно разыскать в Поселке Сталежара, сразу за границей Караноса."] = "1c9825e778eedca69936cc9dcbf549ef",
		["Здесь, в Дун Мороге, ты не найдешь ни одного специалиста по снятию шкур, $gпарень:девушка;. Если уж тебе так надо научиться снимать шкуры, ступай в Стальгорн."] = "6a6954aa23ff423b51b954fe09b144a8",
		["А, Камнелоб последние дни нечасто покидает Стальгорн, так что если ты хочешь научиться профессии портного, то тебе придется отправиться к нему."] = "63ec46e6d95ea9bc754d4ccb65dd8202",
	},
	["Городская стража Штормграда"] = {
		["Хм, грифоны? Никогда ими не интересовался, ну да каждому свое.\n\nОбратитесь к Дунгару Долгопиву в Торговом квартале."] = "258744fe85450f544093d5fd17856341",
		["Хочешь прокатиться на грифоне, а? Дунгар своих птичек держит на валу в Торговом квартале. Только не забывай держаться покрепче!"] = "7df84a254c23565acaa7fc468ead3ab2",
		["Аааа, ну тогда вам надо в гостевой центр Штормграда. Если войти в главные ворота из Аллеи Героев, это будет первый дом слева."] = "646cbbc2bf91bdaa020beb25f4e0a678",
		["Так ты – дитя природы? Тогда тебе прямая дорога к Лунному колодцу в Парке."] = "a63f0a77a472eab18caf48ea8320d27e",
		["Похоже, тебе стоит поговорить с Магинором Дюма! Обычно он находится в Башне магов, в Квартале Магов. Конечно, никогда не знаешь, когда и куда эти маги отправятся через свои порталы."] = "fa0d9c855011039c74c70b23db0b82ea",
		["Советую заглянуть в Храм Света на Соборной площади."] = "7c15eb60533829779dc9fd0c60d26a6a",
		["Если вам нужны разбойники, отправляйтесь в Старый город. Это на северо-востоке Штормграда."] = "cd52082b0fdc76c7dded230c974a2ebf",
		["Посмотрите в Старом городе – в казармах или таверне \"Свинья и свисток\". Если зайдете в таверну, обязательно попробуйте тамошнего пива. Дворфийский эль и рядом не валялся, точно говорю."] = "c621f0b9a4a6a6290dd5972a302122fc",
		["Еще один предприниматель, а? Ну что ж, аукционный дом находится в Торговом квартале. Недалеко от банка."] = "3b18fc0710278c6aa12fb30a85999aaf",
		["Счетная палата Штормграда расположена у передних ворот, в Торговом квартале Штормграда. И, когда устанешь считать деньги, обязательно остановись выпить в \"Позолоченной Розе\"."] = "554b8726d09d342022c5c7eaf5a9818e",
		["$GСлышал:Слышала; про поезд, а? Ну и классно же на нем кататься! Он находится в дальней части Квартала Дворфов. О, главное – руки-ноги на ходу не высовывай!"] = "98484e0cd95c72af21e16247f3eead70",
		["Ах, \"Позолоченная Роза\"… Мягкие кровати, роскошные ванны с теплой водой… только вспомню об этом трактире – и сразу туда хочется… *зевает* Везет же тебе… ты найдешь ее в северной части Торгового квартала… Мягкие подушки, теплые одеяла. *зевает*"] = "e84a11ab6b3896ecf97c8adfbc08636c",
		["А, тебе нужен Дунгар Долгопив. У него одни из самых быстрых грифонов по эту сторону Каз Модана! Ты можешь найти его на валу в Торговом квартале."] = "a36856bf0646fdd5ce14e1bbdbeab7a2",
		["Гильдию, значит, надумали собрать? Ну что ж, удачи!\n\nПоговорите с Альдвином Лолкинсом в гостевом центре Штормграда. Это в Торговом квартале, возле ворот в Аллею Героев."] = "dbd178f951b41e05c59af921ec3b7725",
		["Понятия не имею, как это это происходит… наверное, эти ящики – что-то вроде магических порталов. Тот, что возле банка, вечно толпу собирает. Представляешь, из этого маленького ящичка вытаскивают мечи, щиты, доспехи!"] = "b4b551dc6175faa3e32ad05a88b10b09",
		["Если тебе нужно временно пристроить питомца, поговори с Дженовой Камнещит из Квартала Дворфов."] = "b68ea919378ae726f910e862a386d16f",
		["Мастер Ву Пинг владеет всеми известными видами оружия! Особенно хорошо он управляется с мечом. Большую часть времени он проводит в арсенале Веллера, ожидая новых поставок оружия."] = "ea46258d498568523f3fadf071cc9af0",
		["Так-так, пробиваем себе дорогу в жизни, значит? Тебе нужен Зал Защитника, а найдешь ты его на юго-восточной окраине Старого города. Внутрь пускают только офицеров, а остальные могут поговорить с офицером Арейн. Удачи!"] = "a0e2103ae01da9c6c1707056a504c6ae",
		["Как бы мне хотелось пойти с вами, $n. Отправляйтесь в крепость Штормграда, там в зале для аудиенций найдите Тельмана Сланцевого Кулака. Он поможет вам добраться в Альтеракскую долину."] = "5da822272073a4d726872184c3421ca6",
		["То, что Лига Аратора пытается сделать в Низине Арати, просто замечательно. К сожалению, им мешает нежить и ее приспешники из Орды. Направляйся в Крепость Штормграда, леди Хотешем ожидает тебя в в зале для аудиенций. Она поможет тебе попасть в Низину Арати."] = "adb9b1e902dc3d39490b7c0e4c0e67cd",
		["Среброкрылым Часовым понадобится вся возможная помощь в бою с Всадниками Песни Войны. $n, если вы готовы им помочь, отправляйтесь в крепость Штормграда и поговорите с Эльфарран."] = "a28ad28e180fb23f6b2f30a8926dd8d3",
		["Если вы ищете наставников друидов, то вам стоит пойти в Парк. Теридана и Малдрин можно застать у Лунного колодца в центре этого района."] = "6ca4fdf838b083f58d40a21536adeaed",
		["Охотник, значит? Ну, тогда тебе нужно поговорить с Торфином Камнещитом из Квартала Дворфов.\n\nДа, и не забудь ему передать, что если я еще раз наступлю в сотворенное его питомцем, учить охотников он будет прямо из-за решетки в Тюрьме!"] = "d9d6fc265ce7e558402d3ca53747dac5",
		["Интересуетесь тайной магией? Тогда обязательно посетите Башню магов в Квартале Магов."] = "0493aff58b480f500d524b265550d281",
		["Лорена – верховная жрица Штормграда. Ее можно найти в Храме Света на Соборной площади."] = "4a22a1b67aa8fe418d517ebb0e371796",
		["Тьфу, да от этих лазутчков никакой пользы – только работы нам в Штормграде прибавляют. Взять бы этих Осборна с Матиасом из Старого города – и прямиком в тюрьму."] = "6e24adae0babfe7f1e128960d09c55af",
		["Чернокнижники, да. Дошли до меня слухи, что собираются они в баре под названием \"Зарезанный ягненок\", что в квартале магов, но я ничего тебе не говорил!"] = "f05de425d7bd02752037b8477cf01b53",
		["Хотите подучиться, да? Я мог бы обучить вас куда лучше, чем любой воин Штормграда, но стражам это запрещено. Думаю, вам придется поискать наставника возле казарм или в таверне \"Свинья и свисток\" в Старом городе."] = "cd7fa3fdce25e94d80b36771810f1e93",
		["В Квартале Магов есть маленький магазинчик под названием \"Все для алхимика\". Вообще-то там полно всяких маленьких магазинчиков, но вы идите по внешнему кругу – точно не пропустите."] = "8651024fca6f7bd42a0336d52e7d69fc",
		["Ты что, $gсам:сама; не чуешь запах дыма из дворфийских горнов? Если хочешь учиться кузнечному делу, поищи Терума Подземную Кузню. Он сейчас в Районе гномов, это прямо на север от Соборной площади."] = "a3a18a74f32a8ebab3109103db8d0fd5",
		["В таверне \"Свинья и свисток\", что в Старом городе, есть превосходный повар. Я наблюдал, как он управляется с ножом. Между нами говоря, не думаю, что он всегда был поваром… Но если ты действительно хочешь учиться, обратись к нему."] = "af66b0b5d2d42f34571240ac0c887807",
		["А, ты ищешь Лукана Корделла. Он держит лавку на внешней стороне Квартала Магов, возле дороги к тюрьме."] = "e3f9bcedb2188218c92b8b8fb1e8eb6a",
		["Ой, это мне напомнило, что мне нужно починить свои реактивные сапоги. Мудрым на заметку, мой друг: реактивные сапоги и грифоны плохо сочетаются.\n\nОй, тебе же нужно объяснить, как пройти… просто направляйся в Квартал Дворфов, ты найдешь Лилиама Шпинделя дальше, в глубине."] = "bb3fee63f3293484e591674a691d3c88",
		["Обучение первой помощи лучше всего проходить в Храме Света, под бдительным присмотром Шайны Корпии. \n\nЖелтые крыши Храмового двора и шпиль самого храма видно из любой точки города."] = "b1be3018807cc2da500145c8c2b10794",
		["Этот лодырь Леланд… что сидит на причале возле Торгового квартала и день-деньской удит рыбу. За все то время, что он рыбачит, можно было тридцать раз стать настоящим мастером этого дела. Так что вам надо с ним поговорить."] = "2472ef40c4054390e47d26a2790dcef8",
		["Ничто не сравнится с общением с природой… по крайней мере, так говорят ночные эльфы. Я не особо люблю разговаривать с деревьями и цветами, но Танниса могла бы вам помочь. Она в Квартале магов, возле \"Все для алхимика\"."] = "42747362bb8e6d2164d7e79747248058",
		["Интересуешься кожей, да? Видимо, тебе нужно поговорить с Саймоном Дубильщиком из Старого города. У него тут лавка \"Прочная шкура\"."] = "02b8fd48e20c73453938adc9f4995c2c",
		["В духе дворфов прислать специалиста по шахтам из Стальгорна, чтобы научить нас уму-разуму. Разве сложно взять кирку и долбить по камню? Ну, раз уж он здесь, он, наверное, как раз тот, кто тебе нужен. Его зовут Гельман, и проживает он в Квартале Дворфов."] = "64070f95813e914bdca6f15e390c919e",
		["Вы знаете, я могу пронзить орка насквозь или нарезать тролля на кусочки? Могу даже вырезать свои инициалы на боку огра, но вот шкуры сдирать – это не по мне. Поди пойми. \n\nОднако если у вас на это смелости хватает, то поговорите с Марисой Гренжер в \"Защитной шкуре\" в Старом городе."] = "c7ce82c152a63bc669f1d309ce17f9bd",
		["Портняжное дело, говоришь? Ну, рано или поздно ты в любом случае узнаешь о Джорджио Болеро. Это наш местный законодатель мод. Если хочешь пойти к нему в ученики, отправляйся в Квартал Магов, на внешнее кольцо."] = "9cba4dc5407b5b21f860b325ab149a86",
		["Куда вы хотите пройти?"] = "2402ec9453525b4ec16e1180457c7cfb",
		["Это в Торговом квартале. В прямой видимости от ворот Штормграда."] = "568c01f3e19d99d5f41ea3aac2056ebe",
		["Банк Штормграда находится в Торговом квартале, на северо-запад от городских ворот. Вот, позвольте мне показать на карте."] = "8fedf8298f3edb222d5b5f4355c58675",
		["Не хватает смелости для полета на грифоне, а? К счастью для тебя, у нас есть вариант, при котором тебе не придется отрываться от земли… Ну, более или менее. Это гномский перевозчик людей, подземный поезд, удобно расположенный сзади района гномов."] = "b8a17986e4d6330f2e74f8f8a53c0d86",
		["В Штормграде много заведений, где можно пропустить стаканчик, но хороший ночлег есть только в одном. Отправляйтесь в \"Позолоченную розу\" в Торговом квартале. Там умеренные цены и чистое постельное белье."] = "44af32f368e03c09b89fe9f87be3875e",
		["Укротителя грифонов можно найти на северо-восточном валу Аллеи Героев."] = "f5c1db946eb2f4fba13e922275d9fb95",
		["Альдвина Лолкинса можно найти в гостевом центре Штормграда. Это в Торговом квартале."] = "53cfbdba892d116c2e03388c9fd6d5d0",
		["\"Почтовый ящик находится между банком Штормграда и трактиром \"Позолоченная роза\" в Торговом квартале\"."] = "bb63ff9d75c7726f1d06e21fe2021b8b",
		["Тебе нужна Дженова Камнещит из Квартала Дворфов. Она заботится о питомцах охотников, пока те учатся у ее отца."] = "9654c77653b91d446f531295982fbec7",
		["Ву Пинг невероятно вынослив. Глядя, как он несколько часов подряд тренируется с оружием, я начал жалеть учебный манекен. Лучшего учителя оружейных навыков и придумать трудно."] = "312810e5deb14cd60aa19428f7f51227",
		["А ты уже, значит, Поборник Альянса?! Полагаю, сейчас ты захочешь отправиться в Зал Защитника. Это в Старом городе, но без офицерского звания тебя внутрь не пустят – придется довольствоваться разговором с офицером Арейн. Иди, не задерживайся."] = "33278f8101e800c93fc3d2385cfed699",
		["Какое поле боя вас интересует?"] = "481f209702cc74fc87fe4569d25b276b",
		["Какой класс вас интересует?"] = "7e357056bac5b73342ac2bee0458e300",
		["Какая профессия вас интересует?"] = "ce83ae92effc9c6509cef60c5f919389",
		["Тогда вам нужен Тельман Сланцевый Кулак. Он находится подле короля в крепости Штормграда."] = "bcfcce27aafd9e54ef3d2fcdb27f4139",
		["Леди Хотешем принимает посетителей в королевском зале для аудиенций. Она проводит вас в Низину Арати, где Лига Аратора нуждается в помощи в боях с Осквернителями."] = "9ff1ef7f7918452a7571c3f770ab4e14",
		["Да, Среброкрылым пригодится твоя помощь. Поговори с Эльфарран в зале аудиенций крепости Штормграда."] = "ab67b49961ce98725cccb8a6b0e8e7ef",
		["Ну, Теридана и Малдрина обычно можно встретить в Парке у Лунного колодца. Отправляйся в западную часть Штормграда – ту, что к северу от Квартала магов и к западу от Соборной площади."] = "2c1e9110dff51f5d1d491b13523c5989",
		["Торфин Камнещит проделал долгий путь из Стальгорна к нам, чтобы донести до нас свои знания об охоте. Если ты не против подышать дымным воздухом Квартала Дворфов, ты найдешь его в его доме в северо-восточной части района."] = "8c8ac67be8a32d83d11e1119cbe8b9f8",
		["Маги обычно собираются в Башне магов, в Квартале Магов. У них там такая башня! Рядом с ней наши казармы выглядят просто сараями какими-то."] = "338c8fab07f57033e48217d5973c15df",
		["Если вы хотите стать великим паладином, лучшего учителя, чем лорд Грейсон Тенелом, вам не найти. Грейсона можно встретить в Храме Света на Соборной площади."] = "2d22a7afddcc8d88b9c1353ae28daf09",
		["Храм Света на Соборной площади – это дом жречества Штормграда. Там ты найдешь верховную жрицу Лорену."] = "bb897a746e8a30c2b211e9076b6a286d",
		["Значит, тебе надо поговорить с Осборном. Он – наилучший учитель искусства незаметности в Штормграде. Ищи его в Старом городе."] = "5079ccedcf83df1e6554116dbaa337bd",
		["Что? Я не знаю никаких наставников чернокнижников в Штормграде.\n\nХотя… Были признаки бесовской деятельности возле \"Зарезанного ягненка\" в Квартале магов. Можешь поискать там."] = "f6a52f523eecff532c9530eae7d0e89a",
		["Воинов можно встретить либо в таверне \"Свинья и свисток\", либо в казармах Старого города. И мой тебе совет: сначала сходи в таверну."] = "9434f3b21efa2de084243d600d530ff5",
		["Во всем Штормграде есть только одно место, интересное для алхимиков… Оно так и называется: \"Все для алхимика\". Ты найдешь его в Квартале магов, на внешнем кольце магазинов."] = "7034523efe4bfc8203b790a1d127dca2",
		["Терум Подземная Кузня – как раз тот дворф, который тебе нужен. Один из лучших местных кузнецов, скажу я тебе. Ищи его в центре Квартала Дворфов."] = "a4956fb4f50c46eaea4f68dd50ceb194",
		["Если хочешь научиться отлично готовить, отправляйся в таверну \"Свинья и свисток\" в старом городе и поговори со Стивеном Райбеком. Уж он-то умеет приготовить такие ребрышки, как никто другой.\n\nЭх… даже слюнки потекли из-за тебя. Но не рассчитывай, что он тебя и это блюдо выучит готовить!"] = "dbe19e29f297c8e1fb35a95e50f89466",
		["Лукан Корделл держит магазинчик на берегу канала возле тюрьмы. Я уверен, что он сможет научить тебя искусству зачаровывания."] = "91e3f367dbb0e83b362a5880d1271dc4",
		["Инженерному делу в Штормграде обучает гном по имени Лилиам Шпиндель. Его можно найти в задней части Квартала Дворфов."] = "05e90b70ee82c6ab15e68fec597454c2",
		["В Храме Света собираются целители со всего Штормграда. Найди там Шайну Корпию – она обучит тебя тонкостям своей профессии."] = "fd43bf9ef9a4ea5b42ea21a6017c205b",
		["Ничто не сравнится с днем, проведенным за рыбалкой на озере Хрустальном. Меня обучил этому искусству Арнольд Лиланд. Обычно он стоит на причале в районе каналов и рыбачит целый день.\n\nА, да, и не верь этим его рассказам о монстрах в каналах."] = "852f678dbc06d3601bdf168e7032735a",
		["Таннису можно найти у магазина \"Все для алхимика\", что в Квартале Магов."] = "356b1700581f2c27333ab266a26bb077",
		["Хочешь научиться кожевничеству? Тогда тебе нужен Саймон Дубильщик. Его можно найти в \"Прочной шкуре\", что в Старом городе."] = "52ef93000b10574ffb40f6f451597e26",
		["Поговорите с Гельманом Камнеруком. Кажется, он живет в Квартале Дворфов, но точно не скажу… Посмотрите там."] = "8f8f48c440d58b1a783b868dd9222e74",
		["Если вы хотите научиться искусству снятия шкур, отправляйтесь в Старый город и загляните в \"Прочную шкуру\"."] = "6f55eb7e6eebe144bc957790dae41464",
		["В \"Тканях Дункана\" работает один из самых лучших портных Штормграда – Джорджио Болеро. Обязательно посетите этот магазин в Квартале Магов!"] = "8706ad14fe81bd7bfe9d6986ff68ed63",
	},
	["Городской патрульный Штормграда"] = {
		["Хм, грифоны? Никогда ими не интересовался, ну да каждому свое.\n\nОбратитесь к Дунгару Долгопиву в Торговом квартале."] = "258744fe85450f544093d5fd17856341",
		["Хочешь прокатиться на грифоне, а? Дунгар своих птичек держит на валу в Торговом квартале. Только не забывай держаться покрепче!"] = "7df84a254c23565acaa7fc468ead3ab2",
		["Аааа, ну тогда вам надо в гостевой центр Штормграда. Если войти в главные ворота из Аллеи Героев, это будет первый дом слева."] = "646cbbc2bf91bdaa020beb25f4e0a678",
		["Так ты – дитя природы? Тогда тебе прямая дорога к Лунному колодцу в Парке."] = "a63f0a77a472eab18caf48ea8320d27e",
		["Похоже, тебе стоит поговорить с Магинором Дюма! Обычно он находится в Башне магов, в Квартале Магов. Конечно, никогда не знаешь, когда и куда эти маги отправятся через свои порталы."] = "fa0d9c855011039c74c70b23db0b82ea",
		["Советую заглянуть в Храм Света на Соборной площади."] = "7c15eb60533829779dc9fd0c60d26a6a",
		["Если вам нужны разбойники, отправляйтесь в Старый город. Это на северо-востоке Штормграда."] = "cd52082b0fdc76c7dded230c974a2ebf",
		["Посмотрите в Старом городе – в казармах или таверне \"Свинья и свисток\". Если зайдете в таверну, обязательно попробуйте тамошнего пива. Дворфийский эль и рядом не валялся, точно говорю."] = "c621f0b9a4a6a6290dd5972a302122fc",
		["Еще один предприниматель, а? Ну что ж, аукционный дом находится в Торговом квартале. Недалеко от банка."] = "3b18fc0710278c6aa12fb30a85999aaf",
		["Счетная палата Штормграда расположена у передних ворот, в Торговом квартале Штормграда. И, когда устанешь считать деньги, обязательно остановись выпить в \"Позолоченной Розе\"."] = "554b8726d09d342022c5c7eaf5a9818e",
		["$GСлышал:Слышала; про поезд, а? Ну и классно же на нем кататься! Он находится в дальней части Квартала Дворфов. О, главное – руки-ноги на ходу не высовывай!"] = "98484e0cd95c72af21e16247f3eead70",
		["Ах, \"Позолоченная Роза\"… Мягкие кровати, роскошные ванны с теплой водой… только вспомню об этом трактире – и сразу туда хочется… *зевает* Везет же тебе… ты найдешь ее в северной части Торгового квартала… Мягкие подушки, теплые одеяла. *зевает*"] = "e84a11ab6b3896ecf97c8adfbc08636c",
		["А, тебе нужен Дунгар Долгопив. У него одни из самых быстрых грифонов по эту сторону Каз Модана! Ты можешь найти его на валу в Торговом квартале."] = "a36856bf0646fdd5ce14e1bbdbeab7a2",
		["Гильдию, значит, надумали собрать? Ну что ж, удачи!\n\nПоговорите с Альдвином Лолкинсом в гостевом центре Штормграда. Это в Торговом квартале, возле ворот в Аллею Героев."] = "dbd178f951b41e05c59af921ec3b7725",
		["Понятия не имею, как это это происходит… наверное, эти ящики – что-то вроде магических порталов. Тот, что возле банка, вечно толпу собирает. Представляешь, из этого маленького ящичка вытаскивают мечи, щиты, доспехи!"] = "b4b551dc6175faa3e32ad05a88b10b09",
		["Если тебе нужно временно пристроить питомца, поговори с Дженовой Камнещит из Квартала Дворфов."] = "b68ea919378ae726f910e862a386d16f",
		["Мастер Ву Пинг владеет всеми известными видами оружия! Особенно хорошо он управляется с мечом. Большую часть времени он проводит в арсенале Веллера, ожидая новых поставок оружия."] = "ea46258d498568523f3fadf071cc9af0",
		["Так-так, пробиваем себе дорогу в жизни, значит? Тебе нужен Зал Защитника, а найдешь ты его на юго-восточной окраине Старого города. Внутрь пускают только офицеров, а остальные могут поговорить с офицером Арейн. Удачи!"] = "a0e2103ae01da9c6c1707056a504c6ae",
		["Как бы мне хотелось пойти с вами, $n. Отправляйтесь в крепость Штормграда, там в зале для аудиенций найдите Тельмана Сланцевого Кулака. Он поможет вам добраться в Альтеракскую долину."] = "5da822272073a4d726872184c3421ca6",
		["То, что Лига Аратора пытается сделать в Низине Арати, просто замечательно. К сожалению, им мешает нежить и ее приспешники из Орды. Направляйся в Крепость Штормграда, леди Хотешем ожидает тебя в в зале для аудиенций. Она поможет тебе попасть в Низину Арати."] = "adb9b1e902dc3d39490b7c0e4c0e67cd",
		["Среброкрылым Часовым понадобится вся возможная помощь в бою с Всадниками Песни Войны. $n, если вы готовы им помочь, отправляйтесь в крепость Штормграда и поговорите с Эльфарран."] = "a28ad28e180fb23f6b2f30a8926dd8d3",
		["Если вы ищете наставников друидов, то вам стоит пойти в Парк. Теридана и Малдрин можно застать у Лунного колодца в центре этого района."] = "6ca4fdf838b083f58d40a21536adeaed",
		["Охотник, значит? Ну, тогда тебе нужно поговорить с Торфином Камнещитом из Квартала Дворфов.\n\nДа, и не забудь ему передать, что если я еще раз наступлю в сотворенное его питомцем, учить охотников он будет прямо из-за решетки в Тюрьме!"] = "d9d6fc265ce7e558402d3ca53747dac5",
		["Интересуетесь тайной магией? Тогда обязательно посетите Башню магов в Квартале Магов."] = "0493aff58b480f500d524b265550d281",
		["Лорена – верховная жрица Штормграда. Ее можно найти в Храме Света на Соборной площади."] = "4a22a1b67aa8fe418d517ebb0e371796",
		["Тьфу, да от этих лазутчков никакой пользы – только работы нам в Штормграде прибавляют. Взять бы этих Осборна с Матиасом из Старого города – и прямиком в тюрьму."] = "6e24adae0babfe7f1e128960d09c55af",
		["Чернокнижники, да. Дошли до меня слухи, что собираются они в баре под названием \"Зарезанный ягненок\", что в квартале магов, но я ничего тебе не говорил!"] = "f05de425d7bd02752037b8477cf01b53",
		["Хотите подучиться, да? Я мог бы обучить вас куда лучше, чем любой воин Штормграда, но стражам это запрещено. Думаю, вам придется поискать наставника возле казарм или в таверне \"Свинья и свисток\" в Старом городе."] = "cd7fa3fdce25e94d80b36771810f1e93",
		["В Квартале Магов есть маленький магазинчик под названием \"Все для алхимика\". Вообще-то там полно всяких маленьких магазинчиков, но вы идите по внешнему кругу – точно не пропустите."] = "8651024fca6f7bd42a0336d52e7d69fc",
		["Ты что, $gсам:сама; не чуешь запах дыма из дворфийских горнов? Если хочешь учиться кузнечному делу, поищи Терума Подземную Кузню. Он сейчас в Районе гномов, это прямо на север от Соборной площади."] = "a3a18a74f32a8ebab3109103db8d0fd5",
		["В таверне \"Свинья и свисток\", что в Старом городе, есть превосходный повар. Я наблюдал, как он управляется с ножом. Между нами говоря, не думаю, что он всегда был поваром… Но если ты действительно хочешь учиться, обратись к нему."] = "af66b0b5d2d42f34571240ac0c887807",
		["А, ты ищешь Лукана Корделла. Он держит лавку на внешней стороне Квартала Магов, возле дороги к тюрьме."] = "e3f9bcedb2188218c92b8b8fb1e8eb6a",
		["Ой, это мне напомнило, что мне нужно починить свои реактивные сапоги. Мудрым на заметку, мой друг: реактивные сапоги и грифоны плохо сочетаются.\n\nОй, тебе же нужно объяснить, как пройти… просто направляйся в Квартал Дворфов, ты найдешь Лилиама Шпинделя дальше, в глубине."] = "bb3fee63f3293484e591674a691d3c88",
		["Обучение первой помощи лучше всего проходить в Храме Света, под бдительным присмотром Шайны Корпии. \n\nЖелтые крыши Храмового двора и шпиль самого храма видно из любой точки города."] = "b1be3018807cc2da500145c8c2b10794",
		["Этот лодырь Леланд… что сидит на причале возле Торгового квартала и день-деньской удит рыбу. За все то время, что он рыбачит, можно было тридцать раз стать настоящим мастером этого дела. Так что вам надо с ним поговорить."] = "2472ef40c4054390e47d26a2790dcef8",
		["Ничто не сравнится с общением с природой… по крайней мере, так говорят ночные эльфы. Я не особо люблю разговаривать с деревьями и цветами, но Танниса могла бы вам помочь. Она в Квартале магов, возле \"Все для алхимика\"."] = "42747362bb8e6d2164d7e79747248058",
		["Интересуешься кожей, да? Видимо, тебе нужно поговорить с Саймоном Дубильщиком из Старого города. У него тут лавка \"Прочная шкура\"."] = "02b8fd48e20c73453938adc9f4995c2c",
		["В духе дворфов прислать специалиста по шахтам из Стальгорна, чтобы научить нас уму-разуму. Разве сложно взять кирку и долбить по камню? Ну, раз уж он здесь, он, наверное, как раз тот, кто тебе нужен. Его зовут Гельман, и проживает он в Квартале Дворфов."] = "64070f95813e914bdca6f15e390c919e",
		["Вы знаете, я могу пронзить орка насквозь или нарезать тролля на кусочки? Могу даже вырезать свои инициалы на боку огра, но вот шкуры сдирать – это не по мне. Поди пойми. \n\nОднако если у вас на это смелости хватает, то поговорите с Марисой Гренжер в \"Защитной шкуре\" в Старом городе."] = "c7ce82c152a63bc669f1d309ce17f9bd",
		["Портняжное дело, говоришь? Ну, рано или поздно ты в любом случае узнаешь о Джорджио Болеро. Это наш местный законодатель мод. Если хочешь пойти к нему в ученики, отправляйся в Квартал Магов, на внешнее кольцо."] = "9cba4dc5407b5b21f860b325ab149a86",
		["Куда вы хотите пройти?"] = "2402ec9453525b4ec16e1180457c7cfb",
		["Это в Торговом квартале. В прямой видимости от ворот Штормграда."] = "568c01f3e19d99d5f41ea3aac2056ebe",
		["Банк Штормграда находится в Торговом квартале, на северо-запад от городских ворот. Вот, позвольте мне показать на карте."] = "8fedf8298f3edb222d5b5f4355c58675",
		["Не хватает смелости для полета на грифоне, а? К счастью для тебя, у нас есть вариант, при котором тебе не придется отрываться от земли… Ну, более или менее. Это гномский перевозчик людей, подземный поезд, удобно расположенный сзади района гномов."] = "b8a17986e4d6330f2e74f8f8a53c0d86",
		["В Штормграде много заведений, где можно пропустить стаканчик, но хороший ночлег есть только в одном. Отправляйтесь в \"Позолоченную розу\" в Торговом квартале. Там умеренные цены и чистое постельное белье."] = "44af32f368e03c09b89fe9f87be3875e",
		["Укротителя грифонов можно найти на северо-восточном валу Аллеи Героев."] = "f5c1db946eb2f4fba13e922275d9fb95",
		["Альдвина Лолкинса можно найти в гостевом центре Штормграда. Это в Торговом квартале."] = "53cfbdba892d116c2e03388c9fd6d5d0",
		["\"Почтовый ящик находится между банком Штормграда и трактиром \"Позолоченная роза\" в Торговом квартале\"."] = "bb63ff9d75c7726f1d06e21fe2021b8b",
		["Тебе нужна Дженова Камнещит из Квартала Дворфов. Она заботится о питомцах охотников, пока те учатся у ее отца."] = "9654c77653b91d446f531295982fbec7",
		["Ву Пинг невероятно вынослив. Глядя, как он несколько часов подряд тренируется с оружием, я начал жалеть учебный манекен. Лучшего учителя оружейных навыков и придумать трудно."] = "312810e5deb14cd60aa19428f7f51227",
		["А ты уже, значит, Поборник Альянса?! Полагаю, сейчас ты захочешь отправиться в Зал Защитника. Это в Старом городе, но без офицерского звания тебя внутрь не пустят – придется довольствоваться разговором с офицером Арейн. Иди, не задерживайся."] = "33278f8101e800c93fc3d2385cfed699",
		["Какое поле боя вас интересует?"] = "481f209702cc74fc87fe4569d25b276b",
		["Какой класс вас интересует?"] = "7e357056bac5b73342ac2bee0458e300",
		["Какая профессия вас интересует?"] = "ce83ae92effc9c6509cef60c5f919389",
		["Тогда вам нужен Тельман Сланцевый Кулак. Он находится подле короля в крепости Штормграда."] = "bcfcce27aafd9e54ef3d2fcdb27f4139",
		["Леди Хотешем принимает посетителей в королевском зале для аудиенций. Она проводит вас в Низину Арати, где Лига Аратора нуждается в помощи в боях с Осквернителями."] = "9ff1ef7f7918452a7571c3f770ab4e14",
		["Да, Среброкрылым пригодится твоя помощь. Поговори с Эльфарран в зале аудиенций крепости Штормграда."] = "ab67b49961ce98725cccb8a6b0e8e7ef",
		["Ну, Теридана и Малдрина обычно можно встретить в Парке у Лунного колодца. Отправляйся в западную часть Штормграда – ту, что к северу от Квартала магов и к западу от Соборной площади."] = "2c1e9110dff51f5d1d491b13523c5989",
		["Торфин Камнещит проделал долгий путь из Стальгорна к нам, чтобы донести до нас свои знания об охоте. Если ты не против подышать дымным воздухом Квартала Дворфов, ты найдешь его в его доме в северо-восточной части района."] = "8c8ac67be8a32d83d11e1119cbe8b9f8",
		["Маги обычно собираются в Башне магов, в Квартале Магов. У них там такая башня! Рядом с ней наши казармы выглядят просто сараями какими-то."] = "338c8fab07f57033e48217d5973c15df",
		["Если вы хотите стать великим паладином, лучшего учителя, чем лорд Грейсон Тенелом, вам не найти. Грейсона можно встретить в Храме Света на Соборной площади."] = "2d22a7afddcc8d88b9c1353ae28daf09",
		["Храм Света на Соборной площади – это дом жречества Штормграда. Там ты найдешь верховную жрицу Лорену."] = "bb897a746e8a30c2b211e9076b6a286d",
		["Значит, тебе надо поговорить с Осборном. Он – наилучший учитель искусства незаметности в Штормграде. Ищи его в Старом городе."] = "5079ccedcf83df1e6554116dbaa337bd",
		["Что? Я не знаю никаких наставников чернокнижников в Штормграде.\n\nХотя… Были признаки бесовской деятельности возле \"Зарезанного ягненка\" в Квартале магов. Можешь поискать там."] = "f6a52f523eecff532c9530eae7d0e89a",
		["Воинов можно встретить либо в таверне \"Свинья и свисток\", либо в казармах Старого города. И мой тебе совет: сначала сходи в таверну."] = "9434f3b21efa2de084243d600d530ff5",
		["Во всем Штормграде есть только одно место, интересное для алхимиков… Оно так и называется: \"Все для алхимика\". Ты найдешь его в Квартале магов, на внешнем кольце магазинов."] = "7034523efe4bfc8203b790a1d127dca2",
		["Терум Подземная Кузня – как раз тот дворф, который тебе нужен. Один из лучших местных кузнецов, скажу я тебе. Ищи его в центре Квартала Дворфов."] = "a4956fb4f50c46eaea4f68dd50ceb194",
		["Если хочешь научиться отлично готовить, отправляйся в таверну \"Свинья и свисток\" в старом городе и поговори со Стивеном Райбеком. Уж он-то умеет приготовить такие ребрышки, как никто другой.\n\nЭх… даже слюнки потекли из-за тебя. Но не рассчитывай, что он тебя и это блюдо выучит готовить!"] = "dbe19e29f297c8e1fb35a95e50f89466",
		["Лукан Корделл держит магазинчик на берегу канала возле тюрьмы. Я уверен, что он сможет научить тебя искусству зачаровывания."] = "91e3f367dbb0e83b362a5880d1271dc4",
		["Инженерному делу в Штормграде обучает гном по имени Лилиам Шпиндель. Его можно найти в задней части Квартала Дворфов."] = "05e90b70ee82c6ab15e68fec597454c2",
		["В Храме Света собираются целители со всего Штормграда. Найди там Шайну Корпию – она обучит тебя тонкостям своей профессии."] = "fd43bf9ef9a4ea5b42ea21a6017c205b",
		["Ничто не сравнится с днем, проведенным за рыбалкой на озере Хрустальном. Меня обучил этому искусству Арнольд Лиланд. Обычно он стоит на причале в районе каналов и рыбачит целый день.\n\nА, да, и не верь этим его рассказам о монстрах в каналах."] = "852f678dbc06d3601bdf168e7032735a",
		["Таннису можно найти у магазина \"Все для алхимика\", что в Квартале Магов."] = "356b1700581f2c27333ab266a26bb077",
		["Хочешь научиться кожевничеству? Тогда тебе нужен Саймон Дубильщик. Его можно найти в \"Прочной шкуре\", что в Старом городе."] = "52ef93000b10574ffb40f6f451597e26",
		["Поговорите с Гельманом Камнеруком. Кажется, он живет в Квартале Дворфов, но точно не скажу… Посмотрите там."] = "8f8f48c440d58b1a783b868dd9222e74",
		["Если вы хотите научиться искусству снятия шкур, отправляйтесь в Старый город и загляните в \"Прочную шкуру\"."] = "6f55eb7e6eebe144bc957790dae41464",
		["В \"Тканях Дункана\" работает один из самых лучших портных Штормграда – Джорджио Болеро. Обязательно посетите этот магазин в Квартале Магов!"] = "8706ad14fe81bd7bfe9d6986ff68ed63",
	},
	["Горожанин Каэр Дарроу"] = {
		["Еще один великолепный день на нашем прекрасном острове."] = "6ee2df979a0ec4486607c25f530d005f",
		["Мы не хотели показаться грубыми. Просто сейчас у нас все торопятся – к прибытию Утера все должно быть идеально. Светоносец не так часто приезжает в город."] = "3fd0ad73fe861332551fc4d9af524377",
		["Добро пожаловать в Каэр Дарроу, $gнезнакомец:незнакомка;."] = "7865da4630a47f9938f5a4dfce34dadf",
		["Доводилось пробовать наш хлеб? По-моему, пекарь Мастерсон – величайший кулинар всех времен!"] = "f46f6654ac94eac82e2b0c3924d865e1",
		["Ты что, не видишь – мы готовимся к визиту Утера? Уйди с дороги, и так дел невпроворот!"] = "4e2408ee8c09379d77525ec8b38e694d",
	},
	["Горрик"] = {
		["Куда бы вы хотели слетать?"] = "f686b3319d4af5004c6ee3403aea3f5e",
	},
	["Гранис Быстрый Топор"] = {
		["Может, большие войны и остались в прошлом, но это не повод забывать наши воинские навыки!"] = "ce85977b0f1b155023ca49641a927acd",
		["Ты не воин. Ты не выдержишь и дня моих тренировок! $B$BТоже мне, $c, $gвозомнивший:возомнившая; себя воином! Ха!"] = "64a04066374cb355ff1adeae11f4ae82",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Грарник Ладноскрой"] = {
		["Не откладывай на завтра то, что можно сделать… ммм, послезавтра? Тьфу ты, забыл!"] = "4695d885c5423f51c542ad1df66c86b0",
		["Неплохо для новичка! Я научил тебя всему, что знаю сам. Если хочешь продолжить обучение, найди Джозефа Грегориана в Подгороде."] = "379c74fd86ed0bbf02d5ee95a1c7479c",
		["Ну, не так уж и плохо. Может быть, я смогу тебя чему-то научить."] = "86645eb4b7a73026276b0f113606af33",
		["Ага, ты кое-что знаешь! Если хочешь узнать больше, поговори с Джорджио Болеро в Штормграде."] = "bcf239bdb85060a4bc12b087536a094e",
	},
	["Греган Пивоплюй"] = {
		["Привет! Я Греган. Чем могу помочь?"] = "7673b1e1c1aee85187bd33011e028202",
		["Конечно, $N. По-видимому, тебе можно доверять… Ты заслуживаешь доверия! Я такое за версту определяю…$B$BВ общем, вернемся к моим словам. Для изготовления одной порции эликсира Видере нужен один эвокорень. Добыть остальные ингредиенты будет несложно, а вот с эвокорнем придется повозиться."] = "f6ad8c672faab789040d554fb2b0b5a6",
		["Хе-хе…$GКакой ты любопытный:Какая ты любопытная;, да, $n? Ну, вот что тебе нужно сделать.$B$BК северу отсюда в старых руинах живет очень неприятный гнолл по имени Миблон Рыкозуб. Он охраняет единственный известный мне эвокорень, не смыкая глаз! Похоже, он даже никогда не спит!$B$BЧто ты можешь сделать, так это подкупить его. Я могу продать тебе немного наживки, которая ему покажется вкусной, – просто положи ее перед ним, и она отвлечет его на время. Хватаей эвокорень и беги. Удачи!"] = "f3df391ade7879f97d794ce7af5fee06",
	},
	["Грегор Грейстоун"] = {
		["Приветствую тебя, $gдруг мой:подруга;. Да хранит тебя Рассвет в эти нелегкие времена."] = "9ec1c2021f5f1a32200d3ff28474b403",
	},
	["Грегор Маквинс"] = {
		["Благодаря годам, затраченным на разведение породы, и качественному уходу я могу с гордостью представить тебе этих лошадей! Прошу, подходи, осмотрись, выбери себе скакуна. Лошадь, $gдруг мой:уважаемая;, – это товарищ на года. Обзаведись резвым скакуном, ведь ты этого $gдостоин:достойна;!"] = "b2eb329ecae1bc16999a40f0d3b30dc8",
		["Извини, но я не могу продавать лошадей тому, кто не заслужил полного доверия в королевстве Штормграда. Скакунов лучше не найти нигде, и нам не хотелось бы отдавать их в руки врагов.$B$BНет, я не хочу сказать, что ты враг… в общем, заработай доверие Штормграда, и тогда мы поговорим о делах."] = "3abbcc0541b691e0b8bbe9d7c11ad032",
	},
	["Грегори Ардус"] = {
		["Да хранит тебя Свет в твоих странствиях. Смотри, выбирай. Если понадоблюсь – я рядом."] = "7de891da4a4a6e829ff423333d14b8c9",
	},
	["Грегори Чарльз"] = {
		["С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого."] = "64555eeab27efbc07ad81017e2883ba6",
		["Я не могу учить тебя. Найди учителя своего класса."] = "055cd46d500b03f8da5d75f8fb873481",
		["Посланцы Черного Ворона сегодня утром вручили мне это письмо. Оно адресовано тебе, $n."] = "905f380534c597ffe329082b2db08cd9",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Грезз Десница Гнева"] = {
		["Ты здесь для учебы? Или просто для того, чтобы заставить воина зря тратить время?"] = "141f23d07f540e8c7b0ef9335bda601e",
		["Я не учу таких, как ты, $c. Обращайся к другим, а меня не зли."] = "5c32ac92759b0e79eade7dc21f7e569f",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Гремлок Пилзнор"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "c4162cb7f63061b6eae39dc6b6b814dd",
		["Разыщи Шандрину в приюте Серебряного Ветра. Она может продать тебе \"Поваренную книгу умельца\"."] = "fe8baba790f8edd0a4e3d2f680dfe89a",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "de96efe8437890d30d0aff9e01f5f7cb",
		["Я могу научить тебя готовить!"] = "8aeb96ef5db5b2d70e98dbbaca63f721",
	},
	["Грешка"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "7890c2b1ae34d8a5d70574f03c64ac95",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "1cb32f6470dcf1a2f6a434cc66bea835",
	},
	["Гриззлоу"] = {
		["Должен сказать, в Пиратской бухте готовят лучшую похлебку из моллюсков во всех Южных Морях. О, не интересуешься кулинарыми искусствами, а? Тогда позволь первым пригласить тебя на борт \"Девичьего Каприза\", самого лучшего пассажирского корабля, плавающего между Восточными Королевствами и Калимдором. Скоро он вернется из плавания в Кабестан, так что располагайся поудобнее до тех пор, пока он не причалит."] = "892299cedeab9a28288583ccf9e05af2",
	},
	["Гриманд Элмор"] = {
		["Если вы ищете лучшего мастера на этом и всех остальных континентах, значит, вы пришли по адресу!$B$BГриманд Элмор, к твоим услугам!"] = "42e10d7c6d1c5dff59458f9ee1073107",
	},
	["Грингер"] = {
		["Чем могу быть полезен?"] = "28118fefcc53acdaddf2117a97b1e13a",
	},
	["Гринкль"] = {
		["Хей, хей, хей! Я прибыл сюда, чтобы сообщить вам всем о великолепном турнире по рыбалке в Тернистой долине, но, чтобы выжить там, нужно быть достаточно $gкрепким:крепкой;, а также иметь достаточно развитый навык рыболовства, чтобы ловить рыбу в тех водах.$B$BВозвращайся, когда станешь отвечать всем необходимым требованиям для турнира!"] = "06c7b60c6b427e9bed25fe5bb168ab7a",
		["Эй-эй-эй! Если вы считаете, что умеете ловить рыбу, приходите к нам! В это воскресенье в Тернистой долине пройдет состязание рыбаков!"] = "99cd56092bd54c1d0a5b2852b38b9e5a",
	},
	["Грит Турден"] = {
		["Может, у гномов Громового Молота и быстрокрылые скакуны, но могут ли грифоны Заоблачного пика выдержать жар Великой Кузни? Навряд ли!"] = "d440ae293e3b396fde51ad230c446188",
	},
	["Гриф Дикое Сердце"] = {
		["Чем помочь надо?"] = "ff4c1db50d39977890db3fe889ea21ae",
		["У меня тебе учиться нечему. Ты $c, вот к своему учителю и ступай."] = "65ffa984c80ec793cab656acd848ac8c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Грокор"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "c0a7b5f6072ec3019bad21c645e1b66d",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "e2581a659044cdbda9365b2fd7a22202",
	},
	["Гроль'дар"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "f097ab331f582c2d79e805e164a7c169",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "5a92f47cf481eb3def2615b8693c94fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Грондаль Лунный Бриз"] = {
		["Шитье требует твердой руки. И терпения… главным образом терпения."] = "afa3c58692e1f910f1511cf81176b4cf",
		["Отправляйся в Дарнасс и поговори с Ме'линн. Теперь она будет направлять тебя."] = "2b4f7103b433f22f1e0130533daa0976",
		["Я с радостью возьму тебя под крыло. Начнем же."] = "a5bb9bf7601a2bba6b4270f85bdd04f4",
	},
	["Гроум Камнебород"] = {
		["Чего? Нету времени болтать, надо разобраться с этим заказом для папани."] = "23e45eee692218bf280d545a69ead14a",
		["Ты кое-что знаешь. Пожалуй, достаточно, чтобы я смог тебя учить дальше. Давай посмотрим, что я смогу тебе показать, да?"] = "e7e02c3d3ac0a13d76cb2cf9dc565fb0",
		["Ты больше меня знаешь, это точно. Скажу тебе так: иди поговори кое с кем. Он, конечно, станет тебя проверять, но, даю слово, он хороший учитель. Его зовут Ротгат, он работает у старого Бенгуса."] = "8cb31fa91b233530a009b37757a52a1c",
	},
	["Груббер Блумп"] = {
		["Привет. Я Груббер Блумп."] = "363e9a32646c220ede74b874d124997b",
	},
	["Грулл Соколиный Ветер"] = {
		["Здравствуй, $N, и добро пожаловать в Лагерь Нараче. Весть о твоем прибытии быстро разошлась в племени."] = "20e50f7907859f3c67714458b3ebf738",
	},
	["Грумнус Сталевар"] = {
		["И ради этого ты меня $gпобеспокоил:побеспокоила;? Да если ты дохлого кролика на спину нацепишь и побежишь по логову троллей – и то больше пользы будет, чем от хлама, который ты носишь."] = "199016ae1623083a335a02df66eb48dd",
		["$n, верно? Замечательная работа. Я возьму тебя к себе и выучу делать такие доспехи, чтобы и самому королю Магни носить не стыдно было."] = "5ff44c51f6575ac3bc79f634e821a9e6",
		["С возвращением в Великую Кузню, $n. $gПришел:Пришла; проведать старого дворфа или думаешь, что $gготов:готова; к следующему этапу обучения?"] = "a07c9ac1b4c67fa1992198a90d99379a",
	},
	["Грэхем ван Тален"] = {
		["Темная Госпожа сказала, что знание – наше главное оружие в этой войне."] = "c1ea9f1bbc1fb9412d6073bf79a02085",
		["Теперь ты $gготов:готова; к новым свершениям! Поговори с Франклином Ллойдом, что справа от меня. Отныне он станет направлять тебя."] = "b3ef331cc4f5efde29882dc6787e4557",
		["Познания в инженерном деле позволят тебе разбирать доспехи противников прямо в бою! Позволь мне показать тебе, как."] = "e9c805eb3174e0a7d6f2fc51b91c337a",
	},
	["Гуляка Дарнасса"] = {
		["Добро пожаловать!"] = "229605db995a9c242cc65986e5928a1b",
		["После фейерверков нам принесут чаши, и мы поднимем тост!"] = "6d7a0a461e2650661f34cbb62df4a64c",
		["Уж не знаю, что они держат в этих бочонках, но оно течет, как мед!"] = "73bf520ba54e6d1e7f123875ac134dc2",
		["Обязательно будь тут к началу следующего шоу фейерверков! Начиная с 6 часов оно будет происходить в начале каждого часа!"] = "9e44a7a2990575244bfb03e10d9172dd",
		["Поцелуй бы сейчас. Не подскажешь, как его получить?"] = "4bf540b1bbdebcaec03285d831690899",
