		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "c4162cb7f63061b6eae39dc6b6b814dd",
		["Разыщи Шандрину в приюте Серебряного Ветра. Она может продать тебе \"Поваренную книгу умельца\"."] = "fe8baba790f8edd0a4e3d2f680dfe89a",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "de96efe8437890d30d0aff9e01f5f7cb",
	},
	["Дарил Стак"] = {
		["Здесь сквозняк… но мне-то что? Я мертвый."] = "63cdedde8533ba7dc21f076eea1338a3",
		["Должен признать, ты достойно $gпроявил:проявила; себя в портняжном деле. Пришла пора проверить тебя всерьез…"] = "a76e41885008445eb4f1436b07ccf3ee",
		["Кто тебя прислал? Ты еще не годишься мне в ученики! Когда ты будешь $gготов:готова;, тебе скажут."] = "6628421bf475ed47d8d51a305f80ce4b",
	},
	["Дарла Гаррис"] = {
		["Куда бы вы хотели слетать?"] = "f6ea55ad6f6344693225294350de4559",
	},
	["Дарнан Мехорез"] = {
		["Мои товары из кожи и ткани – лучшие во всей долине!"] = "0f7736dc9f16d7152dca3f99e5a42807",
	},
	["Дарнасский часовой"] = {
		["Ох уж эта повсеместная жажда обогащения. Ну что же, удача тебе улыбнулась, ведь на Террасе торговцев ты найдешь аукционный дом."] = "d90f95e047a57954e455f354c946ef06",
		["Еще $gодин материалист:одна материалистка;? Ну, если ты так уж боишься за свои драгоценные пожитки, то лучше тебе, наверное, хранить их в банке Дарнасса, в центре нашего города."] = "c45c7553069860089340adb456de7764",
		["Вам нужно найти Весприста. Он присматривает за гиппогрифами у подножия Тельдрассила. Чтобы найти его, пройдите через портал на западе Дарнасса в деревню Рут'теран."] = "21666b1c2ab2afe583fd533d9f03402b",
		["Лайшина поможет тебе оформить все бумаги. Она живет на Террасе ремесленников в северо-восточной части Дарнасса. И да прославит твоя гильдия народ ночных эльфов!"] = "3eb0dbc4dec391944ba49aa445235c37",
		["Солнце уже поднялось? Вот ведь, никогда ночи не хватает! Ну что ж, Саэлиэнн всячески о тебе позаботится. Она сейчас занята своими постояльцами на Террасе ремесленников в северо-восточном Дарнассе."] = "4a2ffe6ddb889c11783a240b6fbb5753",
		["Почтовый ящик? А ты письмо отправить хочешь? Или получить? Надеюсь, в нем будут добрые вести! А ящик рядом с банком, в самом центре Дарнасса."] = "4f8593ba9dc0933eabfbe1601c8a4af6",
		["Уже многие сотни лет Алассин заботится о питомцах, которых приручают наши охотники. Мы высоко ценим его мастерство. Если ты тоже ищешь его, иди в Анклав Кенария."] = "417a4e706b4f46ae4fb091d34eec2534",
		["В основном меня научила работе с оружием Илиения Лунный Огонь на Террасе Воинов. Ты не ошибешься, разыскав ее, если хочешь научиться пользоваться новым оружием."] = "3fdb5882d52420a10cedda5c6704aa3b",
		["В тяжелые времена друид может быть очень ценным другом для окружающих. Спроси любого из друидов в Анклаве Кенария, и они скажут тебе то же самое."] = "f818dab29f5921c495fafd0e54c105fe",
		["Иокаста была величайшей охотницей своего времени. Сейчас она учит начинающих охотников в Анклаве Кенария."] = "00076a2f6e55d2922d9773ef70577aa5",
		["Сила Элуны подчиняет тебя себе! Сила Элуны подчиняет тебя себе!\n\nИди же! Разыщи Джандрию в главном зале Храма Луны в южной части Дарнасса!"] = "fe788e668631819d89ea6f47c42c2f9e",
		["Искусство разбойников привлекает многих, но лишь ночные эльфы – истинные избранники ночи. Если ты желаешь ступить на путь теней, найди Сиарну в Анклаве Кенария."] = "9955006745f984da2926e3193c72c1bf",
		["Сильданаира обучала многих стражей, охраняющих наш возлюбленный город. Я уверен, что она сможет сделать из тебя воина. Ищи ее на Террасе Воинов возле входа в город."] = "2fe98252b42a97d60efb568891e47919",
		["Алхимия? Никаких проблем, $c. Айнетиль своим терпением и мастерством превзошла всех алхимиков с Террасы ремесленников. Тебе бы стоило уже бежать туда вприпрыжку. Вприпрыжку, говорю! Ну, ступай!"] = "dd479dae533f32a3992c77a3d1aa7f7e",
		["Элегорн так стряпает – умереть не встать! Он постоянно трудится на террасе Ремесленников, готовит новые лакомства. Обязательно попробуй его Зеленый Салат Кенария, если еще осталось.\n\nА теперь, если не возражаешь, мне надо разобраться с этой суматохой по поводу пропавшего оленя."] = "7a065b152cd98b50e6ec1647535c2bc0",
		["Я, конечно, польщен, но на самом деле… А, что? Где научиться зачаровыванию? Ох, извини. Ну, тебе нужен… как там его… ммм… да, его зовут Таладан. Да, точно, Таладан с террасы Ремесленников!"] = "8efec801651f3192ea4b39d9178f4ff8",
		["За годы рыбалки Астайя выудила несколько прелюбопытных вещиц. Почему бы тебе не поговорить с ней? Найти ее можно на Террасе торговцев."] = "bd5332cda23cfb988a28235b91583693",
		["Так ты – $gбудущий травник:будущая травница;? Тогда тебе стоит посетить Фиродрена Зовущего Луну в Храмовых садах. Он тебя чему-нибудь да научит."] = "ffcf7d3fc05ebc9a1303d2c59a697fcc",
		["Мы сажаем овощи. Овощами питаются кролики. Кроликов съедает волк. Мы убиваем волка, снимаем с него шкуру и получаем мясо. Вот и весь волшебный круг жизни, или как там вы его зовете. \n\nА теперь ступай к Телонису в анклав Кенария и не мешай мне работать."] = "86a6b22447f3864053114200f5749bbf",
		["У нас считается, что ни одна смерть не должна быть напрасной. Если уж нам приходится убивать живое существо, мы забираем все, что можем. \n\nХочешь научиться правильно свежевать добычу – обращайся к Эладриэли на Террасе ремесленников."] = "c96f29161dcade9647c6f8707b27e20c",
		["Ме'линн шьет такие наряды, будто ее иглу благословила сама Элуна. Если вам такого благословения не досталось, непременно сходите к ней и поучитесь. Ее можно найти на Террасе ремесленников, это на северо-востоке Дарнасса."] = "df79484b5472d76db96b41898d02b9b7",
		["В Дарнассе много чудесных мест. Что именно вы ищете?"] = "5f49a0ce5b3654379f0db519a20b64a4",
		["Один из них открылся на Террасе торговцев. Если ты будешь держать свой путь юго-восточнее банка, то легко его найдешь."] = "9053576b60544f166b688a294bcea667",
		["Свои вещи ты можешь хранить в банке Дарнасса, что стоит в центре нашего чудесного города."] = "8eb9ba45b797263e4803382aebcf7ae3",
		["Веспристовы гиппогрифы быстро отнесут тебя, куда надо. Он в деревне Рут'теран, по ту сторону портала, что находится на западе Дарнасса."] = "6d0616990747b3cf281cc9641375724d",
		["Если вы хотите учредить гильдию, поговорите с регистратором гильдий, Лайшиной. Ее можно найти на Террасе ремесленников, это на северо-востоке Дарнасса."] = "36a062f0dc1636d9af51d4236918fc7a",
		["Лично я считаю травяной ковер Тельдрассила лучшей из постелей, но для тех, кто любит роскошь, есть отличные кровати в таверне Саэлиэнн на Террасе ремесленников."] = "5573d0a9c052f20b0f5fb6476dc53256",
		["Почтовый ящик находится возле банка, это в центре Дарнасса."] = "f051b310bb2a6de52b45a40b67fd3a3f",
		["Алассину можно смело доверить любого питомца! Он живет в Анклаве Кенария, где собираются охотники."] = "59d50b4f9dac8cf71ca0cfbdeaec5833",
		["За тысячелетия Илиения Лунное Пламя освоила многочисленные виды оружия и теперь может учить других. Ты можешь найти ее на Террасе Воинов, если хочешь поучиться."] = "9a3ffcf5f60258c99f20760ca3d68d55",
		["Здесь, в Дарнассе, ты найдешь умелых учителей, которые довели навыки избранного ими класса до совершенства за целые эпохи тренировки и преданности делу. Я проведу тебя к возможному учителю – тебе нужно лишь назвать выбранный тобой путь."] = "05f41dc20d172bc58dcbca463c852a7a",
		["Здесь, среди ремесленников Дарнасса, тысячелетие знаний может прийти на помощь избранному тобой ремеслу. Теперь скажи мне, какое ремесло тебя больше всего интересует?"] = "b653ff673ce5e58760ed8282427e63d7",
		["Друидов, стоящих на страже природы, возглавляет верховный друид Фэндрал Олений Шлем. Его можно встретить в Анклаве Кенария в северной части Дарнасса. Там же живут и остальные наставники-друиды."] = "1050e24a7181b4781e75952eb85b3d9a",
		["Тебе повезло, что ты $gприбыл:прибыла; в Дарнасс, где живет такая опытная охотница, как Иокаста. Советую тебе посетить ее в Анклаве Кенария и попроситься к ней в ученики."] = "d15a97ec9abacddad8435f5774a0eb2c",
		["Храм Луны – это дом жрецов Элуны. Здесь ты найдешь Джандрию и Ларию, которые направят тебя на твоем пути жреческого обучения."] = "5963595e8e789ae76d21d76349020da9",
		["Если тебя привлекают пути разбойников, отыщи Сиарну. Она живет в Анклаве Кенария – это вниз по спиральному пути в самом западном дереве."] = "75e196ec78d6cb7a83a96b0b2894c9b7",
		["Ты найдешь Сильданаиру на Террасе Воинов, среди стражников. Она бдительно высматривает врагов, которые могут выйти из леса к нашему прекрасному городу."] = "f44318c049c218b57b0e409073bd7f96",
		["Если ты и вправду желаешь выучиться этому искусству, то я посоветовал бы тебе Айнетиль, ученую-алхимика с Террасы ремесленников в северном Дарнассе."] = "92c77d24eda0e89d883523e9617dfaab",
		["Элегорн – искусный повар, который столетиями оттачивал свое мастерство. Если он согласится тебя учить – считай, что ты $gдобился:добилась; великой милости. Раз думаешь, что $gзаслужил:заслужила; этого, ищи его на Террасе ремесленников."] = "ed3705061b45f850ff33561c67657b78",
		["Не бывает слишком острых клинков и слишком прочных доспехов, поэтому талантливые зачаровыватели всегда в цене. Один из таких – Таладан – может научить тебя, как улучшить оружие и доспехи с помощью магии. Его можно найти на террасе Ремесленников."] = "244792d6c2e0f82f39ae6c0a4b8bc872",
		["Если поблизости нет целителя, готового залечить раны, умение оказывать первую помощь может спасти жизнь. На твоем месте я бы обратился за советом к Даннелору с Террасы ремесленников."] = "6fd835875fbe8020422ad312f515153d",
		["Обучение занимает много времени, но оно того стоит. Поговори с Астайей на Террасе ремесленников – может быть, она научит тебя чему-нибудь полезному."] = "04597ac6ff8258c56c07b668a4c288ac",
		["Фиродрен Зовущий Луну искушен в сборе и изучении различных трав. Ты найдешь его в Храмовых садах в юго-западной части Дарнасса."] = "1e49a3cf6e73b8db88f365f3278429d3",
		["Телонис – несравненный мастер доспехов. Ты $gдолжен:должна; быть $gблагодарен:благодарна;, что он не требует слишком большой платы за знания, которыми щедро делится с другими. Иди и найди его на Террасе ремесленников в северной части Дарнасса."] = "460a90211acc699941f3d86d6b4ff971",
		["Если ты надеешься стать портным, тебе определенно нужна Ме'линн. Ее можно найти на Террасе ремесленников, в северо-восточной части Дарнасса."] = "244b2695394eae58d2ff7f21af8ec998",
	},
	["Дарнат Певец Клинка"] = {
		["Приветствую. Ты желаешь выучиться искусству сражения?"] = "45a2136a6992d2a4bd174e0b70ed104b",
		["Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная:c; $c, и мне нечему тебя учить."] = "cc54bded9c0ad342e3ec1eb23083d5f2",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Двукк"] = {
		["Только попробуй назвать меня Однукком – убью и закопаю!"] = "dcf73814792bd6614277533502604599",
	},
	["Деврак"] = {
		["Мои ветрокрылы привычны к раскаленному небу Степей."] = "27c5a394b6b942d2aa0a5871fb44a353",
	},
	["Дедушка Зима"] = {
		["Да-да, конечно, скажи Дедушке Зиме, что ты хочешь получить на праздник Зимнего Покрова.$B$BХо-хо! Смелее!"] = "27687c305eeec6bfe1d1872f537fa192",
		["Нет… У меня на коленях сидеть нельзя."] = "66f90f5438555127b635f6c18ceba9ca",
		["Есть у меня одна мыслишка о том, как Дедушка Зима сегодня будет отдыхать… Я припас бутылочку \"Зимнего Покрова\" – и я намерен высосать ее до самого донышка."] = "0a5fc9eb27704fbbe32ca289b8ccbc8c",
		["С праздником Зимнего Покрова, э-э… $gмалыш:малышка;. У всех торговцев \"Пастбищ Дымного Леса\" сейчас, э-э… скидки для хороших детей, да!"] = "565d707d3fae5619e5efa2bca426483b",
	},
	["Дези Холодная"] = {
		["Мне жаль, $c, но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати."] = "1bd3c817720e43bbc720fa8704b7cdfe",
	},
	["Дейвил Крокфорд"] = {
		["Битва окончена, и люди Дарроушира спасены.$B$BБольшое спасибо вам за помощь, $n. Вы – $gнастоящий герой:настоящая героиня; Дарроушира."] = "80b02e86f5960caaa7b74c0bed1f6bcf",
	},
	["Дейн Винслоу"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "3b59c956dcfc2045fa9cad04b8290ca9",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "abe46b983f8b3369ae786ab9b4565c64",
	},
	["Дейн Линдгрен"] = {
		["Думаешь, у меня есть время на пустую болтовню?"] = "a14f5faf742204672310f8f5b8263cb5",
		["Ты кое-что умеешь, но позволь-ка показать тебе пару трюков. Авось пригодится."] = "bfdb790af74bc4bc8fd2975752784485",
		["Гораздо лучший кузнец, нежели я, это точно! Несмотря на то что я буду все отрицать, если ты расскажешь кому-то об этом, – но это правда. Тебе надо поговорить с Терумом Подземной Кузней. Если кто-нибудь и может тебя обучить, так это он."] = "09a9c4ad934397dc02876bda84bad0ff",
	},
	["Дейно"] = {
		["Приветствую, $c. Ты желаешь обрести тайное знание?"] = "c8d841d3dd0d9f3195df9fb37ffd84b4",
		["Приветствую, $c. Мне жаль тебя, секреты настоящей магии выше твоего понимания…"] = "b7091bbfed54b698c06cee9a75fe004b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "857ea30c7f6e11d987a132b4e84da4dc",
	},
	["Делишия"] = {
		["Куда бы вы хотели слетать?"] = "e9f2c6ae11c08606a3e902729508a45b",
	},
	["Дельфрум Кремнебород"] = {
		["Нечасто встретишь кузнецов так далеко от Стальгорна. Чем я могу тебе помочь?"] = "6c6565db7cbcd83084366295deee0bb4",
		["Как-то неуютно мне без крепкого гранитного потолка над головой. От этих звезд аж мурашки по коже!"] = "e50375b7265f11678a108fd87e8a8a60",
		["Да, хороша железяка, ничего не скажешь. И форма какая, и подходит хоть парню, хоть девушке… Великолепно! Я только раз видел что-то подобное, работы мастера из Великой Кузни по имени Грумнус Сталевар. С тех пор, небось, еще лучше навострился, и тебя мог бы выучить."] = "aff585eea5e8216eb73afe08f8a7dd6e",
	},
	["Демизетта Клойс"] = {
		["Чары развращают лишь тех, кто слаб духом. Не прекращай работать над собой, если не хочешь, чтобы тебя постигла такая участь."] = "c381816693d5bcf8cf6644c3ad7a0dea",
		["Тьма не примет тебя, $c. Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!"] = "2aabd37566ced1f9550e86910bb3baf8",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Денатарион"] = {
		["Да благославит тебя Ценарион, $c. Наш предводитель, верховный друид Олений Шлем, ведет нас и весь Тельдрассил к новой жизни!"] = "04deb31038105cfd74ab05f52c151823",
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; учиться, я с радостью тебе помогу.$B$BСейчас ходит много слухов о раздорах в Круге Кенария, но на них не стоит обращать внимание. Наш верховный друид Фэндрал Олений Шлем ведет к славе нас и весь Тельдрассил!"] = "765d7c8eab15fae760b184c664fb9e9a",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Дендрит Блеск Звезд"] = {
		["Приветствую тебя, $c. Добро пожаловать в Ночную Гавань и вообще на Лунную поляну. Круг Кенария рад всякому существу, уважающему силу и веления природы.$B$BПока ты здесь, постарайся хранить равновесие во всем. Нарушений здесь не любят, а наши стражи привыкли без колебаний гасить любые проявления вражды."] = "628e4025e875b588722edea856c7e595",
	},
	["Деор Деньгозвон"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "41e918ce5d8b5a41ff38961622d0549a",
		["Сейчас бы каштанов пожарить… Ммм!"] = "b6dafafd31fc1556e3a2a4d282f57535",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "ba70cc90cf6fed160c19534755c94deb",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "cc87a307413254d64af804bd33e37001",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "9e130ea2841a0a72d792c96c8e646148",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "3fabe072e57d6a47c2f6ca2b9c8134a7",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "33f7fa4705c0138ea7a4c54342903154",
		["Сезонные скидки для вас и вашей семьи!"] = "6c6b13e6f0ac323bc0364cf61cf53234",
	},
	["Джаг"] = {
		["Тром-ка! Что ты ищешь, $gнезнакомец:незнакомка;?"] = "2da316ac003f21ca893f1a240bf23d23",
		["Ты $gпришел:пришла; не по адресу. Поговори с экспертом Годаном. У него ты узнаешь больше."] = "f3fe4e0fa8ddc09f54cc1056650576fe",
		["Смерть в бою всегда почетна! Но, надеюсь, ты не умрешь слишком быстро. Все-таки чему-то я тебя научил."] = "4e6679b868c39b4cf04876157b3c3a99",
	},
	["Джаксин Чонг"] = {
		["Мы с Гликсом отлично друг друга понимаем. Он доставляет мне товары, а я делаю его богатым. Серьезно! Знал бы ты, сколько этот пират сдирает с меня за каждый пучок королевской крови… Достаточно, чтобы гоблин расплакался!"] = "e56ab09499777010cc558c0dd0ece4c2",
		["У меня множество рецептов и низкие цены!"] = "0bd8140cb84691dca36c53f2d79843eb",
		["Ты $gпревзошел:превзошла; меня! Тебе нужен более опытный наставник. Например, Айнетиль.Эта ночная эльфийка живет в Дарнассе, на террасе Ремесленников."] = "f84b4daad586c1635158e862119c4e33",
		["Вы успели превзойти меня в мастерстве! Теперь вам нужен более опытный учитель. Это доктор Герберт Галси. Он из нежити, работает в Районе Фармацевтов Подгорода."] = "6ce7cfa7b11912553573a81e9e702be1",
	},
	["Джангор Быстрый Странник"] = {
		["Добро пожаловать в лагерь Мохаче, $gдоблестный:доблестная:c; $c. Чем я могу помочь вам?"] = "e40a5faf56ab3503cf189bed6d939698",
	},
	["Джандрия"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Джаннок Поющий Ветерок"] = {
		["Ты $gцарапался:царапалась;, как кот, которого тащат под дождь, снова и снова… Я вернусь за добавкой… $B$BО, $n, я и не видел, как ты $gвошел:вошла;! Чем тебе помочь?"] = "746aa84532c45c542b365bc29ab72dbf",
		["Мы – тьма и тени. Вечные. Незримые."] = "8bcc28a32ab2390c6dbf3ac05dc5341e",
	},
	["Джаннос Легкое Копыто"] = {
		["$n, чему еще я могу тебя научить, во имя Матери-Земли?"] = "f316fce98de9499e71406388009e60c4",
		["Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, $c."] = "b6f4bdc2a8d3684c359c1880591a1f0c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Джарел Мур"] = {
		["Послушай мой совет: не садись рядом с тенью."] = "f74e7d5a245870415207560edfabf06d",
	},
	["Джарроден"] = {
		["Куда бы вы хотели слетать?"] = "8ee9e2b8b1fbeba82851331d36cb251c",
	},
	["Джартсам"] = {
		["Я могу показать, как лучше держаться на спине тигра, но только если у тебя хватит золота, чтобы заплатить за урок."] = "526f461af3793f53ec97bde2843a2b62",
		["Для того чтобы я мог обучить тебя езде верхом, ночные эльфы Дарнасса должны тебя превозносить…"] = "950e62db1899a7457b6402427589475d",
	},
	["Джаспер Скверн"] = {
		["Говори тихо и с величайшей осторожностью: одно неверное слово – и тебя здесь просто прирежут. Итак, чего ты хочешь?"] = "cd4f537e512124cae61798baa751f6f5",
	},
	["Джахан Соколиное Крыло"] = {
		["Степи с их жарким солнцем и враждебными обитателями – идеальное место для желающих испытать силу своего тела и духа."] = "18a3a77c5ae8b48a2bbaab1d5d833914",
	},
	["Дже'неу Санкри"] = {
		["Стихии говорят с нами, $c. Они делятся с нами своей мудростью, которую мы должны постичь, и секретами, которые обязаны хранить."] = "0a8aa26eccc0242964a89762467e5241",
	},
	["Джеймс ван Брюнт"] = {
		["Хотите стать кузнецом? Хотите ковать клинки, отсекающие головы врагам? Молоты, дробящие черепа? О, да. Я могу помочь, я с удовольствием помогу вам, если это повлечет за собой кровопролитие."] = "a4f5b9fe64550e019e5c5fc4f9716103",
	},
	["Джен'шан"] = {
		["Чем тебе помочь?"] = "9e572f75c6a0e8bd86745cd88bcd9126",
		["Эй, $c, ищи учителя своего класса."] = "990d212bc9e694de1969260a75b5fbb0",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "857ea30c7f6e11d987a132b4e84da4dc",
	},
	["Дженаль"] = {
		["Кругом одни заговорщики. Эти глупцы не понимают важности моего дела и стараются держать меня в постоянном неведении! $B$BНе сочти за оскорбление."] = "af91358e01b26b90df86916c42d32ec1",
		["Что я делаю? Неужели тебе не дано видеть? Я духовидец, $gгосподин мой:госпожа моя;, я вижу лучшее будущее для всех нас. Точнее говоря, я провидец.$B$BНо есть и те, кто стремится заставить нас увязнуть в вещах пустопорожних. Я сказал ему, что я духовидец, и верховный друид Олений Шлем ответил: \"Ну хорошо, миру нужны и те, кто будет копать канавы\".$B$BПока оковы пустопорожнего не будут удалены от нас, я буду помогать Кругу Кенария, перекладывая эти кучи грязи с места на место."] = "912dd407768fd71b3934d051423f5235",
	},
	["Джерон Гранильщик"] = {
		["Будучи частью Лиги Исследователей, я охочусь в этой зоне за артефактами. Говорят, в Зимних Ключах спрятаны вещи чрезвычайной магической силы… И большинство из них строго охраняется."] = "f694c689e77899c4faf5ac919d971f4f",
	},
	["Джес'римон"] = {
		["Горячий привет тебе, $c, от меня и от всей Изувеченной Длани.$B$BНу-ну, не удивляйся, $n. Даже среди самых высокопоставленных лиц Оргриммара есть те, в чьих душах скрывается тень. И даже добросердечный Тралл осознает необходимость Изувеченной Длани для общего блага орков и троллей.$B$BНо если ты здесь не для того, чтобы поговорить о моих делах, то зачем ты пришел?"] = "300f5696e7561e85ca08484375c77012",
		["Кратер Ун'Горо – это далеко на юг от Калимдора. За Тысячей Игл, в Танарисе. Высматривай большие плавающие камни… Ими помечен вход в кратер. Только осторожно… Это нелегкий путь. Хищники скрываются недалеко от входа."] = "396471ddf6b6b14abe39c3cd741bf23e",
	},
	["Джессара Корделл"] = {
		["Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда."] = "49e5864e02449db1b69ff60632939d53",
		["С тех пор как пал Даларан и был разрушен Кель'Талас, такие товары встречаются крайне редко. Но Лукан Корделл и еще несколько торговцев все еще могут выполнять наши заказы."] = "7b74123b73660b230105d037e31ae78f",
	},
	["Джессика Чамберс"] = {
		["Нет, меня самого это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!"] = "54899ff43d9fa3680bd5231fd54eae44",
		["Не хочешь исследовать какое-нибудь подземелье?"] = "9211a5a83384bc6bf667f9e87661f2b5",
		["Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон."] = "8e4dcb74091e2e615d506f3ec7d147ca",
		["Знаки любви можно раздавать романтически настроенным жителям городов и деревень. В ответ вы получите дары обожания.$b$bТе, кто вас уже обожают, могут преподнести вам дары дружбы."] = "cd40129110d4c4917a537fef57180329",
		["Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой."] = "0838f3fe0e3c17a16a7ff7d504eec929",
		["Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла."] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
		["Огненная Пропасть находится под Расселиной теней в центре Оргриммара."] = "b960d46bc6e1afd8a8048e75631efeb5",
		["Мертвые копи находятся в Луноречье, на юге Западного Края."] = "cce75935af7718f82fcb4c3d13f23020",
		["Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях."] = "58d9f5adb0c15d9e359abb8b40a54a91",
		["Крепость Темного Клыка находится в южном Серебряном бору, к северу от деревни Горелое Дерево."] = "17d13be0366794572061fb3fbb409ee6",
		["Непроглядная Пучина находится в северной части Зорамского взморья в Ясеневом лесу."] = "2d41c6e84da0f60aa520a4acc8919f87",
		["Тюрьма Штормграда находится прямо в этом городе, рядом с Кварталом Магов."] = "8b063ee787233090be02c8d7fc8e58a7",
		["Лабиринты Иглошкурых находятся на южном краю Степей, к востоку от дороги."] = "4855c8dab63ff7e92429d6df87b7b3cd",
		["Гномреган находится в западном Дун Мороге."] = "1e16c8ae0545b101ebc5ad4d9c69c248",
		["Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов."] = "fe604977d24d31743e5481d5dcda2e88",
		["Курганы Иглошкурых находятся на южном краю Степи, к востоку от дороги."] = "ae45cd449d9b601c1faa2ad7d470e04a",
		["Мародон находится посреди западного берега Пустошей, в долине Копий."] = "b32b2b77a0839ff8c1415be4d2623dd9",
		["Ульдаман находится на северной границе Бесплодных земель."] = "4324821d63a3f73937dd5abffe6fdf7f",
		["Руины Зул'Фаррака находятся в северо-западной части пустыни Танарис."] = "5521f2e5d2e37d7012ea87b75badcb01",
		["Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей."] = "7beb3ee244d9c85c277537d4ba4a2fe1",
		["Затонувший храм находится посреди большого озера на востоке Болота Печали."] = "75ed2903e0af8abe0c91025f4d1a631e",
		["Руины Забытого Города находятся в центре Фераласа."] = "863a0466292f35423e25fb6b1e18e872",
		["Город Стратхольм лежит в руинах в Восточном Лихоземье к северу от Проклятого леса."] = "d9516bdeb534c80940a3be1f4600bf04",
		["Школа некромантов, известная как Некроситет, находится в Западном Лихоземье, среди руин на острове Каэр Дарроу."] = "4414ebedf67147d4801e58071b11c237",
	},
	["Джиллиан Дубильщица"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "1d035ef80655c9d2cd4e435e275a7bba",
	},
	["Джин'ра Ночная Вестница"] = {
		["Я не обучаю таких, как ты, $c."] = "9bd1614bca66fd26e163696ba1b6b6fc",
		["Чем я могу помочь тебе, дитя?"] = "86385c0e08f5231d7ee0120c77531745",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Джина Ланг"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "24f8a464cacbadb24bac1f53d8aa22dd",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "944b9c64d35c1c1dc8e01e4d94e1e346",
	},
	["Джинар'Зиллен"] = {
		["Эй! Ты когда-нибудь нырял в океан, а? Я расскажу тебе один секрет: под водой есть такие отверстия с пузырьками, и там можно дышать! Только никому не говори – мне не нужны конкуренты по ловле моллюсков… Понятно?!"] = "4e6ffc14d0d8a4483a2dcdfc8694ccbf",
	},
	["Джинния Пушка"] = {
		["Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?"] = "385f571d2bb437e712de5a8637774ac6",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "99ae39f09db2040d0e2e3bcddb52b4b7",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Джозеф Грегориан"] = {
		["Ткань подойдет. Но я предпочитаю работать с человечьей кожей."] = "a28ef0400b8b68493cc0c0bec5e96f56",
		["Вам нужно учиться у настоящего мастера! Найдите Дарила Стака на Мельнице Таррен – вот кто поможет вам."] = "219eb27afa3b0d2ddc962f79765170b8",
		["Я примусь за твое обучение, когда наступит подходящее время… Но пока оно не наступило. Тебе предстоит еще многому научиться!"] = "e8b392cb37c329c537afc0e93b50fbad",
		["Хорошо! Вижу, мои труды не пропадут даром!"] = "094fa5433027839383a3e504a5026efe",
	},
	["Джозеф Грязнуля"] = {
		["Ах, моя милая Брэнди, как мне ее не хватает!"] = "d0de32a7070d9141f53ed58970f3f5f2",
		["Попробуй говорить в микрофоны, которые закреплены на моих КУЛАКАХ ЯРОСТИ!"] = "cbac7251f7cadd2e49d055da41a352e5",
		["Моя должность называется \"специалист по обработке отходов\"."] = "a7ed0b69c3f96a8b2db61ded1d58a42b",
		["Да уж, дом Баровых обеспечивает меня работой. Оттуда постоянно появляются какие-то отбросы."] = "03a7c357a0ab51cdaf720c6be5d6d491",
	},
	["Джон Бернсайд"] = {
		["Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?"] = "884e826914eac49c2ac85af2e236b022",
		["Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!"] = "dcd77e7267840142a221c406ad8d42b0",
	},
	["Джон-Оборванец"] = {
		["Чего ждем-с? *ик*"] = "d504ffea27d7eb3e97b337b0d8f9216c",
		["В тот день Виндзор был особенно зол – а для Виндзора это колоссальное достижение, поверь мне. Он продолжал говорить мне, что \"что-то не так\". И он был прав!$B$BМы были в сердце Черной горы, когда на нас напали злобные твари. Я говорю об орках, разумеется. Слушай внимательно, хорошо? Они так яростно бросились в атаку, что мы слышали лишь их рык да звон мечей."] = "024d63b41f43523cad602cd53f29373c",
		["Так-с *ик*… Слушай, я где-то тебя видел *ик*. Не рассказывал ли я тебе, как мы с Виндзором отбились от тридц-э… от тыщ… от миллиона орков?$B$BО-о, устраивайся, дружок, это такая история!"] = "fa6b094aa05e38c070b4b21733b2104d",
		["С удовольствием… прошу лишь, позволь мне растянуть удовольствие еще на минутку."] = "8354aacf86057a0a57136055524c8b80",
		["Один я против пятидесяти орков? Я не дурак, $n. Папа всегда говорил мне: \"Благоизюмие – лучшая составляющая пирога\", ну или как-то так, в общем, я его понимаю."] = "1be7208d0ab559b4aa9516a496480d4f",
	},
	["Джорджио Болеро"] = {
		["Да, я уже довольно давно держу тут лавку. Дела идут хорошо: здесь проходит много разных путешественников…"] = "191c0730f0b850af3afce8e3beb43593",
		["Меня превосходит в мастерстве только один портной. Говорят, он живет на острове Терамор. Вот он-то тебе и нужен."] = "9485e8cef81326a7a0116e50049a19ba",
		["Боюсь, что, прежде чем я смогу заняться твоим обучением, тебе придется набраться опыта."] = "b35756d26207fcb3c0a6292cafad396c",
		["Хорошо! Вижу, мои труды не пропадут даром!"] = "ddcbbdc4dca9d1bfc3f2a254cfd1dc1a",
	},
	["Джорди Пепелатс"] = {
		["Благодаря открытиям храбрых гномов из Гномрегана мне удалось создать свое величайшее изобретение – Транспортер материи! Теперь мне нужен гном-инженер, чтобы создать для него достаточно мощный маяк."] = "31e604263a5a40b23254a6b2433c24d0",
		["Если узнаешь, как можно улучшить устройство, дай мне знать!"] = "34aa769372e7eb86724070a5f14c6f0a",
		["Как только вы соберете устройство, останется только включить его и перенестись в милый Прибамбасск! Почти все, кто пользовались такими устройствами, попадали на площадку лицом в ту же сторону, что и до переноса.\n\nПравда, говорят, что вместо некоторых путешественников в конечный пункт прибывали их злые двойники из альтернативной вселенной, но с этим мы пока не разобрались."] = "e8a1eedcacd3813cfc32fd8b1ec97266",
	},
	["Джорик Керридан"] = {
		["Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
		["Не думаю, $c, что ты захочешь учиться у меня. Тебе нужны наставники твоего класса."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
	},
	["Джормунд Камнелоб"] = {
		["Ах, эта дарнассийская ткань – самая лучшая!"] = "5eab0d76d4ff9ea837e56c38ac2add13",
		["Ну и не умник ли ты? Ты знаешь больше, чем я, это уж точно! Я бы не стал слишком воображать о себе на твоем месте, но если хочешь продолжить обучение, поболтай с Джорджио Болеро в Штормграде. Говорят, он знает свое ремесло!"] = "852840d250a1d2a2cf4c3f13dd2cdfdf",
		["Нет у меня времени с детьми возиться! С помощником моим говори, с Утраром!"] = "5f5302a774fbbd3527130d5ba986e049",
		["Хм… ну, что-то в тебе есть, это точно. Ладно, на чем мы остановились?"] = "fc2e2e0ae153eab86ed8c1d8e1012b1d",
	},
	["Джорн Заклинатель Небес"] = {
		["Наши Степи не столь бесплодны, как кажется на первый взгляд."] = "be12953a2eb9e2b4f53206a938cf050f",
	},
	["Джули Скороварга"] = {
		["Приветствую. Я гном, наставник магов. Ну а вы – маг."] = "cdf2e086bf2b6776973657b23b505e5a",
		["Здравствуйте, $c. Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано."] = "162dfb07afee97dc4d79532fb14ed623",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "6cabdb4331ddecbb973a32e419e6be83",
	},
	["Джулия Галлина"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Динк"] = {
		["Приветствую. Я гном, наставник магов. Ну а вы – маг."] = "89ebbfb158e8bcf8fa80f49f22684c37",
		["Здравствуйте, $c. Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано."] = "a3abb68c7dc7f0e59d1317d10b3a97cd",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Дирк Громодрев"] = {
		["Добро пожаловать в усадьбу Черного Ворона."] = "a71a88515d6fa1bcf5501c0265097b6d",
	},
	["Док Миксиль-Пиксиль"] = {
		["Могу я быть полезен?"] = "c51c67b1156baa959f6271d3c07c8740",
	},
	["Доктор Герберт Галси"] = {
		["Мы с коллегами собираем все известные яды и испытываем их на наших врагах. Как только мы закончим исследования, я создам такую чуму, какой этот мир еще не видел."] = "c989bb417bf3ad34f8fec01bb109cf46",
		["Невероятно. Твои снадобья не хуже моих. Я больше не могу учить тебя, а вот орк Рогвар из Каменора, думаю, будет рад такому ученику. Ищи его на Болоте Печали."] = "f578ceea65698599fa038d8a9a944952",
		["У тебя пока не хватает навыков, чтобы заниматься со мной. Пойди поговори с доктором Мартином Фелбеном, вон там, или поднимись по скату на юго-восток к доктору Маршу. Они – Отрекшиеся, которые могут научить тебя тому, что тебе нужно."] = "183281291d4acd1b6242a8bc12427ef3",
		["$gГотов:Готова; к обучению, $n? Тогда не отставай. Путь нам предстоит неблизкий."] = "6785653724e3b6091cc91439955fe110",
	},
	["Доктор Грегори Виктор"] = {
		["Здравствуйте, $n. Я доктор Грегори Виктор, ведущий доктор травматологии Орды."] = "2638fdc24fed03d3d2affc64eca0bf76",
		["Рад видеть тебя снова, доктор $n. Я слежу за твоей работой и позволю себе заметить, что тебе пора изучить новые приемы перевязки ран.$B$BВозвращайся ко мне время от времени – и я научу тебя всему, что знаю."] = "adcbd8c041c99ea585dd49cda036f459",
		["Ты знаешь все, чему я пока могу тебя научить, доктор $n. Возвращайся, когда расширишь свою практику, и я расскажу тебе о более сложных методах врачевания."] = "283509ff38d5fe49b3dd45d5e0947aad",
	},
	["Доктор Густав ван Склифф"] = {
		["Рад видеть тебя снова, доктор $n. Я слежу за твоей работой и позволю себе заметить, что тебе пора изучить новые приемы перевязки ран.$B$BВозвращайся ко мне время от времени – и я научу тебя всему, что знаю."] = "f4e3a2c79c79518799f91abcc4d1c545",
		["Здравствуйте, $n. Я доктор Густав ван Склифф, ведущий доктор травматологии Альянса."] = "0ba18a644f30676df3277200c1ada92e",
		["Ты знаешь все, чему я пока могу тебя научить, доктор $n. Возвращайся, когда расширишь свою практику, и я расскажу тебе о более сложных методах врачевания."] = "b4c40d18e1bc694e2ebd862b96fbe637",
	},
	["Доктор Мартин Фелбен"] = {
		["Верно, раньше я был человеком. Но сейчас, $N, это не изьян, а преимущество – ведь я близко знаком с человеческими слабостями."] = "f8d646bc5e246662bfd10d01a3e55223",
		["Очень хорошо. Срежь еще кусочек плоти с одного из образцов. Проверим, чему ты $gнаучился:научилась;, и продолжим."] = "8e532ac34ab9bb5262ee3ed4d514db22",
		["Твое знание о зельях превосходит мое, но тебе еще предстоит многому научиться. Поднимись по ступеням на юго-востоке и обратись к доктору Маршу. Он покажет, что такое настоящие страдани… кхм. Твой будущий учитель – из Отрекшихся."] = "b7269b9e677d42ed7131e6719a1f24ca",
	},
	["Доктор Марш"] = {
		["Благодаря Алжернону я могу работать, не отвлекаясь на каждую травку. Если мне и суждено распрощаться с чудесами природы, это будет нескоро."] = "dbd4a28dca16161d9053687453a92060",
		["У меня больше нет знаний, чтобы дать тебе. Иди через арку и вниз по скату на юго-восток и поговори с доктором Герберт Галси. Он Отрекшийся, который может тебя научить более продвинутым техникам."] = "ef9aaac1e3da49f65602785a177bfb20",
		["У тебя достаточно нахальства, чтобы прийти ко мне учиться, но я не могу сказать того же о твоих знаниях. Пройди через арку и спустись по склону на юго-восток, там поговоришь с доктором Мартином Фелбеном. Он из Отрекшихся, и он может преподать тебе основы."] = "89dfbc51cc4699f0f3e8fbf7cf4a12d8",
		["$GПришел:Пришла; учиться? Очень хорошо. Думаю, то, что я возьмусь тебя учить, не слишком повредит нашим друзьям. Особенно если ты будешь вредить нашим врагам."] = "5c9cac6d701387d0eb5882649854f365",
	},
	["Дольча Деньгозвон"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "f9f9e7611322bf1ddbc11a3d206fbee1",
		["Сейчас бы каштанов пожарить… Ммм!"] = "ec96335ecef05c3900dab2def0ea7d06",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "871ad3477a3322d9a312056c078ef843",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "8d77629139cb2841d86e8e3ea861bc05",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "6d2f68e829351e067178b3f036cd5d75",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "4a32fbea4eafa7cc8a55a50a91ae41de",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "f328cb6cd509244010ffea357d309bfc",
		["Сезонные скидки для вас и вашей семьи!"] = "06446c93717ee24cf71146c8844d5209",
	},
	["Дон Помпа"] = {
		["На этой-то пристани? Ну, можешь сесть на корабль, который ходит к ночным эльфам. Как оно там зовется? Э-э, Аубердин, вроде. Но я ошибаться могу, я ж грузчик простой."] = "ca7d18cf048257b8138d41171774e437",
	},
	["Донал Осгуд"] = {
		["Низина Арати когда-то была нашей. С твоей помощью мы можем ее вернуть. Поможешь ли ты нам, $c?"] = "72c6e36686e172b92adf3e89a32b9bdf",
	},
	["Дональд Рабонн"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "13d2af5f294a07ae2cff1bf240fa32c1",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "43ebea4a5129c29af35af2064eb93951",
		["Могу научить тебя ловить рыбу."] = "b285645e1bdb1be37d7bfdc440534eec",
	},
	["Дорас"] = {
		["Вы не жили, пока не увидели мир со спины ветрокрыла!"] = "f7834eaebb9cc6ecebe0cae418cf5f59",
	},
	["Дорион"] = {
		["Я не обучаю таких, как ты, $c."] = "f2c2c7d6984ce15c597fe07b1c728e29",
		["Добро пожаловать в Круг Кенария, $c. Чем могу помочь?"] = "7dd7ee318342731a34bf5316088d4c74",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Дракк Крепкорук"] = {
		["Я могу делать потрясающие штуковины из материалов, которые тут можно достать. Клянусь бородой Мурадина, в этих холмах живут самые невероятные зверюги! Ступай-ка погоняй их, $n, потом расскажешь, как все прошло!"] = "ad4a6b6d0badc2d4fe6a7a1d542a117b",
		["Я состязаться люблю, а ты? Да любишь, конечно же. Поэтому сделаешь то, что я скажу."] = "ce752e682ab8f0d0c23c727db53bbcf4",
		["Я здесь не для того, чтобы с младенцами нянчиться. Ты и в подметки не годишься тем, кого я учу. Скажу больше: вид у тебя, $gпарень:девушка;, прямо-таки жалкий. Сделай милость, не отвлекай меня болтовней."] = "ae30154a118ba87fdf6f4a2c62f6344f",
	},
	["Друг Риббли"] = {
		["Не мешай мне веселиться…"] = "be9d61d931560a93f3074abf148cd50d",
		["Кажется, Стукарь налил в одну бочку слишком много! Сейчас рванет!!!"] = "f85bd951c3aa0755cff0ab158e1d261b",
		["Мне кружку эля Черного Железа. Ох, ты не $gофициант:официантка;?"] = "e52f59e5f53cbdeeadfe575ab9f95b1a",
		["Чего уставились, $gуважаемый:уважаемая;?"] = "74fec410f05cdc4e4f0a9e7100a7ad5d",
	},
	["Друзилла ла Салле"] = {
		["Тьма не примет тебя, $c. Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!"] = "2aabd37566ced1f9550e86910bb3baf8",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Друлл"] = {
		["Вздумали насмехаться надо мной, пока я прикован к этому железному шару и не могу защищаться?"] = "ed5b5a2b8d5bee46993333b4c3f3eafe",
		["Ключ от этой адской машины хранится у одного человека. Кажется, его зовут Эстон."] = "89766cf6963eb64a903985c79701ac18",
	},
	["Друльзегар Скрюг-скрак"] = {
		["Если ты хочешь охотиться за нагами, тебе пригодится любая помощь. На глубине есть расщелины, из которых поднимаются пузырьки воздуха. Чтобы вдохнуть, подплыви ближе к расщелине."] = "3c57610ceaac598ea2221dac45d2551c",
	},
	["Дугал Крыло Бури"] = {
		["Помоги!"] = "205640ebbf618a0e2d0dc454a288eec9",
	},
	["Дунгар Долгопив"] = {
		["Эти великолепные животные могут добраться в такие места, куда невозможно дойти пешком. Вы быстро долетите в нужное место, а если повезет, увидите кое-что интересное с высоты."] = "483ae8ef81d9a1fa5470403f505b2d87",
		["Куда ты хочешь отправиться, $gюноша:девица;? Всего за несколько монет мои грифоны могут доставить тебя туда быстрее, чем самая быстрая лошадь."] = "6b05ee484d45803ee175e05a07d644f4",
	},
	["Дункан Куллен"] = {
		["Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда."] = "2e4eca05cb76135045a9a7c0e66e45af",
		["С тех пор как пал Даларан и был разрушен Кель'Талас, такие товары встречаются крайне редко. Но Лукан Корделл и еще несколько торговцев все еще могут выполнять наши заказы."] = "52ce57327118edf04bd3864c3342a693",
	},
	["Дунх"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "6b8ea29137624c8512925cd734b18e4f",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "fa94f3b2a7756a7206f2d739132e099b",
		["\"Поваренную книгу умельца\" можно купить у Вулана в Деревне Ночных Охотников. Тебе она понадобится, если ты хочешь расти над собой."] = "178749ad5f34e7d82d4f95b09e30304c",
		["Я могу научить тебя готовить!"] = "3c5599de03c8689a7c59e4a9c7e86daa",
	},
	["Дух Дарроушира"] = {
		["Ах! Пожалуйста, если вы встретите уцелевших жителей Дарроушира, передайте им, что я свободен!"] = "fed623f87b4b87634f238ffb546b2df7",
		["Спасибо! Битва за Дарроушир принесла мне погибель, но ты $gосвободил:освободила; меня!"] = "f2c5356ea5dc812ceaca823c305a9fb8",
		["Наконец-то моя душа свободна!"] = "564b4c2f337c2199f444b5155ea4d428",
		["О, спасибо! Как же долго длился этот кошмар…"] = "f480a00fa10e5310e4267f26515d167f",
		["Спасибо! Вы освободили меня!"] = "7f54e67830fe9b610107dcc6ef833396",
	},
	["Дхугру Кровожадный"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "f097ab331f582c2d79e805e164a7c169",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "5a92f47cf481eb3def2615b8693c94fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Дымок ЛаРу"] = {
		["Таких, как я, зовут капиталистами, $r."] = "4249b5e676f6809f52f9c6f458cc5ae7",
	},
	["Дэн Голтас"] = {
		["Когда я выбрался из могилы, то думал, что родственники встретят меня с радостью. Но они с криками выгнали меня из деревни, и я больше не понимал их языка."] = "94095eb43627763b471b3b24bdf02a82",
	},
	["Железнус Хладосталь"] = {
		["Приветствую, $r."] = "ff6b7b64cb17b855134fc86b013b44ba",
	},
	["Живан Меднокноп"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "41e918ce5d8b5a41ff38961622d0549a",
		["Сейчас бы каштанов пожарить… Ммм!"] = "b6dafafd31fc1556e3a2a4d282f57535",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "ba70cc90cf6fed160c19534755c94deb",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "cc87a307413254d64af804bd33e37001",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "9e130ea2841a0a72d792c96c8e646148",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "3fabe072e57d6a47c2f6ca2b9c8134a7",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "33f7fa4705c0138ea7a4c54342903154",
		["Сезонные скидки для вас и вашей семьи!"] = "6c6b13e6f0ac323bc0364cf61cf53234",
	},
	["Жрец Серебряного Рассвета"] = {
		["Битва выиграна. Угроза Плети устранена – на время. Мы можем направить свои ресурсы в помощь тебе, в благодарность и для подготовки к грядущему."] = "ebde1b78097e360ae80271b45ac8ec9b",
		["Битва протекает неплохо. Силы Плети кажутся ослабевшими. Я уверен, изгнание их с наших берегов – лишь дело времени. Я направлю свою магию в вашу сторону, чтобы помочь вам в этой борьбе."] = "4d4e9052d3c36392e6211cb442ea3b1e",
		["Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет вас к дальнейшим победам."] = "0973188afdf5745ee7a53c42da926c63",
	},
	["Жрец Тени Сарвис"] = {
		["Ни одна раса Азерота не страдала так, как мы, $c. Мы все уже привыкли смеяться в лицо смерти."] = "f3c13d9b72d8b59a9be9b737dae6a6b2",
	},
	["Жрица Алатея"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Жрица Анетта"] = {
		["Я вижу, $n, что душа твоя светла. Могу ли я тебе чем-нибудь помочь?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["Не отворачивайся от Света, $c. Возможно, когда-нибудь он спасет тебя."] = "120875f188ac12780f811009b51a783b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Жрица Жозетта"] = {
		["Я вижу, $n, что душа твоя светла. Могу ли я тебе чем-нибудь помочь?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["Не отворачивайся от Света, $c. Возможно, когда-нибудь он спасет тебя."] = "120875f188ac12780f811009b51a783b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Жрица Тени Вандис"] = {
		["Чума Плети все еще свирепствует в этом районе, и нам еще многое предстоит сделать. Собери необходимые припасы и помоги вести войну!"] = "ce824b41cf0a6db8b1c15559f577b9fb",
		["Распространение чумы Плети практически остановлено. Еще несколько котлов – и мы победим! Только не забудь сделать свою часть дела."] = "9db7de5508eaac9e5611e0a7f2fbf9bc",
		["Мы научились обращать чуму Плети против нее самой, но до победы еще очень далеко! Помоги нам изменить ее котлы!"] = "6af5c07f82dbfe714f7cc1dce270aea0",
		["Мы побеждаем Плеть – измененная чума будет действовать на нежить как минимум еще один день! Но чтобы закрепить эффект, нужно как можно скорее вывести из строя следующий котел!"] = "8d077777e6b7bc9aa577494538df1334",
	},
	["Жрица луны"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
	},
	["Жубал Труполов"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "3b59c956dcfc2045fa9cad04b8290ca9",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "abe46b983f8b3369ae786ab9b4565c64",
	},
	["Жужжер Скрепокрыл"] = {
		["Я придумал интереснейший проект подземной системы транспортировки нефти… Но все почему-то говорят мне, что дело – труба."] = "d607877befae4fc8560330345158b290",
		["Покажите-ка, что у вас есть! Обещаю, вы не пожалеете!"] = "65e704bf14c873956aafc6447de33e25",
		["Я никогда не отказываю тем, кто готов учиться у меня. К сожалению, ты не $gготов:готова;! Тебе еще расти и расти!"] = "d61a0a53b1b257362de2e3db7be1604d",
	},
	["Зазывала ярмарки Новолуния"] = {
		["Ярмарка Новолуния вот-вот откроется! Зайдите чуть позже, наверняка все уже будет готово."] = "81072962754c21f425b3445d9fbaa303",
		["Ярмарка Новолуния – величайшее событие Азерота!"] = "db5e85c0e8fc397c337679dce51d896c",
		["Все верно! Ярмарка Новолуния будет здесь – как только я разгружу эти огромные повозки, поставлю палатки, открою зоопарк и наполню кружки. Возвращайся обязательно!"] = "a9e923e95ef8c0e440880eb043666f7e",
		["Не забудь купить выпивку и подарки!"] = "2eb716d676d0b1b4ecaffc7b58ade0d6",
		["Скоро будет ярмарка!"] = "3609745a4c6616a705cba94a32482147",
		["Развлекаешься?"] = "597f943bfef4a0100928324418268a5a",
		["Не видишь, я здесь работаю!"] = "28c0efd31165758238391b2842e87a69",
		["Как много тут мусорных жуков…"] = "fe440344a9bf50366eead025b3f88505",
	},
	["Зайус"] = {
		["Берегись, $c. Уважай наши традиции, иначе проклятие не минует тебя."] = "155d8f030ac2a727274571a38fa68153",
		["Я сделаю, что смогу, чтобы воспитать из тебя жреца, если ты здесь за этим."] = "a30ce7890edb2bb1c5cc75a4b04b8ba3",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "5016339405f25a1000a29e26a0caf19c",
	},
	["Залдимар Вефхеллт"] = {
		["Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?"] = "3ddc082eac22c52bb34743331a694904",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "54074b0b08d3a499512ae6fba95f3115",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Заместитель судьи Рейнер"] = {
		["Не знаю уж, о чем думали чиновники Штормграда, отсылая значительную часть армии за рубеж… когда у нас и дома полно проблем!$B$BИз Западного Края лезут воры, с востока и запада ломятся гноллы – удивительно, что сам город до сих пор не в осаде."] = "e03d3aaa8df7e98fcb210403aad69ebd",
	},
	["Зандаларский эмиссар"] = {
		["Мы, зандаларские тролли, прибыли сюда с далеких островов, потому что не можем оставаться равнодушными к угрозе, нависшей над нашим миром.$B$BПредводитель нашей экспедиции, Молтор, привел нас на остров Йоджамба у северных берегов Тернистой долины. Сейчас он набирает героев для похода в древний город троллей… в Зул'Гуруб."] = "2b07aacfb7ec7aa8d2c6dc58fbefae37",
	},
	["Зандо'зан"] = {
		["Зандо'зан из Изувеченной Длани. Чем Зандо'зан может вам помочь? Ничем! Он не станет помогать!"] = "278905793296e13c5c606639f4c4456e",
	},
	["Занза Неупокоенный"] = {
		["Я Занза, Лоа Зандалара. Я прибыл из Зандалара в этом эфирном облике, чтобы помочь моему народу. У Хаккара нет власти над моей душой.$B$BЯ помогаю тем, кто помогал народу Зандалара."] = "c8103fbcbe2d18f0cdfa4d909fa00e81",
		["В самом деле? Тогда ты знаешь, как слаба и жалка та разновидность тролльей магии, которую используют Высшие эльфы?$B$BВысшие эльфы не понимают, почему народ с их магическими способностями не в состоянии соперничать с силами тролльей магии Вуду. У этих бледнокожих оно просто в голове не укладывается. Они смирились и используют ухудшенную версию тролльих чар. Кажется, они ее называют Тайными Знаниями.'"] = "0f2be05ebc4b746b42891e97a2db2629",
		["Занза знает древние чары троллей, которые помогут вам победить Хаккара и его приспешников.$B$BЧтобы наложить эти чары, мне нужно два предмета."] = "422211fe9697e4c260bda5b4ed73aa57",
	},
	["Запота"] = {
		["Брат сказал, что на этом торговом маршруте мы сделаем большие деньги, но не сказал, что на этой стороне не будет никого живого! Если вы вдруг будете возвращаться и пройдете мимо дирижабля, не могли бы вы принести мне чего-нибудь поесть? В Оргриммаре продают отличное мясо, а мне бы очень хотелось поесть чего-то, что не сдохло пару недель назад…"] = "29ab1815cf6aff3f41bd5f69c7535753",
	},
	["Заргх"] = {
		["Посмотри-ка на это мясо. Не стоит отправлятся в Степи без хорошенького запаса провизии."] = "3cbc06359ec26be5a68c387070b4ffd6",
	},
	["Зарисса"] = {
		["Куда бы вы хотели слетать?"] = "99afa7bbff40b3ecca37eb15b8c29387",
	},
	["Заррин"] = {
		["Здравствуйте, $n. Если вы хотите научиться готовить, то вы пришли по адресу."] = "f9930fe3fe43966e931eb3d5ec87d2be",
	},
	["Зас'Тиш"] = {
		["Здравствуй, $c. Не тебя ли я недавно видел на одном собрании? Лицо вроде знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду."] = "28755471b38e6eb285e0d80db6c9498a",
	},
	["Захария Пост"] = {
		["От имени Королевского фармацевтического общества я рада предложить вам лучших скакунов, какие только есть у Отрекшихся. Эти кони прошли вместе с нами все испытания и невзгоды, и теперь они сильнее и выносливее своих живых сородичей! Взгляните и убедитесь!"] = "f167e87b57a2b94049d4b806ea806d69",
		["Королевское фармацевтическое общество не терпит дураков, как и я. Может быть, в следующий раз, когда мы будем говорить о моих скакунах, ты заслужишь полное доверие жителей Подгорода. А пока…"] = "eef6f7f6fd25d10d8ba7e4fca44b8d27",
	},
	["Звяк Пружиносвист"] = {
		["Это может вас огорчить, но дела в последнее время идут не слишком хорошо…"] = "df99ffe8f4307e58e2877badedf13a55",
	},
	["Зеврост"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "f097ab331f582c2d79e805e164a7c169",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "5a92f47cf481eb3def2615b8693c94fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Зел'мак"] = {
		["Эй, полегче. Я обучаю только воинов."] = "ca064fbb60369e53eafa38882b28ef51",
		["Чем тебе помочь?"] = "da08a8de6ae36ba7023d844f7af43f4c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "5016339405f25a1000a29e26a0caf19c",
	},
	["Землепроходец Торва"] = {
		["Здравствуйте, $c. Для одних охота – это профессия, образ жизни. Для других это просто развлечение, испытание или ритуал – в зависимости от племени.$B$BДля меня нет разницы между расами и профессиями – меня интересует лишь дух и разум. Бороться с силами природы, задействуя все свои способности – вот высшая честь.$B$BЕсли вы хотите испытать себя и снискать мое уважение, обращайтесь ко мне в любое время."] = "302082b5cf2a5247bbde060d031b8f3d",
		["Ты идешь по благородному пути, $n. Мои предки уважают твой энтузиазм, но ты не получишь моего одобрения, пока не выполнишь мои задания.$B$BТы знаешь, что тебе нужно сделать, чтобы выказать себя охотником по духу."] = "4684810582123d33350ebde21f845247",
		["\"Похоже, местные равазавры – родственники ящеров Степей. Они отличаются умом, хитростью и чутьем – или законами стаи. Самый большой из найденных мною – это Лар'корви. Он – один из наиболее опасных зверей, что я когда-либо видел. На таурахэ \"Лар'корви\" означает \"острый коготь\", но это не единственное его оружие.$B$BНе стоит недооценивать Лар'корви, если ты соберешься поохотиться на него, но я все равно помогу тебе всем, чем смогу."] = "9b861526235ee45fafee1db50791036f",
	},
	["Землепряд Маггран"] = {
		["Боюсь, меня больше нельзя назвать ни тихим, ни скромным. Долгие годы и бессчетные битвы закалили мою кожу и мой дух. Возможно, именно поэтому Кэрн и отправил меня в Приют у Солнечного Камня… Мягкий ветер и теплое солнце облегчают боль."] = "e07000c6839ce000b1b16c6b15d0533f",
	},
	["Зилзибин Барабанный Бой"] = {
		["Сейчас опасные времена, $r. Древнее зло восстает, и ему плевать, из Орды ты или из Альянса."] = "9fdec023d3ece5864f7f1093641f767e",
	},
	["Зимаель Лунный Репей"] = {
		["Хвала Элуне! Сколько же лет у меня не было посетителей!"] = "f479d49557864313202d2081a17b0dc5",
		["Когда я был молодым и жил на Темном Берегу, мои пути пересеклись с группой сомнительных индивидуумов, сторонников Сумеречного Молота. Я подружился с некоторыми из них и, к своему стыду, в конце концов забыл о своей вере в Элуну и принял веру Сумеречного Молота.$B$BЯ пробудился от охватившего меня безумия, лишь когда мне явилась Элуна$B$BПокаявшись, я начал молиться Элуне."] = "ee6ad66a7dc56723278340ce7fc9aaca",
		["На пластине чистого золота было отражено свидетельство моего раскаяния, стыда, сожаления и горести. К несчастью, адепты Сумеречного Молота нашли эту пластину и заклеймили меня как богохульника. Я был немедленно казнен, мне не дали даже завершить молитву Элуне. Теперь я навсегда связан с этим миром. Бесплотный дух, заключенный в клетку и неспособный вознестись в Пустоту. Я служу уроком всем, кто хочет предать веру Сумеречного Молота."] = "19289f6d38df9ab14e68557b881b1054",
	},
	["Зиск Ладноскрой"] = {
		["А, один из моих любимых клиентов. Похоже, ты чернокнижник определенной силы, $N. Я рад встретить тебя. Если я могу что-нибудь для тебя сделать, пожалуйста, просто попроси об этом.$B$BМой брат и я считаем, что именно такие, как ты, поведут нас в новую великую эру. Обладатель такой силы… такого контроля… исключительно вопрос времени, когда сам Легион склонится перед твоей волей.$B$BЯ не могу не позавидовать белой завистью."] = "dfd92d7ff973be700d5eaab3126b732b",
	},
	["Злобр"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "7857c55cf19a633dd72142ae5b1f6578",
		["Да пребудут с тобой духи."] = "e7a2c0dc7f07afebb450c37adc691ede",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Знахарь Узер'и"] = {
		["Существа, против которых мы боремся, обладают невероятно сильным духом.$B$BЗагляните в себя, научитесь владеть силой своего собственного духа, и вы станете сильнее, чем могли даже мечтать!"] = "48f9d9ec946770bdc62b7cf862bfbd1f",
		["В этой области обитает множество созданий, считающихся союзниками ночных эльфов. Эльфы получили доступ к силе каждого из этих созданий, и теперь пришло время, когда и Орда сможет насладиться ею. Я нашел способ, как нам заполучить эту силу и использовать для нашей выгоды.$B$BНе сомневайся в моих словах, $n. Помоги мне, и ты убедишься, что я говорю правду."] = "da8a1f5eba022a30ad8c3b4a69e03d12",
	},
	["Зорбин Дребезгун"] = {
		["Может быть, это было и не лучшее место для закупок…"] = "4878b6fdc757a0fa6ec3fdc0bd2136fd",
		["Ну, привет еще раз, $N! Уж не знаю, сколько я еще буду возиться с этой лавочкой у черта на рогах… Но, как бы то ни было, ты мне $gпомог:помогла;. Покажу-ка я тебе кое-что интересное."] = "35ce1445970071ba504febea09ce9bc3",
	},
	["Зьольнир"] = {
		["Доброго тебе дня, $gхрабрый:храбрая:c; $c. Я знаю, ты ищешь доброго скакуна. Так вот что я скажу, $gбратишка:сестричка;: ручной ящер гораздо лучше! Вот, посмотри! Все как один – свирепые, потомки настоящих лютых бестий!"] = "2429cd9dc5d70eefd9b0308799bd8d64",
		["Извини, $gбрат:сестра;, но я продаю своих ящеров только настоящим друзьям Черного Копья. Вот когда будет наше племя тебя превозносить – тогда и приходи."] = "24ae77aab73cc857fb3bef8cc78e74d1",
	},
	["Зюдд"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "c0a7b5f6072ec3019bad21c645e1b66d",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "e2581a659044cdbda9365b2fd7a22202",
	},
	["Идриана"] = {
		["Добро пожаловать в банк Дарнасса. Мы принимаем денежные вклады и предоставляем ячейки для ценных вещей. У вас уже есть наш счет, $gсэр:мэм;?"] = "72fdda7ff30be23db5fd1e0d05a37089",
	},
	["Иеремия Пэйсон"] = {
		["Хочешь купить таракана?"] = "7693cb63c5c8e9a15a4c651d5eb5c5f7",
	},
	["Изабелла"] = {
		["Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?"] = "6e9c7ec1a61b1c90100ee5b1a2b7cb90",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "6e8456199ea753ead910aea500ef3809",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "568cdabe1d3684de59b70f0a2ef0c659",
	},
	["Иззаспинс"] = {
		["Не могу помочь тебе, $n. Я обучаю только разбойников."] = "43b3f8a2dccd9bc719502a75168dd3a7",
		["Чем мне тебе помочь?"] = "efccc277549ac449f3a2ab1328a8b644",
		["У меня есть кое-что для тебя, $n. Кажется, это важно."] = "1386cec4f6af29f36bd5573434ef6346",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Илана Триас"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Ильса Корбин"] = {
		["Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком."] = "92efeb5a1bded9ddac09c94a148f02c4",
		["Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…"] = "1d00acba5fef6b2efb8c4454e9935541",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Интендант Искромет из ордена Серебряного Рассвета"] = {
		["Серебряный Рассвет приветствует тебя, $c! Меня зовут Искра Света, и я полномочный интендант Рассвета по обмундированию и материалам.$B$BПока ты сражаешься со злом под нашим командованием, тем самым завоевывая наше доверие и уважение, офицер Пьюхарт будет вручать тебе знаки доблести. Эти знаки служат двум целям: используются для улучшения своего положения в наших рядах или для покупки особых предметов.$B$BЧем больше тебя ценят в Серебряном Рассвете, тем больше станет доступных тебе предметов."] = "d2e97bc13412a95addc1ab18ef657784",
	},
	["Интендант Льюис"] = {
		["Я снабжаю Сторожевой холм, хотя сейчас это не так-то просто."] = "f25d9eb86b1a32dfb1649beab901ef4c",
	},
	["Иокаста"] = {
		["Я не обучаю таких, как ты, $c."] = "9bd1614bca66fd26e163696ba1b6b6fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Иондор Стальной Лоб"] = {
		["Ты, похоже, прирожденный лидер. Что, хочешь создать гильдию для борьбы с Альянсом?"] = "f775a0450139eacb7f76a973d4915e00",
	},
	["Иохим Бренлоу"] = {
		["Добро пожаловать в \"Синий Отшельник\" – место, где любители магии могут отдохнуть и выпустить пар. Ну, не в прямом смысле, конечно. Чего бы вы хотели, $gсэр:мэм;?"] = "386f37176e6f7b06d34487928a573d23",
	},
	["Искр Пустокоп"] = {
		["Во имя всего святого, скажи, что заберешь нас из этой глухомани. Я хоть и вхожу в Экспедицию Маршала, но готов отдать золотые зубы, только чтобы забраться тебе в рюкзак и выбраться отсюда."] = "6af8b6ef78b561f72f6edeacc7a46816",
		["Да, да, я знаю, что Даданга не любит дым. Судя по запаху, Даданга еще и мыться не любит."] = "8bd505152491e64f21b57ed618cde404",
	},
	["Историк Карник"] = {
		["Добро пожаловать в Лигу исследователей. Если тебе нужна информация, записанная в книгах, я, возможно, смогу помочь."] = "d0ef52056e69de8890c17a16c8e0a5ac",
	},
	["Йе'кинья"] = {
		["В своих исследованиях я выяснил, что гибель каждой аватары отнимает силы у самого Хаккара. Но он все равно еще очень силен, хоть и таится в глубинах Пустоты.$B$BОднажды вы уже победили его аватару, $N. Возможно, если вы повторите этот подвиг, кровавый бог ослабеет настолько, что мы сможем победить его самого.$B$BЯ составил заклинание, позволяющее вызвать аватару Хаккара в святилище Падшего Бога. Хотите сразиться с ней еще раз?"] = "aa551472a784dfcc7f33fa069f619438",
		["Приветствую, $c. Время и выпивка затупили мои органы чувств, но мой внутренний взор все еще силен."] = "bfbfb8887e0db34733a0a6ad237b1e46",
	},
	["Йелмак"] = {
		["Я занят, $N. По всем вопросам обращайся к Вууту. Этот щенок все время что-то варит. Когда-нибудь он доиграется…"] = "394b7578a863582891b710fc0e4197bb",
		["Для меня честь повстречать тебя, $n, но в зельях ты разбираешься лучше, чем я. Обратись к доктору Герберту Галси из Района Фармацевтов Подгорода. Он тебе поможет, хоть он и нежить."] = "a072b3abc76b71077e3d1be09b95da83",
		["Ты говоришь не с тем орком. Я не тренирую новичков. Иди к молодому Вууту… и постарайся говорить попроще."] = "dc5f01a7caf937c808eda68e7ed6a043",
		["Еще $gодин ученик:одна ученица;? Ну ладно. Посмотрим, чем я смогу тебе помочь."] = "d3bef4bf422a40408d5b3a0703f1e056",
	},
	["Йо Колкая Грива"] = {
		["Страсть к охоте присуща всем тауренам."] = "55a66d0b8af1c06325804f95e63b73a9",
		["Я не владею нужными тебе знаниями."] = "85e3aafdd07b5fa9e4eeb2daf1cd053a",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Каел Жнец Душ"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "f097ab331f582c2d79e805e164a7c169",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "5a92f47cf481eb3def2615b8693c94fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Кайла Смит"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "24f8a464cacbadb24bac1f53d8aa22dd",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "944b9c64d35c1c1dc8e01e4d94e1e346",
	},
	["Каймард Меднокноп"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "41e918ce5d8b5a41ff38961622d0549a",
		["Сейчас бы каштанов пожарить… Ммм!"] = "b6dafafd31fc1556e3a2a4d282f57535",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "ba70cc90cf6fed160c19534755c94deb",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "cc87a307413254d64af804bd33e37001",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "9e130ea2841a0a72d792c96c8e646148",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "3fabe072e57d6a47c2f6ca2b9c8134a7",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "33f7fa4705c0138ea7a4c54342903154",
		["Сезонные скидки для вас и вашей семьи!"] = "6c6b13e6f0ac323bc0364cf61cf53234",
	},
	["Кайра Буше"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Кайра Ветрорез"] = {
		["Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная:c; $c, и мне нечему тебя учить."] = "aff660250ac92075478bdf7475083504",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Кайта Подземная Кузня"] = {
		["Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать."] = "8ee2a69ee63c41a11aeca4da11d55e13",
	},
	["Каландрата"] = {
		["Не хочешь исследовать какое-нибудь подземелье?"] = "f70c987e98c43a9ac4f1ef6eb271008a",
		["Нет, меня самого это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!"] = "3334d2c3be49af24ec80966cd3044afb",
		["Огненная Пропасть находится под Расселиной теней в центре Оргриммара."] = "7bef92afa79765ff95f06d3660786a79",
		["Мертвые копи находятся в Луноречье, на юге Западного Края."] = "c14eefa9bf01ea21ee6c512a62f5270c",
		["Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях."] = "d34171a9fbd911b8f1bf818f71cc3f32",
		["Крепость Темного Клыка находится в южном Серебряном бору, к северу от деревни Горелое Дерево."] = "6f1db228470e4b9d299edd3c7168c063",
		["Непроглядная Пучина находится в северной части Зорамского взморья в Ясеневом лесу."] = "0e3148ee13bdc4aad5af84663b24d1ce",
		["Тюрьма Штормграда находится прямо в этом городе, рядом с Кварталом Магов."] = "8f49377bcf39a38a76d2cf7cbacbefb0",
		["Лабиринты Иглошкурых находятся на южном краю Степей, к востоку от дороги."] = "25a80704f18ee56676b132bdded0fe94",
		["Гномреган находится в западном Дун Мороге."] = "a4f613548f3f5a63415a978d891ce475",
		["Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов."] = "78e6008fbf1d737dce7812540853511c",
		["Курганы Иглошкурых находятся на южном краю Степи, к востоку от дороги."] = "9cdbd4512dccbc458675c5216058ddcd",
		["Мародон находится посреди западного берега Пустошей, в долине Копий."] = "6679f691680afda8b76a2dd04f2e7144",
		["Ульдаман находится на северной границе Бесплодных земель."] = "36de161eff379c5060e7c2e31cdc975a",
		["Руины Зул'Фаррака находятся в северо-западной части пустыни Танарис."] = "927f2bfc50de1f03c38ac6ec3198f4a7",
		["Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей."] = "aab40b74860886caa96dcfdaf979e180",
		["Затонувший храм находится посреди большого озера на востоке Болота Печали."] = "e33d4e6573f24d17efcc2b0ecf76516d",
		["Руины Забытого Города находятся в центре Фераласа."] = "89054fe6fb8e52df563c9e80702c264a",
		["Город Стратхольм лежит в руинах в Восточном Лихоземье к северу от Проклятого леса."] = "8d0c3e032d49fe079017a90965f53922",
		["Школа некромантов, известная как Некроситет, находится в Западном Лихоземье, среди руин на острове Каэр Дарроу."] = "7eddf733901dbca29a5a21752dd1ceb4",
		["Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон."] = "136e146f620b6e7197755a682b68ce84",
		["Знаки любви можно раздавать романтически настроенным жителям городов и деревень. В ответ вы получите дары обожания.$b$bТе, кто вас уже обожают, могут преподнести вам дары дружбы."] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
		["Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой."] = "b19764fa4b6d3a891fa5f750b3dd2517",
		["Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла."] = "f9432ed28b2dabcd595eddb702af9ca1",
	},
	["Каларан Ветрорез"] = {
		["Я отомщу!"] = "49fd111b49093990741931455047f8fb",
		["Моего отца убили эти твари из Котла. Мои обращения в магистрат Штормграда остались без ответа: чиновники делают вид, что этого места вообще не существует. О том, чтобы навести там порядок, и речи нет.$B$BЯ хочу отомстить, $r. Просто отомстить. По-моему, это достойная причина."] = "8abf64ca79d3bfbfd5e67c8a51929983",
		["Как ты можешь видеть, я всего лишь один человек с бестолковым дылдой-оруженосцем. Силы дворфов Черного Железа и тварей под командой Рагнароса наверняка одержали бы верх надо мной одним, но я абсолютно уверен, что $gтакой смелый искатель:такая смелая искательница; приключений, как ты, без проблем справится с обитателями кратера. Если ты решишь помогать мне, я награжу тебя богатством и сокровищами, о которых ты не $gсмел:смела; мечтать."] = "ef7bb97afba3c7564c9dafde000ac6fb",
	},
	["Калестраз"] = {
		["Даже если вы сумеете нас освободить, не победив К'Туна, мы все равно не уйдем, пока не загоним эту тварь обратно в преисподнюю, из которой она явилась. ЛЮБОЙ ЦЕНОЙ."] = "febc6c6f0212bb59db53fa246e390a6c",
		["Наша свобода не стоила бы ни гроша, если бы К'Тун остался жив. Ты – $gнастоящий защитник:настоящая защитница; из пророчества."] = "4a3616c5c52ca099ad816dfc278bf7a9",
	},
	["Калиб"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "3108806b44f37624987d36cafc8de658",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "963db5ef5555edf879e137a605643024",
	},
	["Калин Полет Ветра"] = {
		["Для безопасного спуска я даю крылья тем, кто в них нуждается."] = "095e13d4bc42c0c93f1c874f146d577f",
	},
	["Каль"] = {
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого."] = "95baad8c0ee127ac815bdd480620f4f4",
		["$C, наш повелитель Малфурион все еще не вернулся из Сна. Он – свет маяка, что указывает нам путь, и мы должны сделать все, что в наших силах, дабы сохранить этот свет."] = "d70e036d1260b6893f4c3810f9480af2",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Кандостраз"] = {
		["Тысячу лет назад, когда закончилась война Зыбучих песков, трое из нас согласились пожертвовать собой. Мы сдерживали киражей в этих залах, пока Анахронос и Олений Шлем запечатывали Ан'Кираж. $b$bКаждый из нас поклялся найти Меритру, Аригоса и Калестраза, если стена Скарабея когда-нибудь падет.$b$bИ она пала… и мы пришли."] = "60e14cbaa8435b4075f83aeb3e80dcff",
	},
	["Капитан Гарран Ваймс"] = {
		["Стражи Терамора – лучшие воины Альянса во всем Калимдоре. Наш долг – охранять законы Альянса в этом далеком краю."] = "a3944720bf739eea8f6e8620dda9802f",
		["Мы не много знаем о пожаре в таверне \"Последний привал\", кроме того, что жена Джеймса Хьяля и его ребенок не смогли спастись.$b$bМы сумели вытащить оттуда Джеймса, но с тех пор он сам не свой.$b$bУ нас множество улик, но ни одного свидетеля. Мы лишь надеемся, что с помощью стражи и бдительных жителей Терамора мы сможем раскрыть это ужасное преступление.$b$bЕсли ты захочешь помочь нам в расследовании, то остатки таверны находятся на границе со Степями."] = "c00f3b3d2d31c0618519d6001d85e5e8",
	},
	["Капитан Лободроб"] = {
		["Защищать лесозаготовки Орды в Ясеневом лесу не так-то просто, но мы никогда не боялись войны. Смерть ночным эльфам и их союзникам!"] = "79b85c8b9c23c4e542b6d52221827c9e",
	},
	["Капитан Ровноступ"] = {
		["Несмотря на то что Терамор славится своими воинами, боюсь, я ничем не могу тебе помочь."] = "04ac79bf79b4a0fe7bbe614f88b668d0",
		["$gПришел:пришла; тренироваться вместе со стражниками Терамора?"] = "0507fea60d7059874621212e7d11d203",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Капитан дозорных Лоло Долгобой"] = {
		["Да, это правда, я слеп, как крот. И пьян, как… э-э-э, пьян, как… ну, ты понимаешь.$B$BВот что я тебе скажу, $r. Я только с выпивки и соображаю. Известно ж, что когда одного чувства нет, то другие вроде как за него работают. Вот у меня со здравым смыслом проблемы, а с пьяным – просто блеск!"] = "7dbd9d808230424267a5e8139bdbae10",
	},
	["Каплак"] = {
		["Изувеченная Длань увидит Орду во всей былой славе, когда ее перестанет сдерживать робость Вождя."] = "5070548a9c45a19ece573bb4b49296f4",
		["$C – это не ко мне."] = "60044d7f82718835ed805cb5fdc7067b",
	},
	["Капрал Норг Грозовая Вершина"] = {
		["Хорошо, что на поле боя есть бывалые бойцы вроде тебя, $n! К сожалению, у нас сейчас слишком мало припасов для серьезного штурма позиций Орды.$B$BПоговори с нашим интендантом – он даст тебе задание насчет снабжения."] = "be7b74ece350a6df351c868dce888f81",
	},
	["Кар Певец Бури"] = {
		["Я могу научить тебя новым приемам езды на кодо, если, конечно, у тебя хватит золота заплатить за урок!"] = "544bf09fc5a6bba4ba78407a379f613d",
		["Знай, $c! Прежде чем я научу тебя верховой езде, ты $gдолжен:должна; завоевать полное доверие тауренов Громового Утеса."] = "843dad948139077784615fef7ef434d9",
	},
	["Караванщик Камнетес"] = {
		["Наши караваны уходят два раза в день, но будь я проклят, если Плеть не уберется с наших путей, чтобы остановить Дидье и его мулов при попытке доставить подкрепления на фронт. Самая сумасшедшая вещь, что я когда-либо видел. Если бы только у нас были героические искатели приключений, чтобы помочь защитить караван…"] = "b4e6217834a34f95034b22e071d3a451",
	},
	["Каран Могучий Молот"] = {
		["Делай свое дело, $gпроклятый:проклятая:r; $r.$B$B*Каран опускает голову, подставляя крепкую шею.*"] = "581c2c35bf04fb2d52fc1f0b35728cc0",
		["Все потеряно…"] = "bc07b7581d2615d19b9330c3df7eb939",
		["Ты считаешь меня глупцом, $r? Я ведь и сам могу подписать ей смертный приговор! С какой стати мне следует тебе доверять?"] = "db7ed4a5a553fd42836a5513fd9c8d2a",
		["Слушай внимательно, $r.$B$BНесколько месяцев назад магистрат Озер отправил посланца в Стальгорн. Они умоляли короля помочь защититься от захватчиков из Черной горы, приходящих из Красного Гребня и Пылающих Степей.$B$BПринцесса Мойра вызвалась помочь, несмотря на мои протесты. Мне выделили двадцать элитных стражников на защиту принцессы в ее опасном путешествии из озера Лок в Приозерье."] = "93b9b434b02f7bb9a2588ae09d531eae",
		["*Каран вздыхает.*$B$BПожалуй… пожалуй, что ты $gправ:права;.$B$BГоршак сказал мне, что у твоего вождя грандиозные планы. Планы, способные изменить отношения Орды и Альянса. Что тебе известно об этом?"] = "2a2b5ea32d04677b8b6c1b4d28f1a377",
		["*Каран откашливается.*$B$BМы прошли через туннель Тлеющего Ущелья в разоренную пустыню, включающую в себя ущелье. Задним числом можно сказать, что было подозрительно тихо. Единственная опасность, подстерегавшая нас, исходила от местных хищников – тварей, с которыми мои люди легко справлялись.$B$BМы достаточно легко добрались до Черной горы и пошли по каменному сооружению, как ни в чем не бывало."] = "e1e6605df1bc6199e98f74408dedd4c1",
	},
	["Каранг Амаккар"] = {
		["Приветствую тебя, $c! Добро пожаловать на фронт! Если ты ищешь достойное дело, ты $gпришел:пришла; по адресу. Мы всегда рады $gкрепким парням:способным девушкам;, желающим прославить Орду!"] = "373a32e64da03908f74c18135f0f399a",
	},
	["Карбус"] = {
		["Я не обучаю таких, как ты, $c."] = "f2c2c7d6984ce15c597fe07b1c728e29",
		["Добро пожаловать в Круг Кенария, $c. Чем могу помочь?"] = "7dd7ee318342731a34bf5316088d4c74",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Карден Деньгозвон"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "41e918ce5d8b5a41ff38961622d0549a",
		["Сейчас бы каштанов пожарить… Ммм!"] = "b6dafafd31fc1556e3a2a4d282f57535",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "ba70cc90cf6fed160c19534755c94deb",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "cc87a307413254d64af804bd33e37001",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "9e130ea2841a0a72d792c96c8e646148",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "3fabe072e57d6a47c2f6ca2b9c8134a7",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "33f7fa4705c0138ea7a4c54342903154",
		["Сезонные скидки для вас и вашей семьи!"] = "6c6b13e6f0ac323bc0364cf61cf53234",
	},
	["Кардрис Сновидец"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "93ff0e2abb20dcd5c4b04b86b60d8ab3",
		["Да пребудут с тобой духи."] = "7be5b41b6547e9fda9b4b9cb85616226",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "28f6b8de934060edb89ab0339b080fcf",
	},
	["Кари Громовой Рог"] = {
		["Я не владею нужными тебе знаниями."] = "7aef7b10c6066a85b4dcb024a35dcf16",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Карлин Редпат"] = {
		["Мы все пережили немало ужасных трагедий, но не стоит впадать в отчаяние.$B$BВместо этого надо хранить память о прошлом, чтобы однажды совершить святую месть."] = "c507517029d417a2e6d13173fcac6bfe",
	},
	["Карлс Пропеллерз"] = {
		["Здравствуй, $gюноша:девица;… Звать меня Карлс. Если у тебя есть какое-нибудь гномское устройство, скорее всего, его создал я! Впрочем, если оно взорвалось, тогда это точно не я, но вот если оно помогло тебе разбогатеть, можем обсудить авторский гонорар!$B$BАх да, если ты из Гномрегана, то лучше просто повернись на 180 градусов и иди прямо. С гномреганцами мне говорить не о чем."] = "47c3755d412dea585d1a4ce936b47720",
		["Ну, разве это не $n! Как хорошо встретить тебя снова. До сих пор я не могу полностью выразить свою признательность за помощь, оказанную мне и моим исследованиям.$B$BЧем я могу тебе сегодня помочь?"] = "5943501ff09a6c083506a7484daf7d10",
	},
	["Карн Каменное Копыто"] = {
		["Ты, похоже, ищешь знания. Должно быть, тебе нужен учитель по обращению с молотом и наковальней. Думаю, я могу повести тебя этим путем. Но только после того, как ты примешь духов и услышишь их зов."] = "b0b47cf8dcffc971f677db7811e6e84d",
	},
	["Каролек"] = {
		["Не занят ли я? Ты это о чем? Думаешь, что я тут целый день кукиши верчу? Хочешь что-нибудь купить – поговори с Хандором."] = "5dc27cf243a0b86654eea241255fe527",
		["Мне нечему тебя учить – ты и так уже знаешь слишком много. Если хочешь продолжить обучение, поговори с тауреном Уной. Ищи ее в мастерских на северо-востоке центрального плато Громового Утеса. И передай ей от меня привет, ладно?"] = "27197dd40c94aa0130b97cc1d108ba6a",
		["Ты не поймешь моих методик, не изучив хотя бы основы. Если ты и вправду хочешь учиться, поговори с Камари."] = "2fd61c589f9bb1577b01643f5801f516",
		["Изгибы и повороты Оргриммара рассчитаны на то, чтобы отбить вторжение. Можешь себе представить, как быстро здесь заблудился бы один из этих хлипких гномов? Ха! Если бы ему повезло, я бы его выследил и держал, как домашнее животное."] = "f1a951b15107960a9c72aa1be0135f4d",
	},
	["Каролин Уорд"] = {
		["С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого."] = "d727a9a6c19bda725fe90de6453f386d",
		["Я не могу учить тебя. Найди учителя своего класса."] = "d27bd058351066858c056f51bdfeb0bd",
		["У меня есть кое-что для тебя, $n. Кажется, это важно."] = "1ebfb378bca82042c76b1c5318543ecd",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "568cdabe1d3684de59b70f0a2ef0c659",
	},
	["Карос Раззок"] = {
		["Приветствую. Наши летучие мыши хорошо обучены и сыто накормлены. Мышей быстрее ты не найдешь!"] = "fa762cd2402b543f4083d66aa2a57e13",
	},
	["Каррина Мекенда"] = {
