	},
	["Катрин Лиланд"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Катрум Топорище"] = {
		["Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать."] = "5fa2b9d7e0e76cd011e8acc323829e46",
	},
	["Катум Удильщик"] = {
		["Знаешь, рыбалка – это так здорово… Умением ловить рыбу я обязан своему наставнику и лучшему рыбаку в мире – Нату Пэглу. Ты о нем $gслышал:слышала;?$B$BЕсли ищешь просветления, Нат Пэгл укажет тебе путь."] = "3972c43d4381083fbd6f3734c680f4f3",
	},
	["Ках Вестник Туманов"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "3754efa5bf514e289af226829e49e360",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "85322120ed7dcca1297d4aab61c178ea",
