		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Керас Вульфхарт"] = {
		["Мне жаль, $c, но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати."] = "a88973a558029a639cb379b7365f229a",
		["Надеюсь, ты $gпришел:пришла;, чтобы помочь освободить Низину Арати от Осквернителей. Что скажешь, $n?"] = "9a848f97bc7e29cb25689795f0cb46c4",
	},
	["Кергул Кровавый Топор"] = {
		["Не хочу тебя расстраивать, $c, но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны."] = "7fe3331e4b1c06adee7ab9eb667d175d",
		["$n, мы должны разгромить Среброкрылых Часовых! $gГотов:Готова; ли ты отправиться в Ущелье Песни Войны?"] = "11e58e60ca0813ec5ce983fe8d5fbd5f",
	},
	["Кертош"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "f097ab331f582c2d79e805e164a7c169",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "5a92f47cf481eb3def2615b8693c94fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Кил'Хивана"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "0e953fd8dfbfe1414c60a2989878d380",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "191f9771bbe3c0dfd9d726fd4f02d760",
		["Могу научить тебя ловить рыбу."] = "7709fb559a1b486ad6fbaec0f8f6f8ff",
	},
	["Кил'хала"] = {
		["Эй, дружище, помочь чем?"] = "b9c260f10777917d0aaa23c86b095d93",
	},
	["Килрам"] = {
		["Я Килрам, мастер топора."] = "9bd36faf52beb6ae72539e0731c74b9d",
		["Да, когда-то вы были закаленным ветераном… Килрам может снова сделать вас $gтаким:такой;. Способности у вас есть, только попросите, и он обучит вас искусству школы Топора."] = "6d7eb7644ad83f313e5d689284fb3b48",
	},
	["Кильдар"] = {
		["Я могу научить тебя более быстрой езде на волке, конечно, если у тебя хватит золота заплатить за этот урок!"] = "c5b64d59481d597745eaaada6e211af8",
		["Чтобы начать обучение, тебе необходимо завоевать полное доверие орков Оргриммара, $c."] = "0ad48a7977bee1530dd7069a59b4a0f0",
	},
	["Ким Буйногривая"] = {
		["$n, чему еще я могу тебя научить, во имя Матери-Земли?"] = "0b1e4654cf5625d6348cc8e5879e4287",
		["Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, $c."] = "908557c88c665ff5a3ab222467aa84c9",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Китха"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "7890c2b1ae34d8a5d70574f03c64ac95",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "1cb32f6470dcf1a2f6a434cc66bea835",
	},
	["Клавий Кнавингем"] = {
		["Друг, Штормград нуждается в твоей помощи и твоей щедрости!$B$BНаши когда-то огромные запасы ткани истощились. И теперь Штормград пытается восстановить эти запасы для производства ткани и бинтов! Пожертвовав нам ткань, ты очень поможешь Штормовому Оплоту и заслужишь уважение всех его жителей!"] = "57a0cf3e383340429113af3746750413",
	},
	["Клайд Келлен"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "2d7b16d91c48d1f95424bebad9fad5b4",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "f9765122a8b8d34eb9260fb601b38747",
		["Могу научить тебя ловить рыбу."] = "7e16cec2614e5f2a337e7a0f19d3b1fb",
	},
	["Клод Небесный Танец"] = {
		["Куда бы вы хотели слетать?"] = "8ee9e2b8b1fbeba82851331d36cb251c",
	},
	["Клод Эрксин"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "1566d430b06beb690f54132cef76af32",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "043d1db9fcbabde933fe81bd22b51be2",
	},
	["Колдун Ашкромб"] = {
		["Наконец-то! Я освобожден из этой темницы!$b$bКирин Тор послали меня из Даларана, чтобы выяснить, как у Аругала продвигается дело с нежитью здесь, в Серебряном бору. Как мы могли знать, что волшебник утратил разум?$b$bМне нужно немедленно доложить об этом беспорядке! Но прежде чем я уйду, позволь мне вскрыть заколдованный замок калитки, ведущей во внутренний двор.$b$bРаз ты $gпобедил:победила; Ретилгора, то, должно быть, переживешь и то, что за ней…."] = "417db1c71d710e4496367883630c84ed",
	},
	["Кома"] = {
		["Вы что, доверили бы свои товары гоблину?"] = "bc269ca0f3298e0f908bb9eedbbb29c7",
		["Гарантия безопасности банка – моя жизнь. Вас это устраивает?"] = "3b27a7cc7f607a01029609d1a72bc83d",
		["Мы с братьями сражались на горе Хиджал – как и те воины, что стоят снаружи. Каждый, кто решит что-нибудь украсть, будет иметь дело с нами!"] = "a90d1a70d1794a0870befff1ef52b64e",
	},
	["Командир Ашлам Смелонрав"] = {
		["Добро пожаловать на фронт, $c. Королевство Штормград направило меня сюда сдерживать растущую угрозу Плети. Здесь, в лагере Промозглого Ветра, мы ведем ежедневную борьбу за наше будущее.$B$BЕсли хочешь совершить подвиг, здесь ты найдешь предостаточно возможностей для этого… особенно когда мы пойдем на Андорал и бросим вызов тем силам, что повелевают Плетью."] = "7204425271757ed24a2756a3d1593f28",
	},
	["Командир Карл Филипс"] = {
		["Ты хочешь узнать о битвах, выигранных и проигранных на этом поле? Здесь не бывает победителей…"] = "1b77224af068edacdc86b986bb6acf01",
	},
	["Командир Мар'алит"] = {
		["Почему сейчас, $r? Я не понимаю. Еще ведь столько работы…"] = "45ecbb32f065f665b991c1a4db9e7395",
	},
	["Командир Метц"] = {
		["Я слишком занят, чтоб играть с тобой в угадайку, $r. Говори, что у тебя за дело, или сгинь с глаз моих!"] = "b5c51729cbfc4944277ef2a9a1158a7e",
	},
	["Командир Мощный Молот"] = {
		["Приветствую вас, $r. Я – командир Мощный Молот, полномочный представитель Альянса. Если у вас, $gмолодой человек:девушка;, есть вопросы об успехах Альянса в подготовке к войне, не стесняйтесь их задавать."] = "f07f5e6d40044eae745e47cfd0b2ac14",
		["Правильно, $gюноша:девушка;, военные припасы уже доставляются в Силитус. Последняя партия прибудет туда в течение $2113w дней. После этого нам останется лишь подождать, пока найдется $gгерой, способный:героиня, способная; воссоздать скипетр Зыбучих песков и ударить в гонг на помосте Скарабея. Тогда откроются врата Ан'Киража, и война начнется."] = "698eb8f32440c4b3e71e2db100213268",
		["У нас одна цель, $r. Древнее зло угрожает уничтожить всю жизнь на Калимдоре и погрузить весь мир в хаос. Оно ненавидит всех существ, созданных великими Оформителями – вечными титанами.$B$BМы – первая и последняя линия защиты от армии К'Туна. Если мы не поднимемся на бой с врагом, он уничтожит нас.$B$BВы нужны нам на этой войне!"] = "ea8c9e4b80c9fb807cffa1aa88bd86b7",
		["Отличный вопрос, $c. Последнее, что я слышал, – это то, что Альянсу удалось выплавить $1997w из $1998w медных слитков, $2002w из $2003w слитков стали и $2011w из $2012w слитков тория, нужных для фронта"] = "600752944f2ed7a5f2e5c2e398845f1c",
		["Посмотрим, посмотрим… Где-то у меня тут было записано. Ага, вот же. Так, удавник – $2047w из $2048w, пурпурный лотос – $2053w из $2055w… И, наконец, слезы Артаса – $2057w из $2058w."] = "6a21e863d9f49ec0041bd59ac1f3f839",
		["Забавно, что вы спросили именно сейчас… я как раз только что получил свежую сводку. К настоящему моменту в Альянсе собрали $2060w из $2061w кусков легкой кожи, $2063w из $2064w кусков средней кожи и $2069w из $2071w кусков плотной кожи."] = "80b3888d40c7eca0d3c8b8f9d61f3ac7",
		["Бинты, говоришь? Да, ну, если мне не изменяет память, по последним сведениям, Альянс сделал: льняных бинтов – $2076w из $2077w, шелковых бинтов -$2082w из $2083w и бинтов из рунной ткани – $2088w из $2090w."] = "ac1fc16d38645b54c1f8b2109349f841",
		["Это мне напомнило, что мне надо вскоре найти что-нибудь поесть. Насчет того, что готовят в Альянсе, мне сказали, что уже упаковано $2092w из $2093w радужного тунца. Кроме того, $2098w из $2099w жареного ящера и $2101w из $2103w пятнистого желтохвоста подготовлено и сейчас хранится в холодильнике, ожидая отправки в Крепость Кенария, в Силитусе."] = "1b0ce06896ec82f2b8d9de5f2bdfcecb",
	},
	["Командир Элигор Утросвет"] = {
		["Будь $gосторожен:осторожна;, $r. Мы, Братство Света, не столь снисходительны, как наши братья, когда надо воздать по заслугам тем, кто делает этот мир хуже.$B$BГоре тем, кто разгневает Корфакса.$B$BА теперь, если у тебя нет дела ко мне или другим членам Братства, уходи, пожалуйста, мы должны продолжить наше собрание."] = "ab082a0dacce89f2423a85518fe46a16",
		["Доспех Возмездия носили наши самые благочестивые рыцари – доспех, достойный самого Светоносца!$B$BВ последней войне погибли тысячи. С их трупов сорвали одежды и забрали в ужасную цитадель Наксрамас.$B$BГоворят, что рыцари смерти Наксрамаса извратили латы Возмездия для собственных целей.$B$BТакая трагедия…"] = "413977ef54e229a5943c4a37c970e4e7",
	},
	["Корк Гизлтон"] = {
		["А… $gклиент:клиентка;! Давайте поговорим о моем величайшем изобретении – о \"Торготроне 1000\". В нем есть все, что вам нужно… некоторые редчайшие предметы вы не найдете ни на одном рынке Калимдора… а еще его программирование не допускает торга. Какую цену вы видите, ту и платите."] = "4de54f822df981ac699c8e0f5d6eaca4",
	},
	["Королевский Инспектор Баухас"] = {
		["Я – городской чиновник, работаю над переписью населения Подгорода. Со времени нашего освобождения от Плети мы стараемся тщательно отслеживать численность населения города. Благодаря системе чар и усиленной работе над собой я способен осуществлять доступ к этим данным. Если у вас связанное с этим дело – изложите его, пожалуйста. Во всяком случае, вам следовало бы это знать."] = "24e7ef74fe54cfa4f4d5f92d6d6644ab",
	},
	["Королевский представитель Батрилор"] = {
		["Добро пожаловать в Штормград! Я сотрудник городского бюро переписи населения. Если тебе требуется справка о местонахождении того или иного гражданина, я могу тебе помочь. Познания в области тайной магии позволяют мне мгновенно подавать запросы в архив.$B$BЕсли же у тебя есть какое-то особое дело ко мне, будь $gдобр:добра; изложить его!"] = "8954229236666e51889cd5c64bc6eeb5",
	},
	["Коротышка Джон Мифрил"] = {
		["Эх! Нет ничего лучше, чем смотреть, как народ дерется на арене! Если придете сюда в нужное время, может, тоже сможете подраться!"] = "25938481b6c048114f6758db91eca1de",
	},
	["Корфакс, Воитель Света"] = {
		["Что такое Братство Света? Ну… Мы все по сути состоим в Серебряном Рассвете, только нас не сдерживают мораль, вина и бесполезные человеческие эмоции. Считай нас Алым орденом, только без их глупости, нехватки лидерства и слепого фанатизма.$B$BНе слушай командира Алых если он скажет обратное.$B$BИ не говори Тироссу, что я это сказал… Будет очень жаль, если мы подеремся и придется его покалечить."] = "087fc685b3d3b988443256863a127d39",
		["Первый комплект брони Дредноута был создан специально для Могрейна, верховного лорда Алого ордена. В этом доспехе он выглядел подобно демону из глубин Пустоты.$B$BДа, для Могрейна это был костюмчик что надо: он, бывало, врезался в строй воинов Плети с Испепелителем наперевес, а выходил с другой стороны, весь в золе и пламени."] = "d0454cc1a7f4f7f1c3d786915dd2f879",
		["Это что, серьезный вопрос? Ты правда не знаешь?$B$BЕсли ты $gтрусоват:трусовата; и боишься замарать свои ручки, то найдешь пластины из черного железа у обитателей Пылающих степей и Тлеющего ущелья.$B$BНо если ты искатель приключений, не чуждый кровопролитию, то знай: подземелья Пика Черной горы и Глубин Черной горы содержат огромные залежи пластин…"] = "0b31ddefd183ea40f98d3eae3fd516ca",
		["Только после его неоднозначной гибели рыцари и воины Лордерона стали носить одежды сходного вида в честь их павшего героя. Хотя смерть Моргейна была большой победой Кел'Тузада, связанное с этим мученичество будет ощущаться до конца войны.$B$BГде пал один, восстанут многие…"] = "338d2b414e7e0fbcec01d970b4aa4241",
	},
	["Крагг"] = {
		["Что?"] = "473178aa39ca6564bcadca7c21bbfead",
		["Не трать мое время."] = "77d31ff418c404f97bed5fd865e38ebe",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Кранг Каменное Копыто"] = {
		["Чем больше ты учишься – тем острее осознаешь свое невежество."] = "1b0b0371bfb09e817b8c77bcf69ec99f",
		["Я не могу учить тебя, $c."] = "a304d424ab3fe62125a7e67546f1595a",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Крахок Литой Кулак"] = {
		["Когда кузнец достигает такого уровня мастерства, как ты, я предлагаю ему выбрать дальнейший путь обучения.$B$BТебе выбирать не обязательно, но желательно – не хочешь же ты вечно оставаться в новичках? Мастера-оружейники и мастера-бронники снабжают экипировкой наши войска, выигрывают войны и обретают признание!$B$BНо будь $gосторожен:осторожна;, $n. Выбрав школу и выполнив задание, ты уже не сможешь изменить свой выбор."] = "96173540913b1a1b1f52b21095a0971e",
		["Я Крахок, инспектор этих ремесленников."] = "7e9d679addb34d3d0807c78bae52c702",
	},
	["Крей"] = {
		["Бена работает, как одержимая. День и ночь она корпит над своими зельями, не отвлекаясь ни на сон, ни на еду. Я знаю, что нашим союзникам-нежити необходима помощь, но начинаю опасаться, что она себе повредит."] = "98efca988aa70ef4d3d5510095903801",
		["Прежде чем у меня начали получаться зелья, я разбил больше сотни склянок. Это стекло такое хрупкое… Надеюсь, ты будешь половчее меня."] = "27bb4a92d481d7e2bb454ad5137ab13d",
		["Теперь ты знаешь все, что известно мне. Дальнейшие указания тебе даст Бена Заиндевевшее Копыто. Но не отнимай у нее слишком много времени – ей надо больше отдыхать."] = "16e14575c243b22108364e8f2d7ebf81",
	},
	["Кринкель Сталлер"] = {
		["Добро пожаловать в Танарис, $N. Чем я могу помочь тебе? На кузнеца ты не $gпохож:похожа;… Но внешний вид бывает обманчив, не правда ли?"] = "c6a4de2224006b677c95b27def90d917",
	},
	["Кристал Боумен"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "9894fe017afd5c82d452ec8f283f45f3",
		["Разыщи Шандрину в приюте Серебряного Ветра. Она может продать тебе \"Поваренную книгу умельца\"."] = "efa6e9ddc589d11d0aeee639e21deb43",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "d25a7e0932a93ba447d43caf3968c467",
		["Я могу научить тебя готовить!"] = "1e74135d166c75a3fff7f83d3426831e",
	},
	["Кристоф Уокер"] = {
		["Предназначение воина – защищать. Как защищаем мы в бою своих товарищей, так должны защищать и интересы Отрекшихся."] = "bab02b057326c5ce92b70b19685745ed",
		["Не трать мое время, $c."] = "3484fd102c48eb2fcac5e4f8ecc5347e",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Кристоф Френч"] = {
		["Могу ли я показать вам свои товары?"] = "4dac483e83b8c86599de11ca55258b2c",
	},
	["Кристофер Дракул"] = {
		["Добро пожаловать в подгородское бюро регистрации гильдий. Чего желаете?"] = "3fa902384e7e58171d9d75b73691b44d",
	},
	["Крог"] = {
		["Люди считали своей большую часть Пылевых топей, но клан Каменного Молота, с нашей помощью, смог отбросить их."] = "c54732d09cb3a1663d7e277b1364f2bc",
		["Люди построили таверну на краю Степей. Она называлась \"Последний привал\". Несколько недель назад ее сожгли.$b$bВождь приказал нам не трогать людей, пока они не нарушают наших границ, но, похоже, кто-то его ослушался.$b$bОн поручил мне расследовать это дело. Если ты хочешь помочь, отправляйся к руинам \"Последнего привала\" и принеси все улики, которые там найдешь."] = "8b40a379be9d0422acd93cc0ce1dd2fe",
		["Если Рит как-то связан с поджогом \"Последнего привала\", его надо найти и допросить.$b$bЯ отправил по его следу Огрона. Он ушел на юго-восток, в сторону главной дороги через топи. Встреться с Огроном, а затем найди Рита."] = "4d81478e7c4dd7fd2c1d6764a9644265",
	},
	["Кроум"] = {
		["Куда бы вы хотели слетать?"] = "f686b3319d4af5004c6ee3403aea3f5e",
	},
	["Крубан Черный Клинок"] = {
		["Подходите! Сейчас вы узнаете о самом необычном зрелище на всем Азероте – о ярмарке Новолуния! Ура!"] = "5a260aa92b38ae89795e971a54fac630",
		["Мальчики и девочки – дети всех возрастов – начинается ярмарка Новолуния! Ур-р-а-а-а!"] = "a61a6fccbff7a04c5809455eb91308ce",
		["Ярмарка Новолуния приближается! Веселье для детей ВСЕХ возрастов! Приходите все!"] = "f55a4bb137f50ce95546335186980a53",
		["Ярмарка Новолуния приехала ненадолго, так что поторопитесь, обязательно посетите ее сегодня!"] = "fc119632bedc0d61db36da2ac955a910",
		["Когда в городе откроется ярмарка Новолуния, обязательно сходи туда. Там столько всего интересного!"] = "2d62b0fff2691d1f7dd1c29f59793a31",
		["В городе открылась ярмарка Новолуния! Не пропусти, другого такого зрелища ты не увидишь!"] = "970860b74643126c14b1fc1d64669290",
		["Скоро в городе будет ярмарка Новолуния! Не пропусти!"] = "64ed669f2c530fdee40a973f494727e3",
		["Мы уже здесь! Ярмарка Новолуния открыта! Не пропустите самое веселое событие на Азероте!"] = "31b94b6dc8a5caae5e1dbc1f7df95f70",
		["Ярмарка Новолуния откроется в Мулгоре. Мы поставим палатки к юго-западу от Громового Утеса."] = "1a25e293039b93cebbb2befb5b4159a9",
		["Ярмарка Новолуния откроется в Элвиннском лесу. Мы поставим палатки к югу от Златоземья."] = "6846798e3704084cbf990bb534e12271",
		["Ярмарка Новолуния сейчас проходит на золотистых равнинах Мулгора, к юго-западу от Громового Утеса. Не пропусти!"] = "9de69159b963036fce4d96021d77e77c",
		["Ярмарка Новолуния сейчас проводится в Элвиннском лесу, к югу от Златоземья. Не пропусти!"] = "08d752ff31f6bfde58fc1f526e124ab1",
	},
	["Крульмоо Полная Луна"] = {
		["Лучшие шкуры получаются из тех кодо, которые прилегли отдохнуть в этой глуши."] = "67523c45386916357dd48fdb7eb1a7d6",
		["Теперь ты знаешь все, что знаю я. Отправляйся к таурену Уне. Ее можно найти в северо-западных мастерских на центральном плато Громового Утеса. Она продолжит твое обучение."] = "bffaa502fd9b791647a5cfdc9c001744",
		["Я не предлагаю обучение новичкам. Ищи таурена Валдора в Пещерах Стенаний, здесь, в Степях. Он поможет тебе со всем чем надо."] = "4b0168981471cd2230e7238c590e1752",
		["Ты $Gпришел:пришла; учиться? Стряхни с одежды дорожную пыль – и приступим к работе."] = "7c9d448728e77caa310e938972d07ce1",
	},
	["Крумн"] = {
		["Предки учили нас, что один в поле не воин – каким бы сильным он ни был. Хочешь ли ты прославить Громовой Утес, создав гильдию?"] = "3e32631ac3a950dee327a67b4a766065",
	},
	["Кса'йера"] = {
		["Берегись, $c. Уважай наши традиции, иначе проклятие не минует тебя."] = "155d8f030ac2a727274571a38fa68153",
		["Я сделаю, что смогу, чтобы воспитать из тебя жреца, если ты здесь за этим."] = "a30ce7890edb2bb1c5cc75a4b04b8ba3",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "5016339405f25a1000a29e26a0caf19c",
	},
	["Ксао'цу"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "3e8648aa82161723a67251338bf73c39",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "219bae0db1dc3bac08b33887cbea7f96",
	},
	["Ксар'Ти"] = {
		["Я смогу обучить тебя новым приемам езды на ящерах, если, конечно, у тебя хватит золота, чтобы оплатить урок!"] = "3b10621402a461476ec028521e9fb4e0",
		["Для того чтобы я обучила вас верховой езде, $c, вас должны превозносить в племени Черного Копья."] = "b3696ab9380b9a74f4dbfea7f6fda446",
		["Я не могу учить тауренов езде на ящерах."] = "991e17bc5cedbda60de365b1ffa51bb6",
	},
	["Ксор'джуул"] = {
		["Чем тебе помочь?"] = "da08a8de6ae36ba7023d844f7af43f4c",
		["Эй, $c, ищи учителя своего класса."] = "3a75f8b0a2ec11bc929978a4d421dc5a",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "5016339405f25a1000a29e26a0caf19c",
	},
	["Кузнец Аргус"] = {
		["Прошу прощения, но я сейчас несколько занят изготовлением подков для Вернера Осгуда из Озер."] = "80c8a703f2783e988393cdc3f26954dd",
	},
	["Кузнец Углежог"] = {
		["Если что-то сломалось, Шлакодрев мигом починит!"] = "51031711691097d768356cfcd57947ae",
	},
	["Кургул"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "4e1a9fddd86d3d21099d60aa02fea747",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "200fc4a4b57ca0db7de99023c501ea23",
	},
	["Курден Жилотяг"] = {
		["Не хочу тебя расстраивать, $c, но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны."] = "7fe3331e4b1c06adee7ab9eb667d175d",
		["Ты хочешь сражаться в Ущелье Песни Войны? Лок'тар огар, $c!"] = "61dae5f4ed0e4cb3f60d344587e21b7c",
	},
	["Курьер Удар Молота"] = {
		["Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов."] = "c94ca2feeaad2ed6fcb17744b822fad7",
	},
	["Кхур Острый Рог"] = {
		["Я поставляю сюда разные предметы, необходимые для колдовства и алхимии."] = "3407714a9aac3f0bbd78877a9a9f2f09",
	},
	["Кэрн Кровавое Копыто"] = {
		["Приветствую тебя, о $gюноша:дева;, и добро пожаловать в Громовой Утес. Здесь ты найдешь надежное убежище от бедствий и невзгод. Здесь рады всем, кто принадлежит к Орде.$B$BЗнай: духи прошлого и будущего оживают в этом священном месте. Воздай им должное – и да воздастся тебе."] = "6a6507689e26d6a64d8cd2d70050e9b6",
		["А, молодой воин! Участвуешь в Детской неделе, так? Старику приятно слышать, что ты подаешь другим пример, которому они, несомненно, последуют.$B$BБуду рад принести пользу тебе и парнишке. Хмм… какой же совет ему дать? Слушай волю духов, да… ну и овощи, заодно, кушай, они полезные…"] = "b7a8229dca2676591932185ee439b12b",
	},
	["Лайо Звездный Всполох"] = {
		["В этих отходах, $c, таится прошлое. Будь осторожен: мы не должны разбудить его."] = "72d9e590ddf6bf219b208c8b157ddb5c",
	},
	["Лайрд"] = {
		["Хоть Темный Берег и опаснее побережья Тельдрассила, многие рыбаки предпочитают трудиться именно здесь."] = "40cb7a31eb60d273876ed5e0a23aa52f",
	},
	["Ланко Дальний Выстрел"] = {
		["Что предпочитаешь: ружья или луки?"] = "92447dfb6a16198c949c7f1b1177982f",
		["Я не владею нужными тебе знаниями."] = "85e3aafdd07b5fa9e4eeb2daf1cd053a",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Ланти'га"] = {
		["Здесь была великая битва. Много великих битв."] = "f9fe6067b476d43bd34c6ff1b4e89b22",
	},
	["Лара Мур"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Ларимейн Пардью"] = {
		["Мне кажется, ваших умственных способностей недостаточно для постижения тонкой магии порталов."] = "6169b63082c1481ee1b292a6bd277450",
		["Тебе повезло быть $gодним:одной; из нас – ведь только маг сможет создать портал для возвращения сюда. Я могу научить тебя, если хочешь."] = "c0b64230899c1f169032e2124bab7479",
	},
	["Ларион"] = {
		["Тьфу! С этими паразитами ни сна, ни отдыха! Вы их не видали?$B$BПрыгнуть бы в трубу да убраться от них подальше!.."] = "da1e790ce76a6ecf39767ddfb4578763",
	},
	["Ларис Обалдуй"] = {
		["Изумительно, правда? Все эти артефакты, реликвии…$B$BНе знаю даже, чем восхищаться в первую очередь – их размерами или историей. Мне еще столько всего предстоит узнать…$B$BКстати, говорят, что многие расы имеют тесную историческую связь с ночными эльфами."] = "42caaa998442825e5b9fbce4fbeebb15",
		["Посмотри на эти образцы! Что это значит? Что это значит? Мне понадобится время, время, чтобы посмотреть на всю эту информацию. И мне понадобится больше информации. Информацию я не могу получить… проклятье! Думай, Ларис, думай!$B$BЧто ты собираешься сделать? Что?!$B$BДолжен быть выход!"] = "325202f61bd075f89ee398965028ddbf",
		["Ну, не то чтобы я этого не знаю… Похоже, это зависит от области обитания. Одни расы говорят \"слизь\", другие – \"слизнюк\"…$B$BВсякий раз, когда я сталкиваюсь со слизью, слизнюком или слизненышем, по сути это оказывается одним и тем же существом. Разница, видимо, только в среде обитания. Вот потому-то нам и нужен чистый экземпляр."] = "b987f43f6e42e054381a65cb49093b00",
		["Чистым образцом можно назвать лишь тот, что не подвергся инородному влиянию. Существ нужно искать в самой естественной и свойственной им среде.$B$BВ месте, до которого еще не добралась цивилизация, которое еще не изменили господствующие расы Азерота. В месте, которое было бы… нетронутым."] = "f2a8da67c8ee4c6d3a3393f105fc59f6",
		["Это определенно не в Восточных Королевствах, это точно.$B$BОно должно быть где-то в Калимдоре, но достаточно далеко от Орды и других рас. В месте, нетронутом Расколом – то есть вдали от ночных эльфов.B$BЯ бы предположил, что оно может быть в каком-то охраняемом месте… в долине или в кратере. Не знаю. Я просто перебираю возможные варианты. Извини, что не могу ничем тебе больше помочь."] = "5064c5f5065d6cee4390d39aafdd640a",
	},
	["Лария"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Лау'Тики"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "52b3b18d2b8947ab081ad8d1df22d820",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "d84c6f0cdc86a0609eb3d742d5e17380",
		["Могу научить тебя ловить рыбу."] = "3e45c9e175b521f290ec43f5df6d099e",
	},
	["Леди Хотешем"] = {
		["Мне жаль, $c, но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати."] = "c3b7867dcd5ddb0aafe672da55946ea2",
	},
	["Лейтенант Мурп"] = {
		["Здравствуй, $r! Я лейтенант Хаггердин, отвечаю за вербовку новобранцев в Стражу Грозовой Вершины.$B$BКогда ты станешь достаточно $gизвестен:известна; и $gуважаем:уважаема; в наших рядах, возвращайся ко мне, и я, может статься, повышу тебя в звании. А если тебе случиться потерять знаки различия, я выдам тебе новые."] = "3df9d5b384b97d45f30cd9ba4c8d25a8",
	},
	["Лексингтон Мортейм"] = {
		["Мне кажется, ваших умственных способностей недостаточно для постижения тонкой магии порталов."] = "94b6577e5651410a517d8b6494716ade",
		["Тебе повезло быть $gодним:одной; из нас – ведь только маг сможет создать портал для возвращения сюда. Я могу научить тебя, если хочешь."] = "3de4dfc277400108c32e9317af807f3a",
	},
	["Лекслорт"] = {
		["Нет времени на разговоры."] = "9da1b7ac9439c020560017306b57106d",
	},
	["Леланай"] = {
		["Клянусь грацией Элуны, я счастлив предложить тебе лучшего скакуна во всем Тельдрассиле, а возможно, и в мире – саблезуба. Годами воинство Стражей полагалось на этих помощников.$B$BНе спеши, друг, осмотрите друг друга ко взаимному удовлетворению. Я уверен, что ты не будешь $gразочарован:разочарована;."] = "a781c38bfffdae4147fb52746afd65fc",
		["Увы, $c, в Дарнассе и среди ночных эльфов Тельдрассила ты не считаешься $gдостойным: достойной;. Лишь когда ты зарекомендуешь себя делами, а не только словами, тогда я открою тебе доступ к своим верховым животным."] = "f0e0e0355a74b78bd4d0da79fda2ad22",
	},
	["Ли Браун"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "13d2af5f294a07ae2cff1bf240fa32c1",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "43ebea4a5129c29af35af2064eb93951",
		["Могу научить тебя ловить рыбу."] = "b285645e1bdb1be37d7bfdc440534eec",
	},
	["Лигерфа Меднокноп"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "f9f9e7611322bf1ddbc11a3d206fbee1",
		["Сейчас бы каштанов пожарить… Ммм!"] = "ec96335ecef05c3900dab2def0ea7d06",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "871ad3477a3322d9a312056c078ef843",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "8d77629139cb2841d86e8e3ea861bc05",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "6d2f68e829351e067178b3f036cd5d75",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "4a32fbea4eafa7cc8a55a50a91ae41de",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "f328cb6cd509244010ffea357d309bfc",
		["Сезонные скидки для вас и вашей семьи!"] = "06446c93717ee24cf71146c8844d5209",
	},
	["Лизбет Шнайдер"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Ликоста Меднокноп"] = {
		["Не забудьте запастись оберточной бумагой! Красиво упакованные доспехи и оружие – лучший подарок на праздник Зимнего Покрова для семьи и друзей!"] = "f9f9e7611322bf1ddbc11a3d206fbee1",
		["Сейчас бы каштанов пожарить… Ммм!"] = "ec96335ecef05c3900dab2def0ea7d06",
		["Пусть веселится всяк – и богач, и бедняк! Покупайте лакомства Дымного Леса на праздник Зимнего Покрова!"] = "871ad3477a3322d9a312056c078ef843",
		["Обязательно скажи Дедушке Зиме, какой подарок ты бы $gхотел:хотела; получить на этот Зимний Покров!"] = "8d77629139cb2841d86e8e3ea861bc05",
		["С праздником Зимнего Покрова! Отпразднуйте его как следует, с дымнолесскими лакомствами!"] = "6d2f68e829351e067178b3f036cd5d75",
		["Пришло время отличных сделок! Фа-ла-ла-ла-ла!"] = "4a32fbea4eafa7cc8a55a50a91ae41de",
		["С нашей фермы прямо на вашу тарелку! \"Пастбища Дымного Леса\" – неповторимый, устойчивый вкус!"] = "f328cb6cd509244010ffea357d309bfc",
		["Сезонные скидки для вас и вашей семьи!"] = "06446c93717ee24cf71146c8844d5209",
	},
	["Лилиам Шпиндель"] = {
		["Посмотрим… 14 плюс 7, два в уме… хм, да?"] = "fd0b861b10455c71be1e923c485a65a9",
		["Твое мастерство растет не по дням, а по часам! Я уже не смогу научить тебя чему-то новому, а вот Пружиннер Шумотор точно сможет! Ищи его в Стальгорне. Удачи!"] = "6b140e4603fdd16e06d3034228aceaa4",
		["Когда-нибудь ты сможешь у меня поучиться, но не сейчас! Почему бы тебе не поговорить со Спрайт Прыгозубчик? Она стоит справа от меня. А ко мне приходи, когда опыта наберешься!"] = "5aab1597c28681a02a024175d48768ce",
		["Да, ты меня не $gразочаровал:разочаровала;! Теперь, когда все готово, можно и начать обучение!"] = "6a74e89996624c797ad847ab32ebf1f8",
	},
	["Лина Стовер"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Линкен"] = {
		["Это страшная тайна… даже для меня!$B$BХорошо, что вы нашли меня – по крайней мере мне не приходится прятаться в кустах или под горой."] = "c1f7d0e54a5d6f4ffd50c716ddb1a124",
		["Давным-давно я встретил путника, и он сказал мне: \"Уметь – значит владеть\".$B$BКак по-твоему, что он имел в виду? Тогда я ничего не понял, да и сейчас, по правде, не понимаю…"] = "4882d4a03c1208355c763c1a0bc07069",
		["Когда я блуждал по кратеру после крушения, то вспомнил, как кто-то однажды говорил мне… \"Иди вверх, вверх в горы\", – прозвучал голос в моей голове.$B$BПрислушиваясь к нему, я и оказался здесь, $N!"] = "6c0ca67e97b5ad3215ba128332af2f28",
		["Привет! Рад снова видеть вас, $n. Ну что, как там мое первое задание? Если вы с ним справились, то у меня найдется и второе!"] = "a34ff43e735f0935b3153721bdb9bdf7",
		["Вам ничего не говорит мое имя? Возможно, мы были знакомы давным давно… $B$BКажется, меня назвали в честь чего-то важного…"] = "de7708324e7d052ec52f6108981bb2a8",
		["Я… Я не помню, как попал сюда…$B$BКажется, я плыл на… плоту…$B$B"] = "7604f31c3f3ca5119c647e30d4073393",
		["Плати, и я многое расскажу…$B$B Ой, это ты, $N! Не бери в голову…"] = "b6b61d53c84c4166df1b5f956114aa9f",
	},
	["Лирия дю Лак"] = {
		["Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком."] = "92efeb5a1bded9ddac09c94a148f02c4",
		["Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…"] = "1d00acba5fef6b2efb8c4454e9935541",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	["Ллан Бишер"] = {
		["Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком."] = "0a37426688f72de523d491b07d11f473",
		["Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…"] = "8493fe09c36205db0684a4321f2d5dcf",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Ло'хату"] = {
		["Здравствуй, $c.$B$BСтражи позволили мне остаться в лагере, если я буду сидеть тихо и никому не мешать. Ну, ты же понимаешь, дипломатия – наше все.$B$BЯ провожу исследования возмущений земли, а им это на руку, так что мне разрешили тут быть под соусом \"укрепления шаткого союза между расами Азерота\". Хочешь мне помочь? Я только рад. Только прошу, сиди тихо и никому не мешай."] = "f54143d6861ddef271769d60b550b493",
		["Раз уж вы мне помогли, я расскажу вам все, что знаю об этой земле. Знаю я немного, но, может быть, я вспомню что-нибудь такое, что вас заинтересует."] = "898b582dd44193bf71686d4995bc5367",
		["Я немногое знаю о ночных эльфах, но говорят, что давным-давно, когда они еще владели священным искусством тайной магии, Азшара была величайшей среди них. Прекрасная леди, которую они называли королевой. Увы, но ее пристрастие к магии погубило ее… и привело к ужасным последствиям для всего мира."] = "cadc0e431f4794433c9f20b321f3f84d",
		["Когда-то этим великим городом ночных эльфов правили могущественные маги-высокорожденные. Но потом на них пало проклятие. Теперь они бесплотными духами рыщут по земле, а их город захватили наги из клана Бича Злобы. Похоже, этих полузмей интересуют артефакты высокорожденных, оставшиеся в руинах."] = "177b136c703d996695ff9d9a6ee3304e",
		["Говорят, что на севере живет могущественный маг-человек, который зачем-то следит за тамошними землями. Сам я там не был, но мне рассказывали, что он всегда рад гостям и щедро платит тем, кто ему помогает."] = "ce97a3f0d9b87cbf8e4913c174a68681",
		["Я был свидетелем многих бедствий, которые постигли фурболгов за последние несколько лет. Но я так и не выяснил, почему они изменились. Может быть, их коснулась чума из Оскверненного леса? А может, они просто утратили свое миролюбие и ожесточилось на мир? В любом случае они враждебно относятся ко всем, кто приходит в их земли."] = "b660919fd15bb4acba5ab26eedc550ac",
		["Самих синих драконов здесь нет, но последователи Малигоса здесь. Я не знаю причин этого, но могу сказать тебе следующее: где бы ни быи синий дракон, можно ожидать тайной магии. Я не удивился бы, если бы дракониды здесь что-то защищали… может быть, что-то, что оставили за собой высокорожденные."] = "ff66933a79e40c4363ca877e0bc40aab",
	},
	["Логанаар"] = {
		["Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя."] = "922a94a8f826437fe0370bdcd6a587ac",
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты здесь, чтобы тренироваться, я буду рад потренировать тебя.$B$BСкоро придет время, когда зов Изумрудного Сна завладеет тобой. Ты впадешь в летаргию на долгие годы и будешь ступать среди чистейших форм. Именно там и тогда состоится твое окончательное обучение."] = "1d12fd8e421d229eea70c7677a2daeca",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Локтос Зловещий Торговец"] = {
		["Братство Тория не тратит свое время на всякую мелочь. Ступай отсюда."] = "807f545aa510396b39fd74ed72c9abcb",
		["Братство Тория обладает знаниями, необходимыми, чтобы изготовить священные оружие и доспехи Повелителя Огня, но нам не хватает людей, чтобы добыть нужные для этого материалы.$B$BЯ, Локтос Зловещий Торговец, получил от братства полномочия обменять лучшие рецепты на материалы, собранные в Огненных Недрах.$B$BСкажи, что ты предлагаешь, $r."] = "30d968320ab86521f066be7db8986c04",
		["Сульфуронский слиток?! Не может быть! Он должен быть у меня! Должен! Должен!$B$B$R, я уполномочен щедро наградить вас за этот слиток. Возможно, вы хотели бы узнать секреты Руки Рагнароса? Сульфурас, идиот! Легендарный молот Повелителя Огня."] = "ffe6ef04a13e4da40d3147386221790a",
		["В обмен на один сульфуронский слиток я уполномочен выдать вам одну копию чертежей сульфуронского молота.$B$BВы, должно быть, думаете: \"Зачем мне сдался этот молоток, если мой все равно лучше?\"$B$BЯ вам вот что скажу, $gгосподин:дамочка;: сульфуронский молот – это нечто совершенно особенное!"] = "2d38739dd99aac211a82868d39e682e5",
		["Видишь ли, все что тебе необходимо сделать, – это выковать сульфуронский молот и найти глаз Сальфараса. Совмести их, и получится Сальфарас! Ну, я не собираюсь забивать тебе голову технической информацией, как-то: где, как и когда тебе можно найти глаз Сальфараса. Я уверен, ты выяснишь все это $gсам:сама;. Просто подпишись под контрактом, скрепляющим наше соглашение – и делу конец."] = "436fa6a143302d46598f8cf4299ea9d9",
	},
	["Лорамус Многоног"] = {
		["Ты их видишь, $gсмертный:смертная;? Нет… едва ли. Тебя видят, а ты не видишь – вот твой дар и проклятие."] = "f00870b9a046eed91eb4d0128f2dcee7",
		["В годы войны Разелих Осквернитель был одним из самых опасных приспешников Владыки Каззака. Когда Легион потерпел поражение и Каззак отступил в Гниющий Шрам, Разелиху было приказано закрепиться в Выжженных землях.$B$BВ то время как Альянс воевал с Ордой в других краях, Разелих объединял под своей властью разрозненные секты Совета Теней и жестоких огров Молота Ужаса."] = "d1af7e5517ae83c4c66dff4c1ff060ca",
		["К несчастью, мудрость Тралла привела к окончательному укреплению связи между владыкой демонов и его приспешниками. Именно полк Требора ускорил объединение демонов, Приверженцев Тени и огров. Соблазн заполучить почти бесконечную власть и бессмертные войска заставил предводителей этих сил скрепить договор кровью."] = "3726dcf3467f198a1a4e87d1350ab5d0",
	},
	["Лорд Виктор Нефариус"] = {
		["Надеешься, что я буду трепетать перед мощью легиона, который ведет $N?$B$BТы для меня ничто. Меньше, чем ничто. Пожелай я видеть твою голову, ее бы принесли мне на копье.$B$BТы $gсовершил:совершила; ту же ошибку, что и все смертные.$B$B*Лорд Виктор Нефариус вздыхает.*$B$BВремя творит странные вещи с теми, кто распоряжается им, словно деньгами."] = "5283b76d0c71a7568935cb1ce8af6973",
		["Ослепленные жаждой славы, вы были уверены, что темп игры зависит от ваших действий. Можете ли вы представить, как наивно это звучит для такого создания, как я? Создания, которое может, если того пожелае¬ заставить ваши прекрасные мысли взорвать изнутри серую массу величиной с орех, плавающую в ваших черепах…"] = "747904c03bd92809a1a0c31aba9a13d5",
		["Это очень просто. Дайте-ка я подведу итог…"] = "130699ec6a671fa53155b654690ba9cb",
	},
	["Лорд Грейсон Тенелом"] = {
		["Да хранит тебя Свет в этот день."] = "0635f703e43c62457aadee823a30493b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Лорд Тони Романо"] = {
		["Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
		["Не думаю, $c, что ты захочешь учиться у меня. Тебе нужны наставники твоего класса."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Лорна Утренний Свет"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Лослор Рудж"] = {
		["Добро пожаловать в Поселок Сталежара!"] = "f4728e16ba0ebf0c0e140d78d64f6dd7",
	},
	["Лоуренс Шнайдер"] = {
		["Жизнь – словно изысканно вытканный гобелен."] = "e70d13a96c407b1d174c59f1f077a835",
		["Хмм… То, что ты хочешь знать, выше моего разумения. Поговори с Селландусом из суконной лавки Ларсона – прямо по дорожке и направо. Это он меня всему научил!"] = "35b7486429188df700dbf11b3bbcbd82",
		["Ну что ж, начнем наше путешествие по миру портняжного дела."] = "c5f30755100cfd7f05cda25a366d0602",
	},
	["Лукан Корделл"] = {
		["Если ты достаточно $gопытен:опытна;, я с радостью поделюсь с тобой своими знаниями."] = "442191b2cfb08109059d8086031cf4ea",
		["Настоящий профессионал знает, что он может, а что нет, и я не стыжусь признавать, что твое умение превосходит мое. Я бы хотел, чтобы ты $gнанес:нанесла; визит Китте Огневетер в Башню Азоры. Ее имя хорошо известно, и не случайно."] = "26d3bfbb22d8a54e39ab79db7fab0284",
		["Ты еще не $Gготов:готова;. Поговори с Бетти Куин – вон она, на лестнице стоит. Возвращайся, когда выучишься у нее."] = "a4f377c48a85cd98cb6b0a714f4f8dfb",
		["Твоя уверенность в себе обоснованна, $gпутник:путница;. Теперь начнется твое настоящее обучение!"] = "c1383f7b48e9dcb2540129e0a8e3528b",
	},
	["Лумак"] = {
		["Рыбка такая вкусная. Ты хочешь учиться ловить рыбку? Есть рыбку? Мммммм…"] = "a92b422f060c1d7ccb871bbb1aeede31",
		["Ага, я могу научить тебя ловить рыбу."] = "081b59701643fc144f37758247997960",
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "0b512be0e7d51bb900e38c95885108fe",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "665bbb3772dc4ca6c973b2ba079bf837",
	},
	["Люи'Мала"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "0e953fd8dfbfe1414c60a2989878d380",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "191f9771bbe3c0dfd9d726fd4f02d760",
		["Могу научить тебя ловить рыбу."] = "7709fb559a1b486ad6fbaec0f8f6f8ff",
	},
	["Лютер Рудокоп"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "40ed4acb596b8797e28b2e4ec74f6940",
		["Мне некогда тратить время на таких, как ты, $c."] = "9514382213ea5206a797eeb5423a9138",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Магар"] = {
		["Я лично изготовил большинство товаров, которые ты видишь в этом магазине. Что думаешь? От ответа может зависеть твоя жизнь."] = "d6420130e1b1b2f317ac78e25124b3bc",
		["Тебе нужно учиться у кого-нибудь, кто знает больше, чем я. Пойди поговори с Джозефом Грегорианом в Подгороде. Ну, почему ты еще здесь?"] = "251c4b189af8f0c50a129485f212f8d2",
		["Что? Ну чего тебе от меня надо? Ты ведь наверняка даже иголку держать толком не умеешь! Пойди поговори со Снангом. И не возвращайся, пока не обучишься как следует!"] = "3d2ea831ad1620f66cc7300a9bfe1240",
		["Наконец-то ты себя $gпоказал:показала;! Теперь и я покажу себя!"] = "97a07a6619bced8dc7c9433b4974c6de",
	},
	["Магинор Дюма"] = {
		["Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?"] = "3ddc082eac22c52bb34743331a694904",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "54074b0b08d3a499512ae6fba95f3115",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Магис Искроплащ"] = {
		["Приветствую. Я наставник магов, а ты маг."] = "ba87bd521b00c273a44207b174b44c7a",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "8fd77c576e61a6ac69420c6902a2153b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Маддьюк"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "6b8ea29137624c8512925cd734b18e4f",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "fa94f3b2a7756a7206f2d739132e099b",
		["\"Поваренную книгу умельца\" можно купить у Вулана в Деревне Ночных Охотников. Тебе она понадобится, если ты хочешь расти над собой."] = "178749ad5f34e7d82d4f95b09e30304c",
		["Я могу научить тебя готовить!"] = "3c5599de03c8689a7c59e4a9c7e86daa",
	},
	["Маетрия"] = {
		["Куда бы вы хотели слетать?"] = "e9f2c6ae11c08606a3e902729508a45b",
	},
