		["А, так это ты $gнашел:нашла; письмо. Спасибо за… Видимо, за новости о моей семье. Прошу тебя, раздели мой скромный стол."] = "c5b7759f0cefd29b1a309325dd586e97",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Майор Маттингли"] = {
		["Я живу, чтобы служить королю."] = "9256c8087a9343192abe0385ab00858c",
		["Возможно, когда-нибудь ты так же прославишь Альянс, как и герои, которых ты $gвидел:видела; сегодня. Воздай им почести, $n."] = "160d134552454e27460514c6f0827eab",
	},
	["Мак"] = {
		["Говорят, здесь живет сам Кэрн. Вот смастерю достойный подарок – и нанесу ему визит. Может быть, он поделится со мной своей мудростью."] = "a1adc9308232c8c0f4e71953e5b803bf",
		["Ты талантливей меня, $gдружище:подруга;. Поговори-ка с Тарном. Он разбирается в коже лучше меня и всегда рад новым ученикам."] = "edf5f8de4140afd1bce34fd502315c9b",
		["Мой руки, перед тем как начинать любую работу. Запятнанная кровью или грязью кожа теряет свою природную красоту."] = "9bcfa971f468ee6490afd446429c6d90",
	},
	["Максан Анвол"] = {
		["Да хранит тебя Свет, $c."] = "852369f0d2fbc11e555e75fe5a433853",
		["Надеюсь, $n, Свет на твоей стороне. Могу я чем-нибудь помочь?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Максимилиан Кроу"] = {
		["Чары развращают лишь тех, кто слаб духом. Не прекращай работать над собой, если не хочешь, чтобы тебя постигла такая участь."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
		["Тьма не примет тебя, $c. Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!"] = "c4bef13520e7f7e2f4078fbe96c02345",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Максимиллион"] = {
		["Ты поступаешь разумно, $n, унижаясь передо мной в надежде узнать что-нибудь новое об искусстве чернокнижников."] = "6d671d26f71829b3cfdafaf53866d6f0",
		["Мне некогда тратить время на таких, как ты, $c."] = "9514382213ea5206a797eeb5423a9138",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Малакай Крест"] = {
		["Да, $c?"] = "901d3b1160b38eacb61be277a1eab438",
		["$N, ну что может сделать для вас такое ничтожество, как я? Разве что научить чему-нибудь…"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Малдрин"] = {
		["Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя."] = "922a94a8f826437fe0370bdcd6a587ac",
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты здесь, чтобы тренироваться, я буду рад потренировать тебя.$B$BСкоро придет время, когда зов Изумрудного Сна завладеет тобой. Ты впадешь в летаргию на долгие годы и будешь ступать среди чистейших форм. Именно там и тогда состоится твое окончательное обучение."] = "1d12fd8e421d229eea70c7677a2daeca",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Малифой Черномолот"] = {
		["Братство Тория не тратит свое время на всякую мелочь. Ступай отсюда."] = "807f545aa510396b39fd74ed72c9abcb",
		["Для искусного ремесленника вроде меня это простая задача.$B$BСамое сложное в изготовлении изделий из шкур и панцирей животных – это добыча материала. Если ты принесешь мне безупречную шкуру этого зверя, я изготовлю из нее несколько полезных предметов."] = "5c51b2b4d2e369e2c9b1c95f23c50db1",
		["Я думал, что шансы получить такую вещь – один из миллиона! Такая шкура попадается раз в жизни! Даже самые искусные мастера ремесла, без сомнения, несколько сот раз потерпели бы неудачу в свежевании зверя, прежде чем удалось бы получить безупречный образчик."] = "8a0cd35a24d37645220db16398cde660",
	},
	["Малош"] = {
		["Ты здесь для учебы? Или просто для того, чтобы заставить воина зря тратить время?"] = "141f23d07f540e8c7b0ef9335bda601e",
		["Я не учу таких, как ты, $c. Обращайся к другим, а меня не зли."] = "5c32ac92759b0e79eade7dc21f7e569f",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Малькомб Уинн"] = {
		["У меня не так много времени, чтобы тратить его на всяких чужаков. Излагай свое дело или убирайся!"] = "5326a24ee0ea6449c67c18d4327bde5d",
		["Ну да, ты $gсумел:сумела; дойти досюда… иди встреться с Лавинией Кроу у другого стеллажа, вон там. Если не напортачишь с ней, может быть, сможешь еще чему-нибудь научиться."] = "ef5041ab92f8b0bb4ee9644254c363c9",
		["С виду ты не $gопасен:опасна;, но кто знает – вдруг поблизости прячется какой-нибудь колдун!"] = "61487ac6146fba1f9b5c99729ccb3322",
	},
	["Манкрик"] = {
		["$C, я пришел на Перекресток за помощью, но нашел там только трусов, которые отвернулись от меня – даже могучий Торк! Он хороший правитель, но его отказ оскорбил и разозлил меня.$B$BОн говорит, что ярость помутила мне голову, что я не могу мыслить ясно и оттого слишком тороплюсь – но я не успокоюсь, пока не отомщу!"] = "63a72ba3d24c591ed6c49d61ff2efbe2",
		["Спасибо тебе, $n. Твое упорство позволит душе моей жены упокоиться с миром. Я твой вечный должник.$B$BМоя ненависть к иглогривам никогда не иссякнет, но сейчас моя жажда их крови утолена.$B$BТеперь я могу начать жизнь сначала."] = "bad017b3adfc64250ce72451884a2780",
	},
	["Марвон Клепальщик"] = {
		["Я знаю, знаю, что нахожусь не пойми где!$B$BВообще-то я из Кабестана, но мой дирижабль разбился, и я подумал, что можно исследовать чего-нибудь здесь!"] = "012cba0ea4f7f602188cc6eee3493caa",
	},
	["Марда Веллер"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Мардант Крепкий Дуб"] = {
		["Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя."] = "922a94a8f826437fe0370bdcd6a587ac",
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты здесь, чтобы тренироваться, я буду рад потренировать тебя.$B$BСкоро придет время, когда зов Изумрудного Сна завладеет тобой. Ты впадешь в летаргию на долгие годы и будешь ступать среди чистейших форм. Именно там и тогда состоится твое окончательное обучение."] = "1d12fd8e421d229eea70c7677a2daeca",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Мардук Блэкпул"] = {
		["Не похожи вы на студента…"] = "9a65e2620d90d094df252c8038ca632a",
		["Твое будущее сокрыто. Сосредоточься и спроси еще раз."] = "401299a0cacc697ae0842c601a4e1272",
		["Я чувствую вокруг вас какое-то беспокойство…"] = "18a7c71660d684204d4641014512c4b6",
		["Ты не $gсосредоточен:сосредоточена;. Ты что-то от меня скрываешь?"] = "6fe04378d0356a133c01252fdf1a5069",
	},
	["Марек Железносерд"] = {
		["Здесь, в приюте Странников, охотничьи навыки особенно в цене. Хочешь ко мне в ученики? Это еще заслужить надо.$B$BОтнесись серьезно к этому испытанию, $Gпарень:девица;!"] = "b9a009c23ae18be4d2beb4d5b487dd08",
		["Ты $gстал отличным охотником:стала отличной охотницей;, $n! И ты не только $gдоказал:доказала; свое мастерство, но и $gпомог:помогла; Дерилу, а это дорогого стоит!$B$BБудем рады видеть тебя здесь в любое время."] = "f5c3b81ff7aa2cea4c40a37dadb0f053",
	},
	["Марион Зов"] = {
		["С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого."] = "d727a9a6c19bda725fe90de6453f386d",
		["Я не могу учить тебя. Найди учителя своего класса."] = "d27bd058351066858c056f51bdfeb0bd",
	},
	["Мариса Гренжер"] = {
		["Тут мало кто интересуется снятием шкур. Если вы хотите, я могу вас кое-чему научить."] = "8b3a33ab013eb9665ee196f01e14baf6",
	},
	["Мария Лумере"] = {
		["Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда."] = "49e5864e02449db1b69ff60632939d53",
		["С тех пор как пал Даларан и был разрушен Кель'Талас, такие товары встречаются крайне редко. Но Лукан Корделл и еще несколько торговцев все еще могут выполнять наши заказы."] = "7b74123b73660b230105d037e31ae78f",
	},
	["Маррик Нуррибит"] = {
		["Приветствую. Я гном, наставник магов. Ну а вы – маг."] = "89ebbfb158e8bcf8fa80f49f22684c37",
		["Здравствуйте, $c. Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано."] = "a3abb68c7dc7f0e59d1317d10b3a97cd",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Марта Стрейн"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "24f8a464cacbadb24bac1f53d8aa22dd",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "944b9c64d35c1c1dc8e01e4d94e1e346",
	},
	["Мартин Линдси"] = {
		["Мне жаль, $c, но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати."] = "5d7befc434c3b284ff699c9b717bf554",
		["Вы думаете, у вас хватит сил, чтобы справиться с Лигой Аратора, $c? Надеюсь, что так оно и есть. Так чего вы хотели? Или просто отнимаете мое время?"] = "59736d80c4279b69db8e94d24074d17a",
	},
	["Маршал Макбрайд"] = {
		["Эй! Ты крепко $gсложен:сложена;, а у нас тут стражей не хватает. Нам бы не помешала твоя помощь…"] = "2343fa9b01b2ca00b5bc7a390ac07935",
	},
	["Мастер Матиас Шоу"] = {
		["Добро пожаловать в штаб ШРУ, $n."] = "f02518f56be86de855c4a5c585841f34",
	},
	["Мастер-кузнец Гориврат"] = {
		["Гориврат – мое имя, кузнечное дело – мое призвание… и, эмм… еще я немного торгую едой и водой. Мяса не желаете?"] = "cf73090a6937f1713ac6d2eb671f2040",
		["Ты $gсделал:сделала; все, о чем я тебя просил, $n. Тебе больше нечего здесь делать. Если ты $gзаинтересован:заинтересована; в продолжении своей карьеры агента братства Тория, поговори с Локтосом Зловещим Торговцем в \"Угрюмом обжоре\" – это в глубинах Черной горы.$B$BПрощай!"] = "bff732f0c9b0a483ea8280c43a9f40de",
	},
	["Масток Райльшип"] = {
		["Если тебя интересует расписание появления торговцев и караванов на заставе Расщепленного Древа, ты обратился по адресу. К сожалению, я не слишком люблю общаться.$B$BТак что если тебе что-то нужно, давай побыстрее."] = "0d07f0a4ca3a5cd318acb1ed5b17e3de",
	},
	["Матеус Заклинатель Гнева"] = {
		["Чего ты хочешь, тупица? Убирайся с глаз моих долой, пока я не показал на твоей собственной шкуре, почему меня зовут Заклинатель Ярости."] = "46c26045969305b4f1afa87dc761ac0c",
		["Это сила, глупое создание.$B$B*Взгляд Матеуса темнеет.*$B$BЖЭти безумцы посылают таких, как ты, в Наксрамас за оскверненными доспехами. Они надеются очистить их и вернуть себе кусочек былой славы.$B$B*Матеус сплевывает.*$B$BОт одной мысли об этом у меня начинается изжога.$B$BЯ тоже ищу эти доспехи, но мне они нужны именно в нынешнем, оскверненном виде."] = "c943281a6d8472a873a6c97a00f1de85",
		["Ничего это не отговорки, придурок. Тьма, заключенная в подобных вещах, запросто может уничтожить нас обоих. Потому-то цена так высока. Если мне предстоит умереть, я намерен умереть богачом.$B$BИ мне глубоко начхать, как ты умрешь, – мне только нужно, чтоб ты сделал, как я говорю. Принеси то, что мне нужно, – и мы оба будем в выигрыше или умрем, но это я уже объяснил…"] = "c3138924933336621f5295591b7152ae",
	},
	["Матренгил Медвежья Лапа"] = {
		["Что привело вас в Круг Кенария, $n?"] = "fb107f4dbefdbafaf3a91b5c9b3d998b",
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; учиться, я с радостью тебе помогу.$B$BСейчас ходит много слухов о раздорах в Круге Кенария, но на них не стоит обращать внимание. Наш верховный друид Фэндрал Олений Шлем ведет к славе нас и весь Тельдрассил!"] = "765d7c8eab15fae760b184c664fb9e9a",
		["Помимо обучения я в силах стереть знания из твоей памяти. Но предупреждаю: с каждым разом это сделать все сложнее, поэтому цена все выше и выше."] = "d8d678c1fa7a5d0ec00c8daf69cd26f9",
	},
	["Медик из ордена Серебряного Рассвета"] = {
		["У меня много дел и мало времени, $r! Пожалуйста, не мешай."] = "f21ac82310364bee548aaa65db9ae740",
		["У меня слишком много дел и слишком мало времени, $r! Пожалуйста, уйди с моего пути!$B$BЕсли ты $gболен:больна; слизняком или вурдалачьим гноем, я могу тебе помочь."] = "69087ca98832c4d531ebd24380d184e3",
	},
	["Мелнан Темнокамень"] = {
		["Подходите! Сейчас вы узнаете о самом необычном зрелище на всем Азероте – о ярмарке Новолуния! Ура!"] = "6d6ca23ecd5ae25cef66ba84f4d8acb5",
		["Мальчики и девочки – дети всех возрастов – начинается ярмарка Новолуния! Ур-р-а-а-а!"] = "b4715bed2d4172b99afe64138b478e15",
		["Ярмарка Новолуния приближается! Веселье для детей ВСЕХ возрастов! Приходите все!"] = "8fe8aeb15ebe0e19bcdc798116ff01d4",
		["Ярмарка Новолуния приехала ненадолго, так что поторопитесь, обязательно посетите ее сегодня!"] = "864aaa5f97ede0b83eddc24aeea8facb",
		["Когда в городе откроется ярмарка Новолуния, обязательно сходи туда. Там столько всего интересного!"] = "8a8be9fb7609607a2a73503280292819",
		["В городе открылась ярмарка Новолуния! Не пропусти, другого такого зрелища ты не увидишь!"] = "3aa015524426a84e50f001c38fa67af3",
		["Скоро в городе будет ярмарка Новолуния! Не пропусти!"] = "0b8c021e068c941cfeacca0fdc06342d",
		["Мы уже здесь! Ярмарка Новолуния открыта! Не пропустите самое веселое событие на Азероте!"] = "87545a17514f8d22ebc68ca9371a6f4f",
		["Ярмарка Новолуния сейчас проходит на золотистых равнинах Мулгора, к юго-западу от Громового Утеса. Не пропусти!"] = "7ad0b94ce2fae67cd34a632af8cd35cb",
		["Ярмарка Новолуния сейчас проводится в Элвиннском лесу, к югу от Златоземья. Не пропусти!"] = "a3b2f7b279774ca4d85f4efbcc996fb0",
		["Ярмарка Новолуния откроется в Мулгоре. Мы поставим палатки к юго-западу от Громового Утеса."] = "9be3351865c169e03d2d409a8d522ad0",
		["Ярмарка Новолуния откроется в Элвиннском лесу. Мы поставим палатки к югу от Златоземья."] = "a3cbc5085cb4a57843b97e5d2f2c4e1f",
	},
	["Меридет Карлсон"] = {
		["Благодаря годам, затраченным на разведение породы, и качественному уходу я могу с гордостью представить тебе этих лошадей! Прошу, подходи, осмотрись, выбери себе скакуна. Лошадь, $gдруг мой:уважаемая;, – это товарищ на года. Обзаведись резвым скакуном, ведь ты этого $gдостоин:достойна;!"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
		["Извини, но я не могу продавать лошадей тому, кто не заслужил полного доверия в королевстве Штормграда. Скакунов лучше не найти нигде, и нам не хотелось бы отдавать их в руки врагов.$B$BНет, я не хочу сказать, что ты враг… в общем, заработай доверие Штормграда, и тогда мы поговорим о делах."] = "33c0e9087e12555f8dc52cc2a68cccb1",
	},
	["Мерок Дальний Путь"] = {
		["Какими бы смертоносными ни казались силитиды, они всего лишь ручные звери своих хозяев-кираи."] = "d1ec54aff7b3d41b9cf78637de55db9c",
	},
	["Механик гномского гаража"] = {
		["Мой технологический альманахотрон говорит, что мы выиграем у гоблинов на двадцать секунд больше, чем в прошлый раз!"] = "29cb9f241b67a6bd58f46757f27f6f9e",
		["Да мой сын может собрать машину лучше, чем рухлядь этого гоблина!"] = "5a9bf6255acd34e980aebcd04a7a6def",
		["Я усовершенствовал матричный регулометр нашей машины. Теперь ее скорость должна возрасти как минимум в пятнадцать раз!"] = "bb2e2ac84fdaea93b4cb5f24ace4d539",
		["\"Смелый\"? Я думаю, что распорядитель гонок Гореездник наверху, в башне, знает, где он."] = "288dfdbe6b0b08a6f2781e22dc5d8ce0",
		["Эти гонки дают отличную возможность продемонстрировать нашу изобретательность!"] = "88d6d4700d0a9435deac731bbef17f8c",
		["Джонсон? Я думаю, он где-то здесь…"] = "5d227c61a514e3f0b41f912efe022c52",
		["Правду говорят: дуракам везет, иначе эти гоблины разбивали бы свои машины в каждой гонке!"] = "413ec8412f752d13ea7d3bc09e39592d",
		["Тирт в последнее время сам не свой, и его помощник тоже."] = "329639fd7e8c50ac0b798afe6c0f563e",
	},
	["Мехмастер Замыкалец"] = {
		["Приветствую! Если ты хочешь получить доступ к гномским чертежам, приготовь свой членский билет гильдии гномов-инженеров."] = "899cfe761a6d79c6bdef221e3006e527",
		["Я Мехмастер Замыкалец, главный архитектор современных гномьих инженерных сооружений в мире. В мои обязанности входит следить за тем, чтобы наши гаечные ключи несли повсюду свет изобретательства!$B$BА если тебе известно, как можно устранить радиацию, то мы как раз сейчас готовы заплатить большие деньги за эту информацию…"] = "7b5fc421a7124f4ac3dff2f5ae6ae20e",
	},
	["Мидраннул"] = {
		["Снабжать искателей приключений – большая честь, ведь каждый из них – будущий герой!"] = "1245860919a037af19c20e24c625c670",
	},
	["Мизз Вечноклев"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "3bcdd8ed1fc1986116ad0c43c7de1475",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "0bf837bea513c0c82387777d0998bdfb",
		["Могу научить тебя ловить рыбу."] = "2d127f614bfaf60be0fcf5c914c9f116",
	},
	["Мила Рассветная Странница"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "ecc979039b643fbe07eecf74dbf940d3",
		["Да пребудут с тобой духи."] = "a81b670b0b0a6cd4fd4aafff91e45f6c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Милли Перосвист"] = {
		["Э… Боюсь, вы слишком велики для поездки на механодолгоноге, $gгосподин:госпожа;. Сервоприводы могут не выдержать!"] = "65e354785b26bc4ab909aec7cd4f43eb",
		["Если ты $gпришел:пришла; в поисках дара быстрой и безопасной мобильности, ты уже на месте! Модели новых механодолгоногов этого года недавно прибыли, и я готов показать тебе, что они умеют!"] = "299711f9bfc91cd6e18b4f2a9bc2baae",
		["Эм… Я не очень хорошо тебя знаю, извини. В смысле, как правомочный продавец механодолгоногов, я в действительности продаю своих ездовых животных лишь тем, кто заслужил полного доверия гномов. Если когда-нибудь ты заслужишь подобное отношение в Гномрегане, я с радостью покажу тебе все, что у меня есть."] = "19b68fb6acf9660f5027bc5ba4f9e9ad",
	},
	["Мильстафф Штормоглаз"] = {
		["Мне кажется, ваших умственных способностей недостаточно для постижения тонкой магии порталов."] = "a53aefa25ac89a757bcbfc41b3fc84f0",
		["Тебе повезло быть $gодним:одной; из нас – ведь только маг сможет создать портал для возвращения сюда. Я могу научить тебя, если хочешь."] = "f69b2a52cbd83a17600754efeeae8fbe",
	},
	["Миолор Губительная Ярость"] = {
		["Приветствую, $n. Я Миолор Губительная Ярость, хранитель Великой Кузни."] = "ea87f9213413c02d4186b43c3b1f15ad",
		["Вы достигли исключительных успехов в кузнечном деле, $n, и вам пора принять решение – стать оружейником или бронником.$b$bНо помните, что сделав выбор, вы не сможете отказаться от него. Каждая профессия требует жесткой дисциплины и не оставляет места ничему другому."] = "2f8c9ab139c42a81d62532751c158627",
	},
	["Миркета"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "8dca5bea4ae2a0b9ce008425ae8ac006",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "d02c9efbf965f15cf354f957643c58a4",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "28f6b8de934060edb89ab0339b080fcf",
	},
	["Мировой судья Мардук"] = {
		["Некоторые были избавлены от мук, вызванных воспоминаниями."] = "617c23db3203cf0d7bf17c56cc4f725a",
		["Культ Проклятых сильно разросся. Практически в каждом городе Орды и Альянса, начиная от столиц и заканчивая маленькими деревушками и даже шалашами, среди жителей прячутся члены культа.$B$BНе удивляйся. Культисты носят форменную одежду лишь для ритуалов и церемоний. Очень может быть, что во время своих приключений ты $gвстречался:встречалась; с ними и даже не $gзнал:знала; об этом."] = "5531b0711b11aa45460840d0d2c1ab10",
		["Правда? Узнаю их методы. Что ценнее для Кел'Тузада и Плети? Живой последователь, который может внедриться в общество и распространить чуму, погубив тысячи жизней, или один из множества солдат нежити? Думаю, ты легко ответишь на этот вопрос.$B$BДа, $r, они живут, работают и плетут интриги среди вас."] = "6ac3dfebce6f1d216515255cab46fcf0",
	},
	["Мишеллена"] = {
		["Куда бы вы хотели слетать?"] = "e9f2c6ae11c08606a3e902729508a45b",
	},
	["Мишель Белль"] = {
		["Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора."] = "1d81b661f251fb69f984eaa16be96159",
		["Я слышал, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи."] = "6bb0666f31370413b0bedf9c9606f6aa",
		["Я могу научить тебя оказывать первую помощь."] = "6e0e069ae3df14ed20af0f9912ceff68",
	},
	["Могиль Быстроруб"] = {
		["Может быть, мы и пострадали от засухи, но не испытываем нехватки мяса! Не хочешь изучить мои товары?"] = "544365d47c60f2584b894bd2faf796b0",
	},
	["Моквар"] = {
		["Тралл был очень добр, предоставив мне святилище в своих владениях. Но я не хотел бы злоупотреблять его добротой. Принеси я нашему лидеру хоть какое-то неудобство, это стало бы для меня вечным позором."] = "b9ca2ade5c180a21e305ffe165d2771c",
	},
	["Молтор"] = {
		["Если ты стремишься спасти мир, ты $gпришел:пришла; по адресу. Безликий кровавый бог Хаккар снова вернулся в наш мир!"] = "36ed78ad0299f724a3f13e2686290432",
	},
	["Монти"] = {
		["Монти я зовусь, с крысами вожусь!"] = "ca995c7f0f5f79ad1e87335c01749488",
	},
	["Мор'зул Кровопуск"] = {
		["Наступают времена, когда та жизнь, что мы знаем, заканчивается. Мы попали в ловушку и ищем ответы, и лишившись надежды, найдем ее там, где и не ждали.$B$BТолько тогда, $N, мы сделаем наши первые шаги к свободе."] = "5842c6675f139b38423a41749960a522",
	},
	["Мор'рогал"] = {
		["В горах Каменного Когтя есть множество пещер, в которых уже сгинуло немало алчных искателей приключений.$B$BВидимо, $c, те богатства, что ты ищешь, можно отыскать лишь следуя зову сердца и души."] = "09ad1d72371134696f00bc0ad18afa09",
	},
	["Морридан"] = {
		["Когда-то я следовал путем Сумеречного Молота. Одержимый желанием воскресить Древних богов, я забрался в глубины этого логова, чтобы забрать силу этого проклятого зверя Аку'май.$b$bНо, увидев, сколько невинных приносят здесь в жертву, я опомнился.$b$bЯ был в ловушке, но теперь свободен. Но моя родина, Каз Модан, так далеко отсюда!$b$bВ благодарность за победу над Аку'май я предлагаю тебе, $gхрабрый странник:храбрая странница;, побывать в очень необычном месте. Стоит тебе пожелать, и я отправлю тебя в город Дарнасс."] = "4057eacacb0243ce014c6ce4af544682",
	},
	["Мот Рассветный Странник"] = {
		["Я бы все отдал, чтобы не торчать на этих равнинах в такой день… но что поделаешь, служба."] = "164d32099002118fe8d2117ec015ba57",
		["Я не могу научить тебя ничему, чего бы ты уже не $gзнал:знала;. Однако знания моего отца намного превосходят мои. Заходи и поговори с ним. Удачи!"] = "893d18665c3f26a3bbd2c4c36ee7c554",
		["Есть много тайн, открыть которые помогут терпение и упорство. Приступим же."] = "070204bf722544f25415a86e05271b64",
	},
	["Мрак'нел"] = {
		["Я больше никогда не прикоснусь к камню. Никогда не испытаю радость отливки металла…"] = "fd6c52e798e64559f12964acfc65a412",
		["Ваша воля сильна, а намерения чисты.$B$BВозможно, вы и подойдете…"] = "489bc8fef34e87ae96a0127590c52249",
		["Ты хочешь научиться древнему ремеслу? Ты хочешь плавить черное железо?$B$BПорадуй меня, $r. Принеси мне жертву, и я приму ее!"] = "269bfbd42c1bcdce2bcd3a30b4a4916d",
		["Интересно, интересно… $N, я знаю одну девушку-друида, которая живет на вершине холма над Пещерами Стенаний. Возможно, она знает больше об этом осколке.$B$BТеперь прости, но я должен вернуться к работе."] = "59bb63aa72266fa9deea86b21a7dc575",
		["Ты $gпоказал:показала; мне, чего желаешь, и $gзаплатил:заплатила; драгоценными камнями. Я буду учить тебя…"] = "0480ea8d1ae32be6156e9b1979fcbcb9",
	},
	["Мрачнур Каменное Клеймо"] = {
		["Ага, я могу научить тебя ловить рыбу."] = "d242a87d4357b57022f9a29ca65d59ae",
	},
	["Мрачный завсегдатай"] = {
		["Если Гидраксис привлечет на свою сторону еще больше народу, это может изменить расстановку сил…"] = "47f7cce3de520c5508a34ffded05d078",
		["Повелитель вод Гидраксис скрывается в Азшаре, на острове в Штормовой бухте. Представляете, какая это угроза?"] = "71d0fe83bfcaabb9c727ec622e2c8f4a",
		["Я слышал, что благородный элементаль воды Гидраксис ведет войну со служителями огня. Будем надеяться, что он проиграет!"] = "e6aaf0a5e40d69ade99a9420f809af6e",
		["Элементали воды воюют с элементалями огня, а значит – и с нами. Один из их лидеров, Гидраксис, собирает агентов для своих целей…"] = "dc9fa668ac5349906d636b678a132bab",
		["\"Не было бы \"Угрюмого обжоры\", я бы развлекался, обрывая крылышки дракончикам\"."] = "721ddf9aee8d38be1e406ccfabede9a7",
		["Если бы не \"Угрюмый обжора\", я бы только и делал, что дракончикам крылышки отрывал."] = "8ad7dedf609a62cd82d39e7335ede32b",
		["Пропустите стаканчик, $c! Как знать, вдруг он последний…"] = "5ef4543b47e41607c5262c9bd45be597",
		["Рагнарос подчинит весь мир!"] = "fdda7a3b845dd1fad7eeb2a04301d3d1",
	},
	["Мукдрак"] = {
		["Я люблю строить всякие штуковины. А еще больше люблю их взрывать!"] = "0ff75e91e3efa274b411fe43479cec98",
	},
	["Мукс Маноскреб"] = {
		["Привет, $gдружище:подруга;. Эктоплазматическими конденсаторами не интересуешься? А как насчет всенаправленных спектральных ассимиляторов?"] = "2ee56c2d70a0c3bb5d140a53ddd3fa45",
	},
	["Мулгрис Глубокая Река"] = {
		["Прошу, помоги мне, $gбратец:сестрица;…$B$BСкоро я умру, и хотя страдания мои велики, я знаю, что смерть будет всего лишь раз. Но дикая природа, $gбратец:сестрица;… природа тоже страдает и не знает облегчения… Я прошу твоей помощи, я на последнем издыхании…"] = "67169b2421921ed2ab7e41cf84226c3c",
		["Да, $r, я умею говорить на понятном тебе языке. Мы не животные, хотя твои сородичи и считают нас таковыми. Впрочем, все наши разногласия меркнут перед бедой, постигшей эти земли. Прошу тебя, забудь о вражде наших видов и услышь мою предсмертную мольбу.$B$BЯ прибыл в эти земли, чтобы излечить их. Если ты не поможешь мне, все будет напрасно. На последнем своем дыхании прошу тебя: помоги!"] = "fc72657a0b7757c758fbe98a28b4863d",
		["\"…\"$B$BТело тауренского друида лежит тихо и недвижимо. Очевидно, он наконец-то перешел из этогот мира в обещанное ему славное посмертие."] = "08f10ccaf3a2c6de55534ebff038dd0f",
	},
	["Мэри Эдрас"] = {
		["Теперь лишь известный доктор Грегори Виктор может помочь тебе отточить твои навыки. Его можно найти на Нагорье Арати в Павшем Молоте."] = "1da3761ad74cf7eb8c780bd1d6ef8d0f",
		["Бала Лок'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!"] = "87c89b57e3313dbfc3b9494758c30fff",
		["Я могу научить тебя оказывать первую помощь."] = "b989a2ab06d53ba30e6226c9b588d90b",
	},
	["Мэттью Хопер"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "13d2af5f294a07ae2cff1bf240fa32c1",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "43ebea4a5129c29af35af2064eb93951",
		["Могу научить тебя ловить рыбу."] = "b285645e1bdb1be37d7bfdc440534eec",
	},
	["Мяо'зан"] = {
		["Похоже, тебя тянет на приключения. А я от них уже устал еще до того, как мы, тролли, пришли сюда. Теперь я радуюсь каждому дню и обучаю других тому, что может понадобиться в приключениях."] = "2bddeb2204ae9a7ba01d834050d650f4",
		["$GГотов:Готова; к следующему уроку? Ну, хорошо. Во-первых, расслабься. Ты $gдолжен:должна; чувствовать себя свободно, чтобы приготовить это зелье."] = "d7183ddb231e293b65e81976fe37b4d9",
		["Твои вопросы слишком сложны для меня, $n. Тебе надо поговорить с орком Йелмаком из оргриммарского Волока. Уж он-то точно сможет ответить."] = "3ccc9d3982a4f8dde9b5653bc0c2e796",
	},
	["Надсмотрщик Скрендж"] = {
		["Будучи дежурным десятником, я обязан следить за тем, чтобы любые проявления торговли, труда, отдыха и релаксации были в должной мере утомительными.$B$BЕсли какое-либо задание покажется тебе слишком легким, немедленно доложи мне."] = "793ee16511d200a9b8cd0eb76fa5bc51",
	},
	["Налезетта Буйный Нрав"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "89218c24a0eff1fa5c10022467769ef7",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "4c9a93178a8bd81be46f856336284914",
	},
	["Нара Мейдерос"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Нарайн Причудень"] = {
		["Нарайн Причудень, к твоим услугам! Инженер в отставке и мастер-прорицатель! Я могу предсказать твое будущее даже раньше, чем оно случится!"] = "2494fd01fbbcaa3067f0f6bde8276ef1",
		["Молчите! Шшш! Вы здесь из-за Пеплоносца?! Да… да… Нет! Это я виноват. $b$bЧем я могу помочь вам, $r?"] = "2e27a2e4cf3cdc84c5efe6482fb8f345",
		["Все… все в дымке, $n. Я ничего не вижу! Погоди… Одну минутку. Я вижу… вижу убежище доктора Жло. Да! Похоже, у него глава из книги!$B$BДай-ка попробую взять общий план и рассмотреть получше…$B$B*Нарайн скосил глаза к переносице.*$B$BОстров Алькац! Этот гад на острове Алькац!"] = "fe83661210697890e5faa8788183a890",
		["<Нарайн прикладывает нераспечатанный конверт ко лбу.>$b$bЧто это… Мммм… Бархат!$b$bЯ прав?"] = "225eafda96d1c24ae14477251f082c90",
	},
	["Нарв Кожемяка"] = {
		["Лучшие шкуры получаются из тех кодо, которые прилегли отдохнуть в этой глуши."] = "67523c45386916357dd48fdb7eb1a7d6",
	},
	["Нарм Небесный Охотник"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "d96f407d05286ba207ff46bf75ef4510",
		["Да пребудут с тобой духи."] = "1eec7529a102737979dbaf19908f6ac0",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Нарток"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "f097ab331f582c2d79e805e164a7c169",
		["$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы."] = "5a92f47cf481eb3def2615b8693c94fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Нат Пэгл"] = {
		["Лично я думаю, что самое лучшее в рыбалке – это ее неспешность. Можно спокойно подумать, вспомнить прошлое и спланировать будущее.$B$BА еще хороший повод напиться. Как свинья."] = "9d7745f7746667248f72319a9c4794ef",
		["Спасибо за то, что вернули мою счастливую рулетку, $n! Клянусь, с ней я ловлю огромных рыб!"] = "4b8c6e9b9c6223f29c6ee50817bd5289",
		["Чтобы поймать Газ'ранку, нужна наживка на грязнотинников. Я сам такие делаю!$B$BНо одной наживкой тут не обойдешься – нужны и сами грязнотинники… Положи их в приманку, и она пропитается этим мерзким запахом.$B$BКогда управишься с грязнотинниками, бросай наживку со стоянки Пэгла в Зул'Гурубе, бери бутыль и жди… Только выбирай бутыль поменьше – с такой приманкой Газ'ранка вряд ли заставит себя ждать."] = "bb7840ac1ccbf51d87e9a44ee1a98d48",
	},
	["Натаниэль Дамах"] = {
		["Давным-давно, до последней великой войны, моему отцу принадлежала лесопилка Северного Кряжа. Он посвятил ей всю свою жизнь и не мыслил себя без нее. Когда началась война, ему пришлось скрепя сердце бежать вместе с семьей в Штормград.$B$BМы потеряли многих друзей и членов семьи, и мне больно сознавать, что теперь Алый орден распоряжается лесопилкой, как своей.$B$BВот почему я вернулся."] = "09280c8a100dbf6ab274fcbdf0803b69",
	},
	["Натанос Гнилостень"] = {
		["Еще $gодин простак, решивший:одна наивная особа, решившая; послужить Темной Госпоже…$B$B<Натанос вздыхает.>$B$BВсех ваших предшественников я отправил ей обратно… по частям. Почему бы сейчас не поступить так же?$B$BВпрочем, на этот раз я не буду задаваться вопросом, а просто выполню просьбу Госпожи."] = "36ceb7cebed57b0d09e09d90cea831c6",
	},
	["Недотрогинс"] = {
		["Чары развращают лишь тех, кто слаб духом. Не прекращай работать над собой, если не хочешь, чтобы тебя постигла такая участь."] = "073492d1b775dad17b73e4495accc8b7",
		["Боюсь, твоя душа недостаточно темна, чтобы нам было о чем говорить. Оставь меня в покое."] = "8045db4a1a25656b86eb87b955fbe642",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Нез'раз"] = {
		["Почему ты хочешь покинуть эти солнечные берега и прозрачную голубую воду? Для меня загадка. Здесь настоящий рай. Только не говори этого моему брату Запоте, он и так уже достаточно расстроен тем, что надолго застрял в Тирисфале. Этот дирижабль садится в Оргриммаре, так что можешь не волноваться о необходимости слушать, как он ноет. Но если скоро будешь в Тирисфале, послушай меня и не заводи его."] = "ea11609900c4cc9251d7ec133d6d262b",
	},
	["Нельсон Обаятельный"] = {
		["Я прихожу в Силитус каждый год примерно в это время. Погода необыкновенна для моих шишек.$B$BТы $gдолжен:должна; прогуляться со мной, $gдруг:подруга;. Наслаждайся тем, что можешь узреть и чего не можешь."] = "5e0b696d989d9f556038cd140846f661",
	},
	["Ниби Всемогущий"] = {
		["Склонись передо мной, насекомое! Ты $gдолжен:должна; чувствовать мою власть!"] = "283fc5c382b274b565983a110dfbcccc",
		["Значит, ты $gявился:явилась; к Ниби, чтобы узнать секрет вызова инферналов из Пустоты.$B$BМолчи! Ниби все знает!$B$BНо Ниби не раскрывает таких тайн просто так. Сначала ты $gдолжен:должна; помочь Ниби в очень важном деле."] = "35284cfba5849c0b76c8dffde030b428",
		["К северо-востоку от этого лагеря живет могучий инфернал Крошиус. Поэтому Ниби и здесь. Сила Крошиуса велика – он просуществовал намного дольше, чем ожидалось. Обычно, исполняя волю хозяина, инфернал с невероятной силой обрушивается на землю, но сила эта быстро затихает. Когда пламя, горящее внутри голема, гаснет, он превращается в груду камней."] = "1d846f3de3583986c12a82cbfed8b313",
	},
	["Нииру Огненный Клинок"] = {
		["Прислушивайся к чужим словам и не принимай поспешных решений, $c. Ибо даже у самых верных друзей могут быть свои интересы.$B$BНаш великий вождь знает это. Чтобы доказать ему, что не все чернокнижники стремятся разрушить или подчинить Орду, я вызвался помогать ему в любых начинаниях."] = "b4db7422b050ec4c88d959b16d7d2d02",
		["Ага, еще $gодин:одна; из нас. Хорошо, что наши ряды пополняются так быстро, что я уже не запоминаю всех новичков.$B$BЭтот дурак Тралл думает, что я работаю не покладая рук, дабы обелить чернокнижников и доказать, что мы его верные слуги! Идиот! Сначала Пылающий Легион исчерпает весь его мир, а потом сожжет его до основания!"] = "b8b755fa02767f4b1ab4edb5fb08b0d4",
		["Какая наивность. Пылающий Клинок и есть Совет Теней! Под его правлением существует много культов и организаций, но все они – лишь продолжение их воли. Хоть я и управляю Пылающим Клинком, я всего лишь пешка в руках Совета, как ты – в моих руках. Взгляни на Огненный меч – большинство из них думают, что становятся могущественными чернокнижниками и что они свергнут Совет Теней."] = "9d30b90a514baebe7e41278776ffc316",
	},
	["Никс Шепружин"] = {
		["Здравствуйте! Если вы хотите получить доступ к чертежам, просим вас приготовить свой членский билет гильдии гоблинов-инженеров для проверки."] = "e814cc2694856d5e9fb32efcf2ea7186",
		["Позволь мне преподать тебе урок математики: \"гоблин\" плюс \"инженерное дело\" равно \"НОУ-ХАУ\", детка. Все, кто думает иначе, просто не умеют складывать."] = "cc919cf47bdafb636ea5a25ac2f0b460",
	},
	["Нипси"] = {
		["Лучшие котлеты из подземной крысы по эту сторону Каз Модана!"] = "d070931d907bc8487f4f4b1378bf8ea4",
	},
	["Нирилл"] = {
		["Здравствуйте, $Gгосподин:госпожа;. Меня зовут Нирилл, я ученик господина Ксилема. Если у вас есть вопросы к моему учителю, не стесняйтесь его побеспокоить. $B$B Я буду к вашим услугам, когда вы решите вернуться к подножию горы."] = "c25da7aea73e13a714910fc2805f839f",
	},
	["Нисса Огневик"] = {
		["Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора."] = "199504472bb3974f17f406ea4b61db6d",
		["Я слышал, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи."] = "dd4639950203b6deff95ea3d06de8b2e",
		["Я могу научить тебя оказывать первую помощь."] = "8af3c5ccd98580aeb1ba4bd7aa80e766",
	},
	["Ниттльбур Шумогам"] = {
		["Приветствую. Я гном, наставник магов. Ну а вы – маг."] = "89ebbfb158e8bcf8fa80f49f22684c37",
		["Здравствуйте, $c. Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано."] = "a3abb68c7dc7f0e59d1317d10b3a97cd",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Нице"] = {
		["Куда бы вы хотели слетать?"] = "26d3fb863cf374254276fad4c4fb1b43",
	},
	["Ногг"] = {
		["Если бы в сутках была еще пара лишних часов…"] = "71545b2af437b8e180d49ce9b50338cd",
		["Вы получили право обучаться у более опытного инструктора. Поговорите с моим другом Роксиком, он вон там."] = "00008c92982d394e12b610e2f162f1fb",
		["Ты не $gзаслужил:заслужила; права учиться у меня. Сначала поговори с Тундом – вон он, на другом краю стола. Возвращайся, когда он скажет, что ты $gготов:готова;!"] = "79a7ae7ace70459d2510259f506e19c4",
		["Ты $gпрошел:прошла; тест. Отлично! Теперь мы продолжим твое обучение."] = "aebf8bffcdfdd4b408e4f5ba08fd3f15",
	},
	["Ноггл Шаткобрус"] = {
		["Эй, спасибо, что спасли мою шкуру! Я пока что отсижусь в тишине, пока силы не восстановятся."] = "0e9b47815086b6b0100592326be61808",
		["Кто ты? Где я? Я чувствую себя таким… слабым…"] = "4769fa7dbee7d466df239c3fdc15ce4d",
	},
	["Ньютон Бернсайд"] = {
		["Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?"] = "884e826914eac49c2ac85af2e236b022",
		["Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!"] = "dcd77e7267840142a221c406ad8d42b0",
	},
	["Огромм"] = {
		["Что?"] = "473178aa39ca6564bcadca7c21bbfead",
		["Не трать мое время."] = "77d31ff418c404f97bed5fd865e38ebe",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Огунаро Волкопас"] = {
		["Заг заг, $gхрабрый:храбрая:c; $c! Я могу предложить тебе лучших верховых волков. Зверей, равных волку по выносливости и чутью, ты не найдешь нигде! Пожалуйста, можешь осмотреть их лично."] = "45462d0bfb55988ee297f81dc43938d9",
		["Я продаю своих питомцев только тем, кого превозносят жители Оргриммара и весь народ орков. Докажите, что вы достойны, – и я выберу для вас самого сильного из своих волков!"] = "889004b6fde3d6412a91b1aff5e0f67c",
	},
	["Озрик Штранг"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "0644f6eb50bbf423901c39cf0e35e268",
	},
	["Окофус Жарбулат"] = {
		["Чего тебе надо?"] = "a9064d83aa3ba7a86a2ff7346ed99f64",
	},
	["Оливия Бернсайд"] = {
		["Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?"] = "1cf62073cd912caabcc1fd6d29dd3aa6",
		["Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!"] = "8aebd1628c8cd2becdb32845edc4fbe8",
	},
	["Олмин Пламебород"] = {
		["Если ты здесь, чтобы научиться стратегии и тактике охоты, то $gпришел:пришла; точно по адресу!"] = "41e50470745e1b7a8b43f620b97501b4",
		["У меня тебе учиться нечему. Ты $c, вот к своему учителю и ступай."] = "65ffa984c80ec793cab656acd848ac8c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Оловень"] = {
		["Что? Ты что-то хочешь?"] = "b0fb181dddc32fa304d6805b255e6bde",
		["Я не могу тебе помочь! Тебе нужен кто-то более опытный. Так… Ты у нас из Альянса, значит, тебе лучше пойти в Штормград к Лилиаму Шпинделю."] = "1389ded94ec799fa553e34c3557ac12c",
		["Да, я покажу тебе пару вещей. Посмотрим, как ты справишься – может быть, ты даже удивишь меня!"] = "af9ccb95467b25c6dc0eaa8a4d0cf1cf",
		["Боюсь, теперь ты для меня слишком $gхорош:хороша;! Тебе надо встретиться с Ноггом из Оргриммара."] = "f87c37944192073e24d10f1a070e94b4",
	},
	["Омуса Громовой Рог"] = {
		["Ветрокрыл доставит тебя по назначению, а ты обращайся с ней бережно. Да хранят тебя твои предки, $n."] = "a2429122d1ceeaef4fd2594c4ed06f2b",
		["Неисповедимы пути Матери-Земли. Пусть же она приглядит за тобой в твоих странствиях."] = "6d3a93f6d75f5ea11db68e9fab66c95f",
		["Хотя Перекресток – торговый и культурный центр всех Степей, мне больше по душе тишина Лагеря Таурахо. Куда ты хочешь отправиться?"] = "ab5956b42af65d0c546a7454fb3339dd",
		["Куда же отправить тебя сегодня, $c?"] = "a281fc87589677c9d7b3b3b6c436891c",
	},
	["Опекун Илталайн"] = {
		["Ах, красота Тенистой долины никогда не перестанет восхищать меня!"] = "6d4d5a1ed15f2bc0e550c388cbf7e6d7",
	},
	["Оператор Чудоформера"] = {
		["Новинка года: PX-238 Чудовольт Мороза. Не стесняйтесь, поднимайтесь!$b$bДа, сначала подпишите эти бумажки, потому что у нас тут осталось несколько мелких недоработок…"] = "c7f6f228ba377038424bb81a6fc685cc",
	},
	["Оргриммарский рубака"] = {
		["Отправляйтесь в Аллею Силы – банк Оргриммара находится к югу от Башни Небес."] = "3b2d3f4253346fe54a8af9329b9583ef",
		["А как ты думаешь, где может быть укротитель ветроклылов? Конечно же, на самом верху Башни Небес в Аллее Силы!"] = "058360cd0cfb26d7fc00ef22bcb6d9f7",
		["Посольство Орды находится в западной части Аллеи Силы."] = "96570b0e28f301933f76f87ab8b65194",
		["Таверна у нас стоит в восточной части Аллеи Силы, к северу от главных городских ворот."] = "2bba707a81f7cb342da5648c95205a58",
		["Свои любовные письма вы можете забрать в почтовом ящике в центре Аллеи Силы."] = "072bbffeb611bfaace92898c40fcf12c",
		["Охрипли, нахваливая свои товары? Посетите аукционный дом Оргриммара в Аллее Силы!"] = "180f756a443773f9b08c470a7bf7efc5",
		["Причальная башня дирижабля находится на юго-восточной окраине города."] = "3e4dab27994d3297fb026a55aa21667f",
		["Ищи Сайока и Ханаши в Аллее Чести, в лавке \"Легендарное оружие\". Следи за тем, что говоришь при них, или Сайок может решить отдать кусок тебя на закуску Скалящемуся Псу."] = "0e4181512160358580b16051647a2601",
		["Ксон'ча поможет тебе содержать лишних питомцев. Ищи его в Аллее Чести, у стойл между ареной и Залом Охотников. А теперь проваливай!"] = "b0e64bb72a28ec8edf23f963ff9ce7c8",
		["Тебе нужно в Зал Легенд. Он находится над Аллеей Силы, на западном склоне. Если ты не офицер, внутрь тебе нельзя – зато ты всегда можешь поговорить с сержантом Ба'шей."] = "30dd36a9611a5248ae78a22056a25043",
		["Как бы я хотел присоединиться к тебе в великолепной битве, но вместо этого я застрял здесь, по делам. Отправляйся в Зал Отважных в оргриммарской Аллее Чести и поговори с Катрой Кровавый Рык. Она поможет тебе добраться до Альтеракской долины. Заставь нас гордиться тобой, $n!"] = "85f1dfbc6635cf1f0129f8b498acbd11",
		["Ты хочешь помочь Отрекшимся сражаться против людей в Низине Арати? Тогда отправляйся в Зал Отважных и поговори с Дези Холодной."] = "23bbff30f9e429d824918493908635e8",
		["Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, $c, найди Бракгуля Смертоносного в Зале Отважных."] = "79112947d6abd6ba4573faecea150b38",
		["Идите прямо на северо-запад Аллеи Чести. Там вы и найдете Зал Охотников."] = "51c81b6b8b401941a5a80ec07d3cf189",
		["Что, не можешь открыть туда портал? Ступай в Пристанище Темнотерна за озером в Аллее Духов, это вверх и на запад из Аллеи Силы."] = "2eae00e94c3eecdbf2462e9dfa78b8a4",
		["Исцеление – это для тех, кто не умеет терпеть боль. Впрочем, если тебе это непременно нужно, обратись в Обитель Духов на озере в Аллее Духов, выше Аллеи Силы на запад."] = "03d023b4146dbfca47b38d4edcaa7764",
		["Ваши поиски близки к завершению. Свою правду вы найдете, войдя в крепость Тралла в Аллее Мудрости."] = "2fbfb318d5dc89b3a1d85305c71f4e19",
		["Если я поймаю тебя на краже, ты об этом пожалеешь! А так – ищи Шентула и его Братство Теней в подземельях Расселины теней. Найди туннель, ведущий на юг, в Аллее Мудрости."] = "453a8ae094156bcd4e2d1b85c9a3df31",
		["Мы только что избавились от Пылающего Легиона, а ты опять путаешься с демонами? Найди Анклав Темного Пламени в подземной пещере, известной как Расселина Теней. Из Волока туда ведет туннель."] = "65f8dda67d9c8c8f969b388ee0edf169",
		["Найди Зал Отважных в Аллее Чести и поговори там с Греззом Десницей Гнева. Передай ему, что я вернусь, как только меня сменят."] = "9d782b04ca119ec2bc56975d49b1e444",
		["Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока."] = "fdeac495307fb2d96ba514b92ca0eb97",
		["Возможно, Сару Холодная Ярость когда-нибудь научит тебя владеть топором не хуже моего. Ищи его в \"Пылающей наковальне\", в Аллее Чести – за Рудником Ржавого каньона и направо от дороги."] = "9da815f247cef1730191b3131d74d0b9",
		["Тебе надо поучиться у Замджи. Ступай в \"Жаровню Борстана\" на верхнем уровне Волока – от входа в Аллею Силы по лестнице налево."] = "431eb88bb07fa6381014c842373d0570",
		["Топор мне зачаруешь? Только чтоб постоянно работало. Ладно, потом как-нибудь. А пока иди в лавку Чародейских товаров Годана. Это в западной части Волока, возле Аллеи Мудрости."] = "1280f9f183703298db351e358105cdc5",
		["Этот гоблин держит магазин игрушек в Аллее Чести."] = "8cd6b270a77a323ae36771bf7b388624",
		["Да, кто-то же должен перевязывать наших воинов после битвы… Ищи Арнока в доме \"Выживание сильнейших\" на берегу озера рядом с Обителью Духов. Иди вверх и на запад по Аллее Силы до озера."] = "6be79c4541f77d8d29acbf888f562299",
		["Рыбалка – забава для стариков, не нашедших смерти в бою! Ступай к Лумаку, который сидит на берегу озера в Аллее Чести."] = "a2e192907f9e8f21779ac2c1b989d419",
		["Тебе, слышишь, Дендрарий Джанди нужен. Ой, это что я сказал? Глок'тар, ну и устал же я! Поднимись по деревянным ступенькам за рынком Азорана, в Аллее Мудрости, до входа в Волок, и там, на верхнем этаже, ты найдешь Джанди."] = "ed31d9f384101e3d6caedb2bb8b89983",
		["Тебе нужны \"Кодо-кожевники\". Это прямо в центре Волока."] = "739d876c38f19ef98b95c5ae9bb322ff",
		["Макару проводит дни и ночи на руднике Красного каньона. Это в Аллее Чести, прямо возле озера."] = "9735ac53d3d67045070581d0843fe26d",
		["Это хорошо, что ты стремишься не убивать напрасно. Ищи Тьюда в лавке \"Кодо-кожевники\". Это в центре Волока."] = "b71ac0b129e303f2e0d83640555128a9",
		["Платье?! Это не поможет тебе против хорошей стали! Ба, если ты точно хочешь стать портным, ищи ателье Магара на Волоке."] = "770f29a21112974898d2bcf70bbdc410",
		["Что ты ищешь?"] = "11f7e88f267338a9a8803626e9eb30be",
		["Банк Оргриммара находится в Аллее Силы, к северу от главного входа в город."] = "0d0d3b2be6dc0e0448bd8ad0d1a6199b",
		["Вы найдете укротителя ветрокрылов на верхушке Башни Небес в Аллее Силы. Дорас проследит, чтобы ты $gпопал:попала; на нужное поле боя."] = "c50805eb336264793c344418e5961fbc",
		["Вам нужен Уртрун Кланотворец из посольства Орды. Это в западной части Аллеи Силы."] = "71970291a3ab9199914f897241acc4b3",
		["Второе здание справа в Аллее Силы, к северу от главного входа в город. Хозяйку зовут Гришка."] = "ab72d7c83a6d226e67a075b1ba52048e",
		["Один есть возле банка Оргриммара, прямо посреди Аллеи Силы."] = "e0e6795a2a739fd62fe20834f1d3ff96",
		["Оргриммарский аукционный дом находится в Аллее Силы. Ищи его на восточной стороне, рядом с \"Восточными импортными громобоями\"."] = "311c5f6a0a1dddef0371a0c113bb62ab",
		["Прямо за главными воротами города есть указатель на башню дирижабля. Хозяина дирижабля Фреззу можно найти на верхушке этой башни."] = "ac0ba2a4466278a2ed6ceac133133a36",
		["Хочешь освоить новые виды оружия? Обращайся к Сайоку и Ханаши из \"Легендарного оружия\". Это в Аллее Чести."] = "9edff2b4be1867c383c57d9f437a1916",
		["Отправляйся в Аллею Чести и разыщи Ксон'чу возле стойл."] = "3721283f14bf5a96478d4e27f054a4e2",
		["Поищи наверху западной части Аллеи Силы. Правда, если ты не офицер, внутрь не тебя не пустят! Но можешь поговорить с сержантом Ба'шей."] = "e7866663b8f38742244edaa262c62e11",
		["На каком поле боя ты хочешь искать славы?"] = "e919f627ec93189b9e052d3ae120da80",
		["Какой учитель тебе нужен?"] = "bb48a6496b0f939b97d651fb87555c27",
		["Какая профессия?"] = "539255a3b21365ed1ab0beecd22e319f",
		["Если вы собираетесь в Альтеракскую долину, поговорите с Катрой Кровавый Рык. Ее можно найти в Зале Отважных, что в Аллее Чести."] = "1012c1ecc8ed009687e7f7451230d860",
		["Отправляйся в Зал Отважных. Осквернительница, Дези Холодная, поможет тебе добраться до Низины Арати."] = "d79187c46c1d132053867c2cbc1e9e3e",
		["Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте в Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных."] = "970ddc32d4b7a525c189dc519ff7a728",
		["Иди в Зал Охотников, что в Аллее Чести к западу от Колизея. Там поговори с Ормаком Лютострелом."] = "2cf644ba2f510e7a4b8706d23090659a",
		["Поговори с Пефредо из Пристанища Темнотерна. Это в Аллее Духов, наверх и к западу от Аллеи Силы."] = "716e7e4fb54f6b7f439717f8e1cb509c",
		["Зайус со своими жрецами живет в Обители Духов. Иди к озеру вверх и на запад по Аллее Силы – придешь в Аллею Духов, а там $gсам:сама; увидишь."] = "ea2acf9d681b135ace8c51a731759494",
		["Тебе нужна Кардрис Сновидец. Она и еще один шаман сейчас в зале крепости Тралла, в Аллее Мудрости."] = "51a01677ab631a12e7d309b5687d3723",
		["Ищешь Шентула из Братства Теней, а? В Волоке напротив \"Скупщики Дрофферс и Сыновья\" ищи туннель, ведущий вниз, в Расселину теней."] = "78c4d657469f59de32a6b3a9a4ebdc4e",
		["Ты ищешь Гроль'дара и Анклав Темного Пламени? Тогда тебе надо в пещеру под названием \"Расселина теней\". Туда ведут два туннеля, один прямо к югу от Аллеи Мудрости, а другой от Волока."] = "0698ec224bc7a0fd621ac60e8efa1344",
		["Тебе нужен Грезз Десница Гнева из Зала Отважных, что в Аллее Чести. Да, замолви ему словечко за меня!"] = "d64d7b97dd43fd06735418ebd2a16c48",
		["Иди в лавку \"Алхимия и Эликсиры Йелмака\". Это в центре Волока, к западу от гигантского дерева."] = "9e0185cc1cebabdbc4e8995462442fd6",
		["Тебе нужен Сару Холодная Ярость из \"Пылающей наковальни\". Это в Аллее Чести, в конце дороги, идущей справа от Рудника Ржавого каньона."] = "e64f4df8c7e58b6297509a694416a3f4",
		["Тебе нужна Замджа из Жаровни Борстана. Как войдешь в Волок из Аллеи Силы – вверх и налево."] = "0a849e65bb54685b03424a28e2b4c13c",
		["Тебе нужно в лавку Чародейских товаров Годана. Ищи его в западной части Волока, рядом с Аллеей Мудрости."] = "7c40c8dcef4c28192551a41a2dee01de",
		["Загляните в механическую мастерскую Ногга. Это в Аллее Чести, к северу от Рудника Ржавого каньона."] = "1a123cd209d94b6100489b018fff1c1f",
		["Арнок хорошо перевязывает раны. Ищи его в доме \"Выживание сильнейших\" на берегу озера рядом с Обителью Духов. Иди вверх и на запад по Аллее Силы до озера."] = "bce8743c8a0bd63dc3920724e764d1fa",
		["А, Лумак… Он вечно ловит рыбу, вместо того чтобы драться. Ты найдешь его на берегу озера в Аллее Чести. Кстати, будешь там – передавай привет Шанкису."] = "ff136b77a5b4f0167b2bc90bed633ab3",
		["Травы… Тебе нужно поговорить с Джанди в ее дендрарии, на Волоке. В Аллее Мудрости, за рынком Азорана, есть деревянные ступени. Поднимись по ним – и ты найдешь ее."] = "f4d8e423146d1060237e65e944828604",
		["Отправляйся в Волок, в лавку \"Кодо-кожевники\". Спроси там Камари."] = "ec858405ef47afd35954b41baf604e21",
		["Найди Рудник Ржавого каньона к северо-востоку от озера в Аллее Чести. Там поговори с Макару."] = "03234dcd1c0db3655e7b003ee852c8fd",
		["Тьюд покажет тебе, как свежевать добычу. Ищи его в \"Кодо-кожевниках\", на Волоке."] = "5d4bbbbb15b947844d18eda0fa01c581",
		["Портняжное ателье Магара находится на Волоке. Ищи ее к югу от огромного дерева, по соседству с кодо-кожевниками."] = "908c0040569523d5a3f6346f2a16f4ba",
	},
	["Ордынский вестник войны"] = {
		["Война надвинулась на нас, $n. Для каждого в Орде пришло время ответить на зов и присоединиться к битве против трусливого Альянса."] = "500674c7da105457382c51908165838f",
	},
	["Ормак Лютострел"] = {
		["Я много знаю и многое могу тебе поведать, $c. Научись же охотиться честно."] = "5b5b66a181411dac0931427a9ff18c6c",
		["Я не могу тебя учить."] = "27047ba17cce8edfba9757279f001d39",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Ормир Кремнеглаз"] = {
		["Не могу помочь тебе, $n. Я обучаю только разбойников."] = "fa078d44ecb0731e4c2a45f949ae67b1",
		["Чем я могу помочь тебе, $n?"] = "22dba637f525eff7a4f6ca7d8c7294cb",
		["У меня есть кое-что для тебя, $n. Кажется, это важно."] = "703991b7b1b4a5bcf7524b1a79f94a81",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Ормок"] = {
		["Изувеченная Длань увидит Орду во всей былой славе, когда ее перестанет сдерживать робость Вождя."] = "5070548a9c45a19ece573bb4b49296f4",
		["$C – это не ко мне."] = "60044d7f82718835ed805cb5fdc7067b",
		["Посланцы Черного Ворона сегодня утром вручили мне это письмо. Оно адресовано тебе, $n."] = "665345d33fb8e63831d075e7b6457308",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Оруженосец Леорен Мал'дерат"] = {
		["Здравствуй, $c. Я Леорен, смотритель стойл Крепости Кенария."] = "872c292ead04a6156c67f8c254e7c307",
	},
	["Оруженосец Малтрейк"] = {
		["Моя жизнь – в служении господину."] = "a78bfb1ca9baf31083c2a2913d0f9ec6",
	},
	["Осборн Дитя Ночи"] = {
		["Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
		["Не думаю, $c, что ты захочешь учиться у меня. Тебе нужны наставники твоего класса."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
		["У меня есть кое-что для тебя, $n. Кажется, это важно."] = "6306d9157dde71c4fa6c0cefe5c64195",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Остил де Мон"] = {
		["Предназначение воина – защищать. Как защищаем мы в бою своих товарищей, так должны защищать и интересы Отрекшихся."] = "bab02b057326c5ce92b70b19685745ed",
		["Не трать мое время, $c."] = "3484fd102c48eb2fcac5e4f8ecc5347e",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Остротерн"] = {
		["Чары развращают лишь тех, кто слаб духом. Не прекращай работать над собой, если не хочешь, чтобы тебя постигла такая участь."] = "073492d1b775dad17b73e4495accc8b7",
		["Боюсь, твоя душа недостаточно темна, чтобы нам было о чем говорить. Оставь меня в покое."] = "8045db4a1a25656b86eb87b955fbe642",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	["Отец Иниго Монтой"] = {
		["Король-лич хочет, чтобы о нем узнали в нашем мире. Этого нельзя допустить."] = "2546edb7adcfdf6f1c9a8e4e04303b07",
		["Вера… Кто-то утратил ее, а кто-то обрел. Ее нельзя уничтожить и нельзя создать.$B$BИли вы говорите о ризах Веры? Об одежде, что самые преданные жрецы и воины носили в бою с Плетью во время последней войны?$B$BДа, много таких одежд утеряно… Украдено демонами Наксрамаса."] = "573851fae77cd06367281ad5d921bf9b",
	},
	["Отец Кобб"] = {
		["Да, $c?"] = "901d3b1160b38eacb61be277a1eab438",
		["$N, ну что может сделать для вас такое ничтожество, как я? Разве что научить чему-нибудь…"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Отец Лазарус"] = {
		["Да, $c?"] = "901d3b1160b38eacb61be277a1eab438",
		["$N, ну что может сделать для вас такое ничтожество, как я? Разве что научить чему-нибудь…"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Отец Ланкастер"] = {
		["Да, $c?"] = "901d3b1160b38eacb61be277a1eab438",
		["$N, ну что может сделать для вас такое ничтожество, как я? Разве что научить чему-нибудь…"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Отхо Можи'ко"] = {
		["$gДруг:Подруга;, у меня есть все, что нужно для кулинарии!"] = "c7327c44d6426ff5c6df14952cdcd98e",
	},
	["Отшвартуй"] = {
		["\"Похоже, тебе может потребоваться пересечь Великое море. Ну что ж, ты $gобратился:обратилась; по адресу: здесь место стоянки \"Девичьего Каприза\", лучшего пассажирского корабля этих вод. Когда он прибудет, просто забирайся на борт – и ты $gсам:сама; не заметишь, как очутишься на песчаных пляжах Тернистой долины\"."] = "7384674c38fa1ede1c57e9601476e82b",
	},
	["Отшельник Ортелл"] = {
		["Уходи сейчас же! Мне нет дела до чужаков."] = "e79d5d1fab3e655e71f596369ca816fa",
		["Ты уже $gвернулся:вернулась;! Чем я могу тебе помочь?"] = "48165a36b82154ca1c0e0b8bcd69e4a2",
	},
	["Оуэн Вон"] = {
		["Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда."] = "2e4eca05cb76135045a9a7c0e66e45af",
		["С тех пор как пал Даларан и был разрушен Кель'Талас, такие товары встречаются крайне редко. Но Лукан Корделл и еще несколько торговцев все еще могут выполнять наши заказы."] = "52ce57327118edf04bd3864c3342a693",
	},
	["Офицер Алый Клинок"] = {
		["Здравствуйте, $c – я сотрудник отдела рекомендаций, действующий от имени Оргриммара. В мои обязанности входит помогать тем, кто получил рекомендательные жетоны Орды.$B$BЯ принимаю разное количество жетонов, но выгоднее всего для вас будет сдавать их по 10 штук за раз. Когда сдадите мне жетоны, я внесу ваши деяния в наши летописи, и Оргриммар будет вечно признателен вам за них."] = "949dfe6a8c87b40d13fd01262e2d4142",
	},
	["Офицер Бифштеккер"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь Изгнанников Гномрегана. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Изгнанников Гномрегана за проделанную работу."] = "c2a6c5d7d43cb3650eb787a68e5d0391",
	},
	["Офицер Ву'Шалай"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь племя Черного Копья. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Орды.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность племени Черного Копья за проделанную работу."] = "39dff0023660d86508c6db5afb6c0d8a",
	},
	["Офицер Гаруш из ордена Серебряного Рассвета"] = {
		["Добро пожаловать, $gдруг:подруга;. Я офицер Гаруш. Я горжусь тем, что состою в международной организации, известной как Серебряный Рассвет. Наше дело – быстро и беспощадно бороться с любыми проявлениями зла в Азероте. Мы не являемся политической силой и не собираемся таковой становиться. У нас лишь одна цель, и ради этой цели мы призываем к дружбе как Орду, так и Альянс – дружбе во имя истребления зла!$B$BВо имя Рассвета, $gбрат мой:сестра моя;!"] = "571e467e9d1b4d0f258ad53d2287f355",
	},
	["Офицер Готена"] = {
		["Приветствую, $c! Я сотрудник отдела рекомендаций, действующий по заданию Подгорода. Моя обязанность – помогать искателям приключений, получившим рекомендательный жетон Орды.$B$BЯ принимаю жетоны в любых количествах, но наиболее выгодно для тебя – сдавать их по 10 сразу. Когда ты сдаешь нам жетоны, я заношу это в летописи. В результате ты получишь признание в Подгороде за то, что $gвыполнил:выполнила; свой долг."] = "785ab4fc105ad5b95f78d5dd7a0e36e2",
	},
	["Офицер Громовая Странница"] = {
		["Здравствуйте, $c. Я уполномоченный сотрудник отдела рекомендаций Громового Утеса. В мои обязанности входит помогать всем, кто удостоился рекомендательных жетонов Орды.$B$BЯ принимаю такие жетоны в разных количествах, но лучше всего сдавать их партиями по 10 штук. Приняв жетоны, я внесу в наши записи сведения о ваших заслугах, чтобы вы могли снискать должное уважение среди жителей Громового Утеса."] = "65414b48556b1233b03316c19af1740a",
	},
	["Офицер Железнобород"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь Стальгорн. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Стальгорна за проделанную работу."] = "a002d75a96a783b4847631d35c12cda1",
	},
	["Офицер Лунный Свет"] = {
		["Здравствуйте, $c. Я уполномоченный сотрудник отдела рекомендаций Дарнасса. В мои обязанности входит помогать всем, кто удостоился рекомендательных жетонов Альянса.$B$BЯ принимаю такие жетоны в разных количествах, но лучше всего сдавать их партиями по 10 штук. Приняв жетоны, я внесу в наши записи сведения о ваших заслугах, чтобы вы могли снискать должное уважение среди жителей Дарнасса."] = "9ee40dfd64a80fc0f2e81e82830840f6",
	},
	["Офицер Малуф"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь Штормград. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Штормграда за проделанную работу."] = "a11a7d36f03be1a27def349ef4faa820",
	},
	["Охотник Леопольд"] = {
		["Они едва не отправили моего брата, Локси, на эту встречу. Он за псами-то своими уследить не может, что уж говорить о том, чтобы представлять Алый орден!"] = "55bee4d94fe2ec071c1f49801c48e21a",
		["Люди моей профессии изучают и восхваляют сверхъестественную способность некрорахнидов выслеживать и убивать своего врага. Я сам убил тысячи этих тварей, когда рвался избавить этот мир от Плети.$B$BХотя я терпеть не могу некрорахнидов за жестокость, их способностями нельзя не восхищаться. Они выполняют свою работу – и выполняют ее отлично."] = "1bb2d36c1471ccc6854f72988e3b2362",
		["Эти грязные твари повсюду!$B$BЕсли ты предпочитаешь охотиться на открытом воздухе, большую их часть ты найдешь в районе Проклятого Леса и Долины Ужаса. Немало их также в Долине Ужаса. Еще они появляются, похоже, почти в любом лагере Плети в Восточном Лихоземье.$B$BЕсли ты – $gнастоящий житель:настоящая жительница; подземелий, ты найдешь кучу этих тварей в Стратхольме, а злобных некрорахнидов – в Некроситете."] = "86a91c29a823bc19ba74c174cebf69ae",
		["Я обнаружил, для чего может пригодиться панцирь некрорахнида и различные части его тела. Я смогу смастерить чрезвычайно легкое и очень опасное снаряжение, соединив эти части с оскверненными магическими доспехами, потерянными в Наксрамасе."] = "c3277c86a4fa82a1bddd12127f42cee9",
	},
	["Охотник Мархор"] = {
		["Зул'джин однажды вернется, $r. Помяни мои слова. До тех пор мы все держим наши позиции и делаем, что можем, чтобы сохранить народ лесных троллей.$B$BС учетом этого мой долг как главного охотника деревни Сломанного Клыка – обеспечить безопасность окружающего нас мира.$B$BЗвери на этой территории должны быть под контролем.$B$BТебе нужна работа?"] = "a045bbb3ca0c9722e39090c24a9c5d87",
	},
	["Охранник Каэр Дарроу"] = {
		["Тунеядство, хулиганство, сквернословие, драки и все прочие непотребства, которыми ты собираешься заниматься, в Каэр Дарроу запрещены."] = "4c4f28300ec91dd44dcc6b9766779e5d",
		["У тебя вид, как у уличной шпаны!"] = "f4a68005ee615866bd6901fa901730b9",
		["У меня много нерастраченной злобы и ярости. Только дай повод, бродяга."] = "8aefd7ed4734fdad575f3aa8cabd868b",
		["Я за тобой слежу, $r."] = "98696987285136bfb07bf8b6b4ca71f2",
		["Будь $gосторожен, незнакомец:осторожна, незнакомка;. В нашем городе не терпят еретиков."] = "a97a57480f28e32779349ee115d11474",
	},
	["Павший герой Орды"] = {
		["Сложно себе представить, что столько смерти и отчаяния заключено в столь маленькой площади; но за болотом – земля, полная хаоса и разрушения.$B$BСтупай осторожно, $gискатель:искательница; приключений. В Выжженных землях нашли свой конец существа, намного превосходящие тебя."] = "3df1e6bc0bb085364a05607f4fcd932b",
		["Поверишь ли ты, что в самый черный свой час на вершине всей моей жизни я потерпел неудачу?$B$BКогда я бежал от бессмысленной, всеразрушающей силы, затопившей нас, то слышал только крики моих солдат и громкий стук собственного сердца.$B$BВскоре после того я вернулся в Выжженные земли, надеясь спасти своих людей и восстановить свою честь. Вместо этого меня схватили и забили насмерть.$B$BТо, что я обнаружил во время допроса и последовавшей за ним пытки, было чудовищно."] = "7e860e6ffee6f60c2945a58e828890a1",
		["Нас называли Хваткой Тралла – двадцать самых почитаемых и прославленных солдат Тралла.$B$BЯ приказал полку разбить лагерь здесь, на границе Выжженных земель, пока мы ждали приказа отбыть из Оргриммара. Недели проходили без вестей от предводителя; люди теряли терпение.$B$BНужно было принять решение, $n. Я был молод и честолюбив, не боялся ничего. Батальон должен был отправиться в Выжженные земли под моим началом.$B$BРешение, о котором я потом пожалел."] = "246b857180cfb8d95954fa06f7183c80",
		["Мои тюремщики были очень жестокими, $n. Они поочередно пытали меня и лейтенанта Кирита, заставляя нас смотреть на мучения друг друга. В один из самых жутких дней, когда нам удалось получить небольшую передышку, Кирит рассказал мне о том, что случилось с моими людьми. Он предложил мне план их освобождения.$B$BИх судьба была хуже смерти, даже хуже того, что пришлось перенести нам с Киритом."] = "17112182a94dae91af72cf8bb58dde4b",
		["Сожаление. Это все, что у меня осталось. Одно неверное решение повлекло за собой череду ужасных последствий. Если бы только я дождался тех приказов! Может быть, из них бы мы узнали больше об опасностях этой проклятой земли? Может, нас направили бы в другое место? В итоге во всем виноват я. Все это из-за меня."] = "bde2d9c0c5ebfdc5d27951fa01622b41",
		["Ни ты, ни я не можем даже вообразить ту боль, что испытывает несчастный, когда его душу отрывают от тела. Они не мертвы, но и не живы. Они бродят по земле, прислуживая тем, кто связал их с этим миром.$B$BЛорд Разелих, повелитель демонов этих земель, поработил их всех. Девятерых он забрал с собой, поместив связующие камни у Темного портала. Оставшиеся девять были распределены между его подчиненными."] = "e80fa3ad4ec81953dd42b32b58f4bb3d",
	},
	["Пакстон Гантер"] = {
		["Вы знаете о рыбной ловле больше меня. Я слышал, что у старика Хеминга в Пиратской Бухте есть книга \"Ты и окунь\". Из нее вы точно узнаете что-нибудь полезное."] = "88fec34af6aec4e24b11fe1f3ad60422",
		["Для дальнейшего обучения тебе надо найти Ната Пэгла из Пылевых топей."] = "b4e4101905820aead3b6b58b95cdc8ed",
		["Могу научить тебя ловить рыбу."] = "cc6057593751f84f1d2743551c270cf4",
	},
	["Паладин Серебряного Рассвета"] = {
		["Битва выиграна. Угроза Плети устранена – на время. Мы можем направить свои ресурсы в помощь тебе, в благодарность и для подготовки к грядущему."] = "4b36cae8ffab10bd243caafa37fd7ebd",
		["Битва протекает неплохо. Силы Плети кажутся ослабевшими. Я уверен, изгнание их с наших берегов – лишь дело времени. Я направлю свою магию в вашу сторону, чтобы помочь вам в этой борьбе."] = "fdaab9e2b8a9ef75ee889a83109b9758",
		["Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет вас к дальнейшим победам."] = "b4933008c7c76fbea261d6b6ba7192ca",
	},
	["Панд Камневяз"] = {
		["Теперь лишь известный доктор Грегори Виктор может помочь тебе отточить твои навыки. Его можно найти на Нагорье Арати в Павшем Молоте."] = "9cf8ec329c7dba4ed49715a51df03f95",
		["Бала Лок'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!"] = "b1a4bc076a7a69d393730100ba28a6d7",
		["Я могу научить тебя оказывать первую помощь."] = "0a7cfd25fd53892de58e9eaf21bc1e16",
	},
	["Парквел Финталлас"] = {
		["Всегда приятно, когда кто-то желает со мной поговорить. Как у тебя дела, $c?"] = "b219a709c06746dd4308b42ceae14a51",
		["А теперь ответь мне, $n.$BКто стал Королем-личом еще до распространения чумы в Лордероне?"] = "f6f7ba02da1200cdb9a4345823966550",
	},
	["Пароклапан"] = {
		["Еще столько всего надо сделать! Союз установил нам жесткие сроки – и лучше бы их не срывать!"] = "f04e73ec5cd32473774944eedc48a86f",
		["Директор Ридлвокс назначил меня главным в Союзе по разработке резака. Всего несколько месяцев на новом месте – и уже неприятности! Не поможешь мне, $n?"] = "0cc088f013cb6fc40acf3a7acfed831d",
		["Видишь, новый резак Торговой компании лучше моего последнего образца во всем – от заменяемых рук до управлямых клешней! Мой босс поставил мне очень жесткие сроки, но ни я, ни мои парни не можем ничего придумать. $b$bПоэтому мы решили \"одолжить\" один из их прототипов. Я послал Визлкранка в Нефтяное болото, но он до сих пор не вернулся!"] = "3b982d83ca250aba2a857fe1a2388627",
		["Интересно, интересно… $N, я знаю одну девушку-друида, которая живет на вершине холма над Пещерами Стенаний. Возможно, она знает больше об этом осколке.$B$BТеперь прости, но я должен вернуться к работе."] = "b553c80d00cdd9070918c489df5ae9bc",
		["Ты $gпоказал:показала; мне, чего желаешь, и $gзаплатил:заплатила; драгоценными камнями. Я буду учить тебя…"] = "47394017854fb69c8e3e7c9f33b6da55",
	},
	["Перия Ламенур"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "12e2351404174f85aa98fa3a3524bcd0",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "b439ced1ada35971e9ff2706f428bff0",
	},
	["Пефредо"] = {
		["Приветствую, $c. Ты желаешь обрести тайное знание?"] = "c8d841d3dd0d9f3195df9fb37ffd84b4",
		["Приветствую, $c. Мне жаль тебя, секреты настоящей магии выше твоего понимания…"] = "b7091bbfed54b698c06cee9a75fe004b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "857ea30c7f6e11d987a132b4e84da4dc",
	},
	["Пиалл Тихая Поступь"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "aa33a0b2e8a8965bb6b87437e70b467c",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "74007003c2cd2bd77e1c3e8b0496a254",
		["\"Поваренную книгу умельца\" можно купить у Вулана в Деревне Ночных Охотников. Тебе она понадобится, если ты хочешь расти над собой."] = "3c198949d138d51ba2c086ace10803eb",
		["Я могу научить тебя готовить!"] = "70f65371057af31cdb1fa7f511b011d1",
	},
	["Пирс Шеклтон"] = {
		["Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?"] = "a6c8531f923dc7ee0e543e0e81ce1717",
		["Здравствуй, $c. Вот что я тебе посоветую: будь $gосторожен:осторожна; с магией. Она может легко погубить новичка."] = "449fe8a183d9fbd6474051e5e1ba406e",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Питер Гален"] = {
		["Если ты $gпришел:пришла; охотиться на драконов – будь $gмоим гостем:моей гостьей;. Кстати, по какому адресу мне отправлять соболезнования?"] = "ecd8f490207aa548a5bde5be21a12239",
	},
	["Повар Гильм"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "c4162cb7f63061b6eae39dc6b6b814dd",
		["Разыщи Шандрину в приюте Серебряного Ветра. Она может продать тебе \"Поваренную книгу умельца\"."] = "fe8baba790f8edd0a4e3d2f680dfe89a",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "de96efe8437890d30d0aff9e01f5f7cb",
		["Я могу научить тебя готовить!"] = "8aeb96ef5db5b2d70e98dbbaca63f721",
	},
	["Полководец Горчук"] = {
		["Тром'ка, $c Орды! Будь $gгордым:гордой;! Я полководец Горчук, командир военной кампании Орды. Нас ждут нелегкие времена, но мы победим, как всегда.$B$BЕсли у тебя есть вопросы – задавай."] = "ff1113878810a7326aec257f03be15c6",
		["Война скоро начнется, $c! И Орда, и Альянс закончили все свои приготовления. Сейчас, пока мы разговариваем, припасы уже везут в Силитус, и до их прибытия осталось меньше $2113w. После этого храбрец, сумевший восстановить скипетр Зыбучих песков, ударит им в гонг на помосте Скарабея. Тогда врата Ан'Киража распахнутся, и начнется битва, равных которой не было уже много веков!$b$bЛок'тар огар!"] = "f6c0c1ea475d9aa33d7c2f43bb8f2ba6",
		["Мы заодно с Альянсом, $r. Зло, столь древнее, что мир позабыл о нем, стремится поглотить нас всех – сначала Калимдор, а затем и весь остальной Азерот. Им движет ненависть ко всем творениям великих Творцов: Титанов Вечности.$B$BМы все стоим на пути войск К'Туна. Мы ударим первыми и сломим силы Ан'Киража. Пусть Азерот дрожит от объединенной мощи Орды и Альянса.$B$BТы $gнужен:нужна; фронту!"] = "867569b880563887beb157cd19a1f51b",
		["Ситуация такова: медные слитки – $2018w из $1998w, оловянные – $2005w из $2006w, мифриловые – $2008w из $2009w."] = "44b41addd3f8437df6055fc58b0a56d6",
		["Мне только что принесли отчет. Сейчас у нас имеются следующие припасы: мироцвет – $2020w из $2021w, огнецвет – $2050w из $2051w, пурпурный лотос – $2054w из $2055w."] = "23e117cdf828f64a8f7832003c53ad13",
		["Одну минутку… столько цифр – не упомнишь… Итак, по последним данным заготовлены следующие припасы: тяжелая кожа – $2066w из $2067w, плотная кожа – $2070w из $2071w, прочная кожа – $2073w из $2074w."] = "5c6ee7053a94c92a28eaa92bf7f821d5",
		["Бинты? Что, надеешься выжить? Ха! Ладно, $r, я расскажу о текущих запасах. Шерстяные бинты – $2079w из $2080w, бинты из магической ткани – $2085w из $2086w, бинты из рунной ткани – $2089w из $2090w."] = "263b5382493c8292898a68606c67c3c9",
		["Еда! Я могу говорить на эту тему бесконечно! Итак, постный стейк из волчатины – $2095w из $2096w, пятнистый желтохвост – $2102w из $2103w, запеченный лосось – $2105w из $2106w!"] = "a47ee7bcd6b3b8125ec6007fb1bbd6b9",
	},
	["Полководец Клинозуб"] = {
		["*Клинозуб сплевывает.*$B$BЯ – воин Орды, $n. Знание того, что наши враги сидят в крепости, находящейся меньше чем в дне пути от Каргата, и строят против нас козни, приводит меня в ярость.$B$BКак бы я хотел сбросить с себя оковы долга и уничтожить их во имя Вождя.$B$BУвы, у всех нас есть обязанности, которые мы должны выполнять."] = "9932a76da45813ab365ef10fee5256c9",
		["Воистину, я завидую тебе: сражаться во имя Орды на переднем фронте. Мое дело – командовать.$B$BКонечно, в юности я исполнил мечты, которые сделают сносной мою старость. Теперь меня питают слава побед и горечь поражений – все через солдат, которыми я командую."] = "bb2d2d3e107f276b6034eab77a1e8ed1",
		["Я спал, $N… о да, я спал. В моих снах я умирал тысячи раз разными способами. Некоторые могут назвать такие мои сны кошмарами. НЕ Я! В моих снах я умирал в пылу битвы. За каждую мою смерть десять тысяч врагов Орды падали предо мной. Это прекрасно!"] = "f2a689f6928cda5b485631c437fdedaa",
	},
	["Посвященный Серебряного Рассвета"] = {
		["Битва выиграна. Угроза Плети устранена – на время. Мы можем направить свои ресурсы в помощь тебе, в благодарность и для подготовки к грядущему."] = "ebde1b78097e360ae80271b45ac8ec9b",
		["Битва протекает неплохо. Силы Плети кажутся ослабевшими. Я уверен, изгнание их с наших берегов – лишь дело времени. Я направлю свою магию в вашу сторону, чтобы помочь вам в этой борьбе."] = "4d4e9052d3c36392e6211cb442ea3b1e",
		["Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет вас к дальнейшим победам."] = "0973188afdf5745ee7a53c42da926c63",
	},
	["Посланница Среброкрылых"] = {
		["Времена года сменяются в свой срок, но ты еще пребываешь в весенней поре жизни. Пожалуйста, возвращайся к нам позднее, $c, когда станешь более $gопытным:опытной;."] = "142259b01ef398530e6a98ed1a7c183f",
		["$C, мы не стыдимся сказать, что нуждаемся в любой помощи, которую сможем получить в битве за Ущелье Песни Войны. Принять участие в битве сегодня, использовать в ней свои умения – честь более великая, чем когда либо. Кроме того, Среброкрылые Часовые станут относиться к тебе более благосклонно, когда ты начнешь помогать нам. Ты присоединишься к битве?"] = "8c59b436d4f8db5f6a0c712f93e98b11",
	},
	["Послушник Наралекса"] = {
		["Наралекс вновь спит!$b$bДавным-давно Наралекс отправился в эту пещеру с благородной целью: войти в Изумрудный Сон и превратить Степи в пышный лес. Его сосредоточенность была нарушена, и демонические видения опутали его разум.$b$bТеперь чудовища из его сна пробиваются в мир. Необходимо пробудить его от кошмаров, иначе он навеки затеряется в них, а великое зло вырвется из его сновидений на свободу.$b$bНо начать ритуал пробуждения я смогу не раньше, чем буду уничтожены его приспешники – повелители Змей."] = "a81c0f51674289d2ce942b92e5a47dfd",
	},
	["Праздн'рел"] = {
		["Наша кара одновременно и наше благословение."] = "b402e32cb7eddbc1a8b5f35a4ed01673",
	},
	["Праздничный сказитель"] = {
		["Наслаждаетесь атмосферой фестиваля, $c?$b$bВ то время как Хранители Пламени тяготеют душой к огням настоящего, я в большей степени историк, хранящий воспоминания о фестивалях прошлого. Конечно, я документирую и празднества этого года. Пока все идет неплохо, как по-вашему?$b$bЗнаете, $n, во всех фестивальных огнях, горящих на протяжении всего празднества, присутствует определенная сила. Мы заботимся о наших огнях, но я уверен, что священные огни пылают и в городах наших врагов…"] = "0b4060988eee47f0f6a9f5aadfb007a3",
	},
	["Пратт Макгруббен"] = {
		["Клянусь, если Квинт еще раз попробует закрепить на мне наживку, я срублю его дерево своим мечом – а он не такой уж и ржавый!"] = "850288efe4dccb31f59391e76405f2b9",
		["Приветствую, $c. Если ты ищешь изделия из кожи или инструменты для работы с ней, ты пришел к нужному паладину в отставке."] = "f4227fc6249932f3aa71dc28e89d87cf",
	},
	["Предатель шайки Кровавого Паруса"] = {
		["Дорогу, грязный пес! Ревилгаз избавил меня от виселицы, но мое наказание может быть почти таким же скверным."] = "1fad4f6979d035d1a0174cea5dd2b07c",
	},
	["Предвестник Балтазад"] = {
		["Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов."] = "c42d03e178578b6a44439fb32f8365a9",
	},
	["Призыватель ветров Калдон"] = {
		["Война идет полным ходом, и у нас нет недостатка в отважных воинах Орды и Альянса.$B$BЕсли бы они еще друг друга не убивали…"] = "d3444f4b56739837e99b8054c798a837",
	},
	["Принц Тортелдрин"] = {
		["Я правил этим королевством 10 000 лет. За это время услышал немало удивитильных историй от тех, кто странствовал по священным землям Дома Шен'дралар.$B$BЯ не могу покинуть это место, поэтому люблю обмениваться историями с гостями. У вас есть что рассказать мне, или вы хотите сами что-нибудь послушать?"] = "fb9a6eb92214ce1abb9831293212112b",
	},
	["Профессор Таддеус Палео"] = {
		["Добро пожаловать на ярмарку, молодежь! Мы собрали чудеса со всего света для услаждения вашего взора. О, и пожалуйста, дайте мне знать, если вы смогли собрать младшую колоду Темной Луны, как хозяин… в смысле, я буду нижайше заинтересован в них."] = "175e8b03efe27c1ffb0ce6644f4ac989",
		["Мы разбросали по всему миру карты Новолуния, чтобы кто-нибудь мог собрать колоду из любых восьми мастей. Если найдешь восемь карт одной масти, то получишь одну старшую карту Новолуния, которая действует как могущественный артефакт и поддерживает связь с ярмаркой Новолуния."] = "3f7bf1a688d937c820a4dd5e2b16b4e4",
		["Если ты соберешь колоду pверей, я дам тебе в награду редкую карту Новолуния с синим драконом. Она очень пригодится для восстановления магической энергии."] = "f9fbc218ea70279123d05e8059b07a52",
		["Если вы соберете полную колоду Порталов, то получите старшую карту Новолуния: Энергию Круговерти Пустоты. Эта карта время от времени будет возвращать вашу душу в тело после смерти и воскрешать вас."] = "cabe10467ba55951a39c5efc5b01e754",
		["Если ты сумеешь собрать всю Колоду Элементалей, то получишь в награду карту Водоворота – старшую карту Новолуния. Она будет время от времени наносить значительный урон противнику, с которым ты сражаешься."] = "6c0066e9c134f9932cf5d4baf797844d",
		["Если ты соберешь всю колоду Полководцев, я дам тебе редкую карту Новолуния под названием \"Героизм\", которая будет лечить тебя в ближнем бою."] = "5b4d4908a2259afea5d5edad7b0cb6e5",
	},
	["Пружиннер Шумотор"] = {
		["Если мои расчеты верны, колесо скоро уйдет в историю!"] = "5b4916cbd8099a80750c2e7c7f7d81f4",
		["Ты весьма $gпреуспел:преуспела; в своих познаниях. Если хочешь учиться дальше, найди Жужжера Скрепокрыла в Прибамбасске."] = "7fd261ac07f2ec746da51fd338facc6e",
		["Да у тебя мозги расплавятся от моих уроков! Возвращайся, когда будешь более $gподготовлен:подготовлена;!"] = "b755b1fc6301fcee6cdc7c58adc7f319",
		["Отлично, ты $gпоказал:показала; себя в деле! Пора перейти к следующему этапу…"] = "3f10866c8c4a33701d0af2dbef824694",
	},
	["Пьяный завсегдатай"] = {
		["Не мешай мне веселиться…"] = "f6084500090ca7d12e2c66378cd5aa82",
		["Кажется, Стукарь налил в одну бочку слишком много! Сейчас рванет!!!"] = "b0838447478eb4443855f138adb0edf6",
		["Мне кружку эля Черного Железа. Ох, ты не $gофициант:официантка;?"] = "ece4d3768034c645ef33751734b2eff2",
		["Чего уставились, $gуважаемый:уважаемая;?"] = "655a713e625a9c8aa562c139e3b108c5",
	},
	["Рабин Сатурна"] = {
		["Не слушай пульс мира – ответ сокрыт в тебе. Ты знаешь правду."] = "f4177bd0951c2f715a697139a8a7c918",
	},
	["Райдон Сумеречный Воитель"] = {
		["Приветствую вас, друг мой. Прошу вас, уделите мне пару минут…$B$BМы немало пережили за время становления Тельдрассила. Вдобавок ко всем трудностям и невзгодам, у нас закончилась ткань. Если у вас найдется лишний материал, я прошу вас пожертвовать его на благое дело. Это, разумеется, поднимет вашу репутацию в глазах всех ночных эльфов!"] = "f1bba8b8fe977e9469a2a2d8535cd5bc",
	},
	["Ралстон Фэрнсли"] = {
		["Эй, ты… Заруби себе на носу: помогать Отрекшимся в такие страшные времена – в твоих же интересах. А теперь слушай внимательно – повторять я не люблю.$B$BУ нас сейчас жуткий дефицит ткани. Бинты и другие тканные материалы почти закончились. Чтобы пополнить иссякшие запасы, мы принимаем ткани безвозмездно – то есть даром. Очевидно, денег ты за это не получишь, но твое участие не останется незамеченным."] = "142f4365ed15cdab171cacd75afb66fc",
	},
	["Рамсен Бракодел"] = {
		["Чем я могу помочь тебе? Нет, постой! Чем ты можешь мне помочь?"] = "b89ae8e419d78a1676fef5d680e3b072",
	},
	["Рандал Ворт"] = {
		["Я уже немало знаю о стиле. Осталось лишь отшлифовать технику работы с кожей. Как хорошо, что этот славный малый Саймон всегда готов помочь мне."] = "1308cc62e8033d85625722f0011e1e98",
		["Мне больше нечему тебя учить – разве что некоторым мелким нюансам. Поговори с Саймоном Кожевенником, он знает много сложных приемов работы с кожей."] = "44f2dd6bc6a05014e239cdf105eec1d8",
		["Правда, эта одежда мне идет? Да, мастерства мне не занимать, я могу и поделиться секретами профессии. Не перебивай, ладно?"] = "65cbb6b9c7b22c69fa4cf09268afee79",
	},
	["Рандал Охотник"] = {
		["Я могу научить тебя тонкостям верховой езды, если у тебя достаточно золота, чтобы оплатить урок!"] = "2b4a5b1134898503d988f837bd4622b7",
		["Знай, $c! Прежде чем я научу тебя верховой езде, ты $gдолжен:должна; завоевать полное доверие людей Штормграда."] = "9821f399d475cf61a0344386783f28f9",
	},
	["Рансин Доннер"] = {
		["Здравствуй, $c. Не тебя ли я недавно видел на одном собрании? Лицо вроде знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду."] = "c5afae87abc614718a9d01193dc59430",
	},
	["Распорядитель гонок Гореездник"] = {
		["Гонщики-гоблины обладают огромной мощью, но гномы всегда прячут пару-другую хитростей в их автомобилях…"] = "85279dcb34b8519c4aa585d439098471",
		["У кого самая быстрая машина? Да кто ж знает?!"] = "f8abb3ccf31041b3183d41a1896f28e3",
		["Приветик, $c! Добро пожаловать на гонки Мерцающей равнины!"] = "cf552d2d1ba02525e8fcd3e41003294d",
		["Смелый не хочет, чтобы Тирт знал, что он все еще на Мерцающей равнине, поэтому он превратил себя в цыпленка!$B$BЕсли найдешь Смелого, попробуй подозвать его. Быть может, он выйдет из укрытия."] = "818428d85cc2451411dffed3878e6204",
		["Добро пожаловать на гонки! Надеемся, вам здесь понравится. Да, и не ставьте все деньги на одного!"] = "3fda9ba9ead86b9e29b7d1fc68875623",
	},
	["Рахауро"] = {
		["Рад нашей встрече, $c. Если у тебя нет какого-то особого дела к моей госпоже Магате, ты можешь поговорить со мной.$B$BЯ веду практически все ее дела, чтобы она могла сосредоточиться на более важных вещах. Возможно, нам есть что обсудить, перед тем как ты встретишься с ней?"] = "d3cf6d45a6ea3ef19313a80754b85210",
	},
	["Ребан Вольный Странник"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "aa7ffa0f57cad7bf854f0f5b49d0d64f",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "99ae018db8b20fbf298b816ac77acd9c",
	},
	["Ребекка Лафлин"] = {
		["Добро пожаловать в городское бюро регистрации гильдий. Чем я могу вам помочь?"] = "597ed139334da6a50351437c63a259fd",
	},
	["Регнус Громовой Гранит"] = {
		["Чем помочь надо?"] = "ff4c1db50d39977890db3fe889ea21ae",
		["У меня тебе учиться нечему. Ты $c, вот к своему учителю и ступай."] = "65ffa984c80ec793cab656acd848ac8c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	["Резерфорд Оттяжка"] = {
		["Я – Резерфорд Оттяжка, главный поставщик Осквернителей Низины Арати. Если согласитесь стать нам $gдобрым соседом:доброй соседкой;, сможете покупать у меня товары и чинить поломки."] = "8240b8eb0361e85e9da92de68294dca1",
	},
	["Рексар"] = {
		["Рад встрече, $c. Я – Рексар, герой Орды и повелитель диких животных. Я служу Траллу."] = "af40e357c59edbf15d948e3c6f65eeb5",
	},
	["Ремесленник Вильгельм"] = {
		["Мастер-ремесленник Омарион однажды ночью просто исчез. Прямо как растворился… Ффф! И нету! Выходит, кроме меня, теперь и некому делать товары для фронта."] = "9cb182e6099250bd1e21445a5a8a786a",
	},
	["Ренато Галлина"] = {
		["Эй, $N. Ты $gпохож:похожа; на $c, $Gзнающего:знающую:c; толк в вине. Я хочу попросить тебя об одной услуге и, думаю, могу сделать тебе предложение, от которого ты не сможешь отказаться… а ладно, проехали!"] = "2849e3835de3a2c6a8aa1626f6cec474",
	},
	["Ретгар Врата Смерти"] = {
		["У нас есть долг, $c. Долг перед Ордой."] = "a325f9b1e91967df6e334cb3d0b0784d",
		["Кажется, я слышу его приближение! Взгляни на запад!"] = "99de77c0a5a974e26ae9dfd849d37ce8",
	},
	["Риббли Крутипроб"] = {
		["Здравствуйте! А мне как раз нужен кто-то вроде вас. Присаживайтесь, сейчас я поделюсь с вами планом, благодаря которому мы разбогатеем!"] = "84844fb1528038e49e3a68b7904bc912",
	},
	["Риверн Холодный Ветер"] = {
		["Здравствуй, $gпутешественник:путешественница;. Да, редко у меня бывают гости…$B$BЯ Риверн, дрессировщик ледопардов Зимних Ключей.$B$BЭти создания – самые дикие и непредсказуемые из всех кошачьих. Они не станут носить кого попало.$B$BЧтобы приобрести такого скакуна, ты $gдолжен:должна; не только завоевать мое уважение, но и понравиться самим ледопардам."] = "36c8e9c4ac3bcc7350a02ddb82c11cbc",
	},
	["Риггер Гизлтон"] = {
		["Тебе повезло: я только что закончил чинить \"Робо-торговца 680\". Его ассортимент огромен, а цены порадуют даже самого скупого дворфа. Да ты $gсам:сама; посмотри! Правда, мой брат Корк считает, что его \"Торготрон 1000\" будет торговать лучше…"] = "f3da952cbd390a3e587b455be7a2577f",
	},
	["Риггл Мормыш"] = {
		["Добро пожаловать на состязание рыболовов в Пиратской бухте. Здесь мы каждую неделю выбираем Лучшего удильщика!\n\nС двух до четырех часов дня к побережью Тернистой долины подходят косяки вкуснорыбы. Если ты сумеешь закинуть удочку в такой косяк, твой улов будет необычным для этих мест."] = "5776ad2ab96a8574ffb8006cc2353824",
		["Победитель уже определен, но Джанг все еще готов купить любую вкуснорыбу, которую ты поймаешь!\n\nА свое искусство рыболова ты сможешь продемонстрировать в следующее воскресенье."] = "e7cede3a6a5c6bfa97691dd12ed05122",
	},
	["Риз Лангстон"] = {
		["Добро пожаловать в \"Свинью и свисток\"! Возьми кружечку, $gдруг:подруга;, да присаживайся, – чем нас больше, тем веселее!"] = "42589616848b8292a7b00119aa63bd29",
	},
	["Римблат Землекрушитель"] = {
		["Я ожи…$B$B*Римблат кашляет.*$B$BИзвини, старая привычка. Я Римблат из Служителей Земли."] = "2c121d996480b972ca128fe4dd17568b",
		["Таурены сражались в последней войне. Шаманов отправили на защиту этого мира от нашествия Плети. Большинство погибло. Многие были расчленены, куски их тел использовались для злых экспериментов в этой проклятой цитадели. Я скорблю об их гибели, но мое сердце наполняется гордостью за их мужество."] = "65e7b100fb21e8d6d72f6a72a8e28b8f",
		["В те годы я был молодым тауреном, едва вступившим в пору юности, но уже знал, что тех, кто сражается за нашу свободу, надежно защищают одежды моего тезки."] = "102e0b4ad57167106f63887340efcdd5",
	},
	["Рин'вошо Торговец"] = {
		["Приветствую! Я Рин'вошо, торговец Зулдазара. Я приехал из Южных морей и привез много экзотических товаров.$B$BЕсли вы докажете, что достойны, то я, пожалуй, поторгую с вами. А если у вас есть почетные знаки моего племени, я покажу вам все свои товары!"] = "aca6701e63f56de998a1cc492839d1c2",
	},
	["Ринлинг"] = {
		["Привет! И добро пожаловать! Боюсь, мой балаган закрыт… в нем многое надо чинить…$B$BНо я по-прежнему связан кровавой клятвой, а потому обязан вызвать у тебя улыбку. Прошу тебя, улыбнись! Иначе мне придется отсечь себе руку и не вкушать живой плоти, пока она не отрастет вновь…"] = "dcf71fd938957989dca86c245fa95f64",
	},
	["Ричард Кервин"] = {
		["$n, ты уже знаешь достаточно, чтобы быть $gопасным:опасной;, но тебе все равно стоит подучиться у меня."] = "40ed4acb596b8797e28b2e4ec74f6940",
		["Мне некогда тратить время на таких, как ты, $c."] = "9514382213ea5206a797eeb5423a9138",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Роберто Пупллечерпос"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "a86de99ac7614f683ab7eab24b0a0b93",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "0a50227fd4a79a221c5e74147031f06e",
	},
	["Роган Убийца"] = {
		["Прозвище обманчиво. На самом деле, если узнать меня поближе, я очень добрый."] = "7d3224526057b707f3979b7b1671e479",
		["А, говоря официальным языком, я – убийца на службе Алого ордена. Днем я устраняю цели высокой важности, а ночью – отплясываю на дискотеке в Прибамбасске. Танцы – мое истинное призвание. А убийствами я лишь зарабатываю на оплату счетов."] = "512f340d076023b4c9448a6a0aa5f962",
		["Ты что, $gслепой:слепая;? Ты не $gзаметил: заметила; этих ТОЩИХ КОСТЛЯВЫХ ТВАРЕЙ, испоганивших землю по дороге сюда?$B$B*Роган вздыхает.*$B$BЕсли ты предпочитаешь открытые пространства, то скелетов полным-полно в западных и Восточном Лихоземье. Уж поверь мне, мимо них ты не пройдешь.$B$BЕсли ты больше по подземельям, Стратхольм и Некроситет – самые подходящие места."] = "13a767725c325fa51d467e80639b5c7b",
		["Это хороший вопрос, $r. В юности я был свободным, беззаботным и ни о чем на свете не беспокоился. В то время я пел в квартете, развлекая клиентов цирюльни Штормграда. Нас называли \"Четыре дона\". Там я и узнал про копи костяной косы."] = "c5eeeaf1edcbad1bef6a552484b6b991",
	},
	["Рогвар"] = {
		["Меня позвал сюда сам Вождь Тралл. Я повиновался с радостью. Лучше места, чем Каменор, и не придумаешь. На здешнем перегное растут любые травы, какие только могут понадобиться."] = "6ce2c0940d0dd65750b3907022d09eee",
		["Хммм, хорошо, я вижу, ты кое-что знаешь о том, как составлять зелья. Но $gдостоин:достойна; ли ты стать $gмоим учеником:моей ученицей; – пока неизвестно. У меня есть для тебя работа. Произведи на меня впечатление."] = "82de1081947db7e5efe700935903c696",
		["Да как ты смеешь просить меня об уроках, ничтожество? Буду я тебе тут лекции о сребролисте читать! Вон отсюда! И скажи спасибо, что я не вышиб тебе мозги!"] = "ef707d4afe6c519b2111f0699c611d06",
	},
	["Ройттен Камнемолот"] = {
		["Мои ветрокрылы привычны к раскаленному небу Степей."] = "6aa2da2a9c475a92293555b1a8c56083",
	},
	["Рок'рел"] = {
		["Наша судьба – предостережение всем тем, кто захочет иметь дело с Великим огнем."] = "f0457cce2f9f2f1bd8cea54c70a5306c",
	},
	["Рокар Тень Клинка"] = {
		["Зачем это $gтакой молодой:такая молодая:c; $c $gпришел:пришла:c; к старому фермеру?"] = "9bf55e6c6132c78f689d4a846edbc4fd",
	},
	["Роксик"] = {
		["Иногда я сам себе удивляюсь!"] = "a33d076d120978aaaececdda45031962",
		["Я не могу учить тому, чего не знаю сам! Если бы тут был кто-нибудь, кто знает больше меня… А ведь есть такой! Отправляйтесь к Жужжеру Скрепокрылу в Прибамбасск!"] = "bef0adf1ca4f95d60744bcfb2d4e9e99",
		["Неплохо для новичка, но у меня тебе учиться все-таки рановато. Возвращайся к траншеям!"] = "1b37830fe8480ed6bd57b3d834cd2310",
		["Отлично! Я знал, что не ошибся в тебе. И неважно, что там говорят другие… Ха! Я шучу! Ладно, продолжим урок."] = "a551611cff75484f9e317ceaee4ba354",
	},
	["Рори"] = {
		["Они не понимают, что уже умерли, $r. Они – по крайней мере, большая их часть – обречены вечно переживать последние мгновения перед тем, как пал город. А некоторым повезло еще меньше.$B$BДумаете, это все дело рук Плети? Тогда Плети еще не существовало, а если бы она была, мы бы смогли ее остановить.$B$BНет, это результат чумы, пришедшей из Некроситета и уничтожившей город. Она была ужасной и смертоносной. Никто не выжил.$B$BА теперь оставьте меня наедине со своим горем."] = "313febb63dee5a7c62e6bd14ad042eb5",
	},
	["Ротгат Камнебород"] = {
		["Жизнь кузнеца нелегка, но она делает кости стальными, а сердце огненным. Мой папаша был кузнец, а до него дед, в кузницах под Грим Батол. А сейчас и мой сын пошел по нашим стопам, так что мальчишкой можно гордиться."] = "d8e60ce5ca29731c4ca9356a1d489a59",
		["Прости, $gпарень:девушка;, но тебе еще рано учиться у меня. Лучше сходи к моему сыну Гроуму – он будет рад $gновому ученику:новой ученице;."] = "bd72d5e5581d2bb7837469dfbe7b0df0",
		["Ну да, я б научил тебя ковать всякое. Надевай фартук, хватай молоток – и начнем урок, ага?"] = "d0ab183a7e4df704c1fbf1106d87c75f",
		["Учиться ты умеешь, да и ковать тоже. Я бы тебя хоть сейчас на работу взял, но ты заслуживаешь большего. Пойди поговори с Бенгусом Подземной Кузней. Характер у него тяжелый, но в своем деле он один из лучших."] = "6ff1f5911fd79355d3991c42c4b661fa",
	},
	["Роурк"] = {
		["Теперь лишь известный доктор Грегори Виктор может помочь тебе отточить твои навыки. Его можно найти на Нагорье Арати в Павшем Молоте."] = "700b50a54630ac625819418a1b304af7",
		["Бала Лок'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!"] = "535730e8ed12be3838f3f1ed216dba89",
		["Я могу научить тебя оказывать первую помощь."] = "4a83fcc5ecf8c7c6aa5f55518135444f",
	},
	["Руаг"] = {
		["Изувеченная Длань увидит Орду во всей былой славе, когда ее перестанет сдерживать робость Вождя."] = "5070548a9c45a19ece573bb4b49296f4",
		["$C – это не ко мне."] = "60044d7f82718835ed805cb5fdc7067b",
	},
	["Рубака Колючего Холма"] = {
		["Да, мне и самому надо бы кое-что сбыть. Иди на север по дороге в Оргриммар, там расспросишь местных рубак."] = "97ef6bb6459a1144372decbaa9f48cf8",
		["Не видишь, что я занят? Иди на север в Оргриммар и расспроси местных рубак. Их-то ты точно заметишь."] = "1c4d2642c8dbafb4181f864054a4636a",
		["Большой дом в Колючем Холме, но не казармы. Там поговори с хозяином таверны Гроском. Ясно?"] = "0e0f2725e989891e3b1b209b00b6c6ef",
		["Питомца $gзавел:завела;? Главное, убирать за ним не забывай! Поищи Шоя'май возле трактира."] = "48c83d364a53dcd5c109f0279ac8ef23",
		["А ты $gохотник:охотница;? Ну, тогда ты сможешь выследить нашего Тотара. Он прячется от солнца в своем логове в юго-западной части города."] = "1481902397825d866ef861434702b11b",
		["Этим тролли занимаются. Сходи к Ун'Туве в деревню Сен'джин, это к югу отсюда."] = "c09f94f3738012af627ee0ca8e140589",
		["Ее зовут Тай'джин, ты найдешь ее в бараках в восточной части Колючего Холма. Она научит тебя уважению к богам. Удостоверься, что оказываешь ей должное уважение в ответ!"] = "c1a5522c52594a0f7383273d3f3d052b",
		["С чего это вдруг тебе понадобился Каплак? Впрочем, неважно. Можешь найти его возле логова на юго-западной окраине Колючего Холма. Только не вынимай рук из карманов!"] = "ee3cff8c1213239b77f4d4ebd853af5b",
		["Вождь несет перемены, которые приведут Орду к победе! Ищи Злобра в казарме в восточной части города."] = "12e3380832481755103357bd8e4274e5",
		["Дхугру Кровожадный прячется за казармами на восточной стороне города. Но смотри, если узнаю, что ты на стороне Пылающего Легиона!.."] = "14afad71e6f43ebd4897a73651c3acd5",
		["Тебе нужен Таршо Рваный Шрам. Ищи его в казармах на восточной стороне Колючего Холма. Служи Орде с честью, $gюноша:девушка;!"] = "abc57ca8b9afe5891d11b478b0678324",
		["Говорят, у троллей в деревне Сен'джин живет алхимик по имени Мяо'зан. Сходи туда."] = "252d6ae280f65f0827b5d62b61125ec5",
		["Если ты считаешь, что обладаешь силой выковывать оружия и броню из хорошего металла для дела Орды, ищи Двукка рядом с раскаленной кузницей в северо-западной части Колючего Холма."] = "a2a68134eb6ead66dec0ff1ea26a3473",
		["Ммм, еда. Не то чтобы тут далеко, но тебе надо пойти на север, в Оргриммар, и расспросить тамошних рубак."] = "f3be329749bffcc3c219519d18dac377",
		["Здесь таких, кажется, нет. Тебе бы лучше пойти на север, в Оргриммар. Там спросишь у местных рубак."] = "bad0c10059d93b0ba507c84cd442cad6",
		["Ха, да это работа для гоблинов! Впрочем, у нас на Колючем Холме есть один орк, который занимается такими вещами. Ищи Мукдрака возле кузницы."] = "fe9dd394ba942b3b46f201e888e073ce",
		["Со всеми этими боями, что мы ведем, у нас, конечно же, есть учитель первой помощи на Колючем Холме. Ищи Роурка в бараках в восточной части города."] = "7a5f9a5c9e1af6b938e8d6fdb50d0765",
		["Тебе нужен Лау'Тики. И ты его найдешь на побережье Черного Копья, к югу от деревни Сен'джин."] = "bf50f48d66f33ab47551f76d9412f407",
		["Цветы? В этой пустыне? Если кто и научит тебя искать их здесь, так это Мишики из деревни Сен'джин. Это к югу отсюда."] = "96442a667845894083d0f2231cb79543",
		["Чтобы научиться выделке кожи и работе со шкурами, отправляйся на север, в Оргриммар. А там уже страж-рубака подскажет тебе дорогу."] = "480dcbe4bcc183db295991cfcf3e04ef",
		["Говорят, Дуротар богат полезными ископаемыми… Разумеется, у нас в Колючем Холме есть учитель горного дела. Ты можешь найти Крунна у кузницы в северо-западной части города."] = "28da34a7dcc4893620bc3f9b17dbed6e",
		["Есть один в Оргриммаре. Иди на север и поговори с местными рубаками."] = "e9ff9ec36b22276710cd8fde9ba0ca1f",
		["Шить учат в Оргриммаре. Это на севере. Там спросите любого оргриммарского рубаку."] = "86bee557234aefc08dffcd603a3140f5",
		["Что ты ищешь?"] = "11f7e88f267338a9a8803626e9eb30be",
		["Что? Банк есть в Оргриммаре. Ступайте по дороге на север, а потом спросите у городской стражи."] = "63df14ac6b0e503a51930d85a9b327bd",
		["Иди в Оргриммар к укротителю ветрокрылов. Ступай по дороге на север, а дальше тебе подскажут оргриммарские рубаки."] = "21b93df5517191e6ac378bd3f35e2e19",
		["Да, мне бы тоже не помешало отдохнуть и пропустить стаканчик… Таверна у нас в северо-западной части Колючего Холма. Передавай привет хозяину Гроску!"] = "5a86f360c8ddfe8d0e1d5b8e50ba194b",
		["Ищи Шоя'май возле таверны. Не задерживай меня, я занят."] = "95ec5023f7dcbcb96b665624348b5662",
		["Какой учитель тебе нужен?"] = "bb48a6496b0f939b97d651fb87555c27",
		["Какая профессия?"] = "539255a3b21365ed1ab0beecd22e319f",
		["Наставника охотников зовут Тотар. Его можно найти в его логове в юго-западной части Колючего Холма."] = "e71cc318705554503a1fc94f2fb2cf27",
		["Поговори с Ун'Тувой. Он живет южнее, в деревне Сен'джин."] = "0dcfd534ad129cf3f8457b6c1054259a",
		["Тебе нужна Тай'джин. Ищи ее в казарме в восточной части города."] = "e72ab783318fd9303c927b656da1917d",
		["Ищи Каплака возле логова в юго-западной части города."] = "3f06598ffd8c9999b7f3e6b16011dfc5",
		["Вам нужен Злобр. Он в казармах на восточной стороне Колючего Холма."] = "96d985b616d9e1814e6fa750a01f0e85",
		["На восточной стороне Колючего Холма, позади казармы – ищи Дхугру Кровожадного там."] = "470b3f07f965638e1e086daec3b41a7d",
		["Таршо Рваный Шрам живет в казарме на восточной стороне города."] = "352ae89eeeaac61dcc6845cd9f983cbd",
		["Разыщи Мяо'зана в деревне Сен'джин. Это к югу отсюда."] = "1531e56848a97f6caf0707bde10714be",
		["Это тебе нужен Двукк. Ищи его у работающей кузни в северо-западной части города."] = "68932fb0ffa48a7c03ec6bce0aa873db",
		["Иди по северной дороге в Оргриммар. А там уж любой рубака подскажет, где найти учителя кулинарного искусства."] = "bb526804502f2666b56f5808503d68f7",
		["Это тебе в Оргриммар надо. Расспросишь тамошних рубак – они тебе все покажут и расскажут. А пока ступай на север по этой дороге, мимо не проскочишь."] = "0e41adb6a7e141e297a7a7af38a7a151",
		["В Колючем Холме есть учитель инженерного дела. Его зовут Мукдрак. Обычно его можно встретить возле кузни."] = "88e7460445b466f2393737512b4cace7",
		["Один из них живет в казарме на восточной стороне Колючего Холма. Звать его Роурк."] = "bab9ae7a3d5ab170b5e4373908683d46",
		["Я видел тролля-рыбака по имени Лау'Тики на побережье Черного Копья у деревни Сен'джин. Это к югу отсюда."] = "f531065fd60a051974df176bb74830f1",
		["Ты ищещь Мишики? Она живет в хижине на юге деревни Сен'джин."] = "788e53903ca8bd09c088bd1d27efa397",
		["Тебе нужно в Оргриммар. Иди от Колючего Холма по северной дороге. Пройдешь через каньон – и попадешь прямо туда. Если что, спроси любого рубаку."] = "1c20bee54f940a7ee25ae9b08ddc5bc7",
		["Да-да, у нас в городе есть учитель горного дела. Его зовут Крунн. Живет он в северо-западном углу возле трактира."] = "c63f56c09345cbf81c450bfc0e570916",
		["Учитель снятия шкур есть в Оргриммаре. Чтобы попасть туда, иди на север по дороге из Колючего Холма. Там спроси оргриммарских рубак – они знают."] = "fa4b7059d45bf0250381ea6aab634c1f",
		["Тебе нужно в Оргриммар. Иди от Колючего Холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку."] = "a8f60edf1e35fe995876160fbe01d53e",
	},
	["Румстаг Гордый Странник"] = {
		["Приветствую, $gбрат:сестра;… Я бы хотел отвлечь тебя ненадолго, если возможно.$B$BМы, таурены, перенесли многие испытания и несчастья, завоевывая родину. Теперь мы испытываем сильную нехватку ткани. Если у тебя есть лишние материалы, я бы попросил тебя пожертвовать их нам. Ты, несомненно, заслужишь признательность всех тауренов!"] = "804dac15ce73451780e4cf2e731b64fd",
	},
	["Рунк Покоритель Ветров"] = {
		["Куда бы вы хотели слетать?"] = "008491a7c8f31e3556f00e8c3fdc3190",
	},
	["Руперт Бош"] = {
		["Ты поступаешь разумно, $n, унижаясь передо мной в надежде узнать что-нибудь новое об искусстве чернокнижников."] = "6d671d26f71829b3cfdafaf53866d6f0",
		["Мне некогда тратить время на таких, как ты, $c."] = "9514382213ea5206a797eeb5423a9138",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
	},
	["Рутгар Знакописец"] = {
		["Бронзобород опять исчез! У этого дворфа нет никакого здравомыслия, в отличие от его брата."] = "2e9da6b3338a01eeae4e67b707bbd7e8",
		["Ты лучше присядь, это долгая история.$B$BКогда мы только прибыли в Силитус, госпожа Мар'алит первой из ночных эльфов Крепости Кенария присоединилась к нашей экспедиции. Вот тогда все и началось – мы стали собирать команду для походов в ульи и поисков пропавших артефактов."] = "443b87cdae07e4c1b2c9da0ebeb77760",
		["Это точно они! Эти ульи гудели от всяких силитидов, которые были абсолютно не рады видеть нас.$B$BВсе было в порядке, пока мы не наткнулись в Улье Регал на кристалл, покрытый символами. Он привлек ее, как бабочку к пламени! Она приложила свою прелестную щечку к кристаллу и мгновенно погрузилась в транс. Естественно, это взволновало мою команду. Мы схватили ее и вывели оттуда так быстро, как смогли!"] = "81794f3c4756bdfd389fa69ab46e362c",
	},
	["Рык"] = {
		["Держись подальше от Суми и Туми. Они… в общем, они заняты."] = "3460cf49688cf1e61bb4c182e4fe1f25",
		["Если я докажу Сару, что я достоин, у него не останется выбора, кроме как разрешить мне сражаться за одну из его дочерей. Тогда посмотрим, кто из нас будет смеяться."] = "892843767faa267d3c9dffac4a715fb9",
		["Еще раз придешь ко мне с такой никудышной работой, и я отправлю тебя домой в маленьком железном ящике, закаленном в козлиной моче. Иди поговори с этим идиотом Уг'током, он тебе больше подходит."] = "a5954f50750c048ad3968621a36bb8a8",
		["Так ты считаешь себя $gдостойным:достойной; учиться у меня? У великого Рыка? Да ты всего лишь жалкое ничтожество, пресмыкающееся под моими ногами. Впрочем, взяв себе подмастерье, я мог бы встретить больше приязни со стороны Суми и Туми. Посмотрим, какими крохами умения ты владеешь."] = "ff39ca29b26a2bf82446bf23f9f6bdd7",
		["Мне нечему больше тебя учить – так что проваливай! И не вздумай даже приближаться к Сару – он любит закалять мечи в крови таких, как ты!"] = "9a53f418dd0796c16815bebd0a53e258",
	},
	["Рыцарь Серебряного Рассвета"] = {
		["Битва выиграна. Угроза Плети устранена – на время. Мы можем направить свои ресурсы в помощь тебе, в благодарность и для подготовки к грядущему."] = "4b36cae8ffab10bd243caafa37fd7ebd",
		["Битва протекает неплохо. Силы Плети кажутся ослабевшими. Я уверен, изгнание их с наших берегов – лишь дело времени. Я направлю свою магию в вашу сторону, чтобы помочь вам в этой борьбе."] = "fdaab9e2b8a9ef75ee889a83109b9758",
		["Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет вас к дальнейшим победам."] = "b4933008c7c76fbea261d6b6ba7192ca",
	},
	["Рядовой Торсен"] = {
		["Это опасное место, $N! Будь осторожен."] = "a765bd81d4444d7fa3d03cdef9f00bd6",
	},
	["Сагорн Гривастый Странник"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "d96f407d05286ba207ff46bf75ef4510",
		["Да пребудут с тобой духи."] = "1eec7529a102737979dbaf19908f6ac0",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Сайлас Новолуний"] = {
		["Приветствую вас, мой друг! Добро пожаловать на величайшее событие во всем Азероте!$B$BПожалуйста, проходите и посмотрите на то, что у нас есть! Взгляните на диковинки ярмарки Новолуния, собранные со всего света! Наши развлечения понравятся детям всех возрастов!"] = "bcc4137261fe1b6312ba537a58e54584",
	},
	["Саймон Дубильщик"] = {
		["Рэндал любит щегольнуть, но он – человек надежный, а это можно сказать мало о ком из моих учеников. Зато все остальные – заядлые авантюристы."] = "571fe1d462c23f1767d91712cbca99b5",
		["Это все, чему я могу тебя научить. Если хочешь большего, наведайся к Телонису в Дарнасс. Он там живет на Террасе ремесленников и, говорят, весьма преуспевает в своем деле."] = "7cdf7286e6f367866bc1a6f3988b6d24",
		["Приходи, когда выучишь основы. Рэндал Ценни поможет тебе в этом."] = "0292cf669448ab9bbd0999947fd38746",
		["Хмм, наверно, еще одного ученика я потяну… Ну что ж, не стойте просто так. Говорите, чему вы хотите научиться?"] = "b7d5ec884a804403ab3448289d7db1ac",
	},
	["Сайок"] = {
		["$GПришел:Пришла;, чтобы научиться владеть новым видом оружия или просто так отнимать у меня время?"] = "ac6104deed8fed0d5a86bb3bee66c1bd",
		["Ансеква, тауренский эксперт по оружию, трудится на нижнем ярусе Громового Утеса. Он обучает владению двуручными булавами, посохами и огнестрельным оружием.\n\nХанаши, вот этот тролль рядом со мной, покажет тебе, как пользоваться одноручными и двуручными топорами, посохами и всем возможным метательным оружием.\n\nНежить Арчибальд обитает в Квартале Воинов, что в Подгороде. Он может обучить владению арбалетами, кинжалами, одноручными и двуручными мечами, а также древковым оружием."] = "6fbe1caacff7fcf16cc0478c2dccd149",
	},
	["Самуэль Хок"] = {
		["Я Самуэль Хок, главный снабженец Лиги Аратора в Низине Арати. Когда ты завоюешь наше доверие, я предложу тебе разнообразные полезные товары. Кроме того, я могу чинить твое снаряжение."] = "2b18d0f222c8e7658616bae3c1e5d0a2",
	},
	["Сандал"] = {
		["Чары развращают лишь тех, кто слаб духом. Не прекращай работать над собой, если не хочешь, чтобы тебя постигла такая участь."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
		["Тьма не примет тебя, $c. Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!"] = "c4bef13520e7f7e2f4078fbe96c02345",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	["Сарк Тотем Гнева"] = {
		["Чем больше ты учишься – тем острее осознаешь свое невежество."] = "1b0b0371bfb09e817b8c77bcf69ec99f",
		["Я не могу учить тебя, $c."] = "a304d424ab3fe62125a7e67546f1595a",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Сару Холодная Ярость"] = {
		["Что ты ищешь у моей кузницы? Ты по поводу обучения? Или хочешь узнать секреты стали? Загадки ковки? Поговори с рубакой!"] = "03b20e4ae05f8ecd44ff03f0c3561c3f",
	},
	["Сборщик похвальных значков из Гномрегана"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь Изгнанников Гномрегана. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Изгнанников Гномрегана за проделанную работу."] = "c2a6c5d7d43cb3650eb787a68e5d0391",
	},
	["Сборщик похвальных значков из Громового Утеса"] = {
		["Здравствуйте, $c. Я уполномоченный сотрудник отдела рекомендаций Громового Утеса. В мои обязанности входит помогать всем, кто удостоился рекомендательных жетонов Орды.$B$BЯ принимаю такие жетоны в разных количествах, но лучше всего сдавать их партиями по 10 штук. Приняв жетоны, я внесу в наши записи сведения о ваших заслугах, чтобы вы могли снискать должное уважение среди жителей Громового Утеса."] = "e546a36a7eeaabafa3ea21329d0ac9da",
	},
	["Сборщик похвальных значков из Дарнасса"] = {
		["Здравствуйте, $c. Я уполномоченный сотрудник отдела рекомендаций Дарнасса. В мои обязанности входит помогать всем, кто удостоился рекомендательных жетонов Альянса.$B$BЯ принимаю такие жетоны в разных количествах, но лучше всего сдавать их партиями по 10 штук. Приняв жетоны, я внесу в наши записи сведения о ваших заслугах, чтобы вы могли снискать должное уважение среди жителей Дарнасса."] = "94e2524c35344ffbb05e9b1869c245f6",
	},
	["Сборщик похвальных значков из Оргриммара"] = {
		["Здравствуйте, $c – я сотрудник отдела рекомендаций, действующий от имени Оргриммара. В мои обязанности входит помогать тем, кто получил рекомендательные жетоны Орды.$B$BЯ принимаю разное количество жетонов, но выгоднее всего для вас будет сдавать их по 10 штук за раз. Когда сдадите мне жетоны, я внесу ваши деяния в наши летописи, и Оргриммар будет вечно признателен вам за них."] = "721bb9d7821f092647a0f590fef91922",
	},
	["Сборщик похвальных значков из Подгорода"] = {
		["Приветствую, $c! Я сотрудник отдела рекомендаций, действующий по заданию Подгорода. Моя обязанность – помогать искателям приключений, получившим рекомендательный жетон Орды.$B$BЯ принимаю жетоны в любых количествах, но наиболее выгодно для тебя – сдавать их по 10 сразу. Когда ты сдаешь нам жетоны, я заношу это в летописи. В результате ты получишь признание в Подгороде за то, что $gвыполнил:выполнила; свой долг."] = "89481ded6e9d55cdc37bf5cbd804a86c",
	},
	["Сборщик похвальных значков из Стальгорна"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь Стальгорн. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Стальгорна за проделанную работу."] = "a002d75a96a783b4847631d35c12cda1",
	},
	["Сборщик похвальных значков из Штормграда"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь Штормград. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Штормграда за проделанную работу."] = "a11a7d36f03be1a27def349ef4faa820",
	},
	["Сборщик похвальных значков из племени Черного Копья"] = {
		["Здравствуй, $c. Я – сотрудник отдела рекомендаций, представляющий здесь племя Черного Копья. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Орды.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность племени Черного Копья за проделанную работу."] = "39dff0023660d86508c6db5afb6c0d8a",
	},
	["Священник из ордена Серебряного Рассвета"] = {
		["Битва выиграна. Угроза Плети устранена – на время. Мы можем направить свои ресурсы в помощь тебе, в благодарность и для подготовки к грядущему."] = "ebde1b78097e360ae80271b45ac8ec9b",
		["Битва протекает неплохо. Силы Плети кажутся ослабевшими. Я уверен, изгнание их с наших берегов – лишь дело времени. Я направлю свою магию в вашу сторону, чтобы помочь вам в этой борьбе."] = "4d4e9052d3c36392e6211cb442ea3b1e",
		["Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет вас к дальнейшим победам."] = "0973188afdf5745ee7a53c42da926c63",
	},
	["Седрик Проуз"] = {
		["Куда бы вы хотели слетать?"] = "65b6f5b0f34f015f60d92c6c8d6e3d71",
	},
	["Седынь Полушкур"] = {
		["К сожалению, $c, тебе нужно поднабраться опыта, иначе ты не выживешь в Альтеракской долине."] = "b83ab9c1a9dd85b93121a8a221e21094",
		["Стража Грозовой Вершины должна быть уничтожена! $gГотов:Готова; ли ты к битве в Альтеракской долине, $c?"] = "81ed3ff7e3aa4663fea43677ac077dd8",
	},
	["Сектант-инженер"] = {
		["Этот культист погружен в глубокий транс…"] = "73f0462573697c404b28308bec6f882a",
	},
	["Селландус"] = {
		["Добрый день."] = "488edc59d5f675d7b021f97325a0d71b",
	},
	["Серж Хинотт"] = {
		["Опять отвлекают. Ну и как мне работать в таких условиях? Можешь не отвечать, чихал я на твои оправдания. Иди лучше поприставай к мистеру Всемогущему."] = "24a9f0ae55336ce04597528b79ab3c41",
		["Мне? Учить вас? Вы сами прекрасно знаете, что я не могу! Если вам нужен учитель, поговорите с доктором Гербертом Галси, Отрекшимся из Района Фармацевтов Подгорода."] = "5b3ba56ab8ce8049d84d48d66345c69c",
		["Не отнимай у меня время. Я работаю над проектами, которые старше тебя. Иди поговори с доктором Мартином Фелбеном в Районе Фармацевтов Подгорода. Он Отрекшийся, который, возможно, сможет научить тебя основам."] = "edb3fbffc27addc3693160ddb35ad2b3",
		["Еще один ученик. Превосходно. Вот почему Лидон принадлежит к Королевскому снобскому обществу и занимается исследованиями, а я застрял здесь в качестве инструктора. Если выиграю еще одну награду \"Учитель года\", я этого не переживу!"] = "47491c60fb41002c8b53ee55a847cbc9",
	},
	["Сержант Дарген Грозовая Вершина"] = {
		["*Сержант Грозовой Вершины приветствует вас.*$B$BИмя, звание и серийный номер, боец! Это единственное, что ты имеешь право выдавать грязным псам из Северного Волка!"] = "91ec0e39bf7d8d69df78d4e9d0d5607c",
	},
	["Сержант Дыгал"] = {
		["Эй, ты! Я смотрю, ты выглядишь довольно $gсильным:сильной;… Нам нужна твоя помощь в обороне Южнобережья!$b$bПроклятые Отрекшиеся разбушевались из-за своего Тыквовина и скоро припрутся со своим \"праздником\" прямо сюда. Если у тебя есть время, помоги нам!"] = "aa29eb4cc989127d57a7bf2186381767",
	},
	["Сержант Карнес"] = {
		["\"Они мне говорят: \"Отличная работа, тебе полагается повышение!\" Сказали бы уж сразу: \"Отправляйся к ульям Силитуса и торчи там с потными дворфами, Кернс!\"$B$BСпасибо за повышение, капитан!"] = "668e49c17df4b9aa59370244f97c3f6a",
	},
	["Сех'Джиб"] = {
		["Как жизнь, дружище?"] = "6e6caea26767043589a962c9cf10b835",
	},
	["Сиарна"] = {
		["Мы – тьма и тени. Вечные. Незримые."] = "e8b964bb2f42459fd5d4d58181834b5d",
		["Приветствую, $gюный разбойник:юная лазутчица;. Что ты ищешь?"] = "249236308a24ca006ca2a9251d3eea0a",
		["Посланцы Черного Ворона сегодня утром вручили мне это письмо. Оно адресовано тебе, $n."] = "8a0abdcbc600f60a9fcf653afbc414fa",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Сиделка Нила"] = {
		["Теперь лишь известный доктор Грегори Виктор может помочь тебе отточить твои навыки. Его можно найти на Нагорье Арати в Павшем Молоте."] = "1da3761ad74cf7eb8c780bd1d6ef8d0f",
		["Бала Лок'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!"] = "87c89b57e3313dbfc3b9494758c30fff",
		["Я могу научить тебя оказывать первую помощь."] = "b989a2ab06d53ba30e6226c9b588d90b",
	},
	["Силина Небесная Охотница"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "ecc979039b643fbe07eecf74dbf940d3",
		["Да пребудут с тобой духи."] = "a81b670b0b0a6cd4fd4aafff91e45f6c",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Силина Чёрносердая"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "68d0d326eb02e4bc407880e343512823",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "01293169a620269666474cee8cc40c37",
	},
	["Сильва Фил'навет"] = {
		["Ты не друид!"] = "b6d7af778c178854770fdd337d5b015a",
	},
	["Сильвария"] = {
		["Ты хочешь учиться, чтобы передать знания своим питомцам?"] = "89218c24a0eff1fa5c10022467769ef7",
		["Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам."] = "4c9a93178a8bd81be46f856336284914",
	},
	["Сильданаира"] = {
		["Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная:c; $c, и мне нечему тебя учить."] = "aff660250ac92075478bdf7475083504",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Синдрайл"] = {
		["Куда бы вы хотели слетать?"] = "e9f2c6ae11c08606a3e902729508a45b",
	},
	["Синь Гогельмогель"] = {
		["Тяжело жить в пустыне! Стоишь тут весь день на жаре, пить так хочется…"] = "1d3cd34903e040de6b0c73c1aa2fb0df",
		["Теперь, когда вы упомянули об этом, я вспомнил. Да, я видел нечто странное вчера днем!$B$BЯ бежал мимо старых тролльских руин к югу отсюда, вернее, не бежал, а прыгал… Песок-то горячий!$B$BНу вот, значит, прыгаю я мимо руин и смотрю – там лагерь. По-моему, дурнее места для лагеря не сыскать… Я хотел там походить и посмотреть, но потом мерзкая летающая тварь накинулась на меня, и пришлось бежать дальше."] = "2240dd2ff7335d7ff456813bd7964a8f",
	},
	["Сирил Плетебой"] = {
		["Отойди, а то разрублю напополам!"] = "06af0379d0a4f27cb78f8ccab80db4c6",
		["Если хочешь научиться ковать мечи – только попроси."] = "f6dd091cd31c13e889f5415aa70a5dd6",
	},
	["Сказитель Килдрат"] = {
		["Их украли, $r! Украли три самых ценных тома! Если вернешь нам книги, награда не заставит себя ждать."] = "e5bc2020af21f8dc760efcc4b9b1641e",
	},
	["Сказитель Лидрос"] = {
		["Прежде всего ты $gдолжен:должна; понять, что знание 10 000 лет всемирной истории изменило мой взгляд на жизнь. Все твои беды и невзгоды – ничто в историческом масштабе."] = "6c366d266feb0eb999723d20a1d0371f",
		["Каким же пафосным был мой юный господин… Можно подумать, судьба мира держалась прямо на его плечах! Только у смертных такое искаженное представление о нашем мире.$B$BУвы, мне он оставил лишь малую часть своих секретов… Манускрипты какие-то дурацкие. Мне все это ни к чему, но, может быть, тебе будет интересно."] = "33e9252b9e79f5d50346fb17553ee92a",
	},
	["Сказитель Явон"] = {
		["10 000 лет письменной истории привлекают в Читальню не только мудрецов, но и всякий сброд. Книги крадут, возвращают, крадут снова – и так каждый день."] = "cb6c6ca44638e05ae54e29542e26f374",
	},
	["Сквибби Сверхпятнист"] = {
		["Сунь маленькую монетку в руку босса и посмотри, что из этого выйдет. Обожаю мою работу. Хотя, если бы я смог найти способ перевести этого живчика Снорка в этот порт… ну, лучше не придумаешь. Но спорим, ты здесь не для того, чтобы выслушивать мои рабочие проблемы. Ты ищешь дирижабль до Подгорода, я прав? Ну, это замечательно, потому что он причаливает прямо позади меня. Кстати, если увидишь Снорка, замолви за меня словечко, ладно?"] = "c021420a6f84c190718c0e399aad7e67",
	},
	["Скорн Белое Облако"] = {
		["Ты $gубил:убила; Призрачный Вой. Ну ты даешь!"] = "924b1b0c6fc974b7903fe962433db58f",
		["Подойди поближе, $gюноша:девушка;. Некогда я слышал стук сердца добычи, а теперь тебе придется говорить погромче, если хочешь, чтоб я тебя расслышал."] = "6ab9eb0622e9b06ba41a8dd0ee7e3b47",
		["Много-много лет я проходил по этим равнинам и охотился тут на крупного зверя. Никто никогда не мог противостоять мне… пока я не повстречался с Призрачным Воем.$B$BДавным-давно огромный волк был союзником тауренов и храбро сражался с Пылающим Легионом. Но его жестоко ранил демон, и рана так никогда и не зажила. В конце концов… Призрачный Вой обезумел.$B$BТеперь он носится по равнинам, терзаемый болью, ища способ положить ей конец. К стыду своему должен сказать: когда мы сразились, я не сумел убить его…"] = "d9799a53b63bce336c76cf88c68e6cfc",
	},
	["Скути"] = {
		["Здравствуйте, $n! Я – старший инженер Скути."] = "22c7e447f05eaff769b8cae4f2f6e0c9",
	},
	["Слоан Маккой"] = {
		["Говори тихо и с величайшей осторожностью: одно неверное слово – и тебя здесь просто прирежут. Итак, чего ты хочешь?"] = "abc687be48ac43361d84d47b6ea7f341",
	},
	["Слуга Длани"] = {
		["Зандаларские тролли прошли долгий путь и перенесли немало тягот, чтобы добраться сюда, но не сделали ничего… что бы могло навлечь на нас такую судьбу."] = "e0da321d08e8706f432c7322309f11f8",
	},
	["Снанг"] = {
		["При создании изделий мы используем множество шкур и кож животных."] = "414eb2110800e49fbeef5b9e23f4a1e9",
		["Я кое-что знаю, но экспертом меня назвать нельзя. А вот Магара можно. Он сейчас как раз отдыхает в дальней части лавки. Попробуй договориться с ним о помощи, но учти: характер у него тот еще."] = "ff0d7b4773f6d4aaa94d74340ab3d2c4",
		["Я научу тебя всему, чему смогу."] = "011f710eb536c93c6af1ca4daa89c86b",
	},
	["Снорк Следопутка"] = {
		["$gПривет, красавчик! Хочешь прокатиться в Гром'гол? Там, внизу, в джунглях, говорят, жарковато… А я бы тебе даже компанию составил, настоящего камышового кота показал…:Эй, красавица, хочешь побывать в чудесных, роскошных тропических джунглях Тернистой долины? Позагорать на берегу кристально чистых озер, пока я тут парюсь на жаре в компании своего брата Фреззы? В общем, приятного полета!;"] = "808af6c85a55d2308db805b9fb00b368",
	},
	["Совик"] = {
		["Привет, $n! Если в моей лавке нет нужного тебе товара, спроси меня – и я его достану!"] = "3c995182358b09d304bb6e1c0a9dd8d1",
	},
	["Сольм Харгрин"] = {
		["Не могу помочь тебе, $n. Я обучаю только разбойников."] = "fa078d44ecb0731e4c2a45f949ae67b1",
		["Чем я могу помочь тебе, $n?"] = "22dba637f525eff7a4f6ca7d8c7294cb",
	},
	["Соран"] = {
		["Вы что, доверили бы свои товары гоблину?"] = "bc269ca0f3298e0f908bb9eedbbb29c7",
		["Гарантия безопасности банка – моя жизнь. Вас это устраивает?"] = "3b27a7cc7f607a01029609d1a72bc83d",
		["Мы с братьями сражались на горе Хиджал – как и те воины, что стоят снаружи. Каждый, кто решит что-нибудь украсть, будет иметь дело с нами!"] = "a90d1a70d1794a0870befff1ef52b64e",
	},
	["Сорек"] = {
		["Ты здесь для учебы? Или просто для того, чтобы заставить воина зря тратить время?"] = "141f23d07f540e8c7b0ef9335bda601e",
		["Я не учу таких, как ты, $c. Обращайся к другим, а меня не зли."] = "5c32ac92759b0e79eade7dc21f7e569f",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "3a364a4573d4825a6795e3bb454069d4",
	},
	["Специалист по колоссам Нестор"] = {
		["Изучение колоссов даст нам необходимое преимущество над киражами."] = "ca9c2a76280fa526355a744dfbdacd34",
	},
