		["Что можно делать в таверне?$B$BНу, в таверне можно очень хорошо отдохнуть, гораздо лучше и быстрее, чем в какой-нибудь степи под открытым небом. А те, кто хорошо отдохнул, и опыта набираются быстрее.$B$BТак же любой хозяин таверны может дать вам камень возвращения, и потом с его помощью вы сможете быстро вернуться в свою таверну."] = "9c47dc6c58d31f5fd449e53a155109d8",
		["Не хочешь исследовать какое-нибудь подземелье?"] = "f70c987e98c43a9ac4f1ef6eb271008a",
		["Нет, меня самого это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!"] = "3334d2c3be49af24ec80966cd3044afb",
		["Огненная Пропасть находится под Расселиной теней в центре Оргриммара."] = "7bef92afa79765ff95f06d3660786a79",
		["Мертвые копи находятся в Луноречье, на юге Западного Края."] = "c14eefa9bf01ea21ee6c512a62f5270c",
		["Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях."] = "d34171a9fbd911b8f1bf818f71cc3f32",
		["Крепость Темного Клыка находится в южном Серебряном бору, к северу от деревни Горелое Дерево."] = "6f1db228470e4b9d299edd3c7168c063",
		["Непроглядная Пучина находится в северной части Зорамского взморья в Ясеневом лесу."] = "0e3148ee13bdc4aad5af84663b24d1ce",
		["Тюрьма Штормграда находится прямо в этом городе, рядом с Кварталом Магов."] = "8f49377bcf39a38a76d2cf7cbacbefb0",
		["Лабиринты Иглошкурых находятся на южном краю Степей, к востоку от дороги."] = "25a80704f18ee56676b132bdded0fe94",
		["Гномреган находится в западном Дун Мороге."] = "a4f613548f3f5a63415a978d891ce475",
		["Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов."] = "78e6008fbf1d737dce7812540853511c",
		["Курганы Иглошкурых находятся на южном краю Степи, к востоку от дороги."] = "9cdbd4512dccbc458675c5216058ddcd",
		["Мародон находится посреди западного берега Пустошей, в долине Копий."] = "6679f691680afda8b76a2dd04f2e7144",
		["Ульдаман находится на северной границе Бесплодных земель."] = "36de161eff379c5060e7c2e31cdc975a",
		["Руины Зул'Фаррака находятся в северо-западной части пустыни Танарис."] = "927f2bfc50de1f03c38ac6ec3198f4a7",
		["Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей."] = "aab40b74860886caa96dcfdaf979e180",
		["Затонувший храм находится посреди большого озера на востоке Болота Печали."] = "e33d4e6573f24d17efcc2b0ecf76516d",
		["Руины Забытого Города находятся в центре Фераласа."] = "89054fe6fb8e52df563c9e80702c264a",
		["Город Стратхольм лежит в руинах в Восточном Лихоземье к северу от Проклятого леса."] = "8d0c3e032d49fe079017a90965f53922",
		["Школа некромантов, известная как Некроситет, находится в Западном Лихоземье, среди руин на острове Каэр Дарроу."] = "7eddf733901dbca29a5a21752dd1ceb4",
		["Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон."] = "136e146f620b6e7197755a682b68ce84",
		["Знаки любви можно раздавать романтически настроенным жителям городов и деревень. В ответ вы получите дары обожания.$b$bТе, кто вас уже обожают, могут преподнести вам дары дружбы."] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
		["Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой."] = "b19764fa4b6d3a891fa5f750b3dd2517",
		["Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла."] = "f9432ed28b2dabcd595eddb702af9ca1",
	},
	["Хольт Громовой Рог"] = {
		["Помни, все в мире взаимосвязано. Если бы звери покинули эти земли, наше племя вымерло бы от духовного одиночества. Все, что происходит со зверями, происходит и с тауренами. Судьбу Азерота, какой бы она ни была, разделят все его обитатели."] = "9f7c9c74e4a293c201950a343d3e2e9e",
		["Я не могу учить тебя, $gюноша:девушка;."] = "339f020f3980f14597ba187876244c7e",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
	},
	["Храбрец Ветрогонка"] = {
		["У нас в деревне нет такого места. А вот в высотах Громового Утеса – есть. Направляйся на север по дороге от Деревни Кровавого Копыта, пока не придешь к основанию утесов. Там поднимись на лифте наверх и поговори со стражем утесов. Да хранят тебя твои предки."] = "a07a2212481a399576ae9fe06a7f42c1",
		["Ничто так не освобождает душу, как полет в небе. В главном городе нашего племени, Громовом Утесе, есть подходящее для этого место. Тебя приведет туда дорога, что идет на север из Деревни Кровавого Копыта. Когда поднимешься наверх, поговори с одним из стражей утесов, он сможет дать тебе дальнейшие указания."] = "4cf39374ff7284a5b21cfc6b497fab6b",
		["Всему на свете есть время и место, а уж тем более отдыху. К западу от Деревни Кровавого Копыта хозяин таверны Каут держит приют для тех, кто устал от странствий. Там же он и живет."] = "dbbfad5e8e294f119b31f17d69011c77",
		["Если понадобится, о твоих питомцах может позаботиться Сейква. Ее ты найдешь возле трактира."] = "fe99a91596ce335846112023b5594460",
		["Путь друида сродни пути шамана. Генния Рунический Тотем в этом искусстве поднаторела. Ее ты найдешь в большой палатке на востоке деревни Кровавого Копыта."] = "1847fdcddef3e68075875dabef0e92ec",
		["Научиться единению с природой во славу Матери-Земли – благое дело. Если хочешь постичь пути охотников, ты $gдолжен:должна; найти Йо Колкую Гриву в северной части деревни Кровавого Копыта."] = "bf3892655633ebde448465a11f22228f",
		["В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов."] = "96139546004881a4294304b598ccc1bd",
		["Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни."] = "8561b5ef70805de6adb31be7df0beb1b",
		["Готовить зелья из даров Матери-Земли, чтобы помочь нам в вечной борьбе, – достойное занятие. Чтобы научиться этому искусству, отправляйся на север, в наш великий Громовой Утес. Когда поднимешься на вершину, обратись за помощью к одному из стражей утесов."] = "d0fa2619a007e29f2bcfcd0e5820bc3f",
		["Ты желаешь превращать кости Матери-Земли в орудия, которые послужат делу Орды. Хорошо, хорошо. Иди по дороге на север от деревни Кровавого Копыта, пока не придешь к подъемнику, что ведет на вершину Громового Утеса. Там обратись к любому из стражей."] = "caa3688c962307b9b36884353c132080",
		["Ммм, кулинария – это вкусно… А Пиалл Тихая Поступь – лучший повар Деревни Кровавого Копыта! Его можно найти в большом шатре в северо-восточной части деревни."] = "60277780cb1e0c01412eb7a031a0ca2e",
		["Такие знания можно найти только в великом Громовом Утесе. Иди из деревни Кровавого Копыта по дороге на север. У подножия утесов будет подъемник. Поднимись на нем наверх и обратись к любому из стражей."] = "66caf9c27f97efdb42edc70cc18be649",
		["Повязки, противоядия и подобные вещи незаменимы при жизни на равнинах! Вира Нежное Копыто может обучить вас оказывать первую помощь. Ее можно найти в длинном здании на западе Деревни Кровавого Копыта."] = "d70aa339a19f08bb3a1f9cc6bec76f6a",
		["Дай таурену рыбу, и он будет сыт весь день. Научи таурена рыбачить, и он будет сыт всю жизнь. Утан Тихая Заводь может научить тебя рыбачить. Искать его надо к западу от деревни Кровавого Копыта, на берегах озера Каменного Быка."] = "36df698748e90c5d62441b1b2b971913",
		["Есть те, кто может научить тебя травничеству – в большом доме Громового Утеса к северу. Следуй по дороге из деревни, чтобы добраться туда, и у основания утеса поднимись на лифте до его вершины. Любой из стражей сможет направить тебя."] = "b6bf43efd45295b67a4a5fec348bcbfb",
		["Когда мы используем шкуры зверей, которых мы должны убить для защиты от них или для еды, мы почитаем Мать-Землю и выказываем уважение животному. Чоу Толстая Шкура может научить тебя таким вещам. Ты найдешь его в большом тенте в северо-западном углу деревни Кровавого Копыта."] = "8f17e662420dec70b168bb432ce2a11f",
		["Я слышал, что учителя горного дела можно найти в Громовом Утесе, к северу отсюда. Иди по дороге из деревни, и когда дойдешь туда, поднимись на лифте на вершину. Там тебе сможет помочь любой из стражей утесов."] = "7143577bcefa4d0e783529cbdba526b2",
		["Ах да, снятие шкур. Никто так ловко не управляется с ножом, как Йонн Глубокий Надрез. Ты найдешь его в большом шатре на северо-западном углу деревни."] = "e3314daab9e334b6f1e7993a6167eff9",
		["Портняжное дело, говоришь? Хм. А, конечно! Иди в Громовой Утес, прямо на север. Как доберешься туда – пройди через деревню, а потом, как дойдешь до утесов, воспользуйся подъемником наверх и поговори с кем-нибудь из стражей."] = "6bbecd1d0a266d717b54a938edbfcf57",
		["Что ты ищешь?"] = "00194bd1912d495a809752f13911ce30",
		["А, для этого вам нужно будет подняться на самую вершину Громового Утеса. Из Деревни Кровавого Копыта ступайте на север, и скоро увидите у подножия утесов лифты, которые довезут вас наверх. А там спросите дорогу у одного из стражей утесов."] = "9e59faa86e4dae4d1725cb773a40ef48",
		["В великом городе Громовом Утесе обитает укротитель ветрокрылов. Направь свои стопы на север, поднимись на подъемнике на вершину утеса и обратись к любому из стражей утесов."] = "eaaf7438e186e62ee1ea9c69523e1696",
		["Вам нужен хозяин таверны Каут. Он живет в западной части деревни в одном из длинных домов."] = "d8529bed329ec6d3ba33e0046164fc29",
		["Тебе нужна Сейква. Кажется, я видел ее возле трактира."] = "4b846af59d88843ba65c5b14298e254e",
		["Какой учитель тебе нужен?"] = "cfe020697f1863a2bc8a41431401f702",
		["Какая профессия?"] = "4deee9d3ecac92ac21b2a2f5401711e6",
		["Тебе нужен совет Геннии Рунического Тотема. Ты найдешь ее в большом тенте в восточной части деревни."] = "0c40ff0ebe77be70ce1a62dc6ed9cea5",
		["Йо Колкая Грива ждет тебя на северной стороне деревни. Он может научить тебя охотничьим секретам."] = "ff13d0d3ffce0e3452bba6d278dd54de",
		["На востоке деревни Кровавого Копыта стоит большой шатер. Там живет Нарм Небесный Охотник. Он тебя ждет."] = "2cc8a84851d7a88a809391efe90970e2",
		["Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни."] = "b2a8c34179a4d841383ff97395514958",
		["У нас в деревне Кровавого Копыта нет учителей алхимии, но на севере, в Громовом Утесе, они точно есть. Иди по дороге, поднимись на вершину утеса и спроси у стражей, как тебе найти нужного мастера."] = "c3af611102860e167bee51a4ceaeac25",
		["К северу, в Громовом Утесе – нашей великой обители – живет известный учитель кузнечного дела. Если ты хочешь учиться этому ремеслу, отправляйся туда. Стражи утесов покажут тебе дорогу."] = "20fe8dafb1b652eedfa130fe89774396",
		["Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому."] = "5c95413a6633181b565858b1815a5303",
		["Тогда ваш путь лежит на север, в Громовой Утес. Там обратитесь к любому из стражей – он вам все объяснит."] = "342039144f9b83811abcd0fc69301c5d",
		["Вира Нежное Копыто проводит тренировки в длинном доме на западной стороне деревни."] = "ee9dc1161bbd06619acbadaa1ca2b2f0",
		["Тебе нужен Утан Тихая Заводь. Его можно найти к западу от деревни, на берегу озера Каменного Быка."] = "fee6da195cf9ff2a6c9a1d6acd19b3c7",
		["Если ты желаешь научиться травничеству, тебе нужно направиться в Громовой Утес. Следуй по дороге из Деревни Кровавого Копыта и поднимись на лифте на вершину утеса. Там ты можешь попросить о дальнейшей помощи стража утесов."] = "ce8bb67e85d7a847e3207905f6b1109b",
		["В большой хижине на северо-западном углу деревни живет Чоу Толстая Шкура. Он научит тебя всему, что нужно знать кожевнику."] = "72d3b9186e1596ba056ea710fc81ecf6",
		["Ммм, мне кажется, тебе нужно подняться на верх Громового Утеса, чтобы научиться этому. Отправляйся на север по дороге из Деревни Кровавого Копыта. Она приведет тебя к подножию утеса. Используй лифт, чтобы подняться на вершину, и там поговори с одним из стражей утесов, они тебе помогут."] = "b87378d05f06dc5aa6854e33a9d1da1f",
		["Йонн Глубокий Надрез живет в большом шатре на северо-западном краю деревни Кровавого Копыта."] = "8dae139ad18d57d82ef08b6478035261",
		["К сожалению, никто не преподает портняжное дело здесь, в Деревне Кровавого Копыта, но ты можешь найти учителя в Громовом Утесе. Следуй по тропе на север из деревни, пока не дойдешь до лифтов. Поднимись в одном из них до самого верха и спроси там одного из стражей утесов, куда идти дальше."] = "96adccaa34d859c8a885b02f148efebd",
	},
	["Храбрец Вольный Охотник"] = {
		["У нас в деревне нет такого места. А вот в высотах Громового Утеса – есть. Направляйся на север по дороге от Деревни Кровавого Копыта, пока не придешь к основанию утесов. Там поднимись на лифте наверх и поговори со стражем утесов. Да хранят тебя твои предки."] = "c61c8d0a95bbdd9d8df4d9db44c53e73",
		["Ничто так не освобождает душу, как полет в небе. В главном городе нашего племени, Громовом Утесе, есть подходящее для этого место. Тебя приведет туда дорога, что идет на север из Деревни Кровавого Копыта. Когда поднимешься наверх, поговори с одним из стражей утесов, он сможет дать тебе дальнейшие указания."] = "e3b119cda97abe5ee10979d688350484",
		["Всему на свете есть время и место, а уж тем более отдыху. К западу от Деревни Кровавого Копыта хозяин таверны Каут держит приют для тех, кто устал от странствий. Там же он и живет."] = "d0fbd1df4ebdde74721d6f5659827225",
		["Если понадобится, о твоих питомцах может позаботиться Сейква. Ее ты найдешь возле трактира."] = "38fd4c76a36f825f232997fc50761870",
		["Путь друида сродни пути шамана. Генния Рунический Тотем в этом искусстве поднаторела. Ее ты найдешь в большой палатке на востоке деревни Кровавого Копыта."] = "6c2a1f69d196c4657a53b7c110c61e4c",
		["Научиться единению с природой во славу Матери-Земли – благое дело. Если хочешь постичь пути охотников, ты $gдолжен:должна; найти Йо Колкую Гриву в северной части деревни Кровавого Копыта."] = "21ee90ef1c873dcee3c9e57987f0dab4",
		["В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов."] = "af5b82f4f5903c5285a8c966bbd9396d",
		["Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни."] = "37885a7674244dd6e4cdeec2c68f5685",
		["Готовить зелья из даров Матери-Земли, чтобы помочь нам в вечной борьбе, – достойное занятие. Чтобы научиться этому искусству, отправляйся на север, в наш великий Громовой Утес. Когда поднимешься на вершину, обратись за помощью к одному из стражей утесов."] = "f53e995a55576c4dc433b9e11460ad87",
		["Ты желаешь превращать кости Матери-Земли в орудия, которые послужат делу Орды. Хорошо, хорошо. Иди по дороге на север от деревни Кровавого Копыта, пока не придешь к подъемнику, что ведет на вершину Громового Утеса. Там обратись к любому из стражей."] = "e150bdb40bb2ad6d87a0d8460847996a",
		["Ммм, кулинария – это вкусно… А Пиалл Тихая Поступь – лучший повар Деревни Кровавого Копыта! Его можно найти в большом шатре в северо-восточной части деревни."] = "1c9e8d41e271bfa8a081921047868b8c",
		["Такие знания можно найти только в великом Громовом Утесе. Иди из деревни Кровавого Копыта по дороге на север. У подножия утесов будет подъемник. Поднимись на нем наверх и обратись к любому из стражей."] = "360397b474c43b7dcab78b62333d6ac1",
		["Повязки, противоядия и подобные вещи незаменимы при жизни на равнинах! Вира Нежное Копыто может обучить вас оказывать первую помощь. Ее можно найти в длинном здании на западе Деревни Кровавого Копыта."] = "3134d4a4d8b645aeefba37aba15985b7",
		["Дай таурену рыбу, и он будет сыт весь день. Научи таурена рыбачить, и он будет сыт всю жизнь. Утан Тихая Заводь может научить тебя рыбачить. Искать его надо к западу от деревни Кровавого Копыта, на берегах озера Каменного Быка."] = "a50a61ff9211f062ebc4c78f9fccc5f6",
		["Есть те, кто может научить тебя травничеству – в большом доме Громового Утеса к северу. Следуй по дороге из деревни, чтобы добраться туда, и у основания утеса поднимись на лифте до его вершины. Любой из стражей сможет направить тебя."] = "201f3cba26808c32bb7ee62dfa628e09",
		["Когда мы используем шкуры зверей, которых мы должны убить для защиты от них или для еды, мы почитаем Мать-Землю и выказываем уважение животному. Чоу Толстая Шкура может научить тебя таким вещам. Ты найдешь его в большом тенте в северо-западном углу деревни Кровавого Копыта."] = "e1efe823ee30b1c010852c13a53cb700",
		["Я слышал, что учителя горного дела можно найти в Громовом Утесе, к северу отсюда. Иди по дороге из деревни, и когда дойдешь туда, поднимись на лифте на вершину. Там тебе сможет помочь любой из стражей утесов."] = "e6cb4ccc587cd2a258b3ded78ae7a3f0",
		["Ах да, снятие шкур. Никто так ловко не управляется с ножом, как Йонн Глубокий Надрез. Ты найдешь его в большом шатре на северо-западном углу деревни."] = "822d9c5197a44204042199ef7be11a36",
		["Портняжное дело, говоришь? Хм. А, конечно! Иди в Громовой Утес, прямо на север. Как доберешься туда – пройди через деревню, а потом, как дойдешь до утесов, воспользуйся подъемником наверх и поговори с кем-нибудь из стражей."] = "aae10fc784263c4cb468d55cea4fd71e",
		["Что ты ищешь?"] = "b3d11178772212cc804676804bb92ca1",
		["А, для этого вам нужно будет подняться на самую вершину Громового Утеса. Из Деревни Кровавого Копыта ступайте на север, и скоро увидите у подножия утесов лифты, которые довезут вас наверх. А там спросите дорогу у одного из стражей утесов."] = "9e546e689233ec91191a43a7e36c67f5",
		["В великом городе Громовом Утесе обитает укротитель ветрокрылов. Направь свои стопы на север, поднимись на подъемнике на вершину утеса и обратись к любому из стражей утесов."] = "b0b81da2b32d5fdbc23302be9744240a",
		["Вам нужен хозяин таверны Каут. Он живет в западной части деревни в одном из длинных домов."] = "07ac0c881242c277b1b4be65bb1bb779",
		["Тебе нужна Сейква. Кажется, я видел ее возле трактира."] = "4e99c32785b303ece538f803ff4fcb96",
		["Какой учитель тебе нужен?"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
		["Какая профессия?"] = "4a850dc32d00c265e503622c595cebf4",
		["Тебе нужен совет Геннии Рунического Тотема. Ты найдешь ее в большом тенте в восточной части деревни."] = "dce81535973ad9064578c7dc07d654a1",
		["Йо Колкая Грива ждет тебя на северной стороне деревни. Он может научить тебя охотничьим секретам."] = "4c1b626c145d8077c5aa2db55852dcfa",
		["На востоке деревни Кровавого Копыта стоит большой шатер. Там живет Нарм Небесный Охотник. Он тебя ждет."] = "460e9ebf106048fdb04f6a2f81157b23",
		["Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни."] = "14d4e5dc44125fe42705f2ed118e5aed",
		["У нас в деревне Кровавого Копыта нет учителей алхимии, но на севере, в Громовом Утесе, они точно есть. Иди по дороге, поднимись на вершину утеса и спроси у стражей, как тебе найти нужного мастера."] = "83cd87a9bd04fe41340d47a6a3863fb1",
		["К северу, в Громовом Утесе – нашей великой обители – живет известный учитель кузнечного дела. Если ты хочешь учиться этому ремеслу, отправляйся туда. Стражи утесов покажут тебе дорогу."] = "302142138778affead2a13087925b7b1",
		["Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому."] = "a234d4b10d5440d815b7b7172e8e8687",
		["Тогда ваш путь лежит на север, в Громовой Утес. Там обратитесь к любому из стражей – он вам все объяснит."] = "7c186bc25b44ca7d456a044d9c8671a4",
		["Вира Нежное Копыто проводит тренировки в длинном доме на западной стороне деревни."] = "4f5f7ae4d60dbe2bd1bf43b0ad2e8786",
		["Тебе нужен Утан Тихая Заводь. Его можно найти к западу от деревни, на берегу озера Каменного Быка."] = "50f0680942e77b17d91b589f7a3a11f1",
		["Если ты желаешь научиться травничеству, тебе нужно направиться в Громовой Утес. Следуй по дороге из Деревни Кровавого Копыта и поднимись на лифте на вершину утеса. Там ты можешь попросить о дальнейшей помощи стража утесов."] = "52d1b670cce86f12a40bdf74b938d00d",
		["В большой хижине на северо-западном углу деревни живет Чоу Толстая Шкура. Он научит тебя всему, что нужно знать кожевнику."] = "f68fe1ab41731a31f4c94d358440f989",
		["Ммм, мне кажется, тебе нужно подняться на верх Громового Утеса, чтобы научиться этому. Отправляйся на север по дороге из Деревни Кровавого Копыта. Она приведет тебя к подножию утеса. Используй лифт, чтобы подняться на вершину, и там поговори с одним из стражей утесов, они тебе помогут."] = "bd7be540acfdb0455e58364636e73dda",
		["Йонн Глубокий Надрез живет в большом шатре на северо-западном краю деревни Кровавого Копыта."] = "951cf972b72fa8a3afed83790bceb3f0",
		["К сожалению, никто не преподает портняжное дело здесь, в Деревне Кровавого Копыта, но ты можешь найти учителя в Громовом Утесе. Следуй по тропе на север из деревни, пока не дойдешь до лифтов. Поднимись в одном из них до самого верха и спроси там одного из стражей утесов, куда идти дальше."] = "bbf8a87da18419b0d4c795a3f40babb6",
	},
	["Храбрец Железный Рог"] = {
