		["Ах да, снятие шкур. Никто так ловко не управляется с ножом, как Йонн Глубокий Надрез. Ты найдешь его в большом шатре на северо-западном углу деревни."] = "e3314daab9e334b6f1e7993a6167eff9",
		["Портняжное дело, говоришь? Хм. А, конечно! Иди в Громовой Утес, прямо на север. Как доберешься туда – пройди через деревню, а потом, как дойдешь до утесов, воспользуйся подъемником наверх и поговори с кем-нибудь из стражей."] = "6bbecd1d0a266d717b54a938edbfcf57",
		["Что ты ищешь?"] = "00194bd1912d495a809752f13911ce30",
		["А, для этого вам нужно будет подняться на самую вершину Громового Утеса. Из Деревни Кровавого Копыта ступайте на север, и скоро увидите у подножия утесов лифты, которые довезут вас наверх. А там спросите дорогу у одного из стражей утесов."] = "9e59faa86e4dae4d1725cb773a40ef48",
		["В великом городе Громовом Утесе обитает укротитель ветрокрылов. Направь свои стопы на север, поднимись на подъемнике на вершину утеса и обратись к любому из стражей утесов."] = "eaaf7438e186e62ee1ea9c69523e1696",
		["Вам нужен хозяин таверны Каут. Он живет в западной части деревни в одном из длинных домов."] = "d8529bed329ec6d3ba33e0046164fc29",
		["Тебе нужна Сейква. Кажется, я видел ее возле трактира."] = "4b846af59d88843ba65c5b14298e254e",
		["Какой учитель тебе нужен?"] = "cfe020697f1863a2bc8a41431401f702",
		["Какая профессия?"] = "4deee9d3ecac92ac21b2a2f5401711e6",
		["Тебе нужен совет Геннии Рунического Тотема. Ты найдешь ее в большом тенте в восточной части деревни."] = "0c40ff0ebe77be70ce1a62dc6ed9cea5",
		["Йо Колкая Грива ждет тебя на северной стороне деревни. Он может научить тебя охотничьим секретам."] = "ff13d0d3ffce0e3452bba6d278dd54de",
		["На востоке деревни Кровавого Копыта стоит большой шатер. Там живет Нарм Небесный Охотник. Он тебя ждет."] = "2cc8a84851d7a88a809391efe90970e2",
		["Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни."] = "b2a8c34179a4d841383ff97395514958",
		["У нас в деревне Кровавого Копыта нет учителей алхимии, но на севере, в Громовом Утесе, они точно есть. Иди по дороге, поднимись на вершину утеса и спроси у стражей, как тебе найти нужного мастера."] = "c3af611102860e167bee51a4ceaeac25",
		["К северу, в Громовом Утесе – нашей великой обители – живет известный учитель кузнечного дела. Если ты хочешь учиться этому ремеслу, отправляйся туда. Стражи утесов покажут тебе дорогу."] = "20fe8dafb1b652eedfa130fe89774396",
		["Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому."] = "5c95413a6633181b565858b1815a5303",
		["Тогда ваш путь лежит на север, в Громовой Утес. Там обратитесь к любому из стражей – он вам все объяснит."] = "342039144f9b83811abcd0fc69301c5d",
		["Вира Нежное Копыто проводит тренировки в длинном доме на западной стороне деревни."] = "ee9dc1161bbd06619acbadaa1ca2b2f0",
		["Тебе нужен Утан Тихая Заводь. Его можно найти к западу от деревни, на берегу озера Каменного Быка."] = "fee6da195cf9ff2a6c9a1d6acd19b3c7",
		["Если ты желаешь научиться травничеству, тебе нужно направиться в Громовой Утес. Следуй по дороге из Деревни Кровавого Копыта и поднимись на лифте на вершину утеса. Там ты можешь попросить о дальнейшей помощи стража утесов."] = "ce8bb67e85d7a847e3207905f6b1109b",
		["В большой хижине на северо-западном углу деревни живет Чоу Толстая Шкура. Он научит тебя всему, что нужно знать кожевнику."] = "72d3b9186e1596ba056ea710fc81ecf6",
		["Ммм, мне кажется, тебе нужно подняться на верх Громового Утеса, чтобы научиться этому. Отправляйся на север по дороге из Деревни Кровавого Копыта. Она приведет тебя к подножию утеса. Используй лифт, чтобы подняться на вершину, и там поговори с одним из стражей утесов, они тебе помогут."] = "b87378d05f06dc5aa6854e33a9d1da1f",
		["Йонн Глубокий Надрез живет в большом шатре на северо-западном краю деревни Кровавого Копыта."] = "8dae139ad18d57d82ef08b6478035261",
		["К сожалению, никто не преподает портняжное дело здесь, в Деревне Кровавого Копыта, но ты можешь найти учителя в Громовом Утесе. Следуй по тропе на север из деревни, пока не дойдешь до лифтов. Поднимись в одном из них до самого верха и спроси там одного из стражей утесов, куда идти дальше."] = "96adccaa34d859c8a885b02f148efebd",
	},
	["Храбрец Серогривый"] = {
		["У нас в деревне нет такого места. А вот в высотах Громового Утеса – есть. Направляйся на север по дороге от Деревни Кровавого Копыта, пока не придешь к основанию утесов. Там поднимись на лифте наверх и поговори со стражем утесов. Да хранят тебя твои предки."] = "c61c8d0a95bbdd9d8df4d9db44c53e73",
		["Ничто так не освобождает душу, как полет в небе. В главном городе нашего племени, Громовом Утесе, есть подходящее для этого место. Тебя приведет туда дорога, что идет на север из Деревни Кровавого Копыта. Когда поднимешься наверх, поговори с одним из стражей утесов, он сможет дать тебе дальнейшие указания."] = "e3b119cda97abe5ee10979d688350484",
		["Всему на свете есть время и место, а уж тем более отдыху. К западу от Деревни Кровавого Копыта хозяин таверны Каут держит приют для тех, кто устал от странствий. Там же он и живет."] = "d0fbd1df4ebdde74721d6f5659827225",
		["Если понадобится, о твоих питомцах может позаботиться Сейква. Ее ты найдешь возле трактира."] = "38fd4c76a36f825f232997fc50761870",
		["Путь друида сродни пути шамана. Генния Рунический Тотем в этом искусстве поднаторела. Ее ты найдешь в большой палатке на востоке деревни Кровавого Копыта."] = "6c2a1f69d196c4657a53b7c110c61e4c",
		["Научиться единению с природой во славу Матери-Земли – благое дело. Если хочешь постичь пути охотников, ты $gдолжен:должна; найти Йо Колкую Гриву в северной части деревни Кровавого Копыта."] = "21ee90ef1c873dcee3c9e57987f0dab4",
		["В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов."] = "af5b82f4f5903c5285a8c966bbd9396d",
		["Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни."] = "37885a7674244dd6e4cdeec2c68f5685",
		["Готовить зелья из даров Матери-Земли, чтобы помочь нам в вечной борьбе, – достойное занятие. Чтобы научиться этому искусству, отправляйся на север, в наш великий Громовой Утес. Когда поднимешься на вершину, обратись за помощью к одному из стражей утесов."] = "f53e995a55576c4dc433b9e11460ad87",
		["Ты желаешь превращать кости Матери-Земли в орудия, которые послужат делу Орды. Хорошо, хорошо. Иди по дороге на север от деревни Кровавого Копыта, пока не придешь к подъемнику, что ведет на вершину Громового Утеса. Там обратись к любому из стражей."] = "e150bdb40bb2ad6d87a0d8460847996a",
		["Ммм, кулинария – это вкусно… А Пиалл Тихая Поступь – лучший повар Деревни Кровавого Копыта! Его можно найти в большом шатре в северо-восточной части деревни."] = "1c9e8d41e271bfa8a081921047868b8c",
		["Такие знания можно найти только в великом Громовом Утесе. Иди из деревни Кровавого Копыта по дороге на север. У подножия утесов будет подъемник. Поднимись на нем наверх и обратись к любому из стражей."] = "360397b474c43b7dcab78b62333d6ac1",
		["Повязки, противоядия и подобные вещи незаменимы при жизни на равнинах! Вира Нежное Копыто может обучить вас оказывать первую помощь. Ее можно найти в длинном здании на западе Деревни Кровавого Копыта."] = "3134d4a4d8b645aeefba37aba15985b7",
		["Дай таурену рыбу, и он будет сыт весь день. Научи таурена рыбачить, и он будет сыт всю жизнь. Утан Тихая Заводь может научить тебя рыбачить. Искать его надо к западу от деревни Кровавого Копыта, на берегах озера Каменного Быка."] = "a50a61ff9211f062ebc4c78f9fccc5f6",
		["Есть те, кто может научить тебя травничеству – в большом доме Громового Утеса к северу. Следуй по дороге из деревни, чтобы добраться туда, и у основания утеса поднимись на лифте до его вершины. Любой из стражей сможет направить тебя."] = "201f3cba26808c32bb7ee62dfa628e09",
		["Когда мы используем шкуры зверей, которых мы должны убить для защиты от них или для еды, мы почитаем Мать-Землю и выказываем уважение животному. Чоу Толстая Шкура может научить тебя таким вещам. Ты найдешь его в большом тенте в северо-западном углу деревни Кровавого Копыта."] = "e1efe823ee30b1c010852c13a53cb700",
		["Я слышал, что учителя горного дела можно найти в Громовом Утесе, к северу отсюда. Иди по дороге из деревни, и когда дойдешь туда, поднимись на лифте на вершину. Там тебе сможет помочь любой из стражей утесов."] = "e6cb4ccc587cd2a258b3ded78ae7a3f0",
		["Ах да, снятие шкур. Никто так ловко не управляется с ножом, как Йонн Глубокий Надрез. Ты найдешь его в большом шатре на северо-западном углу деревни."] = "822d9c5197a44204042199ef7be11a36",
