		["В великом городе Громовом Утесе обитает укротитель ветрокрылов. Направь свои стопы на север, поднимись на подъемнике на вершину утеса и обратись к любому из стражей утесов."] = "eaaf7438e186e62ee1ea9c69523e1696",
		["Вам нужен хозяин таверны Каут. Он живет в западной части деревни в одном из длинных домов."] = "d8529bed329ec6d3ba33e0046164fc29",
		["Тебе нужна Сейква. Кажется, я видел ее возле трактира."] = "4b846af59d88843ba65c5b14298e254e",
		["Какой учитель тебе нужен?"] = "cfe020697f1863a2bc8a41431401f702",
		["Какая профессия?"] = "4deee9d3ecac92ac21b2a2f5401711e6",
		["Тебе нужен совет Геннии Рунического Тотема. Ты найдешь ее в большом тенте в восточной части деревни."] = "0c40ff0ebe77be70ce1a62dc6ed9cea5",
		["Йо Колкая Грива ждет тебя на северной стороне деревни. Он может научить тебя охотничьим секретам."] = "ff13d0d3ffce0e3452bba6d278dd54de",
		["На востоке деревни Кровавого Копыта стоит большой шатер. Там живет Нарм Небесный Охотник. Он тебя ждет."] = "2cc8a84851d7a88a809391efe90970e2",
		["Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни."] = "b2a8c34179a4d841383ff97395514958",
		["У нас в деревне Кровавого Копыта нет учителей алхимии, но на севере, в Громовом Утесе, они точно есть. Иди по дороге, поднимись на вершину утеса и спроси у стражей, как тебе найти нужного мастера."] = "c3af611102860e167bee51a4ceaeac25",
		["К северу, в Громовом Утесе – нашей великой обители – живет известный учитель кузнечного дела. Если ты хочешь учиться этому ремеслу, отправляйся туда. Стражи утесов покажут тебе дорогу."] = "20fe8dafb1b652eedfa130fe89774396",
		["Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому."] = "5c95413a6633181b565858b1815a5303",
		["Тогда ваш путь лежит на север, в Громовой Утес. Там обратитесь к любому из стражей – он вам все объяснит."] = "342039144f9b83811abcd0fc69301c5d",
		["Вира Нежное Копыто проводит тренировки в длинном доме на западной стороне деревни."] = "ee9dc1161bbd06619acbadaa1ca2b2f0",
		["Тебе нужен Утан Тихая Заводь. Его можно найти к западу от деревни, на берегу озера Каменного Быка."] = "fee6da195cf9ff2a6c9a1d6acd19b3c7",
		["Если ты желаешь научиться травничеству, тебе нужно направиться в Громовой Утес. Следуй по дороге из Деревни Кровавого Копыта и поднимись на лифте на вершину утеса. Там ты можешь попросить о дальнейшей помощи стража утесов."] = "ce8bb67e85d7a847e3207905f6b1109b",
		["В большой хижине на северо-западном углу деревни живет Чоу Толстая Шкура. Он научит тебя всему, что нужно знать кожевнику."] = "72d3b9186e1596ba056ea710fc81ecf6",
		["Ммм, мне кажется, тебе нужно подняться на верх Громового Утеса, чтобы научиться этому. Отправляйся на север по дороге из Деревни Кровавого Копыта. Она приведет тебя к подножию утеса. Используй лифт, чтобы подняться на вершину, и там поговори с одним из стражей утесов, они тебе помогут."] = "b87378d05f06dc5aa6854e33a9d1da1f",
		["Йонн Глубокий Надрез живет в большом шатре на северо-западном краю деревни Кровавого Копыта."] = "8dae139ad18d57d82ef08b6478035261",
		["К сожалению, никто не преподает портняжное дело здесь, в Деревне Кровавого Копыта, но ты можешь найти учителя в Громовом Утесе. Следуй по тропе на север из деревни, пока не дойдешь до лифтов. Поднимись в одном из них до самого верха и спроси там одного из стражей утесов, куда идти дальше."] = "96adccaa34d859c8a885b02f148efebd",
	},
	["Хранитель мудрости Праздника"] = {
		["Наслаждаетесь атмосферой фестиваля, $c?$b$bВ то время как Хранители Пламени тяготеют душой к огням настоящего, я в большей степени историк, хранящий воспоминания о фестивалях прошлого. Конечно, я документирую и празднества этого года. Пока все идет неплохо, как по-вашему?$b$bЗнаете, $n, во всех фестивальных огнях, горящих на протяжении всего празднества, присутствует определенная сила. Мы заботимся о наших огнях, но я уверен, что священные огни пылают и в городах наших врагов…"] = "5c66a04a03f0c09ed64da9dc7d5312b6",
	},
	["Хрог"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "4e1a9fddd86d3d21099d60aa02fea747",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "200fc4a4b57ca0db7de99023c501ea23",
	},
	["Хронос"] = {
		["Приветствую тебя. Я – Хронос, помнящий все. Моя память безупречна и точна до малейшей детали.$B$BДоверься мне."] = "26f2988f1c71f43761398daa16273de5",
	},
	["Хуум Буйногривый"] = {
		["Духи Силитуса взывают к нам, $N. Земля рыдает, ибо наша история очень и очень печальна…"] = "81fa3f4ee4a97d65004b878d5bb8a931",
	},
	["Цап Телепортыш"] = {
		["Я только что закончил работу над новой пространственной подрывочной машиной, которая сделает меня богаче, чем в самых моих несбыточных гоблинских мечтах! Все, что мне нужно, – это найти толкового гоблина-инженера, чтобы тот сделал многомерный саморез, и останется только подсоединить и испробовать!"] = "0c3633a7d4f6e9b798ba0e339ff2765c",
		["Приятно видеть столь храброго инженера! Настоящие гоблины-инженеры всегда смеются над опасностью!"] = "8f5aefe9123fb8887c7b7bb32250448a",
		["Теория такова. Мы распыляем тебя мощным взрывом, полученные частицы передаем через пространственный разрыв, а затем заново собираем тебя с помощью нашей машины. Мгновенное перемещение! Конечно, это может и не сработать… Но ты же гоблинский инженер, а настоящего гоблинского инженера собственное выживание волнует в последнюю очередь!\nВот чертеж, по которому ты сможешь изготовить Пространственный проходчик."] = "dfd0c3400fd8ac2bb161ce6bba353f92",
	},
	["Чариса Изериан"] = {
		["Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда."] = "49e5864e02449db1b69ff60632939d53",
		["С тех пор как пал Даларан и был разрушен Кель'Талас, такие товары встречаются крайне редко. Но Лукан Корделл и еще несколько торговцев все еще могут выполнять наши заказы."] = "7b74123b73660b230105d037e31ae78f",
	},
	["Часовой Тельдрассила"] = {
		["Если тебе нужен банк, ступай в самое сердце Дарнасса. Там ты найдешь надежное хранилище для своих сокровищ."] = "4ea5d9544049803bcffe33d330e2fb7d",
		["Паром руттеранской переправы отправляется в Аубердин из деревни Рут'теран у подножия Тельдрассила. В эту деревню можно попасть из Дарнасса через портал."] = "6c037df3b7038d9b82a973b662d9e670",
		["Такие документы, как бумаги на создание гильдии, могут быть получены от мастера гильдии в городе Дарнассе."] = "073009f4d29320fba71c2b204da1fac8",
		["Если тебе нужно время на восстановление сил, лучше всего его провести в таверне Доланаара. Хозяин таверны Кельдамир позаботится о твоем отдыхе."] = "7044a367e4a4d0f456163951264eed1d",
		["Тебе нужен кто-нибудь, умеющий ухаживать за животными? Тогда поищи Сериадну возле трактира Доланаара. Она тебе и нужна."] = "f973dc94f8e2f3e5bb9ad0a919636750",
		["Друид Кел проводит много времени у лунного колодца в Доланааре. Я уверен, что он мог бы научить тебя тому, что тебе нужно."] = "16bba8106fe5aa116151356d9d0c1668",
		["Дазалар – самый известный охотник Доланаара. Почему бы тебе не поговорить с ним?"] = "a50cc4748a430d5984fd12118582d8e4",
		["Лорна Утренний Свет лечит всех жителей Доланаара, которые в этом нуждаются. Многим жрецам стоит у нее поучиться."] = "4884b53e55dec4a3470d470b3fa83514",
		["Ищете разбойника? Ну, тогда вам нужен Джаннок. Поговорите с ним, он в доланаарском трактире."] = "7ee91439488e010165881cb797efaa1e",
		["Однажды мне посчастливилось увидеть Кайру Ветрорез в бою. Поэтому я не сомневаюсь, что она хорошо тебя обучит. Найти ее можно в трактире Доланаара."] = "c71b255b624a3a50ff4387076cd62716",
		["Познания Циндры в алхимии не слишком глубоки, но для начала и это сгодится. Ты найдешь ее к востоку таверны в Доланааре."] = "2f7ad8bfc99055a560658a285e3618b3",
		["Еще один повар в Доланааре не помешает, хотя у нас уже есть Заррин. Вы бы сходили к нему – вдруг чему полезному научит?"] = "0a5ce5d8a7759f29e79e96556ab20845",
		["Аланна целыми днями совершенствует свое мастерство на поляне Оракула. Если у кого и учиться зачаровыванию, так это у нее."] = "15211b4d4b796d136e52a122b432560f",
		["Бьанси – настоящий мастер первой помощи. Если хочешь взять у нее несколько уроков, ступай к трактиру Доланаара, а оттуда – на север."] = "51ebad09e83f3656e4c78bc259beef52",
		["Древесники разогнали всех рыбаков в окрестностях Доланаара, поэтому учителей рыбной ловли надо искать в Дарнассе."] = "1806edb01b654109c85d847d2fc7129a",
		["Травничество требует осторожного подхода. Этому учат немногие – в том числе Малорн. Его можно найти восточнее таверны в Доланааре."] = "80ed9b7cf270b2683ac103fb42181eba",
		["Надийя работает с кожей уже много лет. Чтобы найти ее, пройди на запад по дороге в Дарнасс. Может быть, она научит тебя тонкостям своего ремесла."] = "59c29a24054e9781525056418704352b",
		["В Дарнассе производится отличное текстильное сырье. Неудивительно, что все лучшие портные перебрались туда. Если ты хочешь освоить портняжное дело, отправляйся в Дарнасс."] = "565828b0bf2c0a029bdd705634e05c4c",
		["В Тельдрассиле есть много интересных мест. Что именно ты ищешь?"] = "274ed111b1b971c19cf221ceb6d4da6d",
		["Банк находится в безмятежном городе Дарнассе. Тебе придется пойти туда, если хочешь оставить свое имущество на хранение."] = "6427b5ad172185229fdf52a2a91052ea",
		["Чтобы добраться до руттеранской переправы, тебе нужно прийти в Дарнасс и воспользоваться порталом в деревню Рут'теран, расположенную у подножия Тельдрассила."] = "f7f50698e64399e73c940b8e5999f55e",
		["Такие дела решаются только в Дарнассе. Если вы хотите создать гильдию, отправляйтесь туда."] = "d02f310024399482b9dac67cfc148f64",
		["Хорошо отдохнуть и выспаться наверняка можно в кроватях, которые хозяин таверны Кельдамир держит в таверне в Доланааре."] = "94a6749341ef5f66c12f93180c75a230",
		["А, добрая Сериадна… Все животные чувствуют себя в безопасности рядом с ней. Ты найдешь ее прямо возле таверны в Доланааре."] = "4b9bee6beacd2d5faf637d1fc7af3558",
		["В Доланааре ты найдешь множество наставников, посвятивших своему делу долгие годы. Чему именно ты хочешь учиться?"] = "3b62e4181d8e155be0d34c32038137f0",
		["Путь того, кто выбрал себе профессию, долог и прибылен. Какую профессию вы выбрали для себя?"] = "d23c8b801de15e2ee7f38ac7e99b1867",
		["Ты ищешь помощи друидов? Тогда тебе нужен Калль. Его можно встретить возле Лунного колодца, к югу от трактира Доланаара."] = "7c41a2cdee58db931c3f57aaeecede92",
		["Если вы ищете охотника, вам нужен Далазар. Обычно его можно найти возле таверны в Доланааре."] = "6a033c0f5e434887661d585271c95874",
		["Жрица по имени Лорна Утренний Свет называет Доланаар своим домом. Кажется, ее можно встретить к северу от таверны."] = "2c6cd31df344e81e13802e0526bd4f82",
		["Разбойник? Я не имею ничего общего с такими типами, но, думаю, Джаннок – тот, кто тебе нужен. Ищи его в таверне Доланаара."] = "83667d262f35fc73bb7553229dba8a25",
		["Кайра Ветрорез обладает невероятным мастерством в обращении с клинком. Она может научить тебя кое-чему. Ты можешь найти ее в таверне в Доланааре."] = "2ff6748c5381da2b47cccf19dd9e9d98",
		["Когда Циндра не кипит от ярости, как ее зелья, она вполне мила и может многому научить. Ты найдешь ее к востоку от таверны Доланаара."] = "64eab3bd0b6e3e418b180b01fb4cd9a0",
		["Заррин, похоже, хорошо знает кулинарное дело. Почему бы тебе не пойти и не посмотреть, не научит ли он тебя нескольким рецептам? Он обычно готовит в таверне в Доланааре."] = "83e47373c7b037c97ea19a841c67728b",
		["Аланна Око Ворона отчасти приписывает свой талант зачаровывателя общению с духами на Поляне Оракула. Сейчас ты можешь найти ее там."] = "9963e2c8079556e7e03308c3b714ad3d",
		["Бьанси часто помогает стражам, патрулирующим местную глухомань. Если хочешь научиться оказывать первую помощь, обратись к ней."] = "5236c19b097c185960d21473a0f76c58",
		["В последнее время на озере Аль'Амет стало небезопасно, поэтому все рыбаки переехали в Дарнасс. Поищите учителя там."] = "f04c72b9d344f81d24b170747fc637e9",
		["Малорн ухитряется срывать даже самые хрупкие травы, не повредив их. Ясно, что учиться тебе надо у него. Он живет в Доланааре, к востоку от таверны."] = "fa2f6a0bf9ea5e78c7cd9a9670147fcc",
		["Мастера клана Спутанная Грива работают в своем домике у дороги в Дарнасс. Надийя – отличный учитель кожевников. Обязательно возьмите у нее пару уроков."] = "f29cadd86be2633b030d2922ef0d73a4",
		["Раднаал живет в своем доме у дороги в Дарнасс. Быть может, он научит тебя чему-то новому."] = "2e33db29fb989db5225ed21dd00dfc75",
		["Несомненно, в Дарнассе найдется портной, который смог бы учить тебя. Когда доберешься туда, спроси одного из часовых Дарнасса, как можно найти учителя портняжного дела."] = "fde658d3d3dda267bafe6d6134c02642",
	},
	["Чоу Толстая Шкура"] = {
		["Мясо, шкура, кости… У хорошего охотника ничего не пропадает. Даже мельчайший клочок кожи может пригодиться. Сотня таких клочков – вот и готовы доспехи другу. Порознь мы сильны, а вместе – непобедимы!"] = "f13238d0343549166ee185d5c7b13512",
		["Ты $gпревзошел:превзошла; все мои наставления. Иди, и да благословит тебя Мать-Земля. Отыщи в магазинах на северо-западе центрального плато Громового Утеса таурена по имени Тарн. Внемли его мудрости."] = "e5c3faa7754d65e972344cb259b1aec1",
		["Мы живем и умираем, а земля остается, вечная и безразличная к нашим делам. Вот потому-то земля и не может принадлежать нам, $n. Наоборот, мы принадлежим ей. Поэтому мы защищаем землю – без нее не может быть жизни."] = "9802c328fee5a83bc01704102bf807c7",
	},
	["Шайламиир"] = {
		["Надеюсь, ты прерываешь меня не зря. У меня тут очень важная работа."] = "1350458c0cd4617f19601567a9a4d9f2",
		["Очередной травник, хмм. Сомневаюсь, что у тебя такой же великолепный навык, как и у меня, поэтому, может быть, я смогу обучить тебя парочке приемчиков."] = "e5d7ea0ee1b3b55a8e19cbb4d7d4bf32",
	},
	["Шайна Корпия"] = {
		["О, коллега-врач. С радостью научу вас всему, что может пригодиться в поездках."] = "5871df482a5322411e3250bb05234252",
		["Да, $gсын мой:дочь моя;? Чем я могу тебе помочь?"] = "a9c31ad2585736a1fb03d2ae8ab3eacd",
		["Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора."] = "1d81b661f251fb69f984eaa16be96159",
		["Я слышал, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи."] = "6bb0666f31370413b0bedf9c9606f6aa",
	},
	["Шанда"] = {
		["Да пребудет с тобой Элуна, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
		["Мое знание – твое знание, моя мудрость – твоя мудрость. Чем могу служить, $n?"] = "7f25bf796f093ccde831db9e50079867",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
	},
	["Шеаль Рунический Тотем"] = {
		["$n, чему еще я могу тебя научить, во имя Матери-Земли?"] = "0b1e4654cf5625d6348cc8e5879e4287",
		["Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, $c."] = "908557c88c665ff5a3ab222467aa84c9",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "0ad2a902852beef6cfe7ead6b6979fff",
	},
	["Шелли Брондир"] = {
		["Куда бы вы хотели слетать?"] = "f6ea55ad6f6344693225294350de4559",
	},
	["Шельдрас Лунное Древо"] = {
		["Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя."] = "922a94a8f826437fe0370bdcd6a587ac",
		["Добро пожаловать, $gбрат мой:сестра моя;. Если ты здесь, чтобы тренироваться, я буду рад потренировать тебя.$B$BСкоро придет время, когда зов Изумрудного Сна завладеет тобой. Ты впадешь в летаргию на долгие годы и будешь ступать среди чистейших форм. Именно там и тогда состоится твое окончательное обучение."] = "1d12fd8e421d229eea70c7677a2daeca",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Шеман Гриффит"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "0644f6eb50bbf423901c39cf0e35e268",
	},
	["Шен'драларский ревнитель"] = {
		["Мой господин очень интересуется логовом Нефариана. Вот если бы кто-нибудь победил дракона и его прихвостней, а затем рассказал принцу историю об этом… После этого принц точно заговорит. Пеплоносец можно найти!"] = "c1dcc591d8d16fba46b238ec1612e330",
		["Подозреваю, что бесы крадут знания."] = "de92e3bf1b00e122ea4b943635de2b3a",
		["Принц отказался рассказать о Пеплоносце? Эту его историю мы любим больше всего. А ему самому больше нравится ее продолжение. Но, разумеется, он его никому не рассказывает."] = "0b91ae5b7eee6652c2cec68b923afa45",
		["С недавних пор стали пропадать книги. Хранитель мудрости и его помощники обеспокоены. Они подозревают, что в Эльдре'Таласе завелись лазутчики."] = "9a159099d974832b62617bee56187359",
		["Хранитель мудрости очень стар. Он еще помнит нашу славную королеву!"] = "1bb37b5e2ce5b14590bd6d1f7ea818fa",
		["Многие вошли в это святилище, но немногие из него вышли."] = "c4c85ae4efc99586586ab345d2d67fe2",
		["Говори потише, $gстранник:странница;. Не стоит прерывать медитацию Мастера."] = "d5151f42961aedaf4038bdc6a60aa9f2",
		["Нельзя злить господина. В гневе он жесток без меры."] = "4977781f15c9e77ab5e0dab144648ba9",
	},
	["Шентул"] = {
		["Орден Изувеченной Длани существовал до Тралла и будет существовать, когда Тралла давно не будет."] = "4f0a9d40e9cc2c1e6b1295172014d77e",
		["В этих землях очень сильно влияние Изувеченной Длани. Мы – покров, защищающий Калимдор. Мы правители, мы стража, мы судьи, мы присяжные и мы же палачи. Мы видим и знаем все.$B$BТы, $N, заметно $gвырос:выросла; за время службы Руке. Пришла пора отправить тебя в настоящий бой.$B$B$gГотов:Готова; ли ты получить следующее задание?"] = "e5b80def6be2f085b63829ee15ec4de0",
		["$C – это не ко мне."] = "6de484f4be256ef1578f9421e15df66b",
		["У меня есть кое-что для тебя, $n. Кажется, это важно."] = "d40a242b76d3772a9974107e9b235081",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "5016339405f25a1000a29e26a0caf19c",
	},
	["Шиан'дара"] = {
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "857ea30c7f6e11d987a132b4e84da4dc",
	},
	["Шиан'цу"] = {
		["Да пребудут с тобой духи. Чем тролли могут тебе помочь?"] = "6c82842b379af58a9a58e28cb35a4d49",
		["Да хранят тебя духи."] = "5bcfe44c67f5e0a247451c8d54a13c74",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "857ea30c7f6e11d987a132b4e84da4dc",
	},
	["Шикрик"] = {
		["Духи привели тебя ко мне. Чем я могу помочь?"] = "93ff0e2abb20dcd5c4b04b86b60d8ab3",
		["Да пребудут с тобой духи."] = "7be5b41b6547e9fda9b4b9cb85616226",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "28f6b8de934060edb89ab0339b080fcf",
	},
	["Шин"] = {
		["Куда бы вы хотели слетать?"] = "26d3fb863cf374254276fad4c4fb1b43",
	},
	["Шпакл Шиповникс"] = {
		["Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота."] = "fd312c0a6c2a53fe94ce6efbfec8fdf0",
		["Ты не $gчернокнижник:чернокнижница;! Ступай!"] = "a008b2d4b88f3786b6d85d414649daf0",
	},
	["Шрааз"] = {
		["Вишневый пирог – самое вкусное блюдо Азерота!"] = "d3411cffc21c4955c2412b95aba6b187",
		["Свежий вишневый пирог! Пальчики оближешь!"] = "ea78d8c34142c49947facd4181a8e935",
		["Попробуйте этого вишневого пирога – вы сразу улыбнетесь, вот увидите!"] = "c4d447b7e05edffe18bf3bcb19354c50",
		["Этот вишневый пирог так вкусен, что даже взрослый гном бы прослезился."] = "2f19051795d51dc9463970ccd43e85b3",
		["У вас неудачный день? Попробуйте вишневого пирога!"] = "d624f8a342f7b15a346a8164b8a05964",
		["Пирог вышел отличный, хотите?"] = "f6507323af9a61767666f452dc437353",
		["Мама всегда говорила, что нет ничего прекраснее в мире, чем кусок теплого, хрустящего домашнего пирога с вишнями!"] = "73d13905cab099e18703a50ba5f9359e",
		["Люблю пироги."] = "c927831e286d4bf0f00bc791d24f0020",
	},
	["Штормградский стражник"] = {
		["А, так тебе нужна счетная палата… Она совсем рядом с воротами Штормграда."] = "8d0487b1471f828e2ad08533960ce09c",
		["Укротитель грифонов обеспечивает воздушное сообщение Штормграда с другими землями. Если желаете полетать, обращайтесь к нему."] = "e7b869503b0c9fc3c78fef1e53facf50",
		["Такие вопросы решаются только в Штормграде. Если хотите собрать гильдию, отправляйтесь в гостевой центр Штормграда."] = "74f90133248ed081dd63135606a46784",
		["\"Гордость льва\" в Златоземье – не худшая из местных таверн. Зайди туда на огонек и доверься гостеприимству хозяина Фарли."] = "0c144818f02d11af9021a5823b7427f0",
		["Наверное, тебе нужна Ирма. Она заботится обо всех местных зверях. Ищи ее возле таверны\"Гордость льва\"."] = "58e01c3573e8ec29c720f44c53d6fe5f",
		["Я в магии не особо смыслю, но в таверне \"Гордость льва\" сейчас живет маг Залдимар. Он наверняка сможет вам помочь."] = "288705c766a2a8cdf112cab9b1339549",
		["Брат Вильгельм часто тренируется с Лирией дю Лак за кузницей в Златоземье. Возможно, он сможет рассказать тебе что-то новое о пути паладина."] = "31da6527b1db663dc6f3342620895fe3",
		["Готов спорить, Жозетта с радостью научит тебя парочке новых заклинаний. Скорее всего, она сейчас у себя в комнате в трактире \"Гордость льва\"."] = "0131cac34dfe2c78da45684a609b5c32",
		["\"Готов спорить, что Керин Сильвиус знает тех, кто тебе нужен. Вечно она водится с кем попало… Ищи ее в трактире \"Гордость льва\"\"."] = "cec94b6df353509053c932b86d356143",
		["Чернокнижник? Ну, если бы я был чернокнижником, я бы спрятался в самом темном месте… Например, в подвал… Попробуй поискать в подвале таверны \"Гордость льва\"."] = "325caa33bcef35efcdd544756cf14f0f",
		["Если хочешь подучиться, поговори с Лирией. Обычно она стоит за кузницей и ждет, пока там не изготовят очередной доспех или оружие."] = "82b4071e4aa609b4e65e5f67ec183b71",
		["Говорят, в холмах между Североземьем и Штормградом живет один алхимик. Почему бы тебе не навестить его?"] = "e497836bddead8885e3007c40241502e",
		["Должно быть, ты ищешь кузнеца Аргуса. Он обычно присматривает за кузницей в Златоземье. Тебе, наверное, подучиться надо?"] = "43662cd560b3472be8503d8f103e25ee",
		["\"Почему бы тебе не поговорить с поваром из \"Гордости льва\"? Он может подсказать тебе парочку рецептов\"."] = "62fe1dee3e085669493ca628f7533517",
		["Ммм… все мои знакомые зачаровыватели, живут в Штормграде. Почему бы тебе не отправиться туда и не расспросить местных стражников?"] = "ee80e28a58b1049bafc0e9b980b7a239",
		["Наверняка в Штормграде есть гном, который научит тебя профессии. Я уверен, что один из Штормградских стражников покажет тебе, куда идти."] = "67d9b63fc15643383e2f46d266010802",
		["Я знаю, кто тебе нужен! У нашей Мишель Белль все больные в два счета выздоравливают! Если у кого и учиться первой помощи – так это у нее. Сейчас она живет в таверне \"Гордость льва\"."] = "e130db25d19c3095f05bb7862422afec",
		["Несколько месяцев назад Ли выловил что-то странное в Хрустальном озере. Вроде бы какую-то непонятную маску… А может, он просто хлебнул лишку в \"Гордом льве\"."] = "17360956a7039de22d26a002b7bfcd3e",
		["Наш травник живет рядом с алхимиком, в холмах к востоку от Штормграда. Удобно устроились, правда?"] = "228c73c43f5dce6e402e233719bc6c1f",
		["Адель Филдер прославилась на весь Элвиннский лес как искусная кожевница. Ты можешь найти ее на озере Хрустальном, где она работает у себя дома."] = "055387f3f8f3d85f77a3586504bdb666",
		["Лучше вам в Штормграде поискать. Спросите там любого стража, они скажут, куда пройти."] = "60dc358a6e2438c3c568e59ad0bce002",
		["У нас есть отличный учитель снятия шкур. Она живет в хижине возле Хрустального озера. Думаю, она с радостью преподаст тебе основы своей профессии."] = "7b8dd59196b08d9c2aaf28ce9395a4ab",
		["Хочешь заняться портняжным делом? Хмм… Кажется, портной был на Лесопилке Восточной долины. Попробуй поучиться у него."] = "9b934f8faed0473a27a58466b2ffe393",
		["Что ты ищешь?"] = "ed1b18176e479fb1e0c5d47c9f1dd25d",
		["Банк? Ну, ближайший банк у нас – Счетная палата Штормграда. Иди от городских ворот прямо по дороге, она там недалеко."] = "f92f96da1792dd89dc40428e6b0fa147",
		["Ну, если тебе нужно куда-то слетать, ступай в Штормград. Там есть укротитель грифонов. Иди по Аллее Героев и смотри направо. Увидишь, где приземляются грифоны – туда тебе и надо."] = "af3a7d00ee25555e5773f072ba9dd2b6",
		["Надеюсь, Альдвин Лолкинс – по-прежнему постоянный представитель Гильдии в Штормграде. Как пройдешь внутренние ворота, его дом будет слева."] = "c01d6d61aad524ab4f569adfc154bdea",
		["Иди сразу в Златоземье, в \"Гордость льва\". Увидишь, сколько у них сортов пива, – поймешь, что лучше места для отдыха просто не найти!"] = "f25229f44474299d00b3ef221972ff2e",
		["О животных тут уже много лет заботится старушка Ирма, она и за вашим с радостью приглядит. Ее можно найти возле таверны \"Гордость льва\"."] = "02898b1403315800a99b2c54921d2dda",
		["В Элвиннском лесу много разных учителей. Тебе какой нужен?"] = "a5a7622b8f8ebe5afb104225cc531868",
		["Есть у меня парочка знакомых – настоящие мастера своего дела. Что ты хочешь изучать?"] = "20386cfd269226043dcfdd5aa6c1fdc7",
		["Друиды? Не встречал тут ни одного друида, хотя в Штормграде есть целый квартал ночных эльфов."] = "fb2147a6362627351b16b4e670503b33",
		["Я слышал, что есть один дворф в Штормграде, известный охотник. Возможно, тебе стоит обратиться за помощью к нему."] = "0156f92878dd7185920a393b5853d47b",
		["Залдимар может обучить тебя новым заклинаниям. В последнее время он предпочитает останавливаться в \"Гордости льва\". Загляни в одну из комнат этого трактира – вдруг он там?"] = "a8a07c07ddedc32bea4ab7fd7bf3f027",
		["Найди брата Вильгельма – он обычно болтает с Лирией на задворках кузни. Он любит учить паладинов."] = "8c17773e87f0ed8951a19ec2b38a564c",
		["Жозетта своей первой помощью местным стражникам благословляет наш город. Если ты хочешь научиться делу жреца, ты найдешь ее в трактире \"Гордость льва\"."] = "d22f824b0a95fcf0e0fa1f9b6e66ee87",
		["Разбойник? Хммм… Ну, мне говорили, что Керин Сильвиус вечно якшается с какими-то подозрительными типами. Поговорите с ней, может, чему и научитесь."] = "8e11642ef78ecb20aeb15e5bd3d4ac1d",
		["А… так ты из этих. Ну, всякими темными искусствами у нас занимается только Максимилиан. Ищи его в подвале трактира \"Гордость льва\"."] = "d4cde9dec6267a8111368f29e62b71aa",
		["Здесь мало кто может сравниться во владении мечом с Лирией дю Лак. Разыщи ее за кузней и узнай, захочет ли она чему-то тебя учить."] = "0331ca902e3146c78118e62c38363c41",
		["Зелья для местных жителей готовит отшельник Мэллори. Его дом находится в холмах между Штормградом и Североземьем."] = "002edc960865a12462d524da4a9ec5c2",
		["Аргус – главный кузнец Златоземья. Уверен, у него есть чему поучиться."] = "da5177b45d44e25aa57706e08476b9f5",
		["Томас, может, и не лучший повар в мире, но есть несколько блюд, которые ему очень удаются. Сейчас он работает в таверне \"Гордость льва\" – если хочешь научиться профессии."] = "99a5d490289d9bb0176d9a7556472b8e",
		["Нет, у нас в Элвиннском лесу никто не занимается зачаровыванием. А вот в Штормграде есть некий Лукан. Сходи к нему – может быть, он возьмется тебя учить."] = "e821d7ca53f505264e3c4d486d01a7b4",
		["Обычно я поручаю такие вещи гномам. Если хочешь заняться этим ремеслом, в Штормграде, несомненно, найдутся гномы, готовые учить тебя."] = "f0fa0f3fc757caa137f7f79f9bbf14be",
		["Недавно мне здорово досталось от бандитов из Братства Справедливости, но Мишель Белль быстро привела меня в порядок. Разыщи ее в трактире \"Гордость льва\" – может быть, она возьмется тебя учить."] = "96d48bb506899c3338f1cadfcbe2c66a",
		["Ли Браун целыми днями сидит с удочкой на Хрустальном озере. Он расскажет тебе кучу историй и, может быть, даст парочку полезных советов."] = "e5a3403d0988099931e0ac6f2f9d1c86",
		["Мисс Помрой собирает травы для алхимика, который живет в холмах между Североземьем и Штормградом. Иди к ней и попроси ее научить тебя чему-нибудь."] = "91eec838271e2defd97f1ef17cd50484",
		["У озера Хрустального живет леди по имени Адель Филдер. Она чинит кожаные вещи для местных стражников, а кожу берет у специалиста по снятию шкур Хелен. Если ты хочешь научиться этому, тебе, пожалуй, следует повидаться с ней."] = "c42cc1f489ae783fa9e802f59af6a32e",
		["Если хочешь научиться шахтерскому делу, тебе лучше всего направиться в Штормград, в Квартал Дворфов. Наверняка один из дворфов там может научить тебя этой профессии."] = "5b3a63364d822c6bd2559d96ec4d9317",
		["Хелена Меховяз уже много лет снимает шкуры с животных, а Адель Филдер делает из этих кож всякие вещи. Хелену можно найти в ее доме возле озера Хрустального."] = "a0fc4a75717f81994f43c0cc9dcc5a2a",
		["Элдрин – единственный житель Элвиннского леса, которого можно назвать портным. Ты найдешь его на лесозаготовках Восточной долины."] = "99116cecd296f9c7b453b0cd466c1c0c",
	},
	["Щербушка"] = {
		["Куда бы вы хотели слетать?"] = "0edd3c73540d735f036ac6e027466523",
	},
	["Эбб Неплебор"] = {
		["Добро пожаловать! Добро пожаловать в Зоопарк чудовищ Эбба Неплебора – Сокровищницу Живых Легенд и Мистических Странностей! Наслаждайся визитом, друг!$B$BНо подумай дважды, прежде чем что-то трогать! Эти выставочные экспонаты, и артефакты, и звери – ужасные и вместе с тем изумительные! Они могут сжечь руку слишком любопытного посетителя…"] = "7b6f88d5a16eec48ed71f32561eef2a6",
	},
	["Эван Ларсон"] = {
		["Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда."] = "2e4eca05cb76135045a9a7c0e66e45af",
		["С тех пор как пал Даларан и был разрушен Кель'Талас, такие товары встречаются крайне редко. Но Лукан Корделл и еще несколько торговцев все еще могут выполнять наши заказы."] = "52ce57327118edf04bd3864c3342a693",
	},
	["Эвника Барч"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "f5400ec6ebea670b036a6880beada4ab",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "9f8ebedd06a040d3d2ffa50aac35d51f",
		["\"Поваренную книгу умельца\" можно купить у Вулана в Деревне Ночных Охотников. Тебе она понадобится, если ты хочешь расти над собой."] = "fc64c85b44749257ced7e34a940a1c64",
		["Я могу научить тебя готовить!"] = "02987be90f767850ec8e9f572adbc4ed",
	},
	["Эдна Милби"] = {
		["Просто интересуетесь, или ищете что-то особенное? Что-нибудь подсказать?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Самые выгодные сделки во всем Штормграде, друг мой! Итак, чем я могу тебе помочь?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	["Эйнриса Яркошип"] = {
		["Взгляните, какой мудростью и знаниями обладает животное, – и все поймете. Научитесь у совы наблюдательности, у саблезуба – уму, а от волка переймите неукротимый дух."] = "e819ff41951b65f23ee4325d791c4227",
		["У меня тебе учиться нечему. Ты $c, вот к своему учителю и ступай."] = "50c3dde9457501168f44f5feeb295930",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "125a186cc1dc5f89644a87549bcf2140",
	},
	["Эйтригг"] = {
		["Приветствую, $gюный:юная:c; $c."] = "7c980a9713ee9148bd335d78781ea63e",
		["Ренд, сын Чернорука: бессильный вождь клана Черной Горы. Более упрямого ублюдка не существует.$B$BВ конце Второй войны Ренд и его брат Мейм убежали, чтобы найти прибежище в горной твердыне Пика Черной Горы. Именно там Ренд объявил себя военным вождем ослабленного клана Черной Горы."] = "135df692a98ed33e9a1d293d6f787ec3",
		["Да, $gюноша:девушка;, тебе не нужно убеждать меня в этом. У нас с военным вождем богатая история. Однако твоя преданность замечена. $B$BКак я говорил, Ренд нашел новый дом для своего народа, а я был среди тех, кто устало следовал за ним. $B$BОдин конфликт приводил к другому… к бесчисленному множеству других. В битвах за Пик Черной Горы, которые вели между собой клан Черной Горы и дворфы клана Черного Железа, погибли оба моих сына. Тогда я и осознал, что моя жизнь в клане Черной Горы подошла к концу."] = "1f202d29690acd4df3f48c1e0c19c225",
	},
	["Экзал"] = {
		["Здравствуйте, $c. Я Экзал, слуга Растахана."] = "e7cdb9be91ab5ee24261c54b7949c919",
	},
	["Элдрейт"] = {
		["Сделано лучшими мастерами всего Тельдрассила, на руках принесено из Калимдора в Азерот – в знак крепнущего союза между народом Великого Древа и здешними людьми. Если тебе чего-то нужно – только спроси."] = "f819d1b4e7f5fee1a4f4efd60581493e",
	},
	["Элдрин"] = {
		["Могу сказать, что твой гардероб остро нуждается в уходе."] = "b34aad75e8e14753d5e47ece1a2eba61",
		["Я всего лишь простой портной – моих знаний для тебя слишком мало. Но я слышал об одном искусном мастере из ночных эльфов, который живет в Квартале магов Штормграда."] = "c20cda58878fc7ac4e481f3bc65a3f73",
		["Так ты хочешь кое-чему научиться? С удовольствием помогу тебе!"] = "c9603b8eec1e5738749f40b5e7e89a19",
	},
	["Элегорн"] = {
		["Кулинария – страсть на всю жизнь. И, как я вижу, вы тоже не чужды этой страсти!"] = "95be6f4a5e8c06f411a7922aba42f920",
		["Разыщи Шандрину в приюте Серебряного Ветра. Она может продать тебе \"Поваренную книгу умельца\"."] = "9530fe03acd8fd0d529479909397654b",
		["Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!"] = "39b65bdd01752b5105cbbb2683f8191b",
		["Я могу научить тебя готовить!"] = "d8db5bcf701df43b6392f5a3b85ce404",
	},
	["Элисса Дюма"] = {
		["Мне кажется, ваших умственных способностей недостаточно для постижения тонкой магии порталов."] = "6169b63082c1481ee1b292a6bd277450",
		["Тебе повезло быть $gодним:одной; из нас – ведь только маг сможет создать портал для возвращения сюда. Я могу научить тебя, если хочешь."] = "c0b64230899c1f169032e2124bab7479",
	},
	["Эльфарран"] = {
		["Не хочу тебя расстраивать, $c, но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны."] = "db6d2a2e49b804a2cf643369c2d678f3",
	},
	["Эмиссар Лиги Аратора"] = {
		["Спасибо, $c. Но, к сожалению, ты еще недостаточно $gопытен:опытна;, чтобы сражаться в Низине Арати."] = "a7aeb4a623d4e606d380ae2595ce637e",
		["Поможешь ли ты Низине Арати в час великой нужды, $c? Это отличный шанс завоевать немало чести и заслужить наше доброе отношение, если удастся одержать победу над Осквернителями. Можем ли мы рассчитывать на тебя?"] = "f89a0bf28da74e8eb8f97d6f99a54359",
	},
	["Эмиссар Осквернителей"] = {
		["Вы еще недостаточно сильны, $c. Наберитесь сил."] = "4976af9b251b6de3b310c96fc5968bd8",
		["Мы нуждаемся в помощи в Низине Арати куда больше, чем можно себе представить, $N. Но, однако, таковы же честь и репутация, которые можно заслужить в этот трудный час. Я прошу тебя отыскать в этом городе военачальника Низины Арати."] = "36449905f0bb8e68d581301b2d6574fb",
	},
	["Эмиссар Северного Волка"] = {
		["Тебе нужно стать сильнее, $c, прежде чем ты сможешь помочь нам в Альтеракской долине."] = "f4899549736f46c15cd46831ff21c964",
		["Приветствую тебя, $c. Сражаться в Альтеракской долине – не только долг, но и большая честь. Присоединишься ли ты к нашей битве против Стражи Грозовой Вершины?"] = "99f6365eca208317d557bba2b924e015",
	},
	["Эмиссар из клана Грозовой Вершины"] = {
		["Боюсь, в Альтеракской долине вы долго не проживете, $c. Приходите, когда поднаберетесь немного опыта."] = "7482b5799dee6ec1e4b78aa8db8bdd98",
		["$n, Страже Грозовой Вершины нужна твоя помощь в битве против клана Северного Волка в Альтеракской долине. Нужна как никогда. И шанс прославиться у тебя особенно велик! Вступишь ли ты в эту битву?"] = "1bda910e93a73611cc7b700da4c7cb86",
	},
	["Эмиссар из клана Песни Войны"] = {
		["$gСлабоват:Слабовата; ты для Ущелья Песни Войны, $c."] = "f24e4a79c576d78e3b220d459097ffb8",
		["$C, нам очень нужна ваша помощь в борьбе против Среброкрылых Часовых в Ущелье Песни Войны. К тому же это принесет вам много чести и повысит вашу репутацию среди Всадников Песни Войны! Ну как, осмелитесь ли вступить в бой?"] = "94e10ef8ca4f4ba7b2ed059da3d417e8",
	},
	["Энио"] = {
		["Приветствую, $c. Ты желаешь обрести тайное знание?"] = "c8d841d3dd0d9f3195df9fb37ffd84b4",
		["Приветствую, $c. Мне жаль тебя, секреты настоящей магии выше твоего понимания…"] = "b7091bbfed54b698c06cee9a75fe004b",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "857ea30c7f6e11d987a132b4e84da4dc",
	},
	["Эрелас Янтарное Небо"] = {
		["Привет, $n. Я дрессирую молодых гиппогрифов. Можете спокойно все осмотреть."] = "de300aecfe64e2c0dd5018d277df9334",
		["Друиды внимательно следят за всеми живыми существами. Узнав, что этим птицам грозит опасность, мы нашли способ спасти их от фераласской порчи. $B$BНаибольший вклад в это дело внесла гном Кургль Поскакушка. Она собрала яйца и переправила их сюда, а я о них позаботился.$B$BМы всегда рады новым помощникам, $n. Возможно, тебе стоит навестить Кургль в Прибамбасске."] = "b19ba63af1bb1e807752e1767b2f0b9c",
	},
	["Эрика Тейт"] = {
		["Я продаю только лучшее снаряжение, надежное и проверенное. Цены у меня фиксированные, так что если хотите поторговаться – идите к гоблинам."] = "1d035ef80655c9d2cd4e435e275a7bba",
	},
	["Эрион Шепот Тени"] = {
		["$C – это не ко мне."] = "f7c03ed04dab075fddaf94fa5e6690d8",
		["Приветствую, $gюный разбойник:юная лазутчица;. Что ты ищешь?"] = "359b565e3f9598b0c4c99d31465a6002",
		["Посланцы Черного Ворона сегодня утром вручили мне это письмо. Оно адресовано тебе, $n."] = "cd9efe92b4cd73363689d342f33b4061",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "30ee103c545f987ab518c70f6d3e640e",
	},
	["Эстелла Джендри"] = {
		["С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого."] = "d727a9a6c19bda725fe90de6453f386d",
	},
	["Эталас"] = {
		["Не хочу тебя расстраивать, $c, но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны."] = "db6d2a2e49b804a2cf643369c2d678f3",
	},
	["Югрек"] = {
		["Куда бы вы хотели слетать?"] = "f686b3319d4af5004c6ee3403aea3f5e",
	},
	["Явнир Нашак"] = {
		["Здравствуй, $c. Пришло время Праздника Урожая – время щедрых даров и воспоминаний. Мы устраиваем пиры, чтоб отпраздновать все, за что нам следует быть благодарными, и вспоминаем наших предков и героев прошлого, чтобы поблагодарить их за наследие.$B$BНе стесняйся, присоединяйся к нашему пиру. А еще я устраиваю фейерверки, чтобы лучше отпраздновать это радостное время года."] = "07d82752c2b2a676dc03af347776f8b3",
	},
	["Ян Шторм"] = {
		["Не думаю, $c, что ты захочешь учиться у меня. Тебе нужны наставники твоего класса."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
		["Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
		["С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
}